window.__SUM[4]={"LR003641":{"pair":"a -> Mc4r","headline":"Agouti antagonises MC4R in two abstract-only papers, one binding and one functional.","interaction_type":"direct binding","direction_and_effect":"ASIP is a potent inhibitor of hMC4R, with surmountable inhibition [PMID:9058374]. Alanine substitution at agouti Arg116, Phe118 or Phe117 greatly lowers agouti affinity at MC4R [PMID:9454589]. Curators label the effects antagonist and inverse agonist respectively.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 7.3","assay":"melanocortin receptor binding inhibition, curator-recorded","system":"mouse agouti, mouse receptor","cite":"PMID:9454589"}],"species_and_systems":"Mouse agouti and receptor [PMID:9454589]; human ASIP at human MC4R in L cells and OS3 cells [PMID:9058374]. Mouse pair is ortholog-inferred.","localisation_and_range":"Agouti is flagged secreted [flag].","caveats":"Abstracts only. The pKd is curator-recorded and not in the abstract text. Agouti residues Phe117 and Asp108 also affect KI app at MC4R [PMID:9454589].","key_references":[{"PMID":"9058374","why":"Potent ASIP inhibition at hMC4R"},{"PMID":"9454589","why":"Agouti residues governing MC4R binding"}],"covers":["LR003641"]},"LR003551":{"pair":"A2M -> LRP1","headline":"A2M is the classic LRP1 ligand: structural, ligand-blot and receptor purification evidence, with one weak NMR Kd.","interaction_type":"direct binding","direction_and_effect":"Placental alpha2-macroglobulin receptor chains are the alpha and beta subunits of LRP, so LRP is suggested to be the receptor for alpha 2M-proteinase complexes [PMID:1702392]. Alpha(2)M* binds LRP heavy chains by ligand blotting [PMID:12194978]. A curator annotation marks the effect as stimulatory (annotation, not from the abstracts).","molecular_requirements":"The NMR study used complement-like repeat CR3 of LRP against the A2M receptor binding domain, so a single repeat is enough for weak binding [PMID:10652313]. Receptor-recognized alpha(2)M* is the binding form [PMID:12194978]. Silencing LRP did not stop alpha(2)M*-induced signalling via Grp 78 [PMID:12194978].","affinity_potency":[{"value":"Kd approximately 140 microM","assay":"NMR, LRP CR3 with A2M receptor binding domain","system":"isolated domains","cite":"PMID:10652313"}],"species_and_systems":"Human proteins in NMR and purification studies; species unspecified for the placental receptor paper [PMID:10652313, PMID:1702392]. Mouse pair is ortholog-inferred.","localisation_and_range":"A2M is flagged secreted [flag]; LRP described as a scavenger receptor [PMID:12194978].","caveats":"All papers read as abstracts only. The 140 microM Kd is for a single repeat and is called relatively weak [PMID:10652313]. The 1990 paper rests on sequence identity, not a binding measurement [PMID:1702392]. BioGRID lists a co-crystal structure record [DB:BioGRID].","key_references":[{"PMID":"1702392","why":"Identifies LRP as the alpha2-macroglobulin receptor"},{"PMID":"10652313","why":"NMR evidence for CR3 binding to A2M receptor binding domain"},{"PMID":"12194978","why":"Ligand blot of alpha(2)M* on LRP"}],"covers":["LR000001","LR003551"]},"LR003560":{"pair":"ADAM15 -> ITGB1","headline":"Integrin beta1 is implicated as partner of alpha9 and alpha5 in two abstract-only ADAM binding papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]. Metargidin binds MOLT-4 cells in part through alpha5beta1 [PMID:9914169].","molecular_requirements":"Evidence is for alpha9beta1 and alpha5beta1 heterodimers, so the matching alpha chain is required; beta1 alone is not shown [PMID:10944520, PMID:9914169].","affinity_potency":[],"species_and_systems":"Recombinant disintegrin domain and ADAM15-Fc chimera on human cell lines [PMID:9914169]; species not reported for PMID:10944520.","localisation_and_range":"ADAM15 flagged not secreted [flag].","caveats":"Both abstract only; chain-only evidence for ITGB1. One judged row is still pending.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-15 disintegrin domain"},{"PMID":"9914169","why":"alpha5beta1 contribution to ADAM15 binding"}],"covers":["LR000010","LR003560"]},"LR002066":{"pair":"ADAM17 -> CD9","headline":"CD9 directly associates with ADAM17 and dampens its sheddase activity; this is a regulatory partner pair, not a signalling ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"Treatment with CD9-specific antibodies or CD9 neoexpression reduces ADAM17 sheddase activity, and CD9 silencing increases activity against TNF-alpha and ICAM-1 [PMID:21365281]. Curators label the effect antagonist.","molecular_requirements":"Not reported in our evidence beyond CD9 being a tetraspanin [PMID:21365281].","affinity_potency":[],"species_and_systems":"Human endothelial and monocytic cells; proximity ligation, co-IP, crosslinking and pull-down [PMID:21365281].","localisation_and_range":"Both partially co-localise on the cell surface [PMID:21365281]; ADAM17 is flagged not secreted [flag].","caveats":"One paper, abstract only. IntAct has an anti-bait co-IP record from another paper [DB:IntAct].","key_references":[{"PMID":"21365281","why":"Direct ADAM17-CD9 association with negative regulation of shedding"}],"covers":["LR002066","LR005392"]},"LR005018":{"pair":"ADAM7 -> ITGA4","headline":"ADAM7 disintegrin domain supports alpha4beta1-dependent Jurkat adhesion in an activation-dependent manner; abstract only.","interaction_type":"functional only","direction_and_effect":"The ADAM7 disintegrin domain supported alpha4beta1-dependent Jurkat cell adhesion; recognition required either Mn2+ or an activating monoclonal antibody [PMID:15504110].","molecular_requirements":"Alpha4 acts as alpha4beta1; integrin activation is required. The same residues within an ADAM disintegrin domain recognise multiple integrins, from charge-to-alanine mutagenesis [PMID:15504110].","affinity_potency":[],"species_and_systems":"Human ADAM disintegrin-like domains; Jurkat cell adhesion assays [PMID:15504110]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM7 is flagged secreted [flag]; adhesion to immobilised disintegrin domain.","caveats":"Abstract read only; labelled direct binding by curators but the evidence is a cell-adhesion assay.","key_references":[{"PMID":"15504110","why":"ADAM7 disintegrin recognised by alpha4beta1 and alpha4beta7"}],"covers":["LR001630","LR005018"]},"LR002075":{"pair":"ADAMTS1 -> LRP1","headline":"Direct LRP1 binding of ADAMTS1 reported in a chondrocyte ligandome study (abstract only); no affinity for ADAMTS1.","interaction_type":"direct binding","direction_and_effect":"Purified-protein binding assays confirmed direct LRP1 binding of ADAMTS1 among ten ligands, with LRP1 affinity correlating with endocytosis rate, so LRP1 acts as an endocytic receptor that takes up ADAMTS1 [PMID:36028175].","molecular_requirements":"Not reported in our evidence beyond LRP1 itself.","affinity_potency":[],"species_and_systems":"Human chondrocyte proteomics and purified-protein binding; validation in LRP1-deficient fibroblasts and human chondrocytes; a conditional Lrp1 knockout mouse was used for the general ligand set, not shown for ADAMTS1 specifically [PMID:36028175].","localisation_and_range":"Ligand is flagged as secreted [flag]; LRP1 is a cell-surface endocytic receptor [PMID:36028175], consistent with paracrine uptake.","caveats":"One paper read as abstract only; ADAMTS1 is one of ten ligands handled together. No numerical affinity for ADAMTS1 in our evidence. No database support.","key_references":[{"PMID":"36028175","why":"chondrocyte LRP1 ligandome with direct binding of ADAMTS1"}],"covers":["LR002075","LR005401"]},"LR001634":{"pair":"ADGRB1 -> RTN4RL2","headline":"Direct ectodomain binding of ADGRB1 to RTN4RL2 shown in one full-text paper (CRISPRa screen, flow cytometry, AVEXIS).","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells expressing full-length RTN4RL2 but not mock cells [PMID:30477585]. ADGRB1 ectodomain bound all three RTN4R family members directly in both bait-prey orientations [PMID:30477585]. Effect on signalling not reported in our evidence.","molecular_requirements":"ADGRB1 thrombospondin type 1 repeats 1-3 were sufficient for binding [PMID:30477585]. RTN4RL2 is described as GPI-linked [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 cells and recombinant ectodomains; mouse pair is ortholog-inferred, not tested in our evidence [PMID:30477585].","localisation_and_range":"Both partners carry secreted and receptor flags [flag]; the paper describes RTN4RL2 as GPI-linked membrane protein [PMID:30477585], so likely contact-dependent.","caveats":"Single paper; one screen per bait. The paper notes that one RTN4R member was not enriched in the screen, attributed to surface presentation [PMID:30477585]. No affinity reported.","key_references":[{"PMID":"30477585","why":"CRISPRa screen with ADGRB1 probe plus direct ectodomain binding"}],"covers":["LR001634","LR005022"]},"LR005405":{"pair":"ADGRG1 -> TGM2","headline":"GPR56 (ADGRG1) reported to bind TG2 in one abstract-only paper; ligand-receptor direction is unclear.","interaction_type":"direct binding","direction_and_effect":"GPR56 binds specifically to tissue transglutaminase TG2, a stromal component; GPR56 overexpression suppressed melanoma growth and metastasis [PMID:16757564]. UniProt also lists the interaction [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma cell variants and tumour models, per abstract [PMID:16757564]; the human pair is marked ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted and not transmembrane [flag]; the paper calls TG2 a stromal component [PMID:16757564].","caveats":"Abstract only; the binding assay is not described. Growth suppression is in vivo only [PMID:16757564]. UniProt cites the same paper plus two others [DB:UniProt].","key_references":[{"PMID":"16757564","why":"reports GPR56-TG2 binding and tumour suppression"}],"covers":["LR002079","LR005405"]},"LR002084":{"pair":"ADGRL1 -> TENM4","headline":"Latrophilin-1 binds teneurin-4 on cells; full-text excerpt shown for Ten4, abstract describes nanomolar teneurin binding.","interaction_type":"direct binding","direction_and_effect":"Lphn1-Ig proteins, including the lectin domain alone, bound strongly to HEK293T cells expressing Ten2 or Ten4 but not control cells [PMID:24273166]. Teneurin binding mediates cell adhesion; soluble Lphn1 fragments decreased synapse density in cultured neurons [PMID:24273166].","molecular_requirements":"The lectin-like domain of latrophilins binds teneurin; alternative splicing modulates teneurin binding in latrophilin-1 [PMID:24273166].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"teneurin-latrophilin binding, per abstract","system":"not specified for Ten4","cite":"PMID:24273166"}],"species_and_systems":"Cell-surface labelling of HEK293T cells; species unspecified [PMID:24273166]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both are membrane proteins; binding mediates cell adhesion, consistent with trans-synaptic interaction [PMID:24273166].","caveats":"The nanomolar affinity is stated for teneurins generally in the abstract, not specifically for Ten4. Direction is not defined, both being membrane proteins.","key_references":[{"PMID":"24273166","why":"Lphn1-Ten2/Ten4 binding and adhesion"}],"covers":["LR002084","LR005410"]},"LR005414":{"pair":"AGGF1 -> ITGA5","headline":"AGGF1 binds integrin alpha5beta1 on endothelial cells (antibody blocking, pull-down, cell binding); alpha5 and beta1 both appear required.","interaction_type":"direct binding","direction_and_effect":"AGGF1 interacts with alpha5beta1 and activates FAK, Src and AKT; siRNA for ITGA5 reduced AGGF1-stimulated AKT phosphorylation [PMID:34551592]. An RDD angiogenic domain (residues 604-613, FQRDDAPAS) is required; peptides carrying it block AGGF1 function, an RGD-mutant 15-mer did not [PMID:34551592].","molecular_requirements":"Only anti-alpha5, anti-beta1 and anti-alpha5beta1 antibodies blocked HUVEC binding to AGGF1; anti-alpha1, 2, 3, 4, 6, alphaV and beta3 did not. GST-AGGF1 pulled down integrin alpha5 from HUVEC extract, and the angiogenic-domain deletion lost alpha5 and beta1 pull-down [PMID:34551592]. Score as the alpha5beta1 pair.","affinity_potency":[{"value":"T1/2 18.7 nM","assay":"half-maximum binding concentration, cell adhesion assay (not a Kd)","system":"HUVEC","cite":"PMID:34551592"}],"species_and_systems":"Human HUVEC; mouse aortic endothelial cells showed similar signalling; angiogenic domain tested in a mouse peripheral-artery-disease model [PMID:34551592]. The mouse pair is projected from human.","localisation_and_range":"AGGF1 is flagged secreted [flag]; ITGA5 is flagged not secreted and receptor [flag].","caveats":"Binding was shown with cells, blocking antibodies and lysate pull-down, not purified proteins, so direct contact is inferred. Curators recorded the paper as abstract_only but excerpts were available.","key_references":[{"PMID":"34551592","why":"identifies integrin alpha5beta1 as AGGF1 receptor; maps RDD angiogenic domain"}],"covers":["LR002088","LR005414"]},"LR005027":{"pair":"AGRN -> DAG1","headline":"Agrin acting through dystroglycan is supported by one full-text mouse cardiomyocyte paper plus database records; direct binding is suggested but not shown here.","interaction_type":"functional only","direction_and_effect":"Recombinant agrin promoted cardiomyocyte proliferation, and a blocking antibody against the agrin-binding site of Dag1 diminished agrin-induced ERK activation and blocked agrin-induced P7 cardiomyocyte proliferation [PMID:28581497]. Agrin acts as a stimulatory ligand; UniProt function text also describes AGRN binding to alpha-dystroglycan [DB:UniProt].","molecular_requirements":"Agrin was found in glycerol-gradient fractions containing dystrophin-glycoprotein complex components after 2 h, which the authors read as suggesting agrin binds this complex [PMID:28581497]. Reactome lists AGRN:alpha-dystroglycan and Dystroglycan:AGRN:HSPG2 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse primary cardiomyocytes and mouse in vivo, using recombinant rat agrin [PMID:28581497]. Human and mouse pair entries are both ortholog-inferred.","localisation_and_range":"Agrin is flagged as secreted and DAG1 as a receptor [flag]; agrin is described in the paper as an extracellular matrix component [PMID:28581497].","caveats":"Evidence here is an antibody-block experiment and co-fractionation, not a binding measurement with purified proteins [PMID:28581497]. Database records include Far Western and cross-linking entries [DB:BioGRID] [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"28581497","why":"Antibody against the agrin-binding site of Dag1 reduced agrin-induced ERK activation and proliferation (full text read)"}],"covers":["LR001639","LR005027"]},"LR002093":{"pair":"AGRN -> NCAM1","headline":"A 1996 abstract-only study shows NCAM-expressing cells adhere to agrin, a heterophilic adhesion rather than classical signalling.","interaction_type":"functional only","direction_and_effect":"Mouse L cells transfected with chicken NCAM were used to identify agrin as a ligand mediating NCAM adhesion [PMID:8807193]. Reactome lists NCAM-1:Agrin and AGRN:NCAM1, PTPRS complexes [DB:Reactome].","molecular_requirements":"Chondroitin sulfate degradation decreased adhesion in agrin-containing fractions but increased it if agrin had been removed, so proteoglycan chains influence the interaction [PMID:8807193].","affinity_potency":[],"species_and_systems":"Chicken NCAM expressed in mouse L cells, tested against chick brain membrane fractions; this is not human [PMID:8807193]. Curation tags human/human.","localisation_and_range":"NCAM1 is flagged secreted and transmembrane [flag]; the adhesion was to membrane fractions [PMID:8807193].","caveats":"Abstract-only; perlecan did not support NCAM adhesion, so binding is selective among proteoglycans [PMID:8807193]. Direct binding with purified proteins is not shown. The curator effect label 'agonist' fits poorly an adhesion result.","key_references":[{"PMID":"8807193","why":"NCAM-transfected cells adhere to agrin"}],"covers":["LR002093","LR005419"]},"LR005423":{"pair":"AHSG -> TLR4","headline":"Fetuin-A (AHSG) is reported as a direct TLR4 ligand in mice, with mapped binding residues; supported by one paper.","interaction_type":"direct binding","direction_and_effect":"Fetuin-A acts as an agonist: in high-fat-diet mice, knockdown reduced Tlr4-mediated adipose inflammatory signalling, while FetA administration induced inflammation and insulin resistance [PMID:22842477].","molecular_requirements":"FFA-induced cytokine expression in adipocytes needed both FetA and Tlr4. FFAs did not act with galactoside-cleaved FetA or mutated Tlr4 [PMID:22842477].","affinity_potency":[],"species_and_systems":"Mouse experiments (mice and adipocytes) [PMID:22842477]; pair is human with mouse ortholog-inferred.","localisation_and_range":"AHSG is flagged secreted and TLR4 a receptor [flag]; the paper says FetA binds through its terminal galactoside moiety.","caveats":"Binding is reported as Leu100-Gly123 and Thr493-Thr516 in Tlr4 [PMID:22842477]. Single paper read as abstract only. No database records or affinity.","key_references":[{"PMID":"22842477","why":"FetA binds Tlr4 and mediates lipid-induced insulin resistance"}],"covers":["LR002097","LR005423"]},"LR001643":{"pair":"ALCAM -> NRP1","headline":"Antibody blocking suggests Nrp1 is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for Nrp1 abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"Nrp1 is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. ","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001643","LR005031"]},"LR005036":{"pair":"AMBN -> CD63","headline":"Ameloblastin binds CD63 in human-based studies; abstract-level evidence from two papers, with downstream integrin beta1/Src signalling.","interaction_type":"direct binding","direction_and_effect":"Ameloblastin binds CD63 and promotes CD63 binding to integrin beta1, leading to Src inactivation and osteogenic differentiation; anti-CD63 antibody abrogated the effect [PMID:21149578]. Described as an agonist-type effect [PMID:21149578].","molecular_requirements":"CD63 residues 103-205 interact with ameloblastin and enamelin as well as amelogenin; the binding region is predicted to lie within the CD63 extracellular domain 2 [PMID:17708745]. Integrin beta1 is required downstream [PMID:21149578].","affinity_potency":[],"species_and_systems":"Curators recorded human ligand and receptor [PMID:17708745] [PMID:21149578]; cell systems are not reported in our evidence.","localisation_and_range":"Ameloblastin is flagged secreted [flag]; the paper proposes interaction of secreted matrix proteins with membrane CD63 at ameloblast secretory surfaces [PMID:17708745]. Matrix protein acting on a cell-surface tetraspanin.","caveats":"Both papers were read as abstracts only. No affinity values. No database records support this pair.","key_references":[{"PMID":"17708745","why":"Mapping CD63 region 103-205 binding ameloblastin and other enamel proteins"},{"PMID":"21149578","why":"Ameloblastin-CD63-integrin beta1-Src signalling in osteoblasts"}],"covers":["LR001648","LR005036"]},"LR003605":{"pair":"ANGPT1 -> TEK","headline":"Well-established direct ANGPT1 agonist ligand of TEK (Tie2), with binding mapping, phosphorylation, mouse knockout and many database records.","interaction_type":"direct binding","direction_and_effect":"ANGPT1 is a secreted TEK ligand that binds TIE2 and induces its tyrosine phosphorylation without directly promoting cultured endothelial cell growth [PMID:8980223]. Angiopoietin-1 induced TEK phosphorylation in hematopoietic cells [PMID:9723709]. Ang1-deficient mice show angiogenic deficits like Tie2-deficient mice, indicating a primary physiologic ligand [PMID:8980224]. Agonist.","molecular_requirements":"The first Ig-like loop plus EGF-like repeats of Tie-2 (amino acids 1-360) are necessary and sufficient to bind Ang-1 and Ang-2; the first 104 amino acids are essential but not sufficient [PMID:12427764]. Ang-1 and Ang-2 bind similarly with similar affinities in hematopoietic cells [PMID:9723709]. Single chain receptor (TEK).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in recombinant/cell systems [PMID:12427764][PMID:8980223][PMID:9723709]; mouse knockout in vivo [PMID:8980224]; Tie-2 exon-2 knockout mice described [PMID:12427764]. Human PDB structure 4K0V contains both chains [DB:PDB 4K0V].","localisation_and_range":"ANGPT1 is flagged as secreted and TEK as transmembrane [flag]; ANGPT1 is described as a secreted ligand [PMID:8980223].","caveats":"All four shown papers were read as abstracts only and none gives a numeric affinity in our evidence. Ang-1 and Ang-2 share the same binding domain, so binding site alone does not explain their different effects [PMID:12427764]. One further row is review-only and one pending.","key_references":[{"PMID":"8980223","why":"Identification of Ang-1 as secreted TIE2 ligand inducing phosphorylation"},{"PMID":"12427764","why":"Maps the Tie-2 region (aa 1-360) needed for Ang-1 binding"},{"PMID":"8980224","why":"Ang-1 knockout mice phenocopy Tie2 deficiency"}],"covers":["LR000055","LR003605"]},"LR000059":{"pair":"ANGPTL4 -> TIE1","headline":"ANGPTL4 induces TIE1 phosphorylation in endothelial cells; functional evidence only, weaker than for TEK, with a possibly conflicting database record.","interaction_type":"functional only","direction_and_effect":"Native Ang4 induced Tie1 phosphorylation, less efficiently than the engineered COMP-Ang1 chimera [PMID:15851516].","molecular_requirements":"Activation was amplified via Tie2: Tie2 formed heteromeric complexes with Tie1 and enhanced Tie1 activation [PMID:15851516]. Whether Tie1 responds to Ang4 alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells and transfected cells; species not reported in our evidence [PMID:15851516].","localisation_and_range":"Ligand flagged secreted [flag]; receptor localisation not reported in our evidence.","caveats":"Abstract-only evidence, and it shows phosphorylation, not binding. A BioGRID reconstituted-complex record cites another paper [DB:BioGRID]; no binding data from it are shown in this dossier. Two further papers were judged abstract_insufficient.","key_references":[{"PMID":"15851516","why":"Ang4 induces Tie1 phosphorylation, amplified by Tie2"}],"covers":["LR000059","LR003609"]},"LR005432":{"pair":"ANGPTL4 -> CDH11","headline":"ANGPTL4 binds cadherin-11 on fibroblasts and suppresses scar collagen via a beta-catenin-ID3 pathway; one full-text paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 bound cadherin-11, releasing membrane-bound beta-catenin, which entered the nucleus and upregulated ID3; ID3 interacts with scleraxis to inhibit COL1A2 and COL3A1 production [PMID:28740178]. This is an inhibitory effect on collagen expression, not receptor inhibition.","molecular_requirements":"The C-terminal fibrinogen-like fragment (cANGPTL4) is the form studied; Reactome lists ANGPTL4(164-406) in complexes with CDH11, CTNND1 and CTNNB1 [DB:Reactome] [PMID:28740178].","affinity_potency":[],"species_and_systems":"Human fibroblasts for mechanism; mouse (diabetic and ANGPTL4-knockout) and rat wounds; interaction also shown in human scar tissue [PMID:28740178].","localisation_and_range":"ANGPTL4 is described as a matricellular protein [PMID:28740178]; ligand flagged secreted [flag]. Receptor is cadherin-11, a membrane protein by the paper's description (cytoplasmic domain) [PMID:28740178].","caveats":"One paper; the assay used to show binding is not given in the excerpts. No affinity reported. Reactome also lists a membrane-bound CDH11 splice variant lacking the cytoplasmic domain [DB:Reactome].","key_references":[{"PMID":"28740178","why":"ANGPTL4 binds cadherin-11 and suppresses collagen in fibroblasts"}],"covers":["LR002110","LR005432"]},"LR003614":{"pair":"ANXA1 -> FPR2","headline":"Direct binding and agonism of FPR2 by ANXA1, with full-length protein FPR2-selective; several supporting papers read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"ANXA1 acts as an agonist of FPR2 (FPRL1/ALX). Full-length ANXA1 bound FPRL-1/ALX only (not FPR) in transfected HEK-293 cells and caused ERK activation only in FPRL-1/ALX-transfected cells; blocking FPRL-1/ALX with a neutralising antibody abolished its effect on neutrophil adhesion under flow [PMID:16278303]. Chimeric-receptor work places the FPR2/ALX N-terminal region and extracellular loop II as the domain needed for AnxA1 signalling [PMID:22610094]. GtoPdb lists the interaction as full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain, no co-receptor reported in our evidence. The N-terminal peptide Ac2-26 is less selective: it bound and activated both FPR and FPRL-1/ALX [PMID:16278303], and an annexin 1 N-terminal peptide activated all three FPR family members at similar concentrations [PMID:15187149]. The pKd value below came from ANXA1-derived peptides, not intact ANXA1 [PMID:12368905].","affinity_potency":[{"value":"pKd 6.5","assay":"radioligand binding, ANXA1-derived peptide (curator note: not intact ANXA1)","system":"recombinant human ALXR/FPRL1","cite":"PMID:12368905"}],"species_and_systems":"Human receptor and human cells throughout: transfected HEK-293 cells, human neutrophils [PMID:16278303, PMID:22610094, PMID:12368905]. The mouse pair is projected from human evidence (ortholog inferred), not tested here.","localisation_and_range":"ANXA1 is flagged as secreted and FPR2 as transmembrane [flag]; this suggests paracrine signalling to cell-surface FPR2.","caveats":"Four papers were shown and all were read as abstracts (plus excerpts); three further judged papers were abstract-insufficient. FPR2 is also bound by a lipid mediator (aspirin-triggered lipoxin A4), so it is not peptide-exclusive [PMID:12368905]. Peptide fragments and intact ANXA1 differ in receptor selectivity, so peptide data should not be assigned to full-length ANXA1.","key_references":[{"PMID":"16278303","why":"Full-length ANXA1 binds FPR2 but not FPR; peptide Ac2-26 binds both."},{"PMID":"12368905","why":"Radioligand binding with ANXA1-derived peptides on recombinant ALXR."},{"PMID":"22610094","why":"Chimeras map the FPR2 domains needed for AnxA1 signalling."}],"covers":["LR000064","LR003614"]},"LR012128":{"pair":"APCDD1 -> FZD1:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD1 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD1 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD1 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD1. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012128"]},"LR012164":{"pair":"APCDD1 -> FZD9:LRP5","headline":"APCDD1 binds LRP5 (not shown for the Frizzled chain) and inhibits Wnt signalling; evidence is one paper, so the FZD9 complex is inferred.","interaction_type":"direct binding","direction_and_effect":"APCDD1 acts as an inhibitor of Wnt/beta-catenin signalling: it reduced WNT3A-induced TOP/FOP reporter activity ~2-fold, including with LRP5/Fzd2, in HEK293T cells, and reduced Wnt activity in chick neural tube and Xenopus embryos [PMID:20393562]. The authors suggest it may prevent formation of the Wnt receptor complex [PMID:20393562].","molecular_requirements":"The extracellular domain of APCDD1 co-precipitated with tagged LRP5 and WNT3A [PMID:20393562]. No FZD9 binding was tested in this paper; the paper reports no interaction with Fzd2, Fzd8 and Dkk4 (data not shown) [PMID:20393562]. So the LRP5 chain carries the evidence and the Frizzled chain of this complex is not supported by it. FZD9 is not mentioned in the excerpts.","affinity_potency":[],"species_and_systems":"Human APCDD1 and LRP5 constructs, recombinant tagged proteins in HEK293T cells (GST pulldown / co-precipitation); functional tests in HEK293T, chick neural tube and Xenopus embryos [PMID:20393562]. Human pair only.","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein; its extracellular domain was used for binding [PMID:20393562]. Acts at the cell surface, likely cell-autonomously [PMID:20393562].","caveats":"Single paper, interaction shown in vitro only [PMID:20393562]. Binding was to LRP5 and WNT3A, not to the full receptor complex. Our record is listed as the combined complex; IntAct and UniProt entries cite the same paper [DB:IntAct] [DB:UniProt].","key_references":[{"PMID":"20393562","why":"Shows APCDD1 co-precipitates LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012164"]},"LR002129":{"pair":"APLP1 -> CNTN3","headline":"APLP1 binds CNTN3 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN3; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. CNTN3 is among the three that bind APLP1; APLP2 does not bind CNTN3 [PMID:34958801]. APLP1 appeared to bind CNTN4 more strongly than CNTN3 [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002129","LR005446"]},"LR005450":{"pair":"APLP2 -> CNTN5","headline":"APLP2 binds CNTN5 in one paper by binding assays and biolayer interferometry; affinity is weak.","interaction_type":"direct binding","direction_and_effect":"APLP2 association with CNTN5 was detected in extracellular binding assays and confirmed by biolayer interferometry; APLP2 binds CNTN4 and CNTN5 but not CNTN3 [PMID:34958801]. Signalling effect is not reported in our evidence.","molecular_requirements":"The conserved interface involves the second fibronectin type III repeat of CNTNs and the copper-binding domain of amyloid proteins, shown for five CNTN-amyloid pairs; a CNTN5-APLP2 structure is not listed [PMID:34958801].","affinity_potency":[{"value":"38 \u03bcM","assay":"biolayer interferometry (approximate, as written)","system":"CNTN5 with APLP2","cite":"PMID:34958801"}],"species_and_systems":"Human and mouse proteins and zebrafish proteins were used; the species of the CNTN5-APLP2 measurement is not stated in the excerpt [PMID:34958801]. Mouse pair is ortholog-inferred.","localisation_and_range":"APLP2 carries transmembrane and secreted flags [flag]; CNTNs are GPI-anchored [PMID:34958801], suggesting contact signalling.","caveats":"Affinity is weaker than for CNTN5-APP [PMID:34958801]. Single paper.","key_references":[{"PMID":"34958801","why":"Binding, BLI affinity and conserved interface"}],"covers":["LR002133","LR005450"]},"LR002138":{"pair":"APOA1 -> TREM2","headline":"Bio-layer interferometry shows APOA1 binding TREM2-Fc in one paper; UniProt repeats the claim.","interaction_type":"direct binding","direction_and_effect":"APOA1 showed robust binding to TREM2-Fc by bio-layer interferometry, not to control Fc proteins [PMID:27477018]. UniProt states TREM2 acts as a receptor for apolipoproteins including APOA1 and enhances their uptake in microglia [DB:UniProt].","molecular_requirements":"Not reported in our evidence; TYROBP involvement is not tested here (see the TREM2:TYROBP dossier).","affinity_potency":[],"species_and_systems":"TREM2-Fc fusion protein; species of the proteins is not reported in the curated record. The same paper reports uptake of LDL, CLU and APOE, not APOA1, by TREM2-expressing cells [PMID:27477018].","localisation_and_range":"TREM2 is flagged secreted and receptor [flag].","caveats":"The evidence sentence was browser-read and its spot-check is pending. The functional uptake data in the abstract do not name APOA1 [PMID:27477018].","key_references":[{"PMID":"27477018","why":"BLI binding of apolipoproteins and LDL to TREM2-Fc"}],"covers":["LR002138","LR005455"]},"LR005045":{"pair":"APOB -> ENO1","headline":"One abstract-level paper shows apoB binding surface ENO1 with higher affinity than plasminogen and driving inflammation.","interaction_type":"direct binding","direction_and_effect":"ApoB from RA synovial fluid was identified as a ligand of ENO1 with higher affinity than plasminogen; binding on monocytes elicited TNF-alpha, IL-1beta and IL-6 via p38 MAPK and NF-kB, and apoB worsened K/BxN serum-transfer arthritis [PMID:29997113].","molecular_requirements":"Not reported in our evidence beyond ENO1 itself.","affinity_potency":[],"species_and_systems":"Human synovial fluid and peripheral blood mononuclear cells, and mouse arthritis; LDLR-knockout mice showed arthritis severity comparable with wild type [PMID:29997113]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted; ENO1 is expressed on the surface of immune cells, more in RA patients [PMID:29997113].","caveats":"Binding was shown by ligand blotting, binding assay and surface plasmon resonance, but no value is given in the abstract. Abstract only; single paper.","key_references":[{"PMID":"29997113","why":"ApoB-ENO1 binding and pro-inflammatory effect in arthritis"}],"covers":["LR001658","LR005045"]},"LR000068":{"pair":"APOB -> LRP2","headline":"One abstract shows a truncated apoB lipoprotein binds megalin (LRP2) but not the LDL receptor.","interaction_type":"direct binding","direction_and_effect":"On ligand blotting of renal cortical membranes, the lipoprotein containing apo B-70.5 bound only to megalin, and megalin mediated its endocytosis in F9 cells [PMID:10330424].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human lipoprotein with rabbit kidney membranes and rabbits in vivo; F9 cells for endocytosis [PMID:10330424]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted; megalin carries a receptor flag [flag]. Renal proximal tubular cells removed the particle [PMID:10330424].","caveats":"The ligand tested is truncated apoB-70.5, not full-length apoB-100; the abstract suggests apoB sites recognised by LDLR and megalin may differ [PMID:10330424]. Abstract only.","key_references":[{"PMID":"10330424","why":"Ligand blotting shows apo B-70.5 binds megalin"}],"covers":["LR000068","LR003617"]},"LR002147":{"pair":"APOE -> LILRB4","headline":"Full-text evidence of APOE binding LILRB4 (Kd 210 nM) and activating its inhibitory signalling in leukaemia cells.","interaction_type":"direct binding","direction_and_effect":"APOE specifically activated LILRB4 reporter cells; wild-type but not APOE-null mouse serum activated the reporter, and lilrb4 knockout reduced APOE binding to THP-1 cells [PMID:30333625]. Signalling is inhibitory (immunosuppressive): APOE-LILRB4 suppressed T cell proliferation in AML co-culture [PMID:30333625].","molecular_requirements":"APOE N-terminal domain, and LILRB4 residues P35, W106 (first Ig-domain) and Y121 (linker) are critical for activation [PMID:30333625].","affinity_potency":[{"value":"Kd 210 nM","assay":"microscale thermophoresis, recombinant APOE-LILRB4","system":"in vitro","cite":"PMID:30333625"}],"species_and_systems":"Human AML cells and THP-1, mouse models and mouse serum; APOE also activated mouse PirB reporters [PMID:30333625].","localisation_and_range":"APOE flagged secreted, LILRB4 flagged transmembrane receptor [flag]; serum APOE acts as soluble ligand.","caveats":"Single paper. Binding was also confirmed by SPR and Octet per the excerpts [PMID:30333625]. Curation label functional_in_vitro understates the binding data.","key_references":[{"PMID":"30333625","why":"APOE identified as LILRB4 ligand; MST Kd; T cell suppression"}],"covers":["LR002147"]},"LR003623":{"pair":"APOE -> LRP2","headline":"Thin: only an in vivo infusion study and a BioGRID reconstituted-complex record; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Infusing recombinant apoE3 into apoE-deficient and RAP-deficient mice had differential neurotrophic effects correlated with LRP and LDL-R levels [PMID:11421580]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant apoE3 in mice [PMID:11421580]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"ApoE flagged secreted [flag].","caveats":"The curated evidence sentence is a background statement that apoE binds five receptors including megalin, not a result about LRP2; the study itself concerned LRP and LDL-R. Another confirmed paper is not shown; one review-only.","key_references":[{"PMID":"11421580","why":"in vivo apoE infusion; abstract only"}],"covers":["LR000074","LR003623"]},"LR000077":{"pair":"APOE -> SCARB1","headline":"One abstract-level cell study shows free apoE binds SR-BI and raises cholesteryl ester uptake.","interaction_type":"direct binding","direction_and_effect":"Free apoE is a ligand for SR-BI; its direct interaction increased cholesteryl ester uptake from low- and high-density lipoproteins [PMID:12138091]. ApoE associated with lipids or lipoproteins did not modulate binding or uptake [PMID:12138091].","molecular_requirements":"Free (lipid-free) apoE is the active form in this study [PMID:12138091].","affinity_potency":[],"species_and_systems":"Human adrenal NCI-H295R cells [PMID:12138091]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag].","caveats":"Abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"12138091","why":"free apoE binds SR-BI"}],"covers":["LR000077","LR003626"]},"LR002156":{"pair":"APP -> CNTN3","headline":"APP binds CNTN3 directly: the APP copper-binding domain contacts CNTN3 Fn(2) in recombinant binding assays; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"APP-AP fusion proteins bound CNTN3-Fc fusions; the CNTN3 second fibronectin domain (Fn(2)) mediates APP binding and the APP copper-binding domain (CuBD) mediates CNTN3 binding [PMID:31318883]. APP and APLP1 interact with CNTN3, whereas APLP2 did not bind CNTN3 [PMID:34958801]. Curators label the effect as agonist, but the papers show binding, not signalling output; contactins are described as forming co-receptor complexes with transmembrane proteins [PMID:34958801].","molecular_requirements":"Binding needs CNTN3 Fn(2) (the six N-terminal Ig domains were dispensable) and the APP CuBD; the APP E1 domain bound like the full ectodomain [PMID:31318883]. Structures of five contactin-amyloid pairs show a conserved Fn2-CuBD interface [PMID:34958801].","affinity_potency":[],"species_and_systems":"Recombinant ectodomain fusion proteins in vitro [PMID:31318883]. Curators record human; BLI work used mouse proteins because human APP(E1) aggregated [PMID:34958801]. Human pair is ortholog-inferred in our database.","localisation_and_range":"CNTNs are GPI-anchored and lack an intracellular region, so they are described as signalling through co-receptors [PMID:34958801]. CNTN3 is not flagged secreted [flag]; APP is flagged secreted and transmembrane [flag].","caveats":"Primary 2022 paper was read as abstract plus excerpts. No CNTN3-specific affinity is given in our evidence. Earlier Fc/AP-based assays reported 17-35 nM for APP/APLP1 with CNTN3-5, while BLI gave much weaker values, attributed by the authors to oligomeric state [PMID:34958801]. IntAct lists a pull-down [DB:IntAct].","key_references":[{"PMID":"31318883","why":"Maps the binding interface (CNTN3 Fn(2), APP CuBD)"},{"PMID":"34958801","why":"Systematic CNTN-amyloid binding and structures"}],"covers":["LR002156","LR005471"]},"LR003632":{"pair":"APP -> LRP1","headline":"Secreted, KPI-containing APP binds LRP1 and is internalised through it; shown by two older papers plus BioGRID and IntAct.","interaction_type":"direct binding","direction_and_effect":"LRP is responsible for endocytosis of secreted APP; APPs770 degradation was inhibited by the antagonist RAP and by LRP antibodies and was greatly reduced in LRP-deficient fibroblasts [PMID:7543026]. A GST-LRP cluster II fusion bound sAPP-KPI from conditioned medium, and RAP competed with this binding [PMID:12212791].","molecular_requirements":"The KPI-domain-containing form is the ligand: APPs695, which lacks KPI, is a poor LRP ligand [PMID:7543026]. The LRP cluster II region is sufficient for binding in vitro [PMID:12212791].","affinity_potency":[],"species_and_systems":"Cultured cells and LRP-deficient fibroblasts [PMID:7543026]; CHO cells (LRP-deficient L2 and LRP-expressing L3) [PMID:12212791]. Species of fibroblasts not reported in our evidence.","localisation_and_range":"Ligand is secreted APP; the receptor is an endocytic receptor, so the interaction is paracrine or autocrine clearance [PMID:7543026]. LRP1 is flagged receptor [flag].","caveats":"Both papers read as abstracts. The effect is endocytosis and degradation, not a signalling response. One further paper is pending and not shown. BioGRID (Affinity Capture-Western) and IntAct (pull down) also list the pair [DB:BioGRID][DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"7543026","why":"LRP mediates endocytosis of secreted APP"},{"PMID":"12212791","why":"LRP cluster II binds sAPP-KPI"}],"covers":["LR000083","LR003632"]},"LR002165":{"pair":"APP -> NOTCH2","headline":"One paper identified Notch2 as an APP partner by crosslinking, mass spectrometry, co-IP and colocalisation.","interaction_type":"direct binding","direction_and_effect":"Notch2 was found as an APP binding partner and confirmed by co-IP; effect and direction are not reported in our evidence [PMID:16118793].","molecular_requirements":"Full-length Notch2 was used in co-IP with APP751 [PMID:16118793].","affinity_potency":[],"species_and_systems":"Membrane-impermeable crosslinking in HEK293 cells and rat E18 neurons, co-IP in HEK293 cells, and APP/CFP-Notch2/YFP colocalisation in COS cells [PMID:16118793]. Mouse pair is ortholog-inferred.","localisation_and_range":"Colocalised on the plasma membrane, with partial intracellular colocalisation [PMID:16118793]; both flagged transmembrane [flag].","caveats":"Abstract only; no database support in the dossier.","key_references":[{"PMID":"16118793","why":"Discovery and confirmation of APP-Notch2 interaction"}],"covers":["LR002165","LR005480"]},"LR000086":{"pair":"ARTN -> GFRA3","headline":"Well supported: Artemin signals via GFRalpha3-RET, with a structure and several databases.","interaction_type":"direct binding","direction_and_effect":"Artemin is the ligand for GFRalpha3-RET [PMID:9883723]; a second paper confirmed ARTN signals through the GFRa3-RET complex and a peptide agonist, artefin, induced RET phosphorylation [PMID:30853893].","molecular_requirements":"GFRA3 forms a 2:2:2 ternary complex with ARTN and RET [DB:UniProt]; NCAM acts as an alternative receptor [PMID:30853893].","affinity_potency":[],"species_and_systems":"Recombinant human ARTN, cerebellar granule neurons [PMID:30853893]. Mouse pair is ortholog-inferred.","localisation_and_range":"ARTN flagged secreted [flag]; GFRA3 is a co-receptor [DB:UniProt].","caveats":"No affinity numbers reported. PMID 9883723 is abstract only. Structures are listed [DB:PDB 2GH0] [DB:PDB 6Q2S].","key_references":[{"PMID":"9883723","why":"Artemin identified as GFRalpha3-RET ligand"},{"PMID":"30853893","why":"ARTN signals via GFRa3-RET and NCAM"}],"covers":["LR000086","LR003635"]},"LR000095":{"pair":"AVP -> AVPR1B","headline":"Direct, high-affinity agonist binding of vasopressin to the V1b (V3) receptor in human recombinant systems; coupling to Ca2+ and phospholipase C shown.","interaction_type":"direct binding","direction_and_effect":"AVP acts as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP evoked a calcium-dependent chloride current in receptor-transfected Xenopus oocytes [PMID:7929452], concentration-dependent [Ca2+]i increases [PMID:9459574], and phospholipase C stimulation in CHO-V3 cells, partially pertussis toxin-sensitive [PMID:9322919]. Native vasopressin stimulated ACTH secretion in rat anterior pituitary [PMID:12446593].","molecular_requirements":"Single-chain GPCR; no co-receptor reported. Potency of PLC stimulation was proportional to receptor density, and cAMP coupling appeared only at high density [PMID:9322919].","affinity_potency":[{"value":"Kd 0.17 nM","assay":"AVP binding, single site","system":"COS-1 cells expressing human V1b","cite":"PMID:7929452"},{"value":"Ki 0.8 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Kd 0.28 nM","assay":"[3H]AVP saturation binding","system":"COS-1 cells expressing human V1B","cite":"PMID:9459574"},{"value":"Kd 0.25 nM","assay":"[3H]AVP saturation binding","system":"CHO cells expressing hV1B","cite":"PMID:9884074"}],"species_and_systems":"Human receptor in COS-1, CHO and HeLa cells and Xenopus oocytes; rat pituitary and bovine chromaffin cells for native function [PMID:12446593]. Expression was restricted to pituitary by Northern blot [PMID:7929452]. No mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V1b as transmembrane [flag]; pituitary expression suggests endocrine action [PMID:7929452].","caveats":"Abstract-only reading for all papers. Some rows only use V1b as comparator [PMID:16158071][PMID:15084136], and one shows a V2 antagonist does not bind V1b [PMID:9864265]. 3 papers were abstract_insufficient.","key_references":[{"PMID":"7929452","why":"Cloning of human V1b; Kd 0.17 nM and oocyte response"},{"PMID":"9322919","why":"CHO-V3 cells: PLC, arachidonic acid, density-dependent signalling"},{"PMID":"9884074","why":"Kd of AVP at three human receptor subtypes"}],"covers":["LR000095","LR003644"]},"LR009500":{"pair":"B2M -> CD3D","headline":"B2M and CD3D co-occur only as chains in TCR-CD3 and peptide-MHC cryo-EM structures; no direct contact is shown in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. PDB entries are TCR-CD3 engaging peptide-MHC I [DB:PDB 7PHR] and a TCR-CD3 with HLA-A2 MAGEA4 peptide [DB:PDB 8ES8].","molecular_requirements":"Structures contain a B2M chain and a CD3D chain within a larger assembly (6 PDB records) [DB:PDB 7PHR]; whether B2M contacts CD3D is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB only (6 records)). The judged row was classified review_only.","key_references":[],"covers":["LR009500"]},"LR012362":{"pair":"BAMBI -> FZD10:LRP6","headline":"BAMBI-LRP6 has an IntAct co-IP record; FZD10 involvement and effect are not verified.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as Stimulatory [flag]; no paper in our evidence confirms this. IntAct lists O75581-Q13145 by anti tag coimmunoprecipitation [DB:IntAct O75581-Q13145].","molecular_requirements":"Complex members are FZD10 and LRP6; the IntAct record involves two proteins only, not both complex members, so subunit requirements are not reported in our evidence [DB:IntAct O75581-Q13145].","affinity_potency":[],"species_and_systems":"Human pair; experimental species of the record not given in our evidence.","localisation_and_range":"Receptor complex has no secretion flag; LRP6 is flagged transmembrane [flag].","caveats":"Both judged rows were abstract_insufficient; support is one co-IP database record.","key_references":[],"covers":["LR012362"]},"LR012146":{"pair":"BAMBI -> FZD5:LRP5","headline":"Database-asserted only: one IntAct co-IP record; the curated paper concerns LRP6, not LRP5.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward FZD5:LRP5 [flag]. Support is one IntAct anti bait coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper exists for this pair; two judged papers were marked as concerning a different entity and one abstract as insufficient.","molecular_requirements":"Complex FZD5:LRP5 is annotated; LRP5 carries a transmembrane flag [flag]. Which subunit the IntAct record covers is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. Co-IP; cell system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"Database support only. Papers judged for this pair were marked 'different_entity', suggesting the literature concerns another partner (LRP6) rather than LRP5.","key_references":[],"covers":["LR012146"]},"LR003650":{"pair":"BDNF -> NTRK2","headline":"BDNF binds and activates TrkB (NTRK2); supported by binding-domain mapping, a functional synaptic study and several databases.","interaction_type":"direct binding","direction_and_effect":"BDNF is an agonist of NTRK2. Binding domains: two regions of the TrkB extracellular domain each bind BDNF independently [PMID:9312147]. BDNF rapidly enhances synaptic transmission in cultured hippocampal neurons, and the postsynaptic amplitude increase is blocked by the Trk inhibitor K-252a [PMID:7644540]. NT-4/5 is a preferred TrkB ligand, and BDNF is a preferred ligand for TrkB [PMID:7679912]. Reactome lists phosphorylated BDNF:NTRK2 homodimer complexes [DB:Reactome]. UniProt: BDNF binds NTRK2 [DB:UniProt].","molecular_requirements":"Residues 103-181 (third leucine-rich motif and second cysteine cluster) and the region near the second Ig-like domain (residues 342-394) each bind BDNF; Phe347, Asp354 and Tyr361 are involved [PMID:9312147]. Reactome shows homodimer complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human TrkB extracellular domain expressed in CHO cells [PMID:9312147]; cultured hippocampal neurons [PMID:7644540]; neuronal and nonneuronal cells expressing defined Trk receptors [PMID:7679912]. All read as abstracts only.","localisation_and_range":"BDNF has a secreted flag; NTRK2 has a transmembrane flag [flag].","caveats":"All three papers are abstract-only. No affinity values are given in the dossier. The 1995 paper reports a TrkB inhibitor effect, indirect evidence for the receptor.","key_references":[{"PMID":"9312147","why":"maps two BDNF-binding domains in human TrkB extracellular domain"},{"PMID":"7679912","why":"neurotrophin-Trk specificities; BDNF preferred TrkB ligand"},{"PMID":"7644540","why":"BDNF acute synaptic effect blocked by TrkB inhibitor K-252a"}],"covers":["LR000101","LR003650"]},"LR002174":{"pair":"BGLAP -> GPRC6A","headline":"One binding study with SHBG competition suggests osteocalcin acts at human GPRC6A; the evidence sentence concerns SHBG.","interaction_type":"direct binding","direction_and_effect":"Undercarboxylated osteocalcin (ucOC) displaced unliganded SHBG bound to GPRC6A-transfected HEK-293 membranes at 100-fold molar excess, and ucOC-induced Erk1/2 phosphorylation via GPRC6A was blunted by excess SHBG [PMID:27673554]. Mutation constructs support a common binding site [PMID:27673554]. UniProt: GPRC6A is a receptor activated by multiple ligands, including osteocalcin [DB:UniProt].","molecular_requirements":"ucOC form studied; GPRC6A mutation constructs indicate a shared binding site with SHBG [PMID:27673554].","affinity_potency":[],"species_and_systems":"Human GPRC6A in HEK-293 cells [PMID:27673554]; abstract-only read.","localisation_and_range":"Osteocalcin has a secreted flag [flag]; GPRC6A localisation not reported in our evidence.","caveats":"OCN binding is shown indirectly by competition and ERK signalling; the paper focuses on SHBG. Only the undercarboxylated form is described. No affinity values reported. Abstract-only.","key_references":[{"PMID":"27673554","why":"ucOC competes with SHBG at human GPRC6A"}],"covers":["LR002174"]},"LR007106":{"pair":"BMP10 -> ACVR2A:ACVRL1","headline":"Conflicting: the type II chain ACVR2A is supported, but one paper tested ALK1 (ACVRL1) with BMP10 and found no signalling.","interaction_type":"conflicting","direction_and_effect":"BMP10 is annotated as stimulatory (agonist in GtoPdb) [DB:GtoPdb]. A paper titled on BMP9/BMP10 as ALK1 activators calls BMP10 'also a potent ALK1 ligand' [PMID:17068149]. A receptor-screen paper found only ALK3 or ALK6 conferred BMP10 signalling in COS7 cells, so ALK1 was tested negative, while shRNA for BMPRII and ActRIIA suppressed BMP10 signalling in MC3T3 cells [PMID:16049014].","molecular_requirements":"Type II chain ACVR2A has functional support; the ACVRL1 type I chain is the disputed part. BioGRID lists an ACVR2A-BMP10 reconstituted complex [DB:BioGRID]. Whether both chains are needed together is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both papers were read as abstracts only; cells are described as microvascular endothelial cells [PMID:17068149] and COS7/MC3T3 lines [PMID:16049014]. Curators annotate human ligand and receptor.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"The two papers disagree on BMP10-ALK1 and the conflict is unresolved; the positive claim in the endothelial paper is mainly about BMP9 in its abstract body. No binding data for the assembled complex in our evidence.","key_references":[{"PMID":"17068149","why":"BMP10 described as an ALK1 ligand in endothelial cells"},{"PMID":"16049014","why":"Receptor screen: ALK3/ALK6 sufficient, ALK1 negative; BMPRII/ActRIIA shRNA suppresses BMP10 signalling"}],"covers":["LR007106"]},"LR007115":{"pair":"BMP2 -> BMPR1B:BMPR2","headline":"Complex-level evidence is thin: BMP2 binding to BMPR1B and to BMPR2 is shown separately, but not to the BMPR1B:BMPR2 pairing; one study found BMPR1B not significant.","interaction_type":"conflicting","direction_and_effect":"BMP2 binds BMPR-IB (CFK-43a), cloned as a receptor that specifically binds BMP-2 and BMP-4 [PMID:7811286], and binds BMPR-II or ActR-II via a low-affinity epitope [PMID:10880444]. GtoPdb lists agonist records for BMP2-BMPR1B and BMP2-BMPR2 [DB:GtoPdb].","molecular_requirements":"Our evidence does not show a BMPR1B:BMPR2 complex itself engaging BMP-2. The mutational study concerns BMPR-IA and BMPR-II/ActR-II [PMID:10880444].","affinity_potency":[],"species_and_systems":"Receptor ectodomain and cloning/binding assays, species not reported [PMID:10880444][PMID:7811286]. A negative knockdown study used primary human mesenchymal stem cells [PMID:18436533].","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BMP2 is flagged secreted [flag].","caveats":"A verified negative in human mesenchymal stem cells reports BMPR1B was expressed at low levels and not found to play a significant role in BMP signalling, with BMPR1A and BMPR2 used instead [PMID:18436533]. Both confirming papers were abstract-only and neither tests the combined BMPR1B:BMPR2 complex.","key_references":[{"PMID":"7811286","why":"cloning of BMPR-IB, binds BMP-2"},{"PMID":"10880444","why":"BMP-2 epitopes for type I and type II receptors"},{"PMID":"18436533","why":"negative: BMPR1B not significant in hMSC"}],"covers":["LR007115"]},"LR001661":{"pair":"BMP2 -> RGMB","headline":"RGMB (DRAGON) binds BMP2 directly and enhances BMP signalling; strongly supported, with structures.","interaction_type":"direct binding","direction_and_effect":"DRAGON binds directly to BMP2 but not to BMP7 or other TGFbeta ligands; its enhancing action on BMP signalling is reduced by Noggin and by dominant-negative Smad1 or ALK3/6 [PMID:15671031].","molecular_requirements":"DRAGON also associates directly with BMP type I receptors (ALK2, ALK3, ALK6) and type II receptors (ActRII, ActRIIB) [PMID:15671031].","affinity_potency":[{"value":"Kd 5.5 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"Xenopus embryos showed DRAGON lowers the threshold for Smad1-induced marker induction [PMID:15671031]; SPR in another study [PMID:23029472]. PDB 4UHZ, 4UI0, 4UI2 hold structures with BMP2 and RGMB chains [DB:PDB 4UHZ].","localisation_and_range":"DRAGON is GPI-anchored per the paper [PMID:15671031]; the entity flag marks RGMB not secreted [flag]. Membrane-bound co-receptor.","caveats":"Both papers were abstract-only reads. The Kd is from the curator's assay note.","key_references":[{"PMID":"15671031","why":"DRAGON binds BMP2 directly, enhances BMP signalling"},{"PMID":"23029472","why":"SPR affinities of RGMs for BMPs"}],"covers":["LR001661","LR005047"]},"LR007124":{"pair":"BMP5 -> ACVR1:BMPR2","headline":"BMP5 to ACVR1:BMPR2 rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with BMPR2 (a type II receptor) with type I receptor BMPR1A, not ACVR1 [DB:UniProt][PMID:11580864].","molecular_requirements":"Chains in the complex: ACVR1 and BMPR2; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 4 review_only. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007124"]},"LR002183":{"pair":"BMP5 -> RGMB","headline":"BMP5 binds RGMB in SPR with Kd 33 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"RGMB is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. RGMB bound BMP5 less tightly than HJV (17 nM) [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 33 nM","assay":"SPR","system":"RGMB vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. RGMB is flagged not secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR002183","LR005497"]},"LR007133":{"pair":"BMP6 -> ACVR1:BMPR2","headline":"BMP6 to ACVR1:BMPR2 is supported only by database records (BioGRID, GtoPdb, UniProt), with no verified paper row.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP6 as agonist (Stimulatory) at each chain [DB:GtoPdb]. UniProt says BMP6 associates with type I receptor ACVR1 and type II receptor ACVR2B [DB:UniProt][PMID:18070108]. BioGRID has an affinity-capture-Western record of BMPR2-BMP6 from the 1999 paper [DB:BioGRID][PMID:10504300].","molecular_requirements":"Complex of ACVR1 and BMPR2; whether both chains are needed is not reported in our evidence. The database rows are per chain, not for this assembled complex.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond the database annotations; the pair is annotated human.","localisation_and_range":"BMP6 is flagged secreted and the complex flagged transmembrane [flag].","caveats":"Five screened papers were review_only; none is a verified primary result for this complex. UniProt names ACVR2B, not BMPR2, as the type II partner.","key_references":[],"covers":["LR007133"]},"LR007142":{"pair":"BMP7 -> ACVR1:BMPR2","headline":"BMP7 (OP-1) binds ALK-2 in one 1994 abstract-level paper, but the type II chain used was not BMPR2.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP-7) bound ALK-2 efficiently in transfected COS cells and several non-transfected lines [PMID:8006002]. GtoPdb lists BMP7 as agonist at ACVR1 and BMPR2 [DB:GtoPdb]. UniProt notes BMP7 can use BMPR2 as type II receptor for specific functions [DB:UniProt].","molecular_requirements":"Binding was enhanced by co-transfected type II receptor, but the curator notes this was DAF-4 from C. elegans, not human BMPR2, so BMPR2 is not directly evidenced there [PMID:8006002]. BioGRID has BMP7-BMPR2 affinity capture-western records [DB:BioGRID].","affinity_potency":[],"species_and_systems":"COS transfectants, MC3T3-E1 and human foreskin fibroblasts [PMID:8006002]; abstract only.","localisation_and_range":"BMP7 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"BMPR2 as the type II partner rests on database records, not the paper. Five review-only papers. No affinity value.","key_references":[{"PMID":"8006002","why":"BMP-7 (OP-1) binds ALK-2/ACVR1; type II chain was not BMPR2"}],"covers":["LR007142"]},"LR007151":{"pair":"BMP8A -> ACVR1:BMPR2","headline":"BMP8A -> ACVR1:BMPR2 has database records only; no paper confirmed this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at ACVR1 and at BMPR2 [DB:GtoPdb]; no paper was verified for this pair. UniProt states that BMP8A associates with type I receptor BMPR1A and type II receptor BMPR2, not ACVR1 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"ACVR1 and BMPR2 are asserted as separate agonist records, not as a combined complex. Three papers were review-only.","key_references":[],"covers":["LR007151"]},"LR001670":{"pair":"BMP8A -> TGFBR2","headline":"BMP8A -> TGFBR2 is supported only by a mouse spermatogonia signalling abstract, no database record.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). TGFBR2 was one of three type II receptors (with ACVR2A, ACVR2B) paired with ALK5 for SMAD2/3 activation [PMID:28465413].","molecular_requirements":"TGFBR2 pairs with ALK5 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"No database record. Evidence is functional and abstract-only; TGFBR2 is one of several interchangeable type II partners.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001670"]},"LR012443":{"pair":"BOC -> PTCH1:SMO","headline":"BOC is annotated as a ligand for PTCH1:SMO; one abstract-read paper links Boc and Ptch1 in Shh receptor complexes, but binding is not shown in our excerpts.","interaction_type":"functional only","direction_and_effect":"The paper reports that Boc, Cdon and Gas1 are together required for Hh-dependent proliferation of cerebellar granule neuron progenitors, with a mutated Hh ligand that binds Patched1 but not Boc, Cdon or Gas1 unable to activate signalling [PMID:21664577]. Boc is an Hh-binding co-receptor, not a ligand of Ptch1 as such; the annotation is Stimulatory.","molecular_requirements":"Reactome has a BOC:PTCH1 complex at the ciliary membrane [DB:Reactome]. SMO as a partner is not addressed in the excerpts. Boc loss only partly reduces proliferation, and Cdon loss adds nothing further [PMID:21664577].","affinity_potency":[],"species_and_systems":"Cerebellar granule neuron progenitors and mouse cerebella (knockouts); species wording is from the full-text excerpts [PMID:21664577].","localisation_and_range":"Both BOC and PTCH1 are flagged as receptors [flag]; contact-mediated range is implied but not stated in our evidence.","caveats":"The curator's evidence sentence is the paper title; the abstract does not show BOC-PTCH1 binding. The paper reports vertebrate cells still respond to Shh without Boc and Cdon [PMID:21664577]. Read at abstract level plus excerpts.","key_references":[{"PMID":"21664577","why":"Boc, Cdon and Gas1 are required for Shh-driven proliferation; Reactome-linked Boc:Ptch1 complex."}],"covers":["LR012443"]},"LR005504":{"pair":"BSG -> CAV1","headline":"BSG (CD147) associates with CAV1 in human cells, but the described link is intracellular glycoform regulation, not classic ligand-receptor signalling.","interaction_type":"direct binding","direction_and_effect":"Caveolin-1 associates with low-glycoform CD147 and restricts its biosynthetic conversion to the high-glycoform that self-aggregates and induces MMP production; effect on BSG is inhibitory [PMID:15201341]. Reactome lists caveolin-1 binding basigin in the Golgi membrane [DB:Reactome].","molecular_requirements":"Only the low-glycoform BSG (LG-CD147) is reported to associate; high-glycoform is the self-aggregating, MMP-inducing form [PMID:15201341].","affinity_potency":[],"species_and_systems":"Human cells; abstract-level reading [PMID:15201341]. Ortholog-inferred mouse version.","localisation_and_range":"BSG flagged transmembrane and not secreted [flag]; the interaction concerns biosynthetic trafficking, not an extracellular range.","caveats":"Association is stated as previously shown plus a new result; abstract only; no binding assay detail or affinity [PMID:15201341]. CAV1 is an intracellular scaffold, so the pair does not fit an extracellular ligand-receptor model.","key_references":[{"PMID":"15201341","why":"Caveolin-1 associates with low-glycoform CD147 and restricts glycoform conversion."}],"covers":["LR002190","LR005504"]},"LR002192":{"pair":"BSG -> KDR","headline":"BSG (EMMPRIN) directly interacts with VEGFR-2 (KDR) as a co-receptor that enhances VEGF-driven activation, human cells, one full-text paper.","interaction_type":"direct binding","direction_and_effect":"EMMPRIN is described as a coreceptor of VEGFR-2 that regulates its VEGF-mediated activation; EMMPRIN knockdown reduced VEGF-induced VEGFR-2 phosphorylation and VEGFR-2 homodimerization, and overexpression potentiates activation [PMID:25825981]. UniProt records the same coreceptor function [DB:UniProt].","molecular_requirements":"Not a free ligand: BSG acts alongside VEGFA at KDR. Docking and mutagenesis put the binding site in the EMMPRIN extracellular domain near amino acids 195/199 [PMID:25825981]. Pull-down of recombinant EMMPRIN and VEGFR-2 in a cell-free system supports direct binding.","affinity_potency":[],"species_and_systems":"Human endothelial (HMEC) and tumour (M10, MDA-MB-231) cells, tumour xenograft and patient breast and melanoma tissue; recombinant proteins in vitro [PMID:25825981]. Ortholog-inferred mouse version.","localisation_and_range":"BSG is flagged transmembrane and not secreted [flag]; proximity ligation places the interaction at the cell surface [PMID:25825981].","caveats":"Co-receptor relationship; BSG also interacts with VEGF in this paper at lower level [PMID:25825981]. No affinity reported.","key_references":[{"PMID":"25825981","why":"Pull-down, IP, proximity ligation and knockdown showing EMMPRIN-VEGFR-2 interaction and co-receptor role."}],"covers":["LR002192","LR005506"]},"LR000149":{"pair":"BTC -> ERBB4","headline":"BTC activates ERBB4 in two functional papers; no affinity of its own, plus GtoPdb and Reactome records.","interaction_type":"functional only","direction_and_effect":"Betacellulin activates EGFR and erbB-4 and gives cellular response patterns distinct from EGF or neuregulin-beta [PMID:8570211]. In human aortic smooth muscle cells, ErbB4 and EGFR are expressed and BTC is mitogenic, suggesting EGF-family signalling [PMID:11254912]. Annotation: Stimulatory.","molecular_requirements":"ErbB4 may act with EGFR; combination requirements are not reported in our evidence. PDB 8U4J and 8U4K list BTC with an ERBB4 chain [DB:PDB 8U4J].","affinity_potency":[],"species_and_systems":"Human cells (aortic smooth muscle cells) [PMID:11254912]; cell system of 8570211 not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"BTC is flagged secreted and transmembrane; ERBB4 transmembrane [flag].","caveats":"Both verified papers are functional and read at abstract level; one is co-expression with immunohistochemistry only. GtoPdb has a pIC50 record without value shown [DB:GtoPdb]. One paper is pending.","key_references":[{"PMID":"8570211","why":"BTC activates EGFR and erbB-4."},{"PMID":"11254912","why":"BTC mitogenic with EGFR and ErbB4 on human aortic smooth muscle cells."}],"covers":["LR000149","LR003698"]},"LR005513":{"pair":"C1QA -> LRP1","headline":"C1q is reported to act through calreticulin bound to CD91 (LRP1) to stimulate apoptotic cell uptake; the link to LRP1 is likely indirect.","interaction_type":"functional only","direction_and_effect":"C1q and MBL bind apoptotic cells and stimulate ingestion via phagocyte calreticulin, which is bound to CD91; uptake proceeds by macropinocytosis [PMID:11560994].","molecular_requirements":"Calreticulin is required as an intermediary; it has no transmembrane domain and presumably needs CD91 as partner [PMID:11560994].","affinity_potency":[],"species_and_systems":"Human macrophages (HMDM) and apoptotic cells [PMID:11560994].","localisation_and_range":"C1q annotated secreted [flag].","caveats":"Two further rows were abstract_insufficient. An IntAct ELISA record exists [DB:IntAct]. Direct C1q-CD91 binding is not shown in our excerpts.","key_references":[{"PMID":"11560994","why":"C1q-calreticulin-CD91 uptake of apoptotic cells"}],"covers":["LR002199","LR005513"]},"LR005531":{"pair":"C1QL4 -> ADGRB3","headline":"C1QL4 binds the ADGRB3 (BAI3) thrombospondin-repeat domain with high affinity; one abstract-level paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins bind BAI3 and decrease synapse density in cultured neurons, prevented by the soluble BAI3 thrombospondin-repeat fragment, which binds C1ql proteins and acts as a decoy [PMID:21262840].","molecular_requirements":"Binding is to the extracellular thrombospondin-repeat domain, via the ligand's globular C1q domain [PMID:21262840].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in the abstract (curator labels human/human; both interactions ortholog-inferred). UniProt records the interaction [DB:UniProt].","localisation_and_range":"C1QL4 secreted and ADGRB3 transmembrane per flags [flag].","caveats":"Abstract only; the paper covers all four C1ql proteins collectively; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002218","LR005531"]},"LR002219":{"pair":"C1QTNF3 -> ADIPOR1","headline":"CTRP3 relaxes vessels, but the ADIPOR1 dependence was shown for CTRP9, not CTRP3; indirect, family-level support.","interaction_type":"functional only","direction_and_effect":"CTRPs 3, 5 and 9 caused concentration-dependent vasorelaxation; CTRP3 and CTRP5 were comparable to adiponectin [PMID:21836066]. ADIPOR1 knockdown blocked CTRP9-induced AMPK/Akt/eNOS phosphorylation and NO production, ADIPOR2 knockdown did not; this was not reported for CTRP3 in our evidence [PMID:21836066].","molecular_requirements":"Not reported in our evidence for CTRP3.","affinity_potency":[],"species_and_systems":"Aortic vascular rings (murine CTRPs) and human umbilical vein endothelial cells (HUVECs) [PMID:21836066]. Curator labels human/human, but the abstract states murine CTRPs were assayed.","localisation_and_range":"Secreted ligand [flag]; range not reported.","caveats":"No direct binding of CTRP3 to ADIPOR1 shown. The ADIPOR1 mechanism is for CTRP9 only. Abstract-level curation with excerpts. Mouse interaction ortholog-inferred.","key_references":[{"PMID":"21836066","why":"CTRP3/5/9 vasorelaxation; ADIPOR1 knockdown mechanism for CTRP9"}],"covers":["LR002219","LR005532"]},"LR003704":{"pair":"C3 -> C3AR1","headline":"C3a binds and activates C3aR; well supported by binding, cloning and potency data in human and mouse receptors.","interaction_type":"direct binding","direction_and_effect":"C3a is an agonist: cells expressing C3aR bound 125I-C3a and responded to human C3a with calcium mobilization [PMID:8702752]. C3a stimulated calcium mobilization in cells expressing human or mouse C3aR [PMID:9476119]. GtoPdb lists C3-C3AR1 as an agonist interaction [DB:GtoPdb].","molecular_requirements":"The active ligand is the cleavage fragment C3a, not intact C3; this is a curator caveat [PMID:20527893]. Reactome records C3AR1 binding anaphylatoxin C3a [DB:Reactome]. PDB structures contain both chains [DB:PDB 8HK2].","affinity_potency":[{"value":"EC50 0.24 nM","assay":"calcium mobilization","system":"RBL-2H3 cells expressing human C3aR","cite":"PMID:9476119"},{"value":"EC50 1.3 nM","assay":"calcium mobilization","system":"RBL-2H3 cells expressing mouse C3aR","cite":"PMID:9476119"}],"species_and_systems":"Human C3a on human C3aR (transfected cells, neutrophils); mouse receptor tested in transfected RBL-2H3 cells [PMID:9476119]. Mouse pair is ortholog-inferred.","localisation_and_range":"C3a is flagged secreted and C3AR1 transmembrane [flag]; acts on cells in the vicinity of complement activation (annotation-based).","caveats":"All papers read as abstracts only. A C3a analogue peptide was about 10-fold less active than C3a on human C3aR [PMID:9476119]. C4a did not clearly act on this receptor in that study; data were hard to interpret [PMID:9476119].","key_references":[{"PMID":"8702752","why":"Cloning of human C3aR with 125I-C3a binding"},{"PMID":"9476119","why":"Potency on human and mouse C3aR"},{"PMID":"11342658","why":"C3aR pharmacology and antagonist characterisation"}],"covers":["LR000155","LR003704"]},"LR000158":{"pair":"C3 -> ITGAM","headline":"The iC3b fragment of C3 binds ITGAM (CD11b) in CR3; supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated CR3 from human spleen membranes and leukocytes [PMID:4062888]. An anti-alphaM antibody induced adhesion of alphaMbeta2 CHO cells to iC3b [PMID:11073102]. Anti-CD11b blocked platelet-neutrophil complexes, with C3(H2O) antibody inhibiting 75-100% [PMID:26293614]. BioGRID lists affinity capture-Western [DB:BioGRID].","molecular_requirements":"CR3 is the alphaM:beta2 heterodimer; ITGAM acts with ITGB2 [PMID:4062888]. Subunit sufficiency not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: spleen membranes [PMID:4062888], transfected CHO cells [PMID:11073102], platelets and PMN [PMID:26293614]. Mouse pair is ortholog-inferred.","localisation_and_range":"ITGAM is a cell-surface integrin; contact-dependent (annotation flag [flag]).","caveats":"All three papers abstract only. Ligand is iC3b or C3(H2O), not intact C3. Paper 11073102 concerns an activating antibody.","key_references":[{"PMID":"4062888","why":"iC3b affinity chromatography isolating CR3"},{"PMID":"26293614","why":"C3(H2O) and CD11b in platelet-PMN tethering"}],"covers":["LR000158","LR003707"]},"LR000167":{"pair":"C4B -> CR1","headline":"CR1 binds C4b by SPR in one 1999 abstract, with Reactome and UniProt support.","interaction_type":"direct binding","direction_and_effect":"Immobilized CR1 bound C4b, C1q and C3b as independent events by BIAcore, and C1q and C4b additively supported erythrocyte adhesion [PMID:10528211]. Reactome lists CR1:C4b complex [DB:Reactome].","molecular_requirements":"C4b, C1q and C3b bind independently; one C1q site on LHR-D of CR1 is proposed. UniProt notes interaction via Sushi 1 and Sushi 2 domains for a related entry [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins and human erythrocytes; BIAcore SPR and tip-plate adhesion assay [PMID:10528211].","localisation_and_range":"CR1 is flagged as receptor only; no secreted/transmembrane flag for CR1 in our evidence [flag]. Adhesion assays indicate cell-surface presentation.","caveats":"Abstract only; no affinity reported in our evidence. Ligand is activated C4b.","key_references":[{"PMID":"10528211","why":"BIAcore SPR of C4b binding to CR1"}],"covers":["LR000167"]},"LR005054":{"pair":"CADM1 -> CADM1","headline":"CADM1 binds itself (trans-homophilic) and this drives adhesion and PI3K signalling; several papers, mostly abstract-level.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc interacted with CADM1 by SPR imaging [PMID:30131958]. Trans-homophilic CADM1 interaction induced cell spreading through PI3K, Akt and Rac1, via MPP3 and Dlg bridging to p85 [PMID:25268382]. Homophilic binding between nerve and mast cells promoted mast cell degranulation after nerve stimulation [PMID:17250899].","molecular_requirements":"Homophilic dimer; intracellular MAGuK proteins MPP3 and Dlg connect CADM1 to PI3K p85 [PMID:25268382]. UniProt notes the CRTAM interaction competes with CADM1 homodimerization [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human recombinant proteins (SPR), MDCK cells expressing CADM1 [PMID:24503895]; mouse nerve-mast cell work [PMID:17250899] (curated as human species). Reactome and IntAct list homodimer records [DB:Reactome] [DB:IntAct].","localisation_and_range":"Transmembrane, not secreted [flag]; acts by trans-homophilic cell-cell contact (juxtacrine) [PMID:24503895].","caveats":"Self-interaction pair, so direction is not meaningful. Eight papers confirmed, only some shown; one pending. One paper reports CADM1 binding nectin-3 heterophilically instead [PMID:22703826].","key_references":[{"PMID":"30131958","why":"SPR imaging of CADM1 interactions"},{"PMID":"24503895","why":"Trans-homophilic CADM1 activates PI3K"},{"PMID":"17250899","why":"Homophilic nerve-mast cell adhesion in vivo"}],"covers":["LR001678","LR005054"]},"LR002228":{"pair":"CADM2 -> CADM1","headline":"Direct CADM2-CADM1 binding in SPR with Kd 86.8 nM; one primary paper plus Reactome homodimer entries.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc interacted with CADM2 in SPRi [PMID:30131958]. No signalling effect reported.","molecular_requirements":"Whole ectodomain Fc fusions; no extra subunit reported [PMID:30131958].","affinity_potency":[{"value":"Kd 86.8 nM","assay":"SPRi, CADM1-Fc analyte with CADM2-Fc","system":"purified Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound, not secreted [flag]; contact-dependent adhesion is the likely mode but this paper's evidence here is binding only.","caveats":"Single paper. Reactome entries listed concern Necl homodimerisation, not this heterodimer [DB:Reactome].","key_references":[{"PMID":"30131958","why":"SPRi showing CADM1-CADM2 binding and Kd"}],"covers":["LR002228","LR005538"]},"LR005540":{"pair":"CADM2 -> CADM3","headline":"Direct CADM2-CADM3 heterophilic binding detected by SPRi in one paper.","interaction_type":"direct binding","direction_and_effect":"SPRi detected heterophilic interactions of CADM2 and CADM3 with all CADM family proteins [PMID:30131958]. No effect direction reported.","molecular_requirements":"Whole ectodomain Fc fusions; no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag]; Reactome has Necl homodimer entries only [DB:Reactome].","caveats":"One paper. The curated sentence concerns CADM1 as analyte, so this pair rests on the general statement; no Kd for CADM2-CADM3 is reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family including CADM2-CADM3"}],"covers":["LR002230","LR005540"]},"LR002237":{"pair":"CADM4 -> CADM4","headline":"CADM4 homophilic binding is reported by SPRi in one family-wide screen; no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM4 with all CADM family proteins [PMID:30131958]. The same molecule acts as ligand and receptor; no effect direction is reported.","molecular_requirements":"SPRi detects only direct interactions between two molecules [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Flagged transmembrane [flag]; cell-cell adhesion is described for the family [PMID:30131958].","caveats":"Single paper. The curator's evidence sentence concerns CADM1-CADM4, not CADM4 self-binding; the self-binding support is the family-wide SPRi statement in the full text [PMID:30131958]. No Kd for CADM4-CADM4 in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002237","LR005547"]},"LR007160":{"pair":"CALCA -> CALCRL:RAMP1","headline":"Alpha-CGRP acts on the CALCRL:RAMP1 complex, the defining CGRP receptor; one curated paper, abstract-only, plus databases.","interaction_type":"functional only","direction_and_effect":"RAMP1 presents CRLR at the cell surface as a mature glycoprotein and a CGRP receptor [PMID:9620797]. GtoPdb records CALCA as a full agonist [DB:GtoPdb]. UniProt says RAMP1 with CALCRL forms the receptor complex for CGRP1/CALCA [DB:UniProt].","molecular_requirements":"Both CALCRL and RAMP1 are required; UniProt states RAMP1 interaction alters CGRP1/CALCA ligand specificity [DB:UniProt]. With CALCR instead, RAMP1 forms AMYR1, which also responds to CGRP1/CALCA [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:9620797]; no mouse pair.","localisation_and_range":"CALCA flagged secreted; complex flagged receptor and transmembrane [flag].","caveats":"Only one paper, read as abstract; a second row was review-only. GtoPdb pKi values of 6.5-6.8 belong to the CALCA-CALCRL records [DB:GtoPdb].","key_references":[{"PMID":"9620797","why":"Defines RAMP1/CRLR as the CGRP receptor"}],"covers":["LR007160"]},"LR000176":{"pair":"CALCB -> RAMP1","headline":"beta-CGRP acts at CALCRL/RAMP1 receptors; RAMP1 is a subunit, with one functional paper and database records.","interaction_type":"functional only","direction_and_effect":"CALCRL predominantly associates with RAMP1 to form a CALCB receptor in rat uterine artery smooth muscle cells; CALCB reversed TNF-alpha-induced loss of CALCRL/RAMP1 association via ERK1/2 [PMID:27784654]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Receptor is the CALCRL:RAMP1 heterodimer [PMID:27784654][DB:UniProt]; RAMP1 alone is not shown to bind CALCB.","affinity_potency":[{"value":"pKi 9.9 to 11.0","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat uterine artery smooth muscle cells, proximity ligation assay [PMID:27784654]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Only one confirmed paper, read as abstract with full-text excerpts; it concerns CALCRL/RAMP1 association, not CALCB binding to RAMP1. Curator table lists human, but the cells were rat.","key_references":[{"PMID":"27784654","why":"CALCB engages the CALCRL/RAMP1 receptor in rat cells"}],"covers":["LR000176","LR003721"]},"LR009311":{"pair":"CALR -> HLA-F","headline":"UniProt reports that calreticulin interacts with HLA-F; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt says P27797 (calreticulin) interacts with HLA-F, citing PMID 10605026 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"CALR is flagged secreted and HLA-F is flagged transmembrane [flag]; calreticulin is a chaperone and these flags alone do not establish extracellular signalling.","caveats":"Support is a UniProt SUBUNIT line only; one judged paper was review-only. The second UniProt line is about a TAP1-TAP2 complex and CALR, not a direct pair statement [DB:UniProt].","key_references":[],"covers":["LR009311"]},"LR003722":{"pair":"CALR -> LRP1","headline":"Calreticulin as an agonist ligand for LRP1 (CD91) is supported by several abstract-level papers, mostly functional.","interaction_type":"functional only","direction_and_effect":"Calreticulin is described as binding and activating LRP on the engulfing phagocyte as an eat-me signal [PMID:16239148]. CD91 signals for calreticulin, including NF-kappaB activation, and calreticulin immunization primed Th17 responses in a CD91-dependent manner in a TGF-beta setting [PMID:22045000]. LRP mediated thrombospondin-calreticulin focal adhesion disassembly [PMID:12821648].","molecular_requirements":"LRP is called a calreticulin coreceptor because calreticulin is not transmembrane; LRP-deficient fibroblasts did not respond, and the isolated proteins LRP and CRT interact [PMID:12821648]. Calreticulin-CD91 colocalised on macrophage surface and anti-CD91 blocked uptake [PMID:11560994].","affinity_potency":[],"species_and_systems":"Curator fields record human for both partners; abstracts do not name species except macrophages and thymocytes in [PMID:22234309] (peritoneal and bone marrow-derived macrophages, likely rodent, not stated). Cell assays, not in vivo.","localisation_and_range":"CALR is flagged secreted and LRP1 a receptor [flag]; papers describe cell-surface calreticulin on target cells and phagocytes [PMID:16239148].","caveats":"All five shown papers were read as abstracts, with excerpts for [PMID:11560994]. PMID 22234309 uses the pairing as background and its own finding is glucocorticoid upregulation of LRP1. Calreticulin is not transmembrane, so other partners may be needed. A BioGRID Affinity Capture-Western record also exists [DB:BioGRID]. One further paper was abstract_insufficient and one pending.","key_references":[{"PMID":"16239148","why":"Calreticulin binds and activates LRP on phagocytes"},{"PMID":"12821648","why":"LRP as calreticulin coreceptor; isolated proteins interact"},{"PMID":"22045000","why":"CD91 signalling for calreticulin and Th17 priming"}],"covers":["LR000177","LR003722"]},"LR002246":{"pair":"CBLN2 -> GRID2","headline":"CBLN2 binds GRID2 with similar activity to CBLN1 per one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Cbln1 and Cbln2 have similar binding activities to beta-neurexins and Grid2, and ectopic Cbln2 in Purkinje cells rescued cerebellar deficits in Cbln1-null mice [PMID:22117778].","molecular_requirements":"Cbln2 acts by the same bridge with neurexins as Cbln1; no further subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Transgenic and null mice; binding assay species not reported in our evidence; curators recorded human [PMID:22117778]. Human pair is ortholog-inferred.","localisation_and_range":"CBLN2 is flagged secreted and GRID2 transmembrane [flag].","caveats":"Redundancy with Cbln1 holds in cerebellum but not in the thalamic/striatal circuit [PMID:22117778]. Same paper supports CBLN1-GRID2; no database records. A second confirmed paper was not shown.","key_references":[{"PMID":"22117778","why":"Cbln2 shares Grid2 and neurexin binding with Cbln1"}],"covers":["LR002246","LR005556"]},"LR000185":{"pair":"CCL11 -> CCR3","headline":"CCL11 (eotaxin) binds CCR3 with sub-nanomolar Kd and acts as an agonist; strongly supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"CCL11 is an agonist of CCR3: it drives eosinophil and basophil chemotaxis through CCR3 [PMID:9276730][PMID:9005985]. GtoPdb lists a full agonist [DB:GtoPdb]. A structural paper reports eotaxin binds only CCR3 among the receptors compared [PMID:9712872].","molecular_requirements":"CCR3 alone expressed in cells is sufficient for binding and signalling in the transfectant studies; no co-receptor requirement is reported in our evidence [PMID:8642344][PMID:8676064].","affinity_potency":[{"value":"Kd 0.1 nM","assay":"radioligand binding","system":"human CCR3 stably expressed in AML14.3D10 cells","cite":"PMID:8642344"},{"value":"IC50 7.6 nM","assay":"competition of CCL11 binding by antagonist YM-355179","system":"CCR3-expressing B300-19 cells","cite":"PMID:16339911"}],"species_and_systems":"Human ligand and receptor in transfected cells and primary human eosinophils and basophils [PMID:8642344][PMID:9005985][PMID:9276730]. The dossier also covers a mouse pair, which is not ortholog-inferred, but the cited experiments are human.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag]: paracrine signalling by annotation.","caveats":"Most papers were read as abstracts only. CCL11 also binds other receptors (see CCR5 and CXCR3 pairs); CCR3 binds other chemokines such as RANTES and MCP-3 [PMID:8642344].","key_references":[{"PMID":"8642344","why":"Cloning of CCR3 with eotaxin Kd 0.1 nM"},{"PMID":"8676064","why":"CKR-3 transfectants bind radiolabelled eotaxin with high affinity"},{"PMID":"9005985","why":"More than 95% of eosinophil response to eotaxin via CCR3"}],"covers":["LR000185","LR003730"]},"LR003731":{"pair":"CCL11 -> CCR5","headline":"CCL11 binds and activates CCR5 in human cells; supported by two abstract-read papers, with weak binding affinity.","interaction_type":"direct binding","direction_and_effect":"Eotaxin is reported as a CCR5 agonist (and a CCR2 antagonist) [PMID:11264152]. It triggers CCR5 at 100 nM and induces CCR5 internalisation in monocytes and transfected cells [PMID:11264152]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 21.7 nmol/L","assay":"[125I]-MIP-1beta competition binding (five values reported; the curator assigned 21.7 to this ligand)","system":"CCR5-expressing stable cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor, transfected cells and monocytes [PMID:11264152][PMID:10477718]. The mouse pair is projected by orthology.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Both papers read as abstracts only. The affinity row comes from a sentence listing five IC50 values; the curator's note ties 21.7 to this ligand but the sentence itself does not name it.","key_references":[{"PMID":"11264152","why":"Eotaxin is a CCR5 agonist; internalises CCR5"},{"PMID":"10477718","why":"CCR5 competition binding panel of CC chemokines"}],"covers":["LR000186","LR003731"]},"LR002255":{"pair":"CCL13 -> CCR10","headline":"A single paper on CCR10 reports binding of MCP-1/MCP-3 chemokines; CCL13 evidence is thin.","interaction_type":"direct binding","direction_and_effect":"The paper reports CCR10 binds MCP-1 and MCP-3 with highest affinity [PMID:9364936]. Signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 1 nM","assay":"MCP-3 binding (abstract)","system":"cells expressing human CCR10","cite":"PMID:9364936"}],"species_and_systems":"Human receptor expressed in cells [PMID:9364936].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"The quoted affinities are for MCP-3 and MCP-1, not CCL13 (MCP-4); the curator row also lists IC50 7.5 nM with no verifiable assignment. Abstract-only; no database support. Likely a paralog mismatch.","key_references":[{"PMID":"9364936","why":"Cloning of CCR10 binding MCP-1/MCP-3"}],"covers":["LR002255"]},"LR000194":{"pair":"CCL14 -> ACKR2","headline":"CCL14 (HCC1) is reported to bind ACKR2 (D6) in one full-text paper; supported by a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"Binding to D6 is seen with human RANTES, MCP3, MCP4 and HCC1 [PMID:9405404]. Signalling is not reported in our evidence. BioGRID records a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, ligand displacement of 125I-labelled murine MIP-1a [PMID:9405404].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"The excerpt names HCC1; the equivalence to CCL14 is not stated in the dossier excerpt. No affinity for this ligand reported. One paper.","key_references":[{"PMID":"9405404","why":"D6 binds many CC chemokines incl. HCC1"}],"covers":["LR000194"]},"LR000239":{"pair":"CCL2 -> CCR5","headline":"Weak-affinity binding of MCP-1 to CCR5 from one abstract-read paper, with no stated functional activation for MCP-1.","interaction_type":"direct binding","direction_and_effect":"MCP-1 competed for [125I]-MIP-1beta binding to CCR5; the paper highlights MCP-3 as a natural antagonist, but the abstract does not state MCP-1 activity [PMID:10477718]. GtoPdb lists a full agonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 29.9 nM","assay":"competition vs [125I]-MIP-1beta","system":"stable CCR5-expressing cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor in a recombinant cell line [PMID:10477718]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Abstract only; MCP-1 is one of several weaker competitors. Two other papers pending, one abstract_insufficient. The GtoPdb entry cites a different paper [DB:GtoPdb].","key_references":[{"PMID":"10477718","why":"CCR5 competition binding, MCP-1 IC50 29.9 nM"}],"covers":["LR000239","LR003760"]},"LR005063":{"pair":"CCL20 -> ACKR4","headline":"Two recent papers show CCL20 is taken up by and recruits beta-arrestin to ACKR4, with lower affinity than CCL19, CCL21 and CCL25.","interaction_type":"functional only","direction_and_effect":"CCL20 acts as agonist at ACKR4: all four chemokines recruit beta-arrestin1 and beta-arrestin2 to human ACKR4 [PMID:32533638], and a screen of 43 human chemokines confirmed CCL20 as an agonist [PMID:32480426].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers; fluorescent CCL20 uptake and cross-species tests: mouse CCL20 did not recruit beta-arrestins to human ACKR4, while mouse ACKR4 internalises mouse and human CCL20 [PMID:32533638]. Mouse interaction is listed without ortholog inference.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Both papers abstract only; no direct binding constant in our evidence, the 'lower affinity' is a qualitative statement [PMID:32533638]. No database records.","key_references":[{"PMID":"32533638","why":"CCL20 uptake and beta-arrestin recruitment by ACKR4"},{"PMID":"32480426","why":"Systematic 43-chemokine screen confirms CCL20"}],"covers":["LR001690","LR005063"]},"LR003740":{"pair":"CCL20 -> CCR6","headline":"Well supported direct CCL20-CCR6 binding and agonism, shown in several human transfected-cell studies; mouse pair is projected from human.","interaction_type":"direct binding","direction_and_effect":"CCL20 (LARC/MIP-3alpha) acts as an agonist at CCR6: it induced calcium flux and migration in CCR6-expressing cells [PMID:9169459] and calcium flux in STRL22 (CCR6)-transfected HEK293 cells [PMID:9223454]. Activation was pertussis-toxin-sensitive and phospholipase C-dependent in HEK 293 cells [PMID:9294137]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR6 alone was sufficient in transfected cells; no co-receptor or extra subunit is reported in our evidence. CCL20 binding to CCR6 was specific: five other CC chemokines did not compete [PMID:9169459]. A PDB structure of the two chains exists [DB:PDB 6WWZ].","affinity_potency":[{"value":"Kd 0.9 nM","assay":"LARC-SEAP binding to CCR6 (GPR-CY4)-expressing cells","system":"Raji cells stably expressing human CCR6","cite":"PMID:9169459"},{"value":"pIC50 7.9-8.5","assay":"GtoPdb affinity range (assay not given in our evidence)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments were on human ligand and human receptor in recombinant cells (HEK293, Raji, K562) and CCR6 cloned from lung dendritic cells [PMID:9169459][PMID:9223454][PMID:9294137]. The mouse pair is inferred from human, with no mouse experiment in the dossier.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Most papers were read as abstracts only. PMID:12081481 treats CCL20-CCR6 as background and is a receptor cysteine-mutagenesis study, so it supports the pair only indirectly. PMID:10521347 concerns beta-defensin displacing iodinated CCL20 from CCR6, so it supports CCL20 binding only as a reference radioligand.","key_references":[{"PMID":"9169459","why":"Kd 0.9 nM binding and CCR6 identification"},{"PMID":"9223454","why":"independent specific binding and calcium flux"},{"PMID":"9294137","why":"CCR6 cloned as MIP-3alpha receptor; pertussis-toxin-sensitive calcium signalling"}],"covers":["LR000213","LR003740"]},"LR000248":{"pair":"CCL3 -> CCR4","headline":"MIP-1alpha binds human CCR4 in competition binding (IC50 14.5 nM) in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"[125I]MIP-1 alpha binds human and murine CC CKR-4 in equilibrium competition assays; the authors describe this as the first report of direct binding to this receptor [PMID:8573157]. Effect direction not reported in our evidence; curators label it stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 14.5 +/- 9.0 nM","assay":"equilibrium competition binding, [125I]MIP-1 alpha","system":"transfected HL-60 cells, human CC CKR-4","cite":"PMID:8573157"},{"value":"IC50 10.1 +/- 3.0 nM","assay":"equilibrium competition binding, [125I]MIP-1 alpha","system":"transfected HL-60 cells, murine CC CKR-4","cite":"PMID:8573157"}],"species_and_systems":"Transfected HL-60 cells with human and murine CC CKR-4 [PMID:8573157]; ligand species is not stated in the abstract.","localisation_and_range":"CCL3 is flagged as secreted and CCR4 as transmembrane [flag]. BioGRID records a reconstituted complex [DB:BioGRID].","caveats":"Single paper read as abstract only; no functional signalling data in our evidence.","key_references":[{"PMID":"8573157","why":"Direct binding and IC50 of MIP-1 alpha at CC CKR-4"}],"covers":["LR000248"]},"LR002264":{"pair":"CCL5 -> CCR10","headline":"Thin, abstract-only support: RANTES competes with MCP-3 for binding to a receptor named CCR10 (IC50 5.4 nM); no signalling shown.","interaction_type":"direct binding","direction_and_effect":"RANTES and MCP-4 competed for 125I-MCP-3 binding to CCR10, with IC50 values of 5.4 nM for RANTES; CCR10 binds MCP-1 and MCP-3 with highest affinity [PMID:9364936]. No agonism or effect is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 5.4 nM","assay":"competition for MCP-3 binding","system":"CCR10, human","cite":"PMID:9364936"}],"species_and_systems":"Human receptor, as stated in the paper [PMID:9364936]; cell system not given in the abstract. The mouse pair is inferred from human evidence.","localisation_and_range":"CCR10 is transmembrane and a receptor [flag]; the paper reports expression mainly in placenta and fetal liver [PMID:9364936].","caveats":"One paper, abstract only; binding is by competition with MCP-3, not RANTES itself as tracer. No database record.","key_references":[{"PMID":"9364936","why":"CCR10 cloning; RANTES competes with MCP-3 at 5.4 nM"}],"covers":["LR002264","LR005565"]},"LR000257":{"pair":"CCL5 -> CCR3","headline":"CCL5 (RANTES) binds CCR3 with Kd 3.1 nM and activates it (Ca2+ flux), supported by several databases.","interaction_type":"direct binding","direction_and_effect":"RANTES bound CC CKR3 (CCR3) and, with eotaxin, activated it in a Ca2+ flux assay; MIP-1 alpha and MIP-1 beta did not bind [PMID:8642344]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RANTES Phe12 is needed for CCR3 binding, and P2 and Y3 for activation [PMID:9289016]. Reactome describes CCR3, 4 and 5 binding CCL5 [DB:Reactome R-HSA-373061].","affinity_potency":[{"value":"Kd 3.1 nM","assay":"binding to CC CKR3","system":"AML14.3D10 cells stably expressing human CCR3","cite":"PMID:8642344"},{"value":"pKi 8.5 to 9.3","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human CCR3 cloned from eosinophils and stably expressed; primary human eosinophils also tested [PMID:8642344]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"PMID:9289016 was an abstract-only read; PMID:8642344 has full-text excerpts. BioGRID lists reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8642344","why":"Cloned CCR3; RANTES Kd 3.1 nM and Ca2+ flux"},{"PMID":"9289016","why":"RANTES N-loop and N-terminus residues for CCR3"}],"covers":["LR000257","LR003767"]},"LR000266":{"pair":"CCL7 -> CCR1","headline":"Well supported: MCP-3 (CCL7) binds and activates human CCR1 in several binding and functional assays, with Ki about 8 nM.","interaction_type":"direct binding","direction_and_effect":"MCP-3 is a ligand and potent agonist at CCR1 (calcium changes, rank order MIP-1a > MCP-3 > RANTES) [PMID:8530354]; it induced directional migration of CCR1 transfectants and was the most potent chemoattractant of the three [PMID:7545673]. In a Ba/F3-hCCR1 panel, the chemokines other than MCP-2 were full agonists in GTPgammaS exchange [PMID:12381680]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"CCR1 alone is sufficient in transfectants; CCR1 is promiscuous, and MCP-1 competed poorly for MCP-3 binding [PMID:8530354][PMID:7545673].","affinity_potency":[{"value":"Ki 8 nM","assay":"125I-MCP-3 binding","system":"CC CKR1 transfectants (human)","cite":"PMID:8530354"},{"value":"pKi 8.1","assay":"125I-MIP-1alpha displacement","system":"Ba/F3-hCCR1 membranes","cite":"PMID:12381680"}],"species_and_systems":"Human ligand and receptor in transfectants (293, Ba/F3) and the YT NK-like line [PMID:7545673][PMID:12381680]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR1 flagged transmembrane receptor [flag].","caveats":"All three papers read as abstracts. The pKi 8.1 comes from a multi-chemokine panel and is recorded on this row by the curators; the abstract does not state which chemokine it belongs to. UniProt also notes CCR1-NF-kB signalling in macrophage polarisation [DB:UniProt].","key_references":[{"PMID":"8530354","why":"CCL7 binds CCR1 (Ki 8 nM) and is a potent agonist"},{"PMID":"7545673","why":"CCR1 cloned from YT cells; MCP3 binding and chemotaxis"},{"PMID":"12381680","why":"Pharmacological panel at hCCR1"}],"covers":["LR000266","LR003776"]},"LR000275":{"pair":"CCL8 -> CCR2","headline":"CCL8 binds CCR2 in transfected human cells, but the evidence is partly about cleaved forms and a comparator assay; weaker than for CCR1.","interaction_type":"conflicting","direction_and_effect":"MCP-2 bound and signalled through CCR2B in HEK293 transfectants, with significant migration [PMID:9115216]. In L1.2-CCR2 cells CCL8 was a comparator agonist, less efficacious in migration than the viral chemokine vCCL4 [PMID:12554737]; GtoPdb lists a full agonist [DB:GtoPdb]. A protease-truncated MCP-2 still bound CCR2 but lacked chemoattractant activity and acted as an antagonist in migration assays [PMID:12149192].","molecular_requirements":"Processing state matters: MMP cleavage between residues 4 and 5 converts agonist to antagonist (MCP analogs bound CCR-2 and CCR-3) [PMID:12149192]. No subunit requirement is reported.","affinity_potency":[],"species_and_systems":"Human chemokines and receptors in transfected HEK293 [PMID:9115216] and murine pre-B L1.2 cells expressing CCR2 [PMID:12554737]; truncated forms also tested in THP-1 cells and rat paw inflammation [PMID:12149192]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand (CCL8 is flagged secreted) acting on a transmembrane receptor [flag].","caveats":"All three papers read as abstracts only. Direction depends on the form tested (full length agonist vs truncated antagonist). The 2003 paper uses CCL8 only as a comparator, not characterised de novo [PMID:12554737]. No affinity is reported for CCL8 itself in our evidence.","key_references":[{"PMID":"9115216","why":"MCP-2 binds and signals through CCR2B in transfectants"},{"PMID":"12149192","why":"MMP-truncated MCP-2 binds CCR2 but is an antagonist"},{"PMID":"12554737","why":"CCL8 as comparator CCR2 agonist in chemotaxis"}],"covers":["LR000275","LR003785"]},"LR003920":{"pair":"CCN1 -> ITGB3","headline":"CCN1 binds integrin alphavbeta3 and enhances mitogenesis through it; adhesion and binding shown in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"HUVEC adhesion to Cyr61 was inhibited by RGDS and LM609, and purified alphavbeta3 bound Cyr61 directly [PMID:9446626]. In skin fibroblasts, Cyr61 enhancement of growth-factor-induced mitogenesis was through alphavbeta3, whereas migration was through alphavbeta5 and not alphavbeta3 [PMID:11287419].","molecular_requirements":"beta3 functions as part of alphavbeta3, an RGD-sensitive integrin; the effect depends on context (mitogenesis, not migration) [PMID:11287419].","affinity_potency":[{"value":"approximately 5 nM half-saturation","assay":"solid-phase binding of soluble Cyr61 to immobilized alphavbeta3","system":"purified integrin","cite":"PMID:9446626"}],"species_and_systems":"Human CCN1, human umbilical vein endothelial cells and human skin fibroblasts. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers abstract only. The fibroblast paper is functional and states migration is not alphavbeta3-mediated [PMID:11287419]. The half-saturation value is not a formal Kd.","key_references":[{"PMID":"9446626","why":"Direct alphavbeta3 binding and adhesion in HUVEC"},{"PMID":"11287419","why":"alphavbeta3 role in mitogenesis, alphavbeta5 in migration"}],"covers":["LR000423","LR003920"]},"LR002273":{"pair":"CCN2 -> FGFR3","headline":"CCN2 bound FGFR3 in a protein-array screen, with weaker affinity than for FGFR2; thin abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"CCN2 could bind FGFR2 and FGFR3 in a protein-array screen, with higher affinity toward FGFR2 [PMID:23142580]. Effect on FGFR3 signalling is not reported in our evidence; follow-up work in the paper concerned FGFR2.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Protein array; species not specified in the abstract [PMID:23142580]. IntAct holds the protein-array record [DB:IntAct].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Based on a single screening result in an abstract; no confirmatory binding, affinity or functional data for FGFR3 are reported in our evidence [PMID:23142580].","key_references":[{"PMID":"23142580","why":"Protein-array screen showing CCN2 binding to FGFR2 and FGFR3"}],"covers":["LR002273","LR005574"]},"LR000383":{"pair":"CCN2 -> ITGAM","headline":"Two papers report that integrin alphaMbeta2 mediates monocyte adhesion to CCN2 (CTGF) and that the alphaM I domain binds CCN2.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaMbeta2 is an adhesion receptor for CCN2 on monocytes. THP-1 cells and monocytes adhered to CTGF-coated wells in an activation-dependent manner, mainly through alphaM beta2 [PMID:12036876]. Signalling outcome is not reported in our evidence.","molecular_requirements":"The alphaM I domain is sufficient for binding: a GST-alphaMI fusion bound CTGF and the CCN2 H2 peptide (TSVKTYRAKFCGV) [PMID:12036876][PMID:12736251]. Heparan sulfate proteoglycans were tested as co-receptors for Cyr61 (CCN1), not reported for CCN2 [PMID:12036876]. Full functional receptor is the alphaM-beta2 heterodimer.","affinity_potency":[],"species_and_systems":"Human THP-1 cells and peripheral blood monocytes; HEK293 expressing alphaMbeta2 (for Cyr61); GST-fusion binding assays [PMID:12036876][PMID:12736251].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Adhesion to coated protein suggests matrix-bound presentation.","caveats":"Both papers read as abstracts only. Much of the work centres on CCN1 (Cyr61); CCN2 data are mostly parallel observations. No affinity values are reported in our evidence.","key_references":[{"PMID":"12036876","why":"Monocyte adhesion to CTGF mediated by alphaMbeta2; alphaM I domain binds CTGF"},{"PMID":"12736251","why":"H2 peptide in CCN2 binds alphaM I domain"}],"covers":["LR000383","LR003889"]},"LR004532":{"pair":"CCN3 -> NOTCH1","headline":"Non-canonical secreted CCN3 binds the NOTCH1 extracellular domain; effect on signalling is reported as both activating and inhibitory.","interaction_type":"conflicting","direction_and_effect":"CCN3 (NOV) associated with the NOTCH1 EGF-like repeats and activated the HES1 and HES5 promoters, a positive effect on Notch signalling [PMID:12050162]. In K562 leukaemia cells, overexpressed or recombinant CCN3 reduced NOTCH1 signalling (>50% reduction in NOTCH1-ICD), described as a non-canonical NOTCH1 ligand with inhibitory effect [PMID:24308033].","molecular_requirements":"The CCN3 C-terminal cysteine knot (CT) domain contacts the NOTCH1 EGF-like repeat region [PMID:12050162][DB:UniProt]. Other subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both papers used human proteins and cells (human CCN3 and NOTCH1, K562 cells for the second); the dossier lists both human and mouse pair records, with mouse experiments not described [PMID:12050162][PMID:24308033].","localisation_and_range":"CCN3 is flagged secreted and NOTCH1 transmembrane [flag], consistent with a paracrine ligand acting on a membrane receptor.","caveats":"The two papers disagree on the sign of the effect (activation of HES1/HES5 vs reduced NOTCH1-ICD). Both were read as abstracts only for binding; the binding evidence is domain-mapped association, with BioGRID affinity-capture and reconstituted-complex records from the same paper [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"12050162","why":"Domain-mapped CCN3 CT-NOTCH1 EGF-repeat association, HES1/HES5 activation"},{"PMID":"24308033","why":"CCN3 reduces NOTCH1-ICD in K562 CML cells"}],"covers":["LR001121","LR004532"]},"LR008204":{"pair":"CD14 -> ITGA4:ITGB1","headline":"Direct solid-phase binding of CD14-Fc to purified alpha4beta1 complex, activation-dependent; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"CD14-Fc bound affinity-purified alpha4beta1 dose-dependently, induced by activating anti-beta1 antibodies; Jurkat (alpha4beta1+) adhered to CD14-Fc whereas K562 (alpha4beta1-) did not until alpha4 was re-expressed [PMID:17274987].","molecular_requirements":"Needs the alpha4beta1 heterodimer, with activation state mattering, like VCAM-1 [PMID:17274987]. JY cells also attach via alpha4beta7, so beta7 pairing may also occur [PMID:17274987].","affinity_potency":[],"species_and_systems":"Human recombinant CD14-Fc; Jurkat, K562 alpha4 transfectants and JY cells [PMID:17274987].","localisation_and_range":"CD14 flagged secreted/receptor [flag]; the tested setting is cell adhesion to immobilised protein [PMID:17274987].","caveats":"Single paper, abstract only; no database support; no affinity reported.","key_references":[{"PMID":"17274987","why":"CD14-Fc binds alpha4beta1 in an activation-dependent way"}],"covers":["LR008204"]},"LR005072":{"pair":"CD177 -> PECAM1","headline":"CD177 binds PECAM-1 directly (SPR, cation-dependent) and supports neutrophil transmigration; well supported in human.","interaction_type":"direct binding","direction_and_effect":"CD177 is a heterophilic counter-receptor for PECAM-1; blocking antibodies to CD177 or PECAM-1 domain 6 inhibited U937 adhesion and human neutrophil transendothelial migration [PMID:17580308]. Recombinant CD177-Fc suppressed antibody-induced PECAM-1 tyrosine phosphorylation more in LSR-allele cells [PMID:20194726].","molecular_requirements":"Binding is mediated by the heterophilic domains of PECAM-1, notably membrane-proximal IgD 6, and is cation-dependent [PMID:17580308][PMID:20194726].","affinity_potency":[],"species_and_systems":"Human neutrophils, U937 cells and HUVECs; the mouse pair is ortholog-inferred [PMID:17580308][PMID:20194726].","localisation_and_range":"Both flagged membrane receptors, with CD177 also carrying a secreted flag [flag]; PECAM-1 is on endothelial junctions, so interaction is contact-dependent [PMID:20194726].","caveats":"The first paper was read as an abstract only. The PECAM-1 S536N allele changes the response [PMID:20194726]. No affinity value reported. Reactome and IntAct records agree [DB:Reactome R-HSA-202702][DB:IntAct].","key_references":[{"PMID":"17580308","why":"Identifies PECAM-1 as CD177 partner; SPR"},{"PMID":"20194726","why":"PECAM-1 S536N dimorphism modulates CD177 effects"}],"covers":["LR001703","LR005072"]},"LR002282":{"pair":"CD2 -> CD59","headline":"One 1992 abstract-read paper reports CD2-CD59 binding in cell rosetting assays; single-paper support.","interaction_type":"direct binding","direction_and_effect":"CD59-transfected CHO cells formed rosettes with human T cells, blocked by anti-CD59 and anti-CD2 antibodies, and 125I-CD59 bound CD2+ CHO cells; authors conclude CD2 binds CD59 [PMID:1385156].","molecular_requirements":"Not reported in our evidence beyond the CD2 and CD59 pair; antibody against a different CD59 epitope increased rosetting [PMID:1385156].","affinity_potency":[],"species_and_systems":"Human T cells and CHO transfectants [PMID:1385156].","localisation_and_range":"Both are membrane proteins in the assay; CD59 is flagged secreted and receptor [flag].","caveats":"The CD2-CD59 link is described as controversial in the wider literature only outside this dossier; one paper only. Abstract read only. No database record.","key_references":[{"PMID":"1385156","why":"Rosette and radiolabelled CD59 binding to CD2"}],"covers":["LR002282"]},"LR001706":{"pair":"CD200 -> CD200R1","headline":"Well supported direct binding: crystal structure of the CD200-CD200R complex plus FACS and SPR binding; CD200R signals inhibition.","interaction_type":"direct binding","direction_and_effect":"CD200 regulates myeloid cells through the inhibitory receptor CD200R [PMID:23602662]. Anti-CD200R antibody OX131 blocked CD200 binding and prevented CD200-mediated inhibition of IL-2 in a T cell hybridoma assay, while engaging CD200R alone gave an agonistic inhibitory signal [PMID:23691022]. Mice lacking CD200 resisted chemical skin carcinogenesis [PMID:22020332].","molecular_requirements":"Both CD200 and CD200R have two Ig-like domains and interact through their NH2-terminal domains [PMID:23602662]. The activating paralogue CD200RLa fails to bind CD200 [PMID:23602662]. Cells transfected with any CD200R family isoform bound CD200 in one report [PMID:15187158].","affinity_potency":[],"species_and_systems":"Crystal structure of the extracellular regions; the structure figure legend describes mouse CD200R [PMID:23602662]. Cell binding used COS7 transfectants [PMID:15187158] and 2B4 Reay cells with CD200-coated beads and SPR [PMID:23691022]. In vivo evidence is from Cd200-/- mice [PMID:22020332]. Curator species labels say human; the excerpts indicate mouse proteins in several papers. Human and mouse pairs are both listed.","localisation_and_range":"CD200 is a membrane glycoprotein [PMID:23602662]; both partners are flagged transmembrane [flag]. Signalling is by cell-cell contact, compatible with immunological-synapse-like interactions [PMID:23602662].","caveats":"Three of four papers were read as abstract only; no affinity value in our evidence. The knockout paper shows an in vivo functional outcome and not binding itself [PMID:22020332].","key_references":[{"PMID":"23602662","why":"Crystal structure of the CD200-CD200R complex"},{"PMID":"23691022","why":"FACS and SPR binding, antibody blocking, functional inhibition"},{"PMID":"15187158","why":"FACS binding of CD200Fc to CD200R isoforms"}],"covers":["LR001706","LR005074"]},"LR005081":{"pair":"CD274 -> PDCD1","headline":"Well established PD-L1 binding to PD-1: crystal structure, SPR and MST, with inhibitory signalling noted in UniProt.","interaction_type":"direct binding","direction_and_effect":"PD-1 binds PD-L1; signalling through PD-1 upon PD-L1 binding suppresses immune responses [PMID:18287011]. UniProt says PD-1 delivers inhibitory signals on binding CD274 [DB:UniProt]. PD-L1 and PD-L2 compete for PD-1, and an antagonist PD-1 mAb blocked both and enhanced T-cell proliferation [PMID:20587542]. Structure: crystal of murine PD-1 with human PD-L1 [PMID:18287011]; PDB 4ZQK and 5IUS [DB:PDB 4ZQK].","molecular_requirements":"Binding is through the Ig variable domains of both proteins; some loss-of-binding mutations disrupt folding instead [PMID:18287011]. No additional subunit needed in our evidence.","affinity_potency":[{"value":"Kd 8.5 \u00b5M","assay":"microscale thermophoresis","system":"mouse PD-L1 with mPD-1-eGFP in CHO-K1 lysate","cite":"PMID:29247197"}],"species_and_systems":"Murine PD-1 with human PD-L1 in the crystal [PMID:18287011]; human proteins by SPR [PMID:20587542]; the MST data use mouse proteins [PMID:29247197].","localisation_and_range":"PD-L1 flagged membrane-bound and also secreted, PD-1 transmembrane [flag]; contact-dependent signalling.","caveats":"PD-L1 and PD-L2 bound with comparable affinities; PD-L1 shows delayed association [PMID:20587542]. GtoPdb lists binding with no affinity [DB:GtoPdb]. Only abstracts read for the three curated papers.","key_references":[{"PMID":"18287011","why":"Crystal structure of PD-1 with PD-L1"},{"PMID":"20587542","why":"SPR kinetics and competition between PD-L1 and PD-L2"},{"PMID":"29247197","why":"MST protocol measuring Kd"}],"covers":["LR001714","LR005081"]},"LR001715":{"pair":"CD28 -> CD80","headline":"Recombinant soluble CD80 binds CD28-Ig in a direct binding assay; evidence is one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"Recombinant s1CD80 bound recombinant CD28-Ig and CD152-Ig, and recombinant sCD80 inhibited the mixed lymphocyte reaction and T-cell proliferation, suggesting a soluble decoy/inhibitory role [PMID:17953528]. UniProt describes CD28 engagement by CD80 or CD86 as stimulating T-cell proliferation and cytokine production [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond the soluble s1CD80 isoform (lacks the transmembrane domain) binding CD28-Ig [PMID:17953528]. Reactome lists CD28 homodimer binding B7-1 homodimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human T cells [PMID:17953528]; the mouse pair is projected from human evidence.","localisation_and_range":"CD80 is flagged secreted and transmembrane [flag]; the paper shows a naturally occurring soluble form in serum (0 to 1 mg/l) [PMID:17953528]. Membrane form acts by contact [DB:Reactome, plasma membrane complex].","caveats":"Only abstract read; the paper's focus is soluble CD80, so membrane-bound CD80 binding to CD28 is supported mainly by databases (BioGRID, IntAct, Reactome). No affinity reported.","key_references":[{"PMID":"17953528","why":"Recombinant soluble CD80 binds CD28-Ig and inhibits T-cell activation"}],"covers":["LR001715","LR005082"]},"LR000284":{"pair":"CD40LG -> CD40","headline":"Canonical, well supported ligand-receptor pair with binding, structural, in vitro and in vivo evidence across species.","interaction_type":"direct binding","direction_and_effect":"CD40L on activated T cells engages CD40 on APCs; mutagenesis maps interacting residues [PMID:7543281]. Anti-gp39 blocking in mice inhibited germinal-centre formation and memory B-cell generation [PMID:7516405]. Soluble CD40L enhanced ICAM-1 and FAS, and cytokines on tumour lines, and inhibited proliferation [PMID:11163401]. CD154 shedding is triggered by CD40 ligation [PMID:24189063].","molecular_requirements":"Model-guided mutagenesis implicates two clusters of residues and two adjacent gp39 monomers [PMID:7543281]. Soluble CD40L exists as monomer or homotrimer [DB:UniProt]; PDB 3QD6 is a structure of the complex [DB:PDB 3QD6].","affinity_potency":[],"species_and_systems":"Human cell lines and proteins [PMID:7543281][PMID:11163401]; murine ligand cloned [PMID:1374165]; in vivo mouse blocking [PMID:7516405].","localisation_and_range":"CD40LG flagged secreted [flag]; membrane form acts by contact, and soluble CD154 arises by shedding via ADAM10/ADAM17 on CD40 ligation [PMID:24189063].","caveats":"Most papers abstract only. No affinity values reported in our evidence. GtoPdb record lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"7543281","why":"Structure-guided mutagenesis of gp39/CD40 interface"},{"PMID":"1374165","why":"Cloning of murine CD40 ligand"},{"PMID":"24189063","why":"CD154 shedding triggered by CD40"}],"covers":["LR000284","LR003794"]},"LR002291":{"pair":"CD40LG -> ITGB1","headline":"CD40L binding to integrin beta1 partners (alpha5beta1, alpha4beta1) rests on abstract-level papers and UniProt.","interaction_type":"direct binding","direction_and_effect":"CD154 binds alpha5beta1, binds CD40 simultaneously, and together they activated p38 and ERK1/2 and synergised in MMP-2/-9 release [PMID:22461623]. Soluble CD40L activated soluble and cell-surface alphavbeta3, alpha5beta1 and alpha4beta1, including in CD40-negative CHO cells [PMID:33571526]. UniProt records an integrin receptor role for CD40LG [DB:UniProt].","molecular_requirements":"ITGB1 is shared by alpha5beta1 and alpha4beta1; the alpha partner is the one tested, so beta1 alone is not shown to suffice [PMID:33571526]. Integrins bind the CD40L trimeric interface [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human; U937 cells and CHO cells and cell-free soluble integrins [PMID:22461623][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; soluble CD40L used [PMID:33571526].","caveats":"Abstract-only reads; evidence is at heterodimer level (curators stored it per subunit). The binding paper's experiment species are recorded as unspecified [PMID:22461623]. The UniProt entry text names ITGA5:ITGB3 [DB:UniProt]. Two more confirmed papers are not shown.","key_references":[{"PMID":"22461623","why":"CD154 binding to alpha5beta1"},{"PMID":"33571526","why":"sCD40L activates alpha4beta1 and alpha5beta1"}],"covers":["LR002291","LR005590"]},"LR005090":{"pair":"Cd48 -> Cd244a","headline":"Mouse pair supported by one abstract-only functional paper showing inhibitory NK self-recognition.","interaction_type":"functional only","direction_and_effect":"2B4 (CD244) and CD48 are a second system for murine NK-cell self-recognition; 2B4 inhibits NK lysis of syngeneic tumour cells nonredundantly with MHC class I receptors, and NK cells from beta2-microglobulin-deficient mice are inhibited by 2B4 [PMID:15870174]. Curator effect: antagonist (inhibitory).","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine NK cells and mice, including an in vivo bone marrow rejection assay [PMID:15870174]. The curator species fields say human, which does not match the abstract.","localisation_and_range":"Annotation flags: ligand secreted, receptor not secreted [flag]; the paper implies recognition on target cells by NK cells (contact) [PMID:15870174].","caveats":"One paper, abstract only; shows a functional effect rather than direct binding. UniProt text on CD48 names CD244/2B4 as a partner [DB:UniProt].","key_references":[{"PMID":"15870174","why":"Mouse NK-cell self-recognition via 2B4-CD48"}],"covers":["LR005090"]},"LR001724":{"pair":"CD52 -> SIGLEC10","headline":"Soluble CD52 binds the inhibitory receptor Siglec-10 in human systems; binding needs HMGB1 and sialylated glycan.","interaction_type":"direct binding","direction_and_effect":"Soluble CD52 binds the inhibitory receptor Siglec-10, impairs Lck and Zap70 phosphorylation and suppresses T cell activation [PMID:23685786]. CD52-Fc induced Siglec-10 tyrosine phosphorylation and recruited SHP1 [PMID:29997173].","molecular_requirements":"Binding to Siglec-10 requires HMGB1 (Box B promotes it; Box A blocks); the CD52 N-linked glycan in alpha-2,3 sialic acid linkage with galactose is required; a CD52-HMGB1-Siglec-10-SHP1-TCR complex was recovered from T cells [PMID:29997173]. Siglec-10 bound plate-coated CD52-Fc only with HMGB1 in solid-phase assays [PMID:29997173].","affinity_potency":[{"value":"565 nM","assay":"SPR, steady-state estimated Kd, CD52-Fc to immobilised Siglec-10-Fc","system":"recombinant Fc fusions","cite":"PMID:29997173"}],"species_and_systems":"Human and mouse activated T cells; human PBMC and T cell experiments, with NOD mouse transfer [PMID:23685786]; recombinant CD52-Fc and Siglec-10-Fc [PMID:29997173].","localisation_and_range":"CD52 is released in soluble form by phospholipase C and acts on other T cells (paracrine) [PMID:23685786]; annotation flags list both partners as secreted and transmembrane [flag].","caveats":"Direct SPR binding was seen but not in plate assays without HMGB1, and the authors note possible sensitivity or coating differences [PMID:29997173]. Both papers were read as abstracts plus excerpts for 29997173. IntAct records exist [DB:IntAct].","key_references":[{"PMID":"29997173","why":"HMGB1-dependent CD52-Siglec-10 binding, SPR Kd, signalling"},{"PMID":"23685786","why":"Soluble CD52 binds Siglec-10 and suppresses T cells; human and NOD mouse"}],"covers":["LR001724"]},"LR001733":{"pair":"CD86 -> CTLA4","headline":"CD86 engages CTLA-4 and is removed by CTLA-4 transendocytosis; supported by functional papers and structures, read mostly as abstracts.","interaction_type":"functional only","direction_and_effect":"CTLA-4 takes up CD86 by transendocytosis; with CD86 CTLA-4 detaches in a pH-dependent manner and recycles to the surface [PMID:35999394]. Blocking CTLA-4 with antibodies enhanced human T-cell activation in CD80- or CD80/CD86-dependent assays, i.e. the interaction is inhibitory [PMID:10583602]. UniProt describes CTLA4 as a decoy receptor that binds CD80 and CD86 more strongly than CD28 [DB:UniProt].","molecular_requirements":"CD86 and CD80 are both ligands of CTLA-4; the dossier does not report subunit requirements beyond the CTLA-4 cytoplasmic domain and lysines in the CD80 ubiquitylation experiments [PMID:35999394].","affinity_potency":[],"species_and_systems":"Transendocytosis experiments used human cells (CHO transfectants, Jurkat, primary Treg) [PMID:35999394]; the other paper used human T cells [PMID:10583602]. The mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane proteins; contact-dependent (transendocytosis between cells) [PMID:35999394].","caveats":"Both papers read as abstract only for the curator judgement. Physical binding is supported by database structure/binding records (PDB 1I85, BioGRID, IntAct) rather than by the papers shown [DB:PDB 1I85] [DB:BioGRID].","key_references":[{"PMID":"35999394","why":"CD86 vs CD80 transendocytosis and CTLA-4 recycling"},{"PMID":"10583602","why":"CTLA-4 blockade enhances human T-cell activation"}],"covers":["LR001733","LR005098"]},"LR005603":{"pair":"CDH10 -> CDH10","headline":"Homophilic type II cadherin pair; the one verified paper's evidence sentence does not clearly show CDH10 self-binding.","interaction_type":"direct binding","direction_and_effect":"Homophilic adhesion partner of itself; direction is a formality. The curated sentence reports cadherin-6 analyte binding strongest on cadherin-6, -9 or -10 surfaces, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group with similar binding profiles [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"The paper's excerpt states cadherin-10 analyte did not show binding above background on a cadherin-8 surface; homophilic cadherin-10 strength is not quantified in our evidence [PMID:29742438]. Human result is ortholog-projected. No affinity reported.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002305","LR005603"]},"LR002309":{"pair":"CDH2 -> ASTN1","headline":"N-cadherin binds astrotactin and supports neuron-glia adhesion; one abstract-level paper with mouse in vivo and cell data.","interaction_type":"direct binding","direction_and_effect":"ASTN1 binds N-cadherin and the interaction supports cell-cell adhesion. N-cadherin acts as a cis ligand on the neuron and a trans ligand on glia; loss of glial Cdh2 slowed granule cell migration more severely than neuronal loss [PMID:30262652].","molecular_requirements":"The ASTN1 C-terminal ectodomain (MACPF, FNIII, ANX-like region) was needed: CDH2 co-precipitated with full-length ASTN1 but not ASTN1-\u0394CTD in HEK 293T cells [PMID:30262652].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation from HEK 293T cells and P7 mouse cerebellar lysates, cerebellar slice cultures and granule-cell/glia chimeras; the mouse pair is the experimental one [PMID:30262652]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound; acts in cis and trans at the neuron-glia migration junction [PMID:30262652].","caveats":"Only one paper, curated from abstract plus excerpts; binding affinity is not reported, and curator notes say the direct-binding label rests on co-IP and cell assays.","key_references":[{"PMID":"30262652","why":"ASTN1-CDH2 cis and trans binding in glial-guided migration"}],"covers":["LR002309","LR005607"]},"LR005612":{"pair":"CDH4 -> CDH2","headline":"R- and N-cadherin interact weakly in mouse cell aggregation; one abstract-level paper plus a BioGRID record.","interaction_type":"functional only","direction_and_effect":"In L cell aggregation, mixing mouse R-cadherin and N-cadherin cells gave separate and chimeric aggregates, suggesting they can interact although each prefers its own type [PMID:8270638].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cell aggregation assays [PMID:8270638]; the human pair is ortholog-inferred. BioGRID lists CDH4 - CDH2 Affinity Capture-Western [DB:BioGRID] [PMID:10662782].","localisation_and_range":"Membrane-bound adhesion molecules, contact-dependent [flag].","caveats":"Weak, preference-biased heterotypic binding; abstract-only read; direct binding not measured; four papers judged as different entity, three abstract-insufficient.","key_references":[{"PMID":"8270638","why":"Mouse R-/N-cadherin cell aggregation"}],"covers":["LR002314","LR005612"]},"LR002318":{"pair":"CDH6 -> CDH6","headline":"Cadherin-6 binds itself preferentially in SPR on mouse proteins; human pair inferred.","interaction_type":"direct binding","direction_and_effect":"Homophilic binding was favored over all heterophilic interactions for only cadherin-6 and cadherin-20 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 share a specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, contact-dependent; CDH6 is flagged transmembrane [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured. BioGRID also lists a CDH6 - CDH6 co-localization record, which is not binding evidence [DB:BioGRID] [PMID:10207020].","key_references":[{"PMID":"29742438","why":"Homophilic cadherin-6 preference in SPR"}],"covers":["LR002318","LR005616"]},"LR002327":{"pair":"CEACAM16 -> TECTA","headline":"Co-immunoprecipitation shows CEACAM16 interacts with TECTA in transfected cells; UniProt agrees.","interaction_type":"direct binding","direction_and_effect":"Myc-TECTA co-immunoprecipitated when co-expressed with CEACAM16-V5-His [PMID:25080593]. UniProt states TECTA interacts with CEACAM16 [DB:UniProt].","molecular_requirements":"CEACAM16 also interacts with TECTB; the paper suggests it may stabilise TECTA-TECTB interactions [PMID:25080593]. Whether TECTA alone suffices is not reported.","affinity_potency":[],"species_and_systems":"Co-IP in transfected cells; paper is on mouse tectorial membrane [PMID:25080593]. The human pair is ortholog-inferred and the mouse pair is direct.","localisation_and_range":"Secreted glycoproteins in the extracellular tectorial membrane of the inner ear [PMID:25080593]; CEACAM16 flagged secreted [flag].","caveats":"The supporting quote was read by a browser and is marked as unverifiable pending spot-check. Matrix-protein interaction rather than classical signalling.","key_references":[{"PMID":"25080593","why":"CEACAM16-TECTA co-IP and tectorial membrane context"}],"covers":["LR002327","LR005621"]},"LR005621":{"pair":"CEACAM16 -> TECTA","headline":"Co-immunoprecipitation shows CEACAM16 interacts with TECTA in transfected cells; UniProt agrees.","interaction_type":"direct binding","direction_and_effect":"Myc-TECTA co-immunoprecipitated when co-expressed with CEACAM16-V5-His [PMID:25080593]. UniProt states TECTA interacts with CEACAM16 [DB:UniProt].","molecular_requirements":"CEACAM16 also interacts with TECTB; the paper suggests it may stabilise TECTA-TECTB interactions [PMID:25080593]. Whether TECTA alone suffices is not reported.","affinity_potency":[],"species_and_systems":"Co-IP in transfected cells; paper is on mouse tectorial membrane [PMID:25080593]. The human pair is ortholog-inferred and the mouse pair is direct.","localisation_and_range":"Secreted glycoproteins in the extracellular tectorial membrane of the inner ear [PMID:25080593]; CEACAM16 flagged secreted [flag].","caveats":"The supporting quote was read by a browser and is marked as unverifiable pending spot-check. Matrix-protein interaction rather than classical signalling.","key_references":[{"PMID":"25080593","why":"CEACAM16-TECTA co-IP and tectorial membrane context"}],"covers":["LR002327","LR005621"]},"LR001742":{"pair":"CEACAM8 -> CEACAM1","headline":"Soluble CEACAM8-Fc binds CEACAM1 on human airway epithelium and dampens TLR2 responses; one paper plus database complex records.","interaction_type":"direct binding","direction_and_effect":"Recombinant CEACAM8-Fc bound CEACAM1 on human airway epithelium and reduced TLR2-induced IL-8 and IL-6 release, with CEACAM1 ITIM phosphorylation and SHP-1 recruitment, so the effect is inhibitory [PMID:24743304].","molecular_requirements":"Not reported in our evidence beyond CEACAM8 acting as a soluble, granulocyte-released form engaging membrane CEACAM1 [PMID:24743304]. Databases list a CEACAM heterodimer complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human granulocytes, primary human bronchial epithelial cells and recombinant human protein [PMID:24743304].","localisation_and_range":"Soluble CEACAM8 released by granulocytes acts on epithelial CEACAM1, a paracrine granulocyte-to-epithelium route [PMID:24743304]. Both entities carry secreted/receptor/transmembrane annotation flags [flag].","caveats":"Curated from the abstract plus full text; no affinity reported. Database records (BioGRID reconstituted complex, IntAct protein array and solid phase assay, UniProt isoform 1 interaction) support binding [DB:BioGRID] [DB:IntAct] [DB:UniProt].","key_references":[{"PMID":"24743304","why":"Soluble CEACAM8-Fc binds CEACAM1 and inhibits TLR2 signalling"}],"covers":["LR001742"]},"LR000293":{"pair":"CEL -> CXCR4","headline":"CEL (BSDL) acts through platelet CXCR4 in one paper; binding is inferred, not directly measured.","interaction_type":"functional only","direction_and_effect":"BSDL and a V3-loop-like peptide induced calcium mobilization and enhanced thrombin-mediated platelet aggregation in human platelets, abolished by CXCR4 inhibition; classed as agonist [PMID:18037996]. In mice, thrombus formation depended on BSDL and was blocked by CXCR4 antagonism [PMID:18037996].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human platelets and endothelial cells in vitro, plus a mouse thrombosis model and BSDL-knockout mice [PMID:18037996]. Human pair is ortholog-inferred for the mouse record.","localisation_and_range":"CEL is flagged secreted [flag]; range not reported in the paper excerpt.","caveats":"Curator notes that binding is inferred from homology of a BSDL region to the HIV-1 V3 loop plus functional blockade, not a direct binding assay; abstract only [PMID:18037996]. No database records.","key_references":[{"PMID":"18037996","why":"BSDL activates platelets in a CXCR4-dependent manner in vitro and in mice"}],"covers":["LR000293","LR003802"]},"LR002336":{"pair":"CEMIP -> ANXA1","headline":"Secreted CEMIP (KIAA1199) G8 domain binds membrane ANXA1 in rheumatoid arthritis synoviocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"The G8 domain of secreted KIAA1199 bound ANXA1, anchoring it to the membrane and enabling extracellular hyaluronic acid degradation; classed as agonist [PMID:33473125]. Interaction was shown by co-IP in RA fibroblast-like synoviocytes and 293T cells [PMID:33473125].","molecular_requirements":"Only wild-type KIAA1199 and G8-containing mutants co-precipitated with ANXA1; G8 deletion lost the in vivo effect [PMID:33473125].","affinity_potency":[],"species_and_systems":"Human RA synoviocytes and ANXA1-expressing 293T cells; collagen-induced arthritis and knockout mice [PMID:33473125]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted CEMIP attaches to the cell membrane via ANXA1 [PMID:33473125]. ANXA1 is flagged non-transmembrane [flag], so it acts as an anchor rather than a classical receptor.","caveats":"Co-IP evidence; affinity not reported. No database records.","key_references":[{"PMID":"33473125","why":"G8 domain of sKIAA1199 binds ANXA1 for membrane attachment"}],"covers":["LR002336","LR005625"]},"LR003803":{"pair":"CGA -> FSHR","headline":"FSH (CGA alpha chain with FSHB) binds FSHR; structure and photoaffinity labeling support it, but CGA is only one chain.","interaction_type":"direct binding","direction_and_effect":"A 2.9-A crystal structure shows human FSH bound to the FSHR extracellular hormone-binding domain, with a conformational change implicated in activation [PMID:15662415]. A peptide mimic of FSHR exoloop 3 photoaffinity-labeled FSH alpha but not FSH beta [PMID:12374801]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Functional ligand is the CGA:FSHB heterodimer; UniProt describes FSHR binding the CGA/FSHB heterodimer [DB:UniProt]. CGA is shared with LH, hCG and TSH [PMID:12374801].","affinity_potency":[],"species_and_systems":"Human proteins; abstract-only papers [PMID:15662415] [PMID:12374801]. Mouse pair is ortholog-inferred.","localisation_and_range":"CGA is flagged secreted; FSHR is transmembrane [flag].","caveats":"Specificity comes from the beta chain, not CGA alone. No affinity reported (GtoPdb units '-') [DB:GtoPdb]. Structures: [DB:PDB 1XWD] [DB:PDB 4AY9]. Two further judged rows not shown, one pending.","key_references":[{"PMID":"15662415","why":"Crystal structure of FSH bound to FSHR ectodomain"},{"PMID":"12374801","why":"FSHR exoloop 3 labels the FSH alpha subunit"}],"covers":["LR000296","LR003803"]},"LR002345":{"pair":"CIRBP -> TLR4","headline":"Extracellular CIRP binds TLR4 and the TLR4-MD2 complex by SPR and acts as a pro-inflammatory agonist; one paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CIRP stimulates TNF-alpha and HMGB1 release from macrophages and causes tissue injury in vivo; CIRP-deficient mice had reduced hemorrhage-induced TNF-alpha/HMGB1 release and lethality [PMID:24097189]. Annotated agonist by curators [PMID:24097189].","molecular_requirements":"CIRP binds the TLR4-MD2 complex as well as TLR4 and MD2 individually [PMID:24097189].","affinity_potency":[],"species_and_systems":"SPR with human proteins; macrophages and animal models of hemorrhage and sepsis [PMID:24097189].","localisation_and_range":"CIRP flagged secreted [flag]; released into the circulation [PMID:24097189].","caveats":"Single paper, read as abstract; no affinity value reported in our evidence. Functional effects were not shown to be TLR4-dependent in our evidence.","key_references":[{"PMID":"24097189","why":"SPR binding of CIRP to TLR4, MD2 and TLR4-MD2; in vivo effects"}],"covers":["LR002345","LR005628"]},"LR005630":{"pair":"CLCF1 -> SORL1","headline":"SorLA binds the CLC:CLF-1 heterodimer through CLF-1, with nanomolar affinity by SPR; it acts as an endocytic regulator rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"CLC:CLF-1 bound immobilised sorLA by surface plasmon resonance, and sorLA can downregulate the CNTFR-alpha pool; the curator labels the effect antagonist [PMID:26858303]. sorLA may also concentrate the tripartite complex on membranes [PMID:26858303].","molecular_requirements":"Binding is via CLF-1: CLC alone did not engage sorLA, and binding was blocked by sorLA propeptide and RAP, indicating the Vps10p-D beta-propeller [PMID:26858303]. The CLC:CLF-1:CNTFR-alpha tripartite complex links to sorLA [PMID:26858303].","affinity_potency":[{"value":"Kd 5 \u00b1 2.9 nM","assay":"SPR, CLC:CLF-1 on immobilised soluble sorLA","system":"purified proteins","cite":"PMID:26858303"},{"value":"Kd 0.3 \u00b1 0.3 nM","assay":"SPR, CLC:CLF-1 to sCNTFR-alpha (comparison)","system":"purified proteins","cite":"PMID:26858303"}],"species_and_systems":"Human proteins, recombinant; SH-SY5Y cells used for pSTAT3 [PMID:26858303]. Mouse pair is ortholog-inferred.","localisation_and_range":"sorLA is flagged a transmembrane receptor and the ligand secreted [flag]; sorLA also binds the soluble complex.","caveats":"Ligand entity is the CLC:CLF-1 heterodimer; the binding site is on CLF-1 (CRLF1), so CLCF1 alone is not shown to bind. IntAct lists the SPR record [DB:IntAct].","key_references":[{"PMID":"26858303","why":"SPR binding of CLC:CLF-1 to sorLA via CLF-1"}],"covers":["LR002348","LR005630"]},"LR005108":{"pair":"Clec2d -> Klrb1b","headline":"Mouse Clr-b (Clec2d) engages inhibitory NKR-P1 receptors on NK cells; three abstract-only papers, functional readouts.","interaction_type":"functional only","direction_and_effect":"Inhibitory: Nkrp1d recognition of Clrb mediated inhibition [PMID:12858173]; Ocil/Clr-b expressed on mouse tumor cell lines inhibits NK cell-mediated killing, blocked by mAb 4A6 [PMID:14990792]; BALB/c NKR-P1B functionally binds Ocil/Clr-b [PMID:16751398].","molecular_requirements":"Receptor members named in the papers are Nkrp1d and NKR-P1B/D; which maps to the Klrb1b symbol is not stated in our evidence. No co-receptor or subunit requirement reported.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; cell-based NK assays and strain analysis (BALB/c); all papers read as abstracts only [PMID:12858173][PMID:14990792][PMID:16751398].","localisation_and_range":"Membrane-bound (ligand not flagged secreted [flag]); Clr-b is displayed on nearly all hematopoietic cells except erythrocytes [PMID:14990792], so contact-dependent signalling.","caveats":"All three papers abstract-only. Direct binding is asserted (12858173 labelled direct_binding) but no affinity is given. Receptor naming differs between papers (Nkrp1d, NKR-P1B).","key_references":[{"PMID":"12858173","why":"Nkrp1d binds Clrb and mediates inhibition"},{"PMID":"14990792","why":"Ocil/Clr-b is the ligand for inhibitory NKR-P1B/D; blocks NK killing"},{"PMID":"16751398","why":"BALB/c NKR-P1B functionally binds Ocil/Clr-b"}],"covers":["LR005108"]},"LR001751":{"pair":"CLEC4G -> LAG3","headline":"LSECtin (CLEC4G) reported to interact with LAG-3 in melanoma; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"LSECtin interacted with LAG-3, and LAG-3 blockade restored IFN\u03b3 secretion reduced by melanoma LSECtin expression, so the effect is inhibitory on T cells [PMID:24769443].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Paper used B16 melanoma cells and mice; the dossier records ligand and receptor species as human. The mouse pair is listed as a separate interaction; the human pair is ortholog-inferred. Abstract only [PMID:24769443].","localisation_and_range":"CLEC4G is not flagged secreted [flag]; presented on melanoma cell surface [PMID:24769443], so contact-dependent.","caveats":"Only the word 'interacted' is available; the assay type, affinity and whether binding is direct are not shown in the abstract, though labelled direct_binding. Single paper.","key_references":[{"PMID":"24769443","why":"LSECtin interacts with LAG-3; LAG-3 blockade restores IFN\u03b3"}],"covers":["LR001751","LR005109"]},"LR002354":{"pair":"CLSTN3 -> NRXN1","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN1 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN1 specifically; the title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown [PMID:32434929]. The UniProt entry Q9ULB1 notes an interaction with CLSTN3 [DB:UniProt Q9ULB1]. The paper notes direct binding had been debated [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002354","LR005634"]},"LR003812":{"pair":"Cntf -> Il6ra","headline":"Mouse pair projected from human data: human CNTF can use IL-6R as a substitute alpha-receptor in signalling assays; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Human CNTF can use membrane-bound and soluble human IL-6R as a substitute for its cognate alpha-receptor, acting as an agonist [PMID:12643274].","molecular_requirements":"Normally CNTF signals via CNTFR plus gp130 and LIFR; IL-6R substitutes for CNTFR when it is absent [PMID:12643274]. Rat CNTF does not use human IL-6Ralpha [PMID:12643274].","affinity_potency":[],"species_and_systems":"Experiments used human CNTF and human IL-6R in signalling assays [PMID:12643274]. The mouse pair is inferred from this human evidence, not tested in mouse in our evidence.","localisation_and_range":"Ligand carries a secreted flag and receptor a receptor flag [flag]; membrane and soluble IL-6R forms both worked [PMID:12643274].","caveats":"Functional readout only, no binding measurement; abstract-only read; species-crossed (human protein evidence for a mouse pair); rat CNTF uses a different route, so the mechanism is species-specific [PMID:12643274].","key_references":[{"PMID":"12643274","why":"Human CNTF uses IL-6R as alpha-receptor"}],"covers":["LR003812"]},"LR002372":{"pair":"CNTN6 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN6; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN6 and PTPRG are both annotated non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN6 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002372","LR005652"]},"LR003821":{"pair":"COL11A1 -> ITGB1","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A1.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"ITGB1 is named only as part of a2b1; a different alpha partner is not tested [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR000315","LR003821"]},"LR002381":{"pair":"COL17A1 -> LAIR1","headline":"Direct binding of LAIR-1 to collagen XVII shown in one full-text paper; inhibitory receptor, human with cross-species binding.","interaction_type":"direct binding","direction_and_effect":"Collagen XVII is a ligand for LAIR-1: human, rat and mouse LAIR-1-IgG bound collagen XVII-transfected Ba/F3 cells, blocked by anti-LAIR-1 antibodies [PMID:16754721]. LAIR-1 cross-linking is known to inhibit immune cell function, and collagens directly inhibit immune cell activation in vitro; the curator records this as antagonist [PMID:16754721].","molecular_requirements":"Binding depends on the conserved Gly-Pro-Hyp collagen repeat, so the effect is pan-collagen rather than specific to this chain; binding was divalent-cation independent [PMID:16754721]. LAIR-2 also bound collagen XVII [PMID:16754721]. Subunit requirements for LAIR-1 beyond the single chain: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human collagen XVII and LAIR-1-IgG fusion proteins on transfected Ba/F3 and K562 cells; mouse and rat LAIR-1 bound human collagen XVII, so the mouse pair is inferred from human evidence [PMID:16754721]. Affinity values in this paper (surface plasmon resonance) were for collagens I and III, not collagen XVII.","localisation_and_range":"Collagen XVII is a transmembrane collagen in this paper (cell-surface ligand on transfected cells); the entity flag lists it as secreted [flag] [PMID:16754721]. Cells expressing collagen XVII and LAIR-1 formed aggregates, consistent with contact-dependent signalling [PMID:16754721].","caveats":"Single paper. No affinity measured for collagen XVII itself. The curator notes the evidence is motif-level and shared by all collagen rows.","key_references":[{"PMID":"16754721","why":"Collagen XVII binds LAIR-1; Gly-Pro-Hyp dependent; inhibitory function"}],"covers":["LR002381","LR005660"]},"LR003830":{"pair":"COL1A1 -> DDR2","headline":"DDR2 is a collagen-activated receptor tyrosine kinase; type I collagen binds and activates it in three papers.","interaction_type":"direct binding","direction_and_effect":"Both DDRs bound collagen I with high affinity in solid-phase assays, and the isolated DDR2 discoidin domain bound collagen I with high affinity [PMID:12611880]. Collagen I and III activated DDR2 phosphorylation in 293 cells [PMID:9659899]. Collagen type I binding to DDR2 was detectable at 1 mg loading by slot blot [PMID:9659900].","molecular_requirements":"The isolated discoidin domain of DDR2 is sufficient for binding and transmembrane signalling, using three adjacent surface loops [PMID:12611880]. Activation needs native triple-helical collagen [PMID:9659899]. Type I collagen is a COL1A1/COL1A2 heterotrimer, not chain-specific.","affinity_potency":[],"species_and_systems":"Recombinant human DDR extracellular domains [PMID:12611880]; bovine and human or mouse collagen with human DDR2 in 293 cells [PMID:9659900] [PMID:9659899].","localisation_and_range":"Receptor is a membrane tyrosine kinase; collagen is matrix, so contact signalling.","caveats":"The affinity is called high but no value is given in the dossier. One paper was read as an abstract only [PMID:12611880]. BioGRID also lists a reconstituted complex [DB:BioGRID, PMID:16884738].","key_references":[{"PMID":"12611880","why":"Solid-phase binding and discoidin domain mapping"},{"PMID":"9659900","why":"Slot-blot binding of DDR2 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR2 phosphorylation"}],"covers":["LR000324","LR003830"]},"LR000329":{"pair":"COL1A1 -> ITGB1","headline":"Beta1 integrins bind type I collagen (alpha11beta1 affinity capture, chondrocyte adhesion blocking); abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Anti-beta1 completely blocked chondrocyte adhesion to native collagens I and II [PMID:7688313]; alpha11beta1 bound collagen type I-Sepharose [PMID:10464311].","molecular_requirements":"Beta1 acts with an alpha chain: alpha11beta1 heterodimer [PMID:10464311]; anti-alpha2 reduced binding by only 40-50% [PMID:7688313]. ITGB1 alone is not shown to bind.","affinity_potency":[],"species_and_systems":"Human alpha11 integrin binding to collagen I-Sepharose [PMID:10464311]; human fetal chondrocyte adhesion [PMID:7688313].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Both papers read as abstracts. Collagen I is a heterotrimer, so COL1A1 is not separated from COL1A2. BioGRID co-purification [DB:BioGRID]. One row was judged different_entity.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen type I-Sepharose"},{"PMID":"7688313","why":"Anti-beta1 blocks chondrocyte adhesion to collagens"}],"covers":["LR000329","LR003835"]},"LR000338":{"pair":"COL2A1 -> ITGA2","headline":"Alpha2 integrin binds and mediates cell adhesion to collagen II in several systems; ITGA2 evidence is mostly alpha2beta1 cell and I-domain studies.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha2 I domain bound collagens I-III [PMID:16043429]. Alpha2beta1 mediated HCS-2/8 chondrosarcoma binding to native type II collagen [PMID:7520045], and alpha2 transfectants spread on collagen types I-V [PMID:10713152]. Collagen to integrin; adhesion/activation.","molecular_requirements":"Cell studies concern the alpha2beta1 heterodimer; alpha2 I domain alone binds collagen in solution [PMID:16043429; PMID:10713152].","affinity_potency":[],"species_and_systems":"Human recombinant I domains [PMID:16043429]; human chondrosarcoma cells [PMID:7520045]; bovine chondrocyte membranes [PMID:7688313]; CHO transfectants, species of cDNA not stated [PMID:10713152]. Mouse pair is projected.","localisation_and_range":"Matrix ligand, cell-surface receptor [flag].","caveats":"Eight papers are confirmed but four are shown; most read as abstracts. Alpha2 binding to denatured collagen differs: denatured collagen used an alpha5beta1-fibronectin bridge [PMID:7520045]. Alpha2I affinity for the three collagens is described as slightly different, but no values appear in our excerpt [PMID:16043429].","key_references":[{"PMID":"16043429","why":"SPR of alpha2 I domain and collagens"},{"PMID":"7520045","why":"Alpha2beta1 binds native collagen II in chondrosarcoma cells"},{"PMID":"10713152","why":"CHO alpha2 cells spread on collagens I-V"}],"covers":["LR000338","LR003844"]},"LR009320":{"pair":"COL2A1 -> ITGA2B","headline":"No usable primary evidence; the only record is a BioGRID entry citing a paper whose verdicts were mostly 'different_entity'.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. BioGRID lists ITGA2B - COL2A1 as a 'Reconstituted Complex' citing PMID:7520045 [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"COL2A1 flagged secreted, ITGA2B flagged receptor [flag].","caveats":"Rests on one BioGRID record. Judged rows: three different_entity, one unresolvable, one abstract_insufficient; no paper confirmed this pair.","key_references":[],"covers":["LR009320"]},"LR002390":{"pair":"COL2A1 -> OSCAR","headline":"OSCAR binds motifs in fibrillar collagens and costimulates osteoclastogenesis; one abstract-read paper, collagen II not singled out.","interaction_type":"direct binding","direction_and_effect":"OSCAR binds specific motifs within fibrillar collagens and this led to signalling that increased osteoclast numbers in culture [PMID:21841309]. Curator label: agonist.","molecular_requirements":"OSCAR signals through FcR gamma-associated ITAM pathways [PMID:21841309]; chain-specific requirements not reported.","affinity_potency":[],"species_and_systems":"Mouse and patient samples deficient in ITAM pathways; mouse rows marked ortholog-inferred though curators say both species were assayed [PMID:21841309].","localisation_and_range":"Matrix ligand, cell-surface receptor (flags).","caveats":"Abstract read only; 'fibrillar collagens' as a class, so COL2A1 specifically is not tested. No database records.","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs"}],"covers":["LR002390","LR005669"]},"LR000347":{"pair":"COL4A1 -> ITGB8","headline":"Beta8 integrins mediate neuron interactions with collagen IV in chick neurons; indirect and abstract only.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 antibody inhibited sensory neurite outgrowth on collagen IV (and laminin-1, fibronectin) [PMID:7542940].","molecular_requirements":"The beta8 subunit associates with one or more alpha subunits, not identified [PMID:7542940]; the curator notes the entity should be folded into a heterodimer.","affinity_potency":[],"species_and_systems":"Chick sensory neurons; human and mouse pairs are inferred by homology [PMID:7542940].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Antibody blockade, not direct binding; abstract only; collagen chain not identified.","key_references":[{"PMID":"7542940","why":"First ligands for beta8 integrins, including collagen IV"}],"covers":["LR000347","LR003853"]},"LR002408":{"pair":"COL4A3 -> ITGB5","headline":"COL4A3 NC1 binds alphaVbeta5 in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"alpha3NC1 binds alpha(v)beta(5) integrin, predominantly via its RGD site, and supports endothelial adhesion [PMID:14610079].","molecular_requirements":"The receptor is the alphaV:beta5 heterodimer; the domain tested is NC1 [PMID:14610079].","affinity_potency":[],"species_and_systems":"Recombinant human domain expressed in HEK293, endothelial cell assays [PMID:14610079].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Single abstract-only paper; no affinity values reported in our evidence.","key_references":[{"PMID":"14610079","why":"alpha3NC1 RGD site binds alphaVbeta3 and beta5"}],"covers":["LR002408","LR005687"]},"LR005117":{"pair":"COMP -> CD47","headline":"COMP-mediated cell attachment depends on CD47 in one functional study; direct binding not demonstrated.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-CD47 antibody reduced ligament-cell attachment to COMP to background levels at 25 \u03bcg/ml; attachment is inhibited by an SFYVVMWK peptide from COMP's C-terminal domain, independent of RGD-dependent attachment [PMID:20033473].","molecular_requirements":"CD47 acts alongside alphaVbeta3 integrin as a parallel, independent attachment mechanism [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells and human fetal chondrocytes attached to recombinant COMP; ligament cell species is not stated in the excerpts [PMID:20033473].","localisation_and_range":"COMP is an extracellular matrix protein per the paper, and carries a secreted flag [flag][PMID:20033473]; CD47 is a transmembrane receptor by flag [flag]; matrix-to-cell contact.","caveats":"The authors state a direct interaction between COMP and CD47 has yet to be demonstrated and other proteins may be involved [PMID:20033473]. Reactome lists the binding reaction (COMP binds Integrin alpha5beta1, alphaVbeta3, CD47) [DB:Reactome R-HSA-2426259]. One paper, abstract-level curation.","key_references":[{"PMID":"20033473","why":"Anti-CD47 antibody blocks cell attachment to COMP"}],"covers":["LR001759","LR005117"]},"LR005711":{"pair":"COMP -> ITGA7","headline":"COMP pulls down alpha7 integrin and alpha7 blockade reduces VSMC adhesion to COMP; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Alpha7 integrin co-immunoprecipitated with COMP in rat VSMCs and vessels; neutralizing antibody or siRNA against alpha7 inhibited VSMC adhesion to COMP, so alpha7beta1 is proposed as a potential COMP receptor. Blocking alpha7 abolished COMP's effect on preserving the contractile phenotype [PMID:20019333].","molecular_requirements":"The authors name alpha7beta1 as the receptor, implying a beta1 partner; subunit requirement is otherwise not reported in our evidence [PMID:20019333].","affinity_potency":[],"species_and_systems":"Rat vascular smooth muscle cells and vessels; human pair, mouse pair ortholog-inferred [PMID:20019333].","localisation_and_range":"COMP is a vascular extracellular matrix protein per the abstract and carries a secreted flag [flag][PMID:20019333].","caveats":"Described only as a potential receptor; co-IP and adhesion blockade, no purified binding or affinity. Abstract only; evidence is rat, projected to human.","key_references":[{"PMID":"20019333","why":"Co-IP and adhesion blockade implicate alpha7beta1 as COMP receptor"}],"covers":["LR002432","LR005711"]},"LR011408":{"pair":"COMP -> ITGAV:ITGB3","headline":"Supported only by database records (Reactome, UniProt); no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; two papers judged abstract_insufficient. Reactome records COMP binding Integrin alphaVbeta3 [DB:Reactome R-HSA-2426259].","molecular_requirements":"Heterodimer ITGAV:ITGB3 is the recorded receptor [DB:Reactome R-HSA-2426259].","affinity_potency":[],"species_and_systems":"Human records; experimental system not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"UniProt statements for ITGB3 ('Interacts with COMP') and for COMP ('Interacts with ITGB3, ITGA5 and FN1') exist [DB:UniProt P05106][DB:UniProt P49747]. No curator-verified paper for this pair.","key_references":[],"covers":["LR011408"]},"LR001760":{"pair":"COMP -> ITGB3","headline":"Anti-alphaVbeta3 antibody reduces cell attachment to COMP; functional evidence only, beta3 as part of the alphaVbeta3 heterodimer.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-alphaVbeta3 antibody reduced cell attachment to COMP, alongside anti-CD47; this is agonist-type adhesion [PMID:20033473].","molecular_requirements":"Evidence concerns the alphaVbeta3 heterodimer, not ITGB3 alone [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells attached equally to purified human COMP and recombinant mouse COMP ('almost identical'); ligament cell species not stated in excerpts [PMID:20033473].","localisation_and_range":"Extracellular matrix ligand acting on a cell-surface receptor [PMID:20033473].","caveats":"Antibody blocking only; no binding assay. Chain-level entry for a heterodimer. A further review_only paper was judged. Reactome lists the reaction [DB:Reactome R-HSA-2426259].","key_references":[{"PMID":"20033473","why":"Anti-alphaVbeta3 antibody reduces COMP attachment; human and mouse COMP compared"}],"covers":["LR001760","LR005118"]},"LR000365":{"pair":"CORT -> GHSR","headline":"Cortistatin displaces a radioligand from human pituitary membranes at about 10^-7 M; one abstract-level binding paper.","interaction_type":"direct binding","direction_and_effect":"In competition binding, ghrelin and cortistatin (CST) fully displaced 125I-Tyr-Ala-hexarelin from pituitary membranes, whereas somatostatin fragments did not [PMID:11227737].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"4.6-5.4e-7 M (ghrelin and cortistatin, similar affinity)","assay":"125I-Tyr-Ala-hexarelin competition binding","system":"human pituitary membranes","cite":"PMID:11227737"}],"species_and_systems":"Human pituitary membranes; mouse pair is ortholog-inferred [PMID:11227737].","localisation_and_range":"CORT is secreted by flag [flag]; GHSR is a transmembrane receptor by flag [flag].","caveats":"About four orders of magnitude weaker than hexarelin [PMID:11227737]. Native membranes rather than recombinant GHSR, so receptor identity is inferred; abstract only; one further paper is still pending.","key_references":[{"PMID":"11227737","why":"Cortistatin displaces hexarelin radioligand on pituitary membranes"}],"covers":["LR000365","LR003871"]},"LR002435":{"pair":"CR2 -> FCER2","headline":"CD21 (CR2) and CD23 (FCER2) bind directly in one 1992 paper; the ligand and receptor roles are ambiguous.","interaction_type":"direct binding","direction_and_effect":"Fluorescent CD23-liposomes bound CD21 on B cells and CD21-transfected BHK-21 cells, blocked by anti-CD21 and anti-CD23 antibodies; triggering CD21 with antibody or soluble CD23 increased IL-4-induced IgE production [PMID:1386409].","molecular_requirements":"UniProt records CD23 interacting via its C-terminus with CD21 Sushi domains 1 and 2 [DB:UniProt P06734].","affinity_potency":[],"species_and_systems":"Human B cells, blood mononuclear cells and transfected BHK-21 cells [PMID:1386409].","localisation_and_range":"Both are membrane proteins by flags; FCER2 carries both secreted and transmembrane flags [flag]; soluble CD23 is active per the paper [PMID:1386409].","caveats":"The paper describes CD21 as the ligand for CD23 and UniProt calls CD23 the ligand for CD21, whereas this entry lists CR2 as ligand [PMID:1386409][DB:UniProt P20023]. Abstract only; no affinity. BioGRID and IntAct also list it [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"1386409","why":"CD23-liposomes bind CD21; effect on IgE production"}],"covers":["LR002435"]},"LR004820":{"pair":"CRIPTO -> ACVR1B","headline":"Cripto binds ALK4 (ACVR1B) directly and acts as a Nodal co-receptor; also blocks activin signalling.","interaction_type":"direct binding","direction_and_effect":"Cripto binds ALK4 and enables Nodal signalling through it [PMID:11485994, PMID:11909953]. The synthetic CFC domain binds ALK4, and the paper frames this as blocking the activin/ALK4 pathway [PMID:19035567]. Cripto is a co-factor rather than a conventional signalling ligand [PMID:11485994].","molecular_requirements":"ALK4 mediates Nodal signalling only in the presence of Cripto [PMID:11485994]. Smad-2 phosphorylation required both Nodal and ALK4, whereas MAPK/AKT activation did not [PMID:11909953]. The CFC domain alone binds ALK4 but not ActRIIB [PMID:19035567].","affinity_potency":[{"value":"K(D) in micro M range","assay":"SPR binding of synthetic CFC domain to ALK4","system":"synthetic human Cripto CFC domain","cite":"PMID:19035567"}],"species_and_systems":"Human CFC domain in vitro [PMID:19035567]; mouse and human mammary epithelial cells [PMID:11909953]; vertebrate development model [PMID:11485994]. Human and mouse pairs are listed.","localisation_and_range":"CRIPTO is flagged secreted [flag]; papers describe it as a GPI-anchored co-receptor/co-factor [PMID:11909953].","caveats":"All three papers read as abstracts only. BioGRID lists a reconstituted ACVR2A-TDGF1 complex only [DB:BioGRID]. Part of Cripto activity is ALK4-independent [PMID:11909953].","key_references":[{"PMID":"11909953","why":"Binding by phage display, FACS and co-IP"},{"PMID":"19035567","why":"CFC domain SPR/NMR with ALK4"},{"PMID":"11485994","why":"Cripto with ALK4/ALK7 in Nodal signalling"}],"covers":["LR001425","LR004820"]},"LR001427":{"pair":"CRIPTO -> ACVR2A","headline":"Cripto associates with ActRII (ACVR2A) only as part of an activin ternary complex, where it blocks activin signalling.","interaction_type":"direct binding","direction_and_effect":"Cripto forms a complex with activin and ActRII/IIB and, with ALK4 and ActRII/IIB cotransfected, inhibits activin crosslinking to ALK4 and blocks ALK4-ActRII/IIB association, blocking activin signalling in HepG2 and 293T cells [PMID:12682303]. The effect is antagonism of activin.","molecular_requirements":"Activin binding to Cripto was undetectable without ActRII/IIB, so a type II receptor is required, unlike Nodal [PMID:12682303].","affinity_potency":[],"species_and_systems":"Human cell lines (HepG2, 293T) [PMID:12682303]. Human pair is inferred from mouse; BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Read as abstract only. This is not shown as an independent pairwise Cripto-ActRIIA interaction; the ligand-receptor framing is indirect.","key_references":[{"PMID":"12682303","why":"Cripto-activin-ActRII complex that blocks activin signalling"}],"covers":["LR001427","LR004822"]},"LR005720":{"pair":"Crp -> Fcgr1","headline":"Mouse pair projected from human data; CRP binds Fc\u03b3RI in human-cell and SPR experiments, with micromolar affinity.","interaction_type":"direct binding","direction_and_effect":"CRP binding was blocked by an Fc\u03b3RI-specific antibody but not by anti-Fc\u03b3RII antibodies, and bound CRP co-localised with Fc\u03b3RI; effect labelled agonist by the curators [PMID:18412163]. An SPR array confirmed CRP binding to Fc\u03b3RIa [PMID:33790888]; blocking Fc\u03b3RIa abrogated CRP's amplification of IgG-mediated neutrophil functions [PMID:33790888].","molecular_requirements":"Single receptor chain Fc\u03b3RI; no co-subunit requirement reported in our evidence.","affinity_potency":[{"value":"KD (6.6 +/- 1.5) microM","assay":"live-cell confocal imaging of fluorescent CRP binding","system":"human Mono Mac 6 cells","cite":"PMID:18412163"}],"species_and_systems":"All experiments were human (human cell line, recombinant human receptors); the mouse pair is ortholog-inferred, with no mouse experiment in our evidence [PMID:18412163, PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Mouse relevance rests on projection from human. One paper was read as abstract only [PMID:18412163]. Affinity is low (micromolar).","key_references":[{"PMID":"18412163","why":"live-cell binding, Fc\u03b3RI-specific, KD in micromolar range"},{"PMID":"33790888","why":"SPR array of CRP against human Fc\u03b3Rs"}],"covers":["LR005720"]},"LR002444":{"pair":"CRP -> FCGR2B","headline":"CRP binds Fc\u03b3RIIb by SPR and drives Fc\u03b3RIIB-dependent endothelial effects in mice; functional and binding support.","interaction_type":"direct binding","direction_and_effect":"SPR showed CRP binding to Fc\u03b3RIIb [PMID:33790888]. In mice, elevated CRP caused insulin resistance in mice with endothelial Fc\u03b3RIIB but not in mice lacking it; in culture CRP suppressed endothelial insulin transcytosis via Fc\u03b3RIIB activation [PMID:27207525]. This is an activating effect on the receptor.","molecular_requirements":"Single chain Fc\u03b3RIIB; downstream eNOS antagonism reported [PMID:27207525].","affinity_potency":[],"species_and_systems":"SPR with human recombinant proteins [PMID:33790888]; mouse genetics (CRP transgenic, endothelial Fc\u03b3RIIB-deficient) for function [PMID:27207525]; species of cultured cells not reported in our evidence.","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"The mouse study is functional and does not itself show binding [PMID:27207525].","key_references":[{"PMID":"33790888","why":"SPR binding to Fc\u03b3RIIb"},{"PMID":"27207525","why":"endothelial Fc\u03b3RIIB required for CRP-induced insulin resistance"}],"covers":["LR002444","LR005721"]},"LR000374":{"pair":"CRP -> OLR1","headline":"CRP interacts with LOX-1 in a calcium-dependent way and triggers complement activation; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"CRP increased complement activation in LOX-1-expressing CHO cells but not native CHO cells, and activated the C1q-requiring classical pathway on immobilised recombinant LOX-1; anti-LOX-1 antibody reduced complement activation and leukocyte infiltration after CRP injection in hypertensive rats [PMID:21821723]. Curators label it an agonist effect [PMID:21821723].","molecular_requirements":"The interaction is Ca2+-dependent and competes with phosphocholine, suggesting LOX-1 binds the CRP B-face [PMID:21821723]. Annotated as transmembrane [flag].","affinity_potency":[],"species_and_systems":"Human CRP and LOX-1 in cultured CHO cells and recombinant protein; in vivo in hypertensive rats [PMID:21821723]. Mouse pair is ortholog-inferred.","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only). The receptor is flagged transmembrane [flag].","caveats":"Abstract-only read; no affinity reported. The direct-binding claim in the abstract is partly background from earlier work, and this paper's own readouts are complement activation and competition [PMID:21821723].","key_references":[{"PMID":"21821723","why":"LOX-1-dependent complement activation by CRP"}],"covers":["LR000374","LR003880"]},"LR002453":{"pair":"CTSG -> FPR1","headline":"Cathepsin G is a chemotactic agonist at FPR1 per one abstract-read paper and UniProt.","interaction_type":"functional only","direction_and_effect":"Cathepsin G chemoattracts FPR-expressing RBL cells but not parental cells or cells with other chemoattractant receptors; an anti-FPR antibody and cyclosporin H abolished chemotaxis, so it is an agonist [PMID:15210802]. UniProt states it acts as a ligand for FPR1 [DB:UniProt].","molecular_requirements":"Atypical PKCzeta was essential for chemotaxis; cathepsin G is a weaker Ca2+/MAPK activator than fMLP [PMID:15210802].","affinity_potency":[],"species_and_systems":"Human FPR in rat basophilic leukemia cells and human phagocytes; mouse pair ortholog-inferred [PMID:15210802].","localisation_and_range":"CTSG flagged secreted [flag]; paracrine from neutrophil granules.","caveats":"Functional chemotaxis, no binding or affinity measurement in our evidence; abstract only; one further paper pending.","key_references":[{"PMID":"15210802","why":"Cathepsin G identified as chemotactic agonist for FPR"}],"covers":["LR002453","LR005729"]},"LR000392":{"pair":"CXCL10 -> CCR3","headline":"CXCL10 competes with eotaxin for CCR3 and acts as an antagonist; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"CXCL10 (IP10) competed for eotaxin binding to CCR3 and inhibited CCR3-mediated signalling, without inducing CCR3 internalisation, i.e. antagonist behaviour [PMID:11110785]. GtoPdb lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of ligand and receptor not clearly stated; curator labels not given in the shown fields. Mouse pair is projected from human evidence.","localisation_and_range":"CXCL10 is flagged secreted and CCR3 transmembrane [flag].","caveats":"Read from the abstract only. No affinity value reported in our evidence.","key_references":[{"PMID":"11110785","why":"CXCR3 agonists act as CCR3 antagonists"}],"covers":["LR000392","LR003898"]},"LR003902":{"pair":"CXCL11 -> CXCR3","headline":"CXCL11 is a high-affinity agonist of CXCR3, supported by binding, functional and database evidence.","interaction_type":"direct binding","direction_and_effect":"I-TAC/CXCL11 interacts selectively with CXCR3 with significantly higher affinity than IP-10 and HuMig, with higher potency and efficacy in calcium mobilization and chemotaxis in activated T cells and CXCR3 transfectants [PMID:9625760]. Potency rank CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. In mouse CXCR3 transfectants, ITAC induced chemotaxis and calcium increases [PMID:10556837]. GtoPdb lists a full agonist [DB:GtoPdb]. Activating.","molecular_requirements":"Single receptor chain; CXCL11 is monomeric at millimolar concentrations in an NMR study of the free ligand [PMID:15273303]. Binding determinants are not reported in our evidence.","affinity_potency":[{"value":"KD 1.41 +/- 0.20 nM","assay":"ligand binding to transfected cells","system":"murine CXCR3 in L1.2 cells","cite":"PMID:10556837"},{"value":"pKi 10.4-10.5","assay":"GtoPdb affinity record","system":"human, per database","cite":"PMID:15761110"}],"species_and_systems":"Human ligand and receptor in most papers [PMID:9625760][PMID:15761110]; the KD above comes from murine CXCR3 [PMID:10556837]. Mouse pair is listed.","localisation_and_range":"CXCL11 flagged secreted, CXCR3 transmembrane [flag]; paracrine.","caveats":"Most papers read as abstracts. 15273303 is a free-ligand NMR structure with no receptor experiment. In 12884299 CXCL11 agonism at CXCR3 is background; its own finding is CCR3 antagonism.","key_references":[{"PMID":"9625760","why":"Identification of I-TAC as the highest-affinity CXCR3 ligand"},{"PMID":"15761110","why":"Ligand potency rank order and Ki-based pharmacology"},{"PMID":"10556837","why":"Murine CXCR3 binding KD for ITAC"}],"covers":["LR000397","LR003902"]},"LR002462":{"pair":"CXCL12 -> ACKR1","headline":"Dimeric CXCL12 binds the ACKR1 N terminus with low nanomolar affinity; single abstract-read paper, human system.","interaction_type":"direct binding","direction_and_effect":"Dimeric CXCL12 bound the extracellular N terminus of ACKR1 with low nanomolar affinity by NMR and ITC, whereas monomeric CXCL12 bound orders of magnitude more weakly [PMID:34404752]. In transfected MDCK cells and primary human Duffy-positive erythrocytes, dimeric but not monomeric CXCL12 bound and internalised with ACKR1 [PMID:34404752]. ACKR1 is atypical, so this is retention or internalisation, not signalling.","molecular_requirements":"CXCL12 oligomeric state matters: dimer binds, monomer binds weakly; ACKR1 N terminus is the binding region [PMID:34404752].","affinity_potency":[{"value":"low nanomolar","assay":"NMR and ITC, dimeric CXCL12 to ACKR1 N terminus","system":"recombinant proteins","cite":"PMID:34404752"}],"species_and_systems":"Human proteins, MDCK transfectants and human erythrocytes [PMID:34404752]. Mouse pair is projected from human by ortholog inference, not tested.","localisation_and_range":"CXCL12 flagged secreted, ACKR1 transmembrane [flag]; chemokine presentation or retention on cells.","caveats":"One paper read as abstract and excerpts; the paper notes previous reports gave contradicting claims on CXCL12-ACKR1 [PMID:34404752]. No database support in our evidence.","key_references":[{"PMID":"34404752","why":"NMR/ITC and cell evidence for dimeric CXCL12 binding ACKR1"}],"covers":["LR002462","LR005736"]},"LR005126":{"pair":"CXCL12 -> ITGA5","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alpha5beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alpha5beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGA5 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001769","LR005126"]},"LR003911":{"pair":"CXCL2 -> CXCR1","headline":"Weak or indirect support: low-affinity binding and a functional readout, with an explicit report that CXCR1 is selective for IL-8.","interaction_type":"conflicting","direction_and_effect":"CXCL2 acts as an agonist for ASMC migration; in asthmatic cells migration is mainly PI3K-mediated through CXCR1, whereas normal-cell CXCL2 migration depended on p38 MAPK and CXCR2 [PMID:23904157].","molecular_requirements":"Not reported in our evidence beyond receptor-dependence by neutralizing antibody/siRNA [PMID:23904157].","affinity_potency":[{"value":"Kd > 120 nM","assay":"binding of recombinant murine MIP-2 to human type A IL-8 receptor","system":"recombinant, human receptor","cite":"PMID:9260277"}],"species_and_systems":"Human primary airway smooth muscle cells (normal and asthmatic) [PMID:23904157]; HEK293 transfectants for the other papers. Murine MIP-2 was tested on human receptors [PMID:9260277].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"An abstract-read paper states IL-8RA (CXCR1) is selective only for IL-8 and counted as a verified negative for this pair [PMID:8550564]. GRO-family chemokines competed only weakly at IL8RA [PMID:8702798]. The mouse ligand showed low-affinity binding to type A receptor [PMID:9260277]. The positive CXCR1 evidence for CXCL2 is a functional, abstract-only report. All papers abstract-only.","key_references":[{"PMID":"23904157","why":"CXCL2 migration of ASMCs; CXCR1 role in asthmatic cells"},{"PMID":"9260277","why":"Kd > 120 nM at type A receptor"},{"PMID":"8550564","why":"Reports CXCR1 selective only for IL-8"}],"covers":["LR000409","LR003911"]},"LR002471":{"pair":"CXCL6 -> ACKR1","headline":"Direct binding of CXCL6 to the Duffy antigen on human erythrocytes (single study, Ki 66.7 nM).","interaction_type":"direct binding","direction_and_effect":"CXCL6 bound strongly (category Ki < 100 nM) to the Duffy antigen; this is binding to an atypical chemokine receptor, with no signalling effect reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 66.7 nM","assay":"125I-CXCL8 competition displacement","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, human proteins [PMID:15358176].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Single paper; the individual Ki comes from a table not shown in the excerpts. No database record.","key_references":[{"PMID":"15358176","why":"Ki for CXCL6 at Duffy antigen"}],"covers":["LR002471"]},"LR000923":{"pair":"CXCL8 -> ACKR1","headline":"Direct binding of CXCL8 to the Duffy antigen (Ki 21.3 nM), supported by Reactome and a PDB structure.","interaction_type":"direct binding","direction_and_effect":"CXCL8 bound strongly (Ki < 100 nM category) to the Duffy antigen on human erythrocytes; endothelial binding of 125I-CXCL8 was also seen in synovia [PMID:15358176]. Reactome describes DARC as a non-specific receptor for many chemokines [DB:Reactome R-HSA-374251]. No signalling effect is reported.","molecular_requirements":"Not reported in our evidence. PDB 8YNF has a chain of P10145 and a chain of Q16570 [DB:PDB 8YNF].","affinity_potency":[{"value":"Ki 21.3 nM","assay":"125I-CXCL8 competition displacement","system":"human erythrocytes","cite":"PMID:15358176"},{"value":"Kd 19.5 nM","assay":"125I-CXCL-8 saturation","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes and synovia [PMID:15358176].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Only one verified paper; the Ki for this pair comes from a table not shown here.","key_references":[{"PMID":"15358176","why":"Ki for CXCL8 at Duffy antigen"}],"covers":["LR000923"]},"LR000419":{"pair":"CXCL9 -> CXCR3","headline":"CXCL9 (Mig) is a CXCR3 agonist, directly bound with nM affinity in human and mouse receptor systems; strongly supported.","interaction_type":"direct binding","direction_and_effect":"Agonist (stimulatory). CXCL9 binds CXCR3 and induces chemotaxis and calcium rise with mouse CXCR3 [PMID:10556837]. Human HMEC-1 cells with CXCR3-A or CXCR3-B both bound CXCL9 [PMID:12782716]. Potency rank order was CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Both CXCR3 splice isoforms, CXCR3-A and CXCR3-B, bind CXCL9, with different downstream effects (pro-survival vs. pro-apoptotic) [PMID:12782716].","affinity_potency":[{"value":"Ki 4.9 nM","assay":"radioligand competition binding","system":"heterologously expressed human CXCR3","cite":"PMID:9660793"},{"value":"Kd 11.65 nM","assay":"binding of Mig","system":"murine CXCR3 in L1.2 pre-B cells","cite":"PMID:10556837"}],"species_and_systems":"Human CXCR3 with human ligand [PMID:9660793, PMID:12782716]; murine CXCR3 with human ligand [PMID:10556837]. Dossier covers human and mouse pairs.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Most papers abstract-only. The mouse-CXCR3 Kd is listed in the abstract for Mig among IP10, ITAC and Mig. CXCL9 binds CXCR3 more weakly than CXCL10 or CXCL11 [PMID:15761110]. CXCL9 also antagonises CCR3, a separate action; the CXCR3 agonist label here is background in PMID:12884299.","key_references":[{"PMID":"9660793","why":"CXCR3 binds MIG, Ki 4.9 nM"},{"PMID":"12782716","why":"binds both CXCR3-A and CXCR3-B"},{"PMID":"10556837","why":"mouse CXCR3 binding and chemotaxis"}],"covers":["LR000419","LR003916"]},"LR002480":{"pair":"DEFB103A -> CCR2","headline":"DEFB103A (hBD-3) is a noncognate CCR2 agonist with binding, chemotaxis and knockout evidence.","interaction_type":"direct binding","direction_and_effect":"Agonist: hBD3:Ig bound CCR2-transfected HEK293 cells and induced CCR2-specific chemotaxis; CCL2/MCP-1 preincubation abolished this and reciprocally hBD3:Ig inhibited MCP-1 migration; Ccr2-deficient mouse cells failed to migrate [PMID:20483750].","molecular_requirements":"Not reported in our evidence beyond CCR2.","affinity_potency":[],"species_and_systems":"Human CCR2 HEK293 cells, human monocytes, mouse peritoneal exudate cells; hBD3 fused to human IgG1 Fc [PMID:20483750]. No binding to CXCR4 cells in the same paper.","localisation_and_range":"DEFB103A flagged secreted; CCR2 transmembrane receptor [flag].","caveats":"One paper (abstract plus excerpts); Fc-fusion ligand; no affinity reported. Reactome records the complex [DB:Reactome R-HSA-1973966].","key_references":[{"PMID":"20483750","why":"hBD3 binds and activates CCR2"}],"covers":["LR002480"]},"LR000428":{"pair":"DEFB103A -> CCR6","headline":"CCR6 evidence for DEFB103A here is only a background statement; no primary data in this paper.","interaction_type":"functional only","direction_and_effect":"Not tested: the paper cites previous studies of beta-defensin chemoattraction through CCR6 as background [PMID:20483750]. Reactome records beta-defensins 1, 4A and 103 binding CCR6 [DB:Reactome R-HSA-1471338].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported for CCR6; the paper's experiments targeted CCR2, in monocytes that lack CCR6 [PMID:20483750].","localisation_and_range":"DEFB103A flagged secreted; CCR6 transmembrane receptor [flag].","caveats":"Support is a database assertion plus background citation; Reactome cites PMIDs 10521347, 10914484 and 11934878 [DB:Reactome R-HSA-1471343].","key_references":[],"covers":["LR000428"]},"LR000437":{"pair":"DHH -> HHIP","headline":"Well supported direct binding: crystal structure of the HHIP-DHH complex, plus a paper showing Hip binds all three mammalian Hedgehogs.","interaction_type":"direct binding","direction_and_effect":"HHIP is a vertebrate-specific inhibitor of Hh signalling; the structure of human HHIP ectodomain with DHH was solved [PMID:19561611]. Hip binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1, and is proposed to attenuate Hedgehog signalling as a negative feedback [PMID:10050855].","molecular_requirements":"Interaction determinants were confirmed by biophysical studies and mutagenesis; Zn2+ makes a key contribution to the Hh-HHIP interface and Ca2+ likely prevents electrostatic repulsion [PMID:19561611]. A single receptor chain is involved; no co-receptor is reported.","affinity_potency":[],"species_and_systems":"Human HHIP ectodomain and DHH in crystal structures (recombinant) [PMID:19561611]; the 1999 work concerns mammalian Hip and Hedgehog proteins [PMID:10050855]. Database records: PDB 2WG3, IntAct solid phase assay and molecular sieving, UniProt [DB:PDB 2WG3] [DB:IntAct] [DB:UniProt].","localisation_and_range":"HHIP is flagged as a receptor, not transmembrane, while DHH is flagged secreted and transmembrane [flag]; the 1999 paper describes Hip as a membrane glycoprotein [PMID:10050855].","caveats":"Both confirmed papers were read as abstract or full text without a numeric affinity for DHH in our excerpts; the 1999 paper gives affinity only as comparable to Ptc-1. Two further rows were abstract-insufficient.","key_references":[{"PMID":"19561611","why":"Crystal structure of HHIP-DHH complex"},{"PMID":"10050855","why":"Hip binds all three mammalian Hedgehog proteins"}],"covers":["LR000437","LR003929"]},"LR005135":{"pair":"DKK4 -> KREMEN1","headline":"DKK4 CRD2 binds the Kremen1 extracellular domain with high affinity in a structural/binding study; one paper.","interaction_type":"direct binding","direction_and_effect":"Dkk4 cysteine-rich domain 2 (CRD2) mediates high-affinity binding to the Kremen1 extracellular domain; Dkk and Krm function synergistically to inhibit Wnt signalling [PMID:29925589]. Curator effect: antagonist.","molecular_requirements":"CRD2 is the Krm-binding region; the N-terminal region alone did not interact with Krm proteins [PMID:29925589]. Ternary Dkk-Krm-LRP5/6 complexes are proposed [PMID:29925589].","affinity_potency":[],"species_and_systems":"Human proteins, recombinant NMR/binding study; the human pair is not ortholog-inferred, the mouse pair is [PMID:29925589].","localisation_and_range":"Soluble recombinant domains used; Kremen1 is a transmembrane receptor [flag].","caveats":"One paper. The excerpt gives affinities only for other Dkks from earlier work, not for Dkk4, and no Dkk4 value is stated in our evidence [PMID:29925589]. No database record.","key_references":[{"PMID":"29925589","why":"Dkk4 CRD2 binds Krm1 ectodomain and LRP6 E1E2"}],"covers":["LR001779","LR005135"]},"LR000446":{"pair":"DLK1 -> NOTCH1","headline":"DLK1 interacts with NOTCH1 EGF-like repeats and inhibits NOTCH signalling; one primary paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"DLK1 interacts with specific EGF-like repeats of the NOTCH1 extracellular region involved in canonical ligand binding, inhibiting basal NOTCH signalling in preadipocytes and mesenchymal multipotent cells; DLK1 and DLK2 act as inhibitory non-canonical ligands [PMID:21419176]. This is described from the authors' earlier reports.","molecular_requirements":"DLK1 also interacts with itself; a membrane DLK1 variant lacking the TACE recognition sequence also inhibits NOTCH signalling [PMID:21419176].","affinity_potency":[],"species_and_systems":"Cell studies in preadipocytes and mesenchymal cells; human pair ortholog-inferred, mouse pair direct [PMID:21419176]. Reactome lists a NOTCH1:DLK1 plasma membrane complex [DB:Reactome].","localisation_and_range":"DLK1 flagged both secreted and transmembrane [flag]; the TACE-sequence finding concerns shedding [PMID:21419176].","caveats":"The curated paper is mainly about DLK2 and refers to DLK1 findings from previous reports; abstract only. Two review-only papers not shown. No affinity reported.","key_references":[{"PMID":"21419176","why":"DLK1/DLK2 inhibitory non-canonical NOTCH1 ligands"}],"covers":["LR000446","LR003938"]},"LR005144":{"pair":"DSC2 -> DSG2","headline":"DSC2 -> DSG2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct, PDB, UniProt), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct] [DB:PDB 5J5J] [DB:PDB 7A7D] [DB:UniProt]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001788","LR005144"]},"LR005153":{"pair":"DSG2 -> DSC3","headline":"DSG2 -> DSC3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001797","LR005153"]},"LR000455":{"pair":"EBI3 -> IL27RA","headline":"EBI3 is a subunit of IL-27; IL27RA engagement is by the complex, so this chain-level pair is inferred.","interaction_type":"functional only","direction_and_effect":"IL-27 (EBI3 + p28) acts through WSX-1/TCCR (IL27RA) as agonist; this is functional attribution, not a binding measurement [PMID:12121660].","molecular_requirements":"EBI3 is not an independent IL27RA ligand; it needs p28 to form IL-27 [PMID:12121660]. Structures of IL27RA/IL6ST chains with EBI3 are in the PDB [DB:PDB 7U7N][DB:PDB 8D85]; UniProt describes IL6ST as a signal-transducing subunit for p28/EBI3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-only functional study of naive CD4+ T cells.","localisation_and_range":"EBI3 is flagged as secreted [flag].","caveats":"Database records (BioGRID Affinity Capture-Western, Reactome, GtoPdb agonist) are at complex level. A curator note warns not to read this as EBI3 monomer binding.","key_references":[{"PMID":"12121660","why":"IL-27 identified as EBI3 + p28 acting via WSX-1"}],"covers":["LR000455","LR003946"]},"LR002507":{"pair":"EDIL3 -> ITGAL","headline":"Del-1 (EDIL3) interferes with LFA-1-dependent leukocyte-endothelial adhesion; functional only.","interaction_type":"functional only","direction_and_effect":"Antagonist: Del-1 interferes with LFA-1-dependent leukocyte-endothelial adhesion in Del-1 and Del-1/LFA-1 double-deficient mice [PMID:19008446].","molecular_requirements":"Chain-only: LFA-1 is ITGAL plus ITGB2; the partner chain is not reported in this paper's abstract.","affinity_potency":[],"species_and_systems":"Mouse in vitro and in vivo (the mouse pair is the direct one; the human pair is ortholog-inferred).","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only; a direct binding assay is not stated, and the curator notes it is functional interference.","key_references":[{"PMID":"19008446","why":"Del-1 interferes with LFA-1-dependent adhesion"}],"covers":["LR002507","LR005775"]},"LR000464":{"pair":"EDN3 -> EDNRA","headline":"ET-3 reaches ETA only weakly in our evidence; two abstract-read papers, with unclear support.","interaction_type":"conflicting","direction_and_effect":"ET-3 produced gallbladder contraction acting mainly via ETB and also interacting with ETA [PMID:11982704]. A cloned-ETA displacement study reports BQ123 with a potency similar to ET-3 against 125I-ET-1 [PMID:8440682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human gallbladder muscle strips and an opossum model [PMID:11982704]; COS cells with cloned ETA [PMID:8440682]. Mouse pair is ortholog-inferred.","localisation_and_range":"ET-3 secreted, EDNRA transmembrane [flag].","caveats":"The functional paper attributes the effect mainly to ETB, so ETA involvement is secondary [PMID:11982704]. The binding paper gives no ET-3 affinity number in our evidence. Both read as abstracts only. Reactome lists generic EDN binding by EDNRA [DB:Reactome R-HSA-9731924].","key_references":[{"PMID":"11982704","why":"ET-3 gallbladder contraction, ETB main and ETA also"},{"PMID":"8440682","why":"cloned human ETA binding pharmacology"}],"covers":["LR000464","LR003955"]},"LR000473":{"pair":"EFNA1 -> EPHA7","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA7 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000473","LR003964"]},"LR000482":{"pair":"EFNA2 -> EPHA8","headline":"Database-only: UniProt says EFNA2 interacts with EPHA8; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT: Interacts with EPHA8 [DB:UniProt PMID:19836338]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair ortholog-inferred.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA8 transmembrane [flag].","caveats":"Single database annotation, no paper evidence.","key_references":[],"covers":["LR000482","LR003973"]},"LR000491":{"pair":"EFNA4 -> EPHA1","headline":"Only a UniProt note: EphA1 binds EFNA4 with low affinity; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says EPHA1 binds 'with a low affinity EFNA3 and EFNA4' and with high affinity EFNA1, its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane; EPHA1 is flagged membrane-bound [flag].","caveats":"No curator-verified paper (all judged papers review-only); evidence is one database statement.","key_references":[],"covers":["LR000491","LR003982"]},"LR000509":{"pair":"EFNB1 -> EPHB1","headline":"Functional ligand-stimulation evidence in mouse cells plus database statements of high-affinity binding; no primary binding paper shown.","interaction_type":"functional only","direction_and_effect":"Stimulating endogenous EphB1 with its ligand ephrinB1 in P19 embryonal carcinoma cells increased EphB1 association with Grb7 [PMID:12223469]. UniProt states ephrin-B1 shows high affinity for EPHB1 [DB:UniProt]. Annotated stimulatory.","molecular_requirements":"Grb7 binding requires EphB1 tyrosine autophosphorylation, with Tyr-928 as the main site [PMID:12223469].","affinity_potency":[],"species_and_systems":"Mouse P19 cells [PMID:12223469]. Pair listed for human (not ortholog-inferred) and mouse (ortholog-inferred). IntAct has a solid phase assay record [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"The paper is about Grb7 binding to EphB1, abstract only; ligand binding itself was not measured there. UniProt cites PMID 7973638 and 8070404, which are not in our judged papers [DB:UniProt].","key_references":[{"PMID":"12223469","why":"Ephrin-B1 stimulation of endogenous EphB1 in P19 cells"}],"covers":["LR000509","LR004000"]},"LR000518":{"pair":"EFNB2 -> EPHB1","headline":"Ligand activity reported in a 1995 cloning paper and a neurite-outgrowth study; no affinity data.","interaction_type":"direct binding","direction_and_effect":"LERK-5 (ephrin-B2) is a ligand for elk and hek and induces receptor phosphorylation [PMID:8559144]. Ephrin-B2 inhibited neurite outgrowth of substantia nigra dopaminergic neurons, which express high EphB1, but not ventral tegmental neurons with low EphB1 [PMID:10066262]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine cDNAs [PMID:8559144]; neuron work species not reported in our evidence [PMID:10066262]. Pair listed for human and mouse (ortholog-inferred).","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Both abstract level; the neurite result is correlative with receptor expression, and its quote was browser-read and unverified. Elk to EPHB1 is a curator mapping.","key_references":[{"PMID":"8559144","why":"LERK-5 binds elk/hek and induces phosphorylation"},{"PMID":"10066262","why":"Ephrin-B2/EphB1 inhibit nigral dopaminergic neurites"}],"covers":["LR000518","LR004009"]},"LR000527":{"pair":"EFNB3 -> EPHB2","headline":"Weak binding in ELISA plus a synapse-density paper in which ephrin-B3 acts via intracellular Erk1/2.","interaction_type":"direct binding","direction_and_effect":"A trans-synaptic EphB2 (presynaptic) to ephrin-B3 (postsynaptic) interaction regulates synapse density and spine formation [PMID:20410461]. Ephrin-B3 Fc binds most weakly to all EphB receptors [PMID:22568954].","molecular_requirements":"Ephrin-B3 is said to bind Erk1/2 directly to inhibit postsynaptic Ras/MAPK signalling [PMID:20410461].","affinity_potency":[],"species_and_systems":"Cultured cortical neurons [PMID:20410461]; ELISA species unspecified. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract level; binding of EphB2 to ephrin-B3 is assumed, not measured, in the synapse paper. ELISA quote unverified.","key_references":[{"PMID":"20410461","why":"EphB2/ephrin-B3 regulates synapse density"},{"PMID":"22568954","why":"ELISA weak binding of ephrin-B3 Fc"}],"covers":["LR000527","LR004018"]},"LR004019":{"pair":"EFNB3 -> EPHB3","headline":"Direct binding with a Kd of approximately 1 nM, described as selective.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B3 had a high-affinity interaction with EphB3 among five receptors tested for transmembrane-ligand binding [PMID:9484836]. ELISA shows ephrin-B3 Fc binds EphB receptors most weakly [PMID:22568954]. Annotated stimulatory.","molecular_requirements":"Ephrin-B3 cytoplasmic domain is close to ephrin-B2's [PMID:9484836].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"binding studies, dissociation constant","system":"murine ephrin-B3 characterisation","cite":"PMID:9484836"}],"species_and_systems":"Murine ephrin-B3 [PMID:9484836]; ELISA species unspecified. BioGRID: reconstituted complex [DB:BioGRID]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract level. Ephrin-B3 binds heparan sulfate proteoglycans per the ELISA paper, which was browser-read and unverified [PMID:22568954].","key_references":[{"PMID":"9484836","why":"Ephrin-B3 identified; ~1 nM EphB3 binding"},{"PMID":"22568954","why":"ELISA across EphB receptors"}],"covers":["LR000528","LR004019"]},"LR008240":{"pair":"EGF -> ERBB2:ERBB3","headline":"EGF binds only cells co-expressing ErbB2 and ErbB3 in one mouse-cell study; no other paper in the dossier.","interaction_type":"direct binding","direction_and_effect":"EGF specifically binds and can be cross-linked to 32D cells co-expressing ErbB2 and ErbB3, but not to cells expressing either alone; EGF also induced receptor phosphorylation, signalling and proliferation [PMID:9312020]. Classified as agonist by the curators [PMID:9312020].","molecular_requirements":"Both ErbB2 and ErbB3 are required; neither alone binds EGF [PMID:9312020]. Binding sites form by co-expression of two distinct receptors [PMID:9312020].","affinity_potency":[],"species_and_systems":"Murine IL-3-dependent 32D transfectants (no detectable EGFR), supported by human MDA MB134 breast carcinoma cells expressing ErbB2/ErbB3 without EGFR [PMID:9312020]. Ligand is [125I]EGF; species of EGF not stated beyond curator label human.","localisation_and_range":"EGF is secreted [flag].","caveats":"Single 1997 paper, read as abstract only. A separate paper reports that native EGF does not bind ErbB-2/ErbB-3 without engineering [PMID:12093292] in a different row; this may conflict. Database records for this pair are EGF-ERBB2 / ERBB3 reconstituted complexes citing that paper [DB:BioGRID].","key_references":[{"PMID":"9312020","why":"EGF binds ErbB2/ErbB3 co-expressing cells only"}],"covers":["LR008240"]},"LR002525":{"pair":"EGFL7 -> ITGAV","headline":"EGFL7 is reported as an alpha-v beta-3 integrin ligand supporting T-cell adhesion; abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"Activated T cells adhere to EGFL7 through integrin alphavbeta3; EGFL7 loss worsens and recombinant EGFL7 improves EAE in mice, so EGFL7 limits CNS immune infiltration [PMID:29483510]. Curators label it antagonist.","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer; both ITGAV and ITGB3 are needed [PMID:29483510].","affinity_potency":[],"species_and_systems":"Human and mouse activated T cells; MS patient tissue and EAE mice [PMID:29483510].","localisation_and_range":"EGFL7 is ECM-bound and secreted by endothelial cells (matrix, contact range) [PMID:29483510][flag].","caveats":"Single paper, abstract only; adhesion rather than a binding measurement; no affinity. Support is functional, not biophysical.","key_references":[{"PMID":"29483510","why":"T cell adhesion to EGFL7 through alphavbeta3; EAE phenotypes"}],"covers":["LR002525","LR005793"]},"LR005801":{"pair":"EPHA1 -> EFNA4","headline":"EPHA1-EFNA4 rests on a single UniProt statement of low-affinity binding; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that EPHA1 binds EFNA4 with low affinity, and that EFNA1 is its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Flags: EPHA1 non-secreted transmembrane receptor; EFNA4 flagged both secreted and transmembrane, which is inconsistent [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Low affinity only per UniProt; no values.","key_references":[],"covers":["LR002533","LR005801"]},"LR005810":{"pair":"EPHA2 -> EFNA3","headline":"EPHA2-EFNA3 has only BioGRID affinity-capture records; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA3-EPHA2 by affinity capture-MS and affinity capture-Western from one study [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Ten judged rows were review-only or abstract-insufficient; both BioGRID records come from the same study, so they are not independent. No affinity data.","key_references":[],"covers":["LR002542","LR005810"]},"LR002543":{"pair":"EPHA2 -> EFNA4","headline":"EPHA2-EFNA4 has BioGRID and IntAct association records only; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA4-EPHA2 by affinity capture-MS and -Western [DB:BioGRID]; IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EFNA4 is flagged secreted, EPHA2 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Four review-only rows. Association assays only, no affinity data.","key_references":[],"covers":["LR002543","LR005811"]},"LR002561":{"pair":"EPHA5 -> EFNA5","headline":"Eph/ephrin-A pair supported only by two IntAct co-purification records and a UniProt statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that the interaction of EFNA5 with EPHA5 mediates communication between pancreatic islet cells to regulate glucose-stimulated insulin secretion [DB:UniProt]. Direction and agonist/antagonist role are not reported beyond this. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct lists association by affinity chromatography [DB:IntAct EBI-32717888] and by anti-tag coimmunoprecipitation [DB:IntAct EBI-54501476], which show association rather than a defined direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002561","LR005829"]},"LR002570":{"pair":"EPHA7 -> EFNA4","headline":"Database-only pair: IntAct comigration in SDS-PAGE records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners carry secreted and transmembrane flags [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. IntAct records one entry described as direct interaction by comigration in SDS-PAGE [DB:IntAct EBI-5241581] and a second comigration entry [DB:IntAct Q15375-P52798]; this is a weak assay type for binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002570","LR005838"]},"LR001805":{"pair":"EPO -> EPHB4","headline":"One paper proposes EphB4 as an alternative Epo receptor in cancer cells; binding and tumour-growth data, but a single study.","interaction_type":"direct binding","direction_and_effect":"EphB4 is reported as an Epo receptor that triggers downstream STAT3 signalling and promotes rhEpo-induced tumour growth and progression (agonist) [PMID:26481148]. The paper assessed rhEpo binding to EphB4 by microscale thermophoresis and surface plasmon resonance [PMID:26481148].","molecular_requirements":"No direct EpoR-EphB4 interaction was detected by EpoR immunoprecipitation in A2780 cells, so EpoR did not appear to be required for the complex [PMID:26481148].","affinity_potency":[],"species_and_systems":"Recombinant human Epo and human ovarian and breast cancer cell lines and samples; Cos-1 cells in control experiments [PMID:26481148].","localisation_and_range":"Not reported in our evidence beyond cell-based assays; no annotation flags are listed.","caveats":"Only one confirming paper. Affinity values are not in the abstract or excerpts shown. Clinical correlation is with decreased survival in rhEpo-treated patients. IntAct lists anti bait coimmunoprecipitation from the same paper [DB:IntAct P01588-P54760].","key_references":[{"PMID":"26481148","why":"Identifies EphB4 as an Epo receptor driving STAT3 signalling and tumour growth."}],"covers":["LR001805","LR005161"]},"LR000536":{"pair":"EPO -> EPOR","headline":"Canonical, well supported EPO-EPOR agonist interaction: structures, binding mutagenesis and signalling studies in human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"EPO binding to EPOR induces receptor dimerization and JAK2 activation [DB:UniProt]; GtoPdb lists it as an agonist [DB:GtoPdb]. Epo binding initiates tyrosine phosphorylation and AP-1 induction [PMID:9442088], and minimal receptor forms retaining Tyr-343 relay Epo bioresponses [PMID:11124255].","molecular_requirements":"Receptor dimerization is the principal extracellular activation step; a crystal structure with an antagonist peptide shows dimerization still occurs but with altered orientation [PMID:9808045]. Phe93 and Phe205 of the EPOR extracellular domain are important for EPO binding [PMID:10318834]. An EpoR with only Tyr-343 or Tyr-464 supported maximal AP-1 activation [PMID:9442088]. Co-signalling with c-Kit enhances bcl-x(L) transcription [PMID:11124255].","affinity_potency":[],"species_and_systems":"Human receptor in COS cells with cross-linked 125I-EPO giving 66 and 100 Kd bands [PMID:2163696]; mouse FDCER cell lines [PMID:11124255]; human systems in [PMID:10318834], [PMID:9442088], [PMID:9808045].","localisation_and_range":"Not reported in our evidence; no annotation flags are listed.","caveats":"All five shown papers were read as abstracts only. The crystal-structure paper concerns EPOR with an antagonist EPO-mimetic peptide, not EPO itself [PMID:9808045]. No Kd or EC50 value is given in our evidence; GtoPdb lists pIC50 units without a value. Two further papers are pending and not shown. PDB structures [DB:PDB 1CN4], [DB:PDB 1EER] contain EPO and EPOR chains.","key_references":[{"PMID":"2163696","why":"Cloned human EPOR; 125I-EPO cross-linking in COS cells."},{"PMID":"10318834","why":"Mutagenesis of EPOR residues for EPO and mimetic-peptide binding."},{"PMID":"9808045","why":"Structure of EPOR with an antagonist peptide; dimer orientation matters."}],"covers":["LR000536","LR004027"]},"LR004028":{"pair":"EREG -> EGFR","headline":"EREG binds EGFR directly by cross-linking and is an agonist; supported by structures and databases.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound EGFR in human breast carcinoma lines, and epiregulin stimulated tyrosine phosphorylation of ErbB receptors, with EGFR and/or ErbB-4 mediating the main signal [PMID:9419975]. Annotated as stimulatory [flag]. UniProt lists epiregulin among EGFR ligands [DB:UniProt].","molecular_requirements":"Binding was seen to EGFR alone as a cross-linked species; no co-receptor requirement is reported in our evidence. Epiregulin did not bind ErbB-2 or ErbB-3 directly [PMID:9419975].","affinity_potency":[],"species_and_systems":"Experiments used human ligand and receptor in four human breast carcinoma lines [PMID:9419975]. The mouse pair is projected from human evidence (ortholog-inferred) [flag]. Structures PDB 5WB7, 7LEN, 7LFR, 7LFS and 8HGP contain both chains [DB:PDB 5WB7].","localisation_and_range":"EREG is flagged both secreted and transmembrane, EGFR transmembrane [flag]; paracrine or juxtacrine action is not distinguished in our evidence.","caveats":"Primary evidence is one 1997 paper read as abstract. No affinity reported. GtoPdb record lists binding without affinity values [DB:GtoPdb].","key_references":[{"PMID":"9419975","why":"Cross-linking shows epiregulin binds EGFR directly"}],"covers":["LR000537","LR004028"]},"LR010661":{"pair":"EREG -> ERBB2:ERBB4","headline":"Epiregulin directly binds ErbB-4, not ErbB-2; the ERBB2:ERBB4 complex is supported only through ErbB-4.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound ErbB-4 but not ErbB-2 in human breast carcinoma lines, and stimulated tyrosine phosphorylation of ErbB receptors [PMID:9419975]. BioGRID and GtoPdb list EREG-ERBB4 [DB:BioGRID].","molecular_requirements":"Direct binding is shown for the ERBB4 chain; ERBB2 was explicitly not bound [PMID:9419975]. Heterodimer requirement not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor, breast carcinoma lines [PMID:9419975].","localisation_and_range":"Annotated transmembrane [flag].","caveats":"Abstract-only; single paper. Complex scored by least-expressed subunit would depend on ERBB2 despite no direct ERBB2 binding. Reactome entries concern ERBB4 binding EGF-like ligands generally [DB:Reactome].","key_references":[{"PMID":"9419975","why":"ErbB-4 bound directly; ErbB-2 not bound"}],"covers":["LR010661"]},"LR002606":{"pair":"F11R -> ITGAL","headline":"JAM-A (F11R) is a ligand of LFA-1; the alphaL I domain binds recombinant JAM-A directly.","interaction_type":"direct binding","direction_and_effect":"JAM-1 is a ligand of LFA-1 and contributes to LFA-1-dependent transendothelial migration of T cells and neutrophils [PMID:11812992]. Solid-phase assays confirmed direct binding of recombinant JAM-A to the immobilised locked-open alphaL I domain [PMID:15528364].","molecular_requirements":"The alphaL I domain is crucial; deleting it abolishes adhesion to JAM-A [PMID:15528364]. JAM-A Ig-like domain 2 is required [PMID:11812992]. Evidence is for the LFA-1 heterodimer; ITGAL alone has the binding site.","affinity_potency":[],"species_and_systems":"Human JAM-A and LFA-1 in Jurkat, Mono Mac 6, CHO transfectants and endothelium [PMID:15528364][PMID:11812992]. Reactome and UniProt agree [DB:Reactome][DB:UniProt]. Mouse pair is projected from human evidence [flag].","localisation_and_range":"JAM-A transmembrane; access needs cytokine-induced redistribution out of tight junctions [PMID:11812992].","caveats":"Both papers read as abstracts. No affinity.","key_references":[{"PMID":"15528364","why":"I domain of LFA-1 binds JAM-A directly"},{"PMID":"11812992","why":"JAM-1 identified as LFA-1 ligand in transmigration"}],"covers":["LR002606","LR005873"]},"LR005162":{"pair":"F11R -> JAM2","headline":"Jam1a-Jam2a interaction is needed for Notch signalling in zebrafish HSC specification; functional, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Jam1a-Jam2a interactions facilitate transduction of Notch signals from the somite to HSC precursors; Notch reactivation rescued HSCs in jam1a- or jam2a-deficient embryos [PMID:25119047]. Curators classed it as agonist-like [PMID:25119047].","molecular_requirements":"jam1a (f11r) in HSC precursors and Jam2a in the somite alongside Notch ligands Dlc and Dld [PMID:25119047]. Direct binding not shown.","affinity_potency":[],"species_and_systems":"Experiments were in zebrafish embryos [PMID:25119047]; the pair is recorded as human and mouse, both ortholog-inferred, so the evidence is cross-species.","localisation_and_range":"JAMs are transmembrane; juxtacrine contact is described [PMID:25119047; flag].","caveats":"Zebrafish genetics; no binding assay; abstract-level. Dossier lists human species for experiments, which seems inaccurate.","key_references":[{"PMID":"25119047","why":"Zebrafish genetics placing Jam1a-Jam2a upstream of Notch signalling"}],"covers":["LR001806","LR005162"]},"LR000545":{"pair":"F2 -> F2RL1","headline":"Thrombin-PAR2 has no positive evidence; one paper states PAR2 exodomain showed no thrombin effect.","interaction_type":"conflicting","direction_and_effect":"MALDI mass spectrometry of recombinant PAR2E predicted no effect of thrombin; PAR2 is preferentially cleaved by trypsin [PMID:10978167]. Direction effect not supported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant PAR2 exodomain from E. coli, human sequences [PMID:10978167]. Reactome records generic PAR-thrombin binding [DB:Reactome].","localisation_and_range":"F2 flagged secreted, not transmembrane [flag].","caveats":"The one verified row is a negative (pair_absent); five rows were abstract_insufficient, one review_only and one pending. Database support is generic to PARs. Annotated stimulatory despite this [flag].","key_references":[{"PMID":"10978167","why":"Verified negative: no thrombin effect on PAR2E"}],"covers":["LR000545","LR004036"]},"LR004037":{"pair":"F2 -> F2RL2","headline":"Thrombin binds the PAR-3 exodomain peptide in a non-catalytic high-affinity mode; abstract-level, polypeptide only.","interaction_type":"direct binding","direction_and_effect":"Thrombin was found to bind two PAR-3 polypeptides, one without catalysing hydrolysis; PAR-3 inhibited thrombin fibrinogen clotting completely with K(I) of 3 microM [PMID:12732212]. Annotated stimulatory [flag].","molecular_requirements":"PAR-3 at low concentrations binds thrombin in a configuration that blocks the anion-binding exosite but not the catalytic site [PMID:12732212].","affinity_potency":[{"value":"K(I) 3 microM","assay":"inhibition of fibrinogen clotting by PAR-3 polypeptide","system":"solution kinetics","cite":"PMID:12732212"},{"value":"half-saturation 2.5 microM","assay":"enhancement of nitroanilide hydrolysis by PAR-3 polypeptide","system":"solvent lacking Na+","cite":"PMID:12732212"}],"species_and_systems":"Purified thrombin and PAR-3 extracellular domain polypeptide; species not stated in our evidence.","localisation_and_range":"F2 flagged secreted; F2RL2 transmembrane [flag].","caveats":"Cell-free peptide kinetics, abstract-only; receptor activation in cells not shown. Two further rows pending.","key_references":[{"PMID":"12732212","why":"PAR-3 peptide binds thrombin with K(I) 3 microM"}],"covers":["LR000546","LR004037"]},"LR000554":{"pair":"FASLG -> FAS","headline":"FASLG binds and activates FAS (CD95); direct binding mapped by mutagenesis, plus DISC signaling and strong database support.","interaction_type":"direct binding","direction_and_effect":"FASLG is the stimulatory ligand for FAS, which transduces the apoptotic signal [DB:UniProt]. Flag-tagged human FasL stimulation of human HT1080 cells led to Fas DISC formation with FADD and caspase-8 on co-IP [PMID:12887920].","molecular_requirements":"Binding involves two Fas domains; R86 and R87 (D2) mutation totally abolished interaction and K84S, L90S, E93S, H126S reduced it [PMID:9126929]. Three FasL monomers bind three Fas molecules in a model, and FasL Tyr-218 is predicted to contact a Fas basic-residue cluster [PMID:9228058].","affinity_potency":[],"species_and_systems":"Human proteins in all three papers; HT1080 cells in the signaling study [PMID:12887920]. Reactome, BioGRID, IntAct and GtoPdb records exist [DB:Reactome] [DB:BioGRID] [DB:IntAct] [DB:GtoPdb].","localisation_and_range":"FASLG is flagged both secreted and transmembrane [flag]; sFasL was soluble and Fas is activated on cross-linking [PMID:9228058].","caveats":"Two papers read as abstract only. The signaling paper [PMID:12887920] is mainly about TNFR1 and the Fas DISC is a comparison panel. GtoPdb record has no type, action or affinity [DB:GtoPdb]. One review-only row not used.","key_references":[{"PMID":"9126929","why":"Fas residues required for FasL binding."},{"PMID":"9228058","why":"FasL residues required for Fas binding, cytotoxicity."},{"PMID":"12887920","why":"Fas DISC formation after FasL, full text."}],"covers":["LR000554"]},"LR004046":{"pair":"FAT4 -> DCHS1","headline":"FAT4 and DCHS1 are a cadherin pair acting across cell boundaries; binding in a synthetic cell system, with mouse and human genetic evidence.","interaction_type":"direct binding","direction_and_effect":"Dchs1 and Fat4 are described as a ligand-receptor pair in mouse development, with similar phenotypes in single and double mutants [PMID:21303848]. Mutations in DCHS1 and FAT4 cause a human recessive syndrome including periventricular neuronal heterotopia [PMID:24056717].","molecular_requirements":"Fat4-Ds1 complexes accumulate at cell boundaries, with slower dynamics than unbound Fat4 and Ds1 [PMID:28826487]. Co-expression in the same cells induced polarization of the complexes [PMID:28826487].","affinity_potency":[],"species_and_systems":"Mammalian cells expressing human Fat4 and Ds1 [PMID:28826487]; mouse knockouts [PMID:21303848]; human patients and mouse neuroepithelium knockdown [PMID:24056717]. PDB 8EGW and 8EGX contain both chains [DB:PDB 8EGW] [DB:PDB 8EGX].","localisation_and_range":"Both are flagged not secreted [flag]; the papers describe complexes at cell boundaries, so signaling is by cell-cell contact [PMID:28826487].","caveats":"All three papers read as abstract only. Genetic papers show shared phenotypes, not direct binding. Roles of ligand versus receptor are annotation; Fat4 is also flagged receptor. Affinity not reported.","key_references":[{"PMID":"28826487","why":"Synthetic system showing Fat4-Ds1 complex formation at cell boundaries."},{"PMID":"21303848","why":"Mouse Dchs1 and Fat4 mutants show shared phenotypes."},{"PMID":"24056717","why":"Human and mouse genetics of DCHS1 and FAT4."}],"covers":["LR000555","LR004046"]},"LR002615":{"pair":"FBLN2 -> ITGAV","headline":"Fibulin-2 binds alpha V beta 3 only weakly; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 showed lower binding to alpha V beta 3 than to alpha IIb beta 3, and almost none to alpha 5 beta 1 [PMID:7543056]. RGD-peptide affinity for alpha V beta 3 was 10- to 50-fold lower than for GRGDS [PMID:7543056].","molecular_requirements":"Binding was to the alpha V beta 3 heterodimer; the single RGD site of mouse fibulin-2 is implicated [PMID:7543056].","affinity_potency":[],"species_and_systems":"Purified integrins and recombinant mouse fibulin-2 [PMID:7543056]. Human fibulin-2 (RGD changed to RSS) bound less strongly to alpha IIb beta 3 [PMID:7543056].","localisation_and_range":"FBLN2 is flagged secreted [flag]; matrix protein per the paper [PMID:7543056].","caveats":"Low-activity binding described qualitatively; no affinity values for fibulin-2. Abstract only.","key_references":[{"PMID":"7543056","why":"Compares fibulin-2 binding to five integrins."}],"covers":["LR002615","LR005882"]},"LR000563":{"pair":"FCN2 -> LRP1","headline":"L-ficolin binds CD91 (LRP1) in one abstract-level paper, with an IntAct SPR record.","interaction_type":"direct binding","direction_and_effect":"Both MBL and L-ficolin were found to bind CD91, suggesting a role as soluble recognition molecules for scavenging apoptotic and microbial material [PMID:21054788]. Effect direction not given in our evidence.","molecular_requirements":"Not reported for L-ficolin. The MASP-site finding applies to MBL, whose MASP-binding-deficient mutants did not bind CD91 [PMID:21054788].","affinity_potency":[],"species_and_systems":"Human (curator fields); assay details for L-ficolin are not in the abstract. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"FCN2 is flagged secreted [flag], a soluble ligand.","caveats":"Abstract only; the ficolin result is a single sentence, and the quantitative work was on MBL. No affinity reported.","key_references":[{"PMID":"21054788","why":"MBL and L-ficolin bind CD91"}],"covers":["LR000563"]},"LR004055":{"pair":"FGA -> ITGB3","headline":"Fibrinogen engages beta3 integrins alphaVbeta3 and alphaIIbbeta3; three papers, direct binding for alphaVbeta3 at abstract level.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta3 recognises fibrinogen gamma and alphaE C-terminal domains; two gammaC peptides block alphaVbeta3 binding and clot retraction but not fibrinogen binding to alphaIIbbeta3 [PMID:10747940]. Mouse platelets bound fibrinogen continuously via active alphaIIbbeta3 [PMID:23551977].","molecular_requirements":"beta3 pairs with alphaV or alphaIIb. The gammaC sites (190-202 and 346-358) lie on the gamma chain, not FGA; alphaEC binding concerns the extended alpha chain [PMID:10747940].","affinity_potency":[],"species_and_systems":"Human proteins (PMID:10747940); mouse platelets (PMID:23551977); human fibrinogen on mouse trophoblast (PMID:15031111). BioGRID lists FGA - ITGB3 protein-peptide [DB:BioGRID].","localisation_and_range":"FGA flagged secreted; ITGB3 not secreted [flag].","caveats":"Two papers abstract only; PMID:15031111 statement is background. No affinity. Mouse interaction listed separately.","key_references":[{"PMID":"10747940","why":"alphaVbeta3 binding sites in fibrinogen gammaC"},{"PMID":"23551977","why":"in vivo fibrinogen-alphaIIbbeta3 binding"}],"covers":["LR000571","LR004055"]},"LR000572":{"pair":"FGB -> ITGA2B","headline":"Fibrinogen binding to alphaIIb-beta3 is well supported at the complex level; chain-level attribution to FGB is indirect.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaIIbbeta3 binds fibrinogen via RGD sequences; RGD peptides trigger high-affinity fibrinogen binding and act as partial agonists and competitive antagonists [PMID:2018974]. Murine platelets bound fibrinogen continuously with active alphaIIbbeta3 [PMID:23551977].","molecular_requirements":"alphaIIb-beta3 heterodimer with whole fibrinogen; assays do not separate fibrinogen chains, and FGB alone is not tested.","affinity_potency":[],"species_and_systems":"Human platelet integrin (curator fields) [PMID:2018974]; mouse platelets [PMID:23551977]; human fibrinogen on mouse trophoblast [PMID:15031111]. Human interaction is ortholog-inferred.","localisation_and_range":"FGB flagged secreted; ITGA2B receptor [flag].","caveats":"Two papers abstract only; PMID:15031111 relies on background text. Three further rows were abstract_insufficient. No affinity.","key_references":[{"PMID":"2018974","why":"RGD peptides activate alphaIIbbeta3 fibrinogen binding"},{"PMID":"23551977","why":"fibrinogen-bound alphaIIbbeta3 in vivo"}],"covers":["LR000572","LR004056"]},"LR002624":{"pair":"FGB -> ITGB3","headline":"Direct binding of fibrinogen to integrin alphaIIbbeta3 (abstract-level), plus functional trophoblast data; chain-level for both partners.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaIIbbeta3 binds fibrinogen, and RGD peptide binding converts it to a high-affinity fibrinogen-binding, platelet-aggregating state; RGD mimetics can be partial agonists and competitive antagonists [PMID:2018974]. Fibrinogen is stated to be recognized by alphaVbeta3 and alphaIIbbeta3, curated as agonist [PMID:15031111].","molecular_requirements":"The receptor in both papers is the alphaIIbbeta3 integrin (beta3 paired with alphaIIb); fibrinogen is FGA:FGB:FGG and the assay does not separate the chains [PMID:2018974]. Fibrinogen binding requires agonist activation of platelets [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human platelets, human ligand and receptor [PMID:2018974]; human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both human and mouse interaction records exist, neither ortholog-inferred.","localisation_and_range":"FGB is flagged secreted [flag]; the paper context is soluble fibrinogen binding platelet receptors [PMID:2018974].","caveats":"Both papers are read at abstract or limited level for this pair; no affinity value in our evidence. The trophoblast sentence is partly literature-cited background [PMID:15031111]. Five further papers were judged abstract_insufficient. No database records.","key_references":[{"PMID":"2018974","why":"Fibrinogen binding to alphaIIbbeta3 and RGD-induced activation"},{"PMID":"15031111","why":"Fibrinogen recognition by beta3 integrins in mouse trophoblast outgrowth"}],"covers":["LR002624","LR005890"]},"LR004082":{"pair":"FGF1 -> NRP1","headline":"FGF1 binds neuropilin-1 strongly in an optical biosensor assay; one paper, no functional effect shown for FGF1.","interaction_type":"direct binding","direction_and_effect":"FGF-1, FGF-2, FGF-4 and FGF-7 all showed strong binding to immobilised Npn-1 [PMID:15695515]. Direction or agonist/antagonist effect for FGF1 is not reported in our evidence; the paper reports potentiation of FGF-2 activity, not FGF-1 [PMID:15695515].","molecular_requirements":"Binding was heparin-sensitive and dependent on ionic strength, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Whether other co-receptors are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified proteins on an optical biosensor surface (IAsys); species of the proteins not reported in our evidence [PMID:15695515]. Both human and mouse pairs are projected (ortholog_inferred).","localisation_and_range":"FGF1 flagged secreted; NRP1 flagged secreted and transmembrane, so it exists as membrane and soluble forms [flag].","caveats":"Kinetic constants were given for FGF-2, FGF-4 and HGF/SF only, not FGF-1. Binding is heparin-inhibited, so it may be non-specific for heparin-binding proteins. Single paper [PMID:15695515].","key_references":[{"PMID":"15695515","why":"biosensor binding of FGF1 to Npn-1"}],"covers":["LR000598","LR004082"]},"LR001814":{"pair":"FGF10 -> FGFRL1","headline":"FGF10 binds FGFRL1 with high affinity, which acts as a kinase-lacking decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"The FGFRL1 ectodomain, shed or membrane-bound, binds FGF2, FGF3, FGF4, FGF8, FGF10 and FGF22 with high affinity (dot blot, cell-based binding, surface plasmon resonance) [PMID:19920134]. FGFRL1 lacks the split tyrosine kinase domain and antagonises FGF signalling in Xenopus embryos, so it acts as a decoy [PMID:19920134].","molecular_requirements":"Both the soluble shed ectodomain and the membrane form bind; no co-receptor requirement is reported in our evidence [PMID:19920134].","affinity_potency":[],"species_and_systems":"C2C12 myoblasts and HEK293 cells for shedding and binding; Xenopus embryos for the functional assay [PMID:19920134]. Mouse pair is projected.","localisation_and_range":"FGFRL1 can be shed as a soluble ectodomain, so it may act at range as well as at the cell surface [PMID:19920134].","caveats":"Affinity values for FGF10 specifically are not given in the dossier. Abstract-only reading. Decoy action does not drive a kinase signal, so CCC scoring should treat it as inhibitory.","key_references":[{"PMID":"19920134","why":"FGFRL1 binds FGF10 and acts as a decoy"}],"covers":["LR001814","LR005169"]},"LR004064":{"pair":"FGF17 -> FGFR1","headline":"FGF17 activates FGFR1c in BaF3 cells and transforms 3T3 cells, consistent with FGFR1c or FGFR2c activation.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-domain form of FGFR4 [PMID:16597617]. Mouse FGF17 transformed 3T3 fibroblasts, indicating it can activate the c form of FGFR1 or FGFR2 [PMID:10381577]. Agonist.","molecular_requirements":"c splice forms; FGFR1c is not distinguished from FGFR2c in the transformation assay [PMID:10381577].","affinity_potency":[],"species_and_systems":"BaF3 panel [PMID:16597617]; mouse FGF17 in mouse 3T3 fibroblasts [PMID:10381577]. Human and mouse pairs both listed (not projected).","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Transformation result is abstract-only. Two other papers were abstract-insufficient.","key_references":[{"PMID":"16597617","why":"BaF3 panel"},{"PMID":"10381577","why":"FGF17 transformation of 3T3 cells"}],"covers":["LR000580","LR004064"]},"LR000581":{"pair":"FGF17 -> FGFR2","headline":"FGF17 activates FGFR2c in BaF3 cells and transforms 3T3 cells; functional evidence, with a BioGRID record.","interaction_type":"functional only","direction_and_effect":"Mouse FGF17 transformed 3T3 fibroblasts, indicating activation of the c form of FGFR1 or FGFR2 [PMID:10381577]. FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the FGFR4 two-Ig form [PMID:16597617]. Agonist.","molecular_requirements":"c splice forms [PMID:16597617]; FGFR2 is not separated from FGFR1 in the transformation assay [PMID:10381577].","affinity_potency":[],"species_and_systems":"BaF3 panel [PMID:16597617]; mouse FGF17 on mouse 3T3 cells [PMID:10381577]. A BioGRID protein-peptide record exists [DB:BioGRID].","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Transformation result abstract-only; one paper abstract-insufficient.","key_references":[{"PMID":"10381577","why":"FGF17 transforms 3T3 via FGFR1c/2c"},{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000581","LR004065"]},"LR000590":{"pair":"FGF19 -> FGFR3","headline":"Functional evidence only: FGF19 activates FGFR3 c splice forms in one BaF3 assay; no binding data.","interaction_type":"functional only","direction_and_effect":"FGF19 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but none toward FGFR1b, 2b or 3b in a BaF3 cell mitogenic assay [PMID:16597617].","molecular_requirements":"Only the c splice form of FGFR3 responded; KLB involvement is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 cells expressing individual FGFRs; species not stated [PMID:16597617]. No database records for this pair.","localisation_and_range":"Ligand annotated secreted and receptor transmembrane [flag].","caveats":"Single functional paper, read as abstract only, with the quote marked as browser-read and pending spot-check. No direct binding, no affinity, no KLB dependence tested for this pair in our evidence.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic activity of FGF19 on c-form FGFRs"}],"covers":["LR000590"]},"LR004091":{"pair":"FGF2 -> CD44","headline":"Heparan-sulfate-modified CD44 isoforms bind FGF2 in one 1995 paper; no affinity or signalling data.","interaction_type":"direct binding","direction_and_effect":"HS-modified CD44 isoforms were able to bind b-FGF (FGF2) and HB-EGF, but not amphiregulin [PMID:7532176]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Binding required CD44 isoforms containing alternatively spliced exon V3 carrying heparan sulfate [PMID:7532176]; the binding is therefore likely HS-mediated.","affinity_potency":[],"species_and_systems":"COS cell transfectants and keratinocyte-derived CD44; species not stated in our evidence [PMID:7532176]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are annotated secreted and transmembrane-capable [flag]; CD44 acts as a membrane growth-factor presenter.","caveats":"Single paper. CD44 appears to act as an HS-bearing presenter rather than a signalling receptor; no affinity reported. Full-text excerpts shown concern CD44 expression in skin, not binding.","key_references":[{"PMID":"7532176","why":"HS-modified CD44 binds bFGF in COS cells and keratinocytes"}],"covers":["LR000607","LR004091"]},"LR000608":{"pair":"FGF2 -> FGFR1","headline":"Strongly supported canonical FGF2-FGFR1 interaction, including a 3 A ternary crystal structure with heparin.","interaction_type":"direct binding","direction_and_effect":"FGF2 binds FGFR1 well [PMID:10950949]; a 3 A crystal structure of a dimeric 2:2:2 FGF:FGFR:heparin complex shows heparin contacting both ligand and receptor [PMID:11030354]. Perlecan heparan sulfate formed ternary complexes with FGF2 and FGFR1c [PMID:24509440]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Heparin or heparan sulfate is part of the signalling complex: it augments FGF-FGFR binding and promotes FGFR dimerisation; the 6-O-sulfate of heparin is pivotal [PMID:11030354]. Ternary complexes were sensitive to Hep III digestion [PMID:24509440].","affinity_potency":[],"species_and_systems":"Human proteins in all three papers [PMID:11030354][PMID:10950949][PMID:24509440]. Structures PDB 1CVS and 1FQ9; BioGRID, IntAct and UniProt records [DB:PDB 1CVS][DB:PDB 1FQ9][DB:BioGRID][DB:IntAct][DB:UniProt].","localisation_and_range":"FGF2 is annotated secreted and FGFR1 transmembrane [flag]; HS in the matrix (perlecan) acts as an adaptor.","caveats":"Two of three papers were read as abstract only. No Kd given in our evidence. Three further papers were abstract_insufficient.","key_references":[{"PMID":"11030354","why":"3 A FGF:FGFR:heparin ternary structure"},{"PMID":"24509440","why":"Perlecan HS forms FGF2-FGFR1c ternary complexes"},{"PMID":"10950949","why":"FGF2 binds FGFR1 well"}],"covers":["LR000608","LR004092"]},"LR008015":{"pair":"FGF2 -> FGFR1:TGFBR3","headline":"One neuroblastoma paper reports TGFBR3 binding FGF2 and FGFR1 as a co-receptor; complex-level evidence is thin.","interaction_type":"functional only","direction_and_effect":"TGFBR3 bound FGF2 and exogenous FGFR1, promoting neuronal differentiation of neuroblastoma cells; TGFBR3 and FGF2 cooperated to induce Id1 via Erk MAPK [PMID:24216509]. Reactome lists FGF2:TGFBR3 [DB:Reactome].","molecular_requirements":"Needs FGFR1 together with TGFBR3: TGFBR3 bound FGF2 and exogenous FGFR1, forming a functional co-receptor complex [PMID:24216509].","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells [PMID:24216509]. Not a purified binding assay in our evidence.","localisation_and_range":"FGF2 annotated secreted [flag]; TGFBR3 is a membrane co-receptor, so action is at the cell surface.","caveats":"Single paper read as abstract only; assay class functional. TGFBR3 expression is lost in MYCN-amplified neuroblastoma, so the complex may be absent in aggressive tumours [PMID:24216509]. No affinity reported.","key_references":[{"PMID":"24216509","why":"TGFBR3 binds FGF2 and FGFR1; co-receptor for differentiation"}],"covers":["LR008015"]},"LR000617":{"pair":"FGF2 -> SDC3","headline":"Purified N-syndecan (SDC3) binds bFGF with Kd = 0.5 nM through its heparan sulfate chains; one older abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"N-syndecan purified from neonatal rat brain bound bFGF in a saturable solid-phase assay; soluble bFGF competed, showing solution-phase interaction. The authors suggest N-syndecan may act as a bFGF co-receptor [PMID:8344959]. BioGRID lists a reconstituted-complex record [DB:BioGRID].","molecular_requirements":"Heparin and heparan sulfate, not chondroitin sulfate, inhibited binding; the isolated core protein did not bind bFGF significantly, so HS chains are responsible [PMID:8344959]. Acidic FGF did not bind significantly [PMID:8344959].","affinity_potency":[{"value":"KD = 0.5 nM","assay":"solid-phase binding assay, N-syndecan with bFGF","system":"N-syndecan purified from neonatal rat brain","cite":"PMID:8344959"}],"species_and_systems":"Rat brain protein; the dossier records human for both partners, but the abstract describes neonatal rat brain [PMID:8344959]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Entity flags give no membrane annotation for SDC3 beyond receptor [flag]; N-syndecan is described as a cell-surface proteoglycan [PMID:8344959].","caveats":"Single paper, abstract only. Binding is mediated by HS chains rather than the core protein. Co-receptor role is a suggestion, not tested here.","key_references":[{"PMID":"8344959","why":"Purified N-syndecan binds bFGF, Kd 0.5 nM"}],"covers":["LR000617","LR004101"]},"LR002633":{"pair":"FGF2 -> TGFBR3","headline":"TGFBR3 binds FGF2 and promotes FGF2-driven neuronal differentiation of neuroblastoma cells; one abstract-only paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"T\u03b2RIII bound FGF2 and exogenous FGFR1, promoting neuronal differentiation of neuroblastoma cells; T\u03b2RIII and FGF2 cooperated to induce Id1 expression via Erk MAPK [PMID:24216509]. The authors describe a coreceptor function. Reactome has a FGF2:TGFBR3 complex and binding reaction [DB:Reactome].","molecular_requirements":"T\u03b2RIII acts with FGFR1 as a coreceptor [PMID:24216509]. Whether TGFBR3 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells and in vivo tumour models; ligand and receptor recorded as human [PMID:24216509]. Mouse pair is ortholog-inferred.","localisation_and_range":"TGFBR3 is flagged transmembrane [flag].","caveats":"Single paper read as abstract only; no affinity is given. Reactome cites the same paper and an additional PMID not in our papers [DB:Reactome].","key_references":[{"PMID":"24216509","why":"T\u03b2RIII binds FGF2 and acts as coreceptor in neuroblastoma differentiation"}],"covers":["LR002633","LR005899"]},"LR005171":{"pair":"FGF20 -> FGFR2","headline":"FGF20 activating FGFR2 is supported only indirectly by a family mitogenic screen and mouse heart genetics.","interaction_type":"functional only","direction_and_effect":"The BaF3 screen reports FGF9, 16 and 20 activating FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. In mouse heart, FGF signals including Fgf9/16/20 were received by FGFR1 and FGFR2 acting redundantly [PMID:15621532].","molecular_requirements":"FGFR1 and FGFR2 act redundantly [PMID:15621532]; the screen implicates c-splice isoforms [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 lines, species unspecified [PMID:16597617]; mouse knockout and heart organ culture [PMID:15621532].","localisation_and_range":"FGF20 flagged secreted, FGFR2 transmembrane [flag].","caveats":"No direct binding. Neither quote names FGF20 and FGFR2 on their own: one is a subfamily statement, the other a joint knockout inference. Both papers read at abstract level.","key_references":[{"PMID":"16597617","why":"Mitogenic receptor-specificity screen of FGF9/16/20"},{"PMID":"15621532","why":"Mouse heart FGF signals via FGFR1/FGFR2"}],"covers":["LR001816","LR005171"]},"LR005900":{"pair":"FGF21 -> FGFR1","headline":"FGF21 binds FGFR1 with KLB present, with stronger affinity than FGFR4; direct binding evidence, KLB-dependent.","interaction_type":"direct binding","direction_and_effect":"FGF21 binds FGFR1 with much higher affinity than FGFR4 in the presence of KLB [PMID:22442730]. GtoPdb lists the pair as agonist [DB:GtoPdb]. A BaF3 mitogenic assay also reports FGF21 activity toward FGFR1c [PMID:16597617].","molecular_requirements":"KLB is described as an indispensable mediator of FGF19/FGF21 binding to FGFRs [PMID:22442730]. FGF21 competed with labeled FGF19 on FGFR1-KLB cells and on KLB alone, with over 90% efficiency at 1 ug/ml [PMID:22442730]. Activity toward FGFR1c but not FGFR1b is reported [PMID:16597617].","affinity_potency":[{"value":"half-maximum competition about 150 ng/ml","assay":"competition of unlabeled FGF21 against 125I-FGF19 binding","system":"cells co-expressing FGFR1 and KLB","cite":"PMID:22442730"}],"species_and_systems":"The 2012 study used recombinant protein in cultured cells (T-Rex 293 expressing FGFR1-KLB) and mice for signaling [PMID:22442730]; the species of reagents in the 2006 BaF3 study is unspecified [PMID:16597617].","localisation_and_range":"FGF21 is flagged secreted and not transmembrane [flag]; the receptor is flagged transmembrane [flag]. Endocrine range is not stated in our evidence beyond the flags.","caveats":"FGF21 could not be radio-iodinated without losing activity, so binding was measured indirectly by competition with FGF19 [PMID:22442730]. The 2012 paper was curated from the abstract plus excerpts; the 2006 paper was read only as an abstract in the dossier and its quote is unverified. Mouse pair is projected from human.","key_references":[{"PMID":"22442730","why":"Quantitative binding of FGF21 to FGFR1-KLB vs FGFR4-KLB"},{"PMID":"16597617","why":"BaF3 mitogenic activity of FGF21 on FGFR1c"}],"covers":["LR002634","LR005900"]},"LR004109":{"pair":"FGF4 -> NRP1","headline":"FGF4 binds immobilised NRP1 in a biosensor, apparently via heparin-mimetic site; functional relevance unproven.","interaction_type":"direct binding","direction_and_effect":"FGF4 interacts with immobilised neuropilin-1 and in a solution assay [PMID:15695515]. Npn-1 potentiated FGF-2 (not FGF4) growth stimulation of HUVEC [PMID:15695515]; any FGF4 effect is not reported in our evidence.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Optical biosensor and solution assays with human proteins [PMID:15695515]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"NRP1 is flagged as a transmembrane receptor with a secreted form [flag]; FGF4 is flagged secreted [flag].","caveats":"The curator notes the binding is largely electrostatic and heparin-competable, so specificity and signalling relevance for FGF4 are not established. Association rate constants of 270,000-1,600,000 M-1s-1 are given for FGF-2, FGF-4 and HGF/SF together, not FGF4 alone.","key_references":[{"PMID":"15695515","why":"Biosensor and solution binding of FGF4 to NRP1"}],"covers":["LR000625","LR004109"]},"LR000626":{"pair":"FGF5 -> FGFR1","headline":"FGF5 binds and activates FGFR1 with nanomolar affinity in human recombinant studies; also supported by database records.","interaction_type":"direct binding","direction_and_effect":"Recombinant human FGF-5 bound and induced autophosphorylation of FGFR1 and FGFR2 (agonist) [PMID:8386828]. The BaF3 survey reports FGF5 activating c splice forms [PMID:8663044].","molecular_requirements":"Activity was shown in the presence of heparin [PMID:8386828]. UniProt lists FGF5 among in vitro interactors of FGFR1 [DB:UniProt]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[{"value":"KD between 0.5 and 1.5 x 10(-9) M","assay":"competition binding","system":"recombinant human FGF-5 with human FGFR-1","cite":"PMID:8386828"}],"species_and_systems":"Human recombinant FGF-5 purified from E. coli [PMID:8386828]; BaF3 cells with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF5 is flagged secreted; FGFR1 is flagged as a transmembrane receptor [flag].","caveats":"Main binding paper was read as abstract only; the KD range is shared with FGFR2. The BaF3 quote is browser-read and pending spot-check.","key_references":[{"PMID":"8386828","why":"KD and autophosphorylation for FGF-5 with FGFR1"},{"PMID":"8663044","why":"BaF3 receptor specificity survey"}],"covers":["LR000626","LR004110"]},"LR004118":{"pair":"FGF7 -> FGFR1","headline":"Reported only in an organoid study where FGF7 acts through FGFR2 and FGFR1; no direct binding.","interaction_type":"functional only","direction_and_effect":"In hESC-derived islet organoids FGF7 interacts with FGFR2 and FGFR1 to upregulate ACE2, and FGFR inhibition counteracted the induction [PMID:38654010].","molecular_requirements":"FGFR2 and FGFR1 are named together; the relative contribution of FGFR1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human embryonic stem cell-derived islet organoids, with animal models and COVID-19 patient serum mentioned in the abstract [PMID:38654010].","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Abstract-only reading; the word \"interacts\" is not backed by a binding assay in the dossier, and an FGFR inhibitor does not distinguish receptors. Seven further papers were abstract-insufficient.","key_references":[{"PMID":"38654010","why":"FGF7 acts via FGFR2 and FGFR1 in islet organoids"}],"covers":["LR000634","LR004118"]},"LR000635":{"pair":"FGF7 -> FGFR2","headline":"Well supported: FGF7 activates the b isoform of FGFR2, with BaF3 mitogenesis and database binding records.","interaction_type":"functional only","direction_and_effect":"FGF7 and FGF10 activate only the b isoform of FGFR2 [PMID:12591959]; FGFs 7, 10 and 22 strongly activated FGFR2b in BaF3 cells [PMID:16597617]. The pair is annotated stimulatory.","molecular_requirements":"Splice isoform FGFR2b (exon IIIb) is the responsive form [PMID:12591959]. Heparan sulfate is described as a modulating cofactor in the survey abstract [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell lines, species unspecified [PMID:16597617]. The structure paper (abstract only) restates FGF7 activity but solved FGF10-FGFR2b, not FGF7 [PMID:12591959]. Database records: BioGRID reconstituted complex, IntAct cross-linking/saturation binding [DB:BioGRID][DB:IntAct].","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"The FGF7 statement in PMID:12591959 is background rather than this paper's own result. BaF3 quote is browser-read and pending spot-check.","key_references":[{"PMID":"16597617","why":"FGF7 strongly activates FGFR2b in BaF3"},{"PMID":"12591959","why":"States FGF7 and FGF10 activate only FGFR2b"}],"covers":["LR000635","LR004119"]},"LR001823":{"pair":"FGF8 -> FGFRL1","headline":"FGF8 binds FGFRL1 with high affinity; FGFRL1 acts as a decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF8 (among FGF2, FGF3, FGF4, FGF10, FGF22), and FGFRL1 expressed in Xenopus embryos antagonised FGFR signalling, supporting a decoy role [PMID:19920134].","molecular_requirements":"FGFRL1 has an FGFR-like extracellular domain but lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. Heparin dependence is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand dot blot, cell-based binding and surface plasmon resonance; shed ectodomain from C2C12 myoblasts and HEK293 cells; Xenopus embryo antagonism [PMID:19920134]. Mouse pair is projected from human.","localisation_and_range":"FGFRL1 ectodomain is shed from the membrane by an unidentified protease, giving soluble and membrane-bound forms [PMID:19920134].","caveats":"Abstract-only reading. \"High affinity\" has no number in our evidence, and the abstract does not resolve binding per ligand.","key_references":[{"PMID":"19920134","why":"FGFRL1 shedding, FGF8 binding and antagonism"}],"covers":["LR001823","LR005178"]},"LR004127":{"pair":"FGF9 -> FGFR3","headline":"FGF9 binds and activates FGFR3 (c and b splice forms); several binding and mitogenic papers plus BioGRID support.","interaction_type":"direct binding","direction_and_effect":"FGF9 is an agonist of FGFR3: it binds and activates the c splice form and also the b form [PMID:8576175]. FGF9 stimulated DNA synthesis in FGFR3-expressing stromal cells, with epithelial FGF9 signalling to stromal FGFR3 [PMID:15231666]. FGF9 bound FGFR3 well but FGFR2/FGFR1 poorly in soluble receptor assays [PMID:10574949].","molecular_requirements":"Splice form matters: c forms are preferred, with some activity on FGFR3b [PMID:8663044][PMID:16597617]. Binding specificity maps to Ig domain II and sequences N-terminal to it [PMID:10574949]. Co-factor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assays used human receptor constructs for two papers [PMID:10574949][PMID:8576175]; the prostate tumour paper used rat Dunning R3327 tumour cells [PMID:15231666]; BaF3 mitogenic assays did not specify species [PMID:8663044][PMID:16597617]. Human and mouse records share this dossier; mouse is not inferred.","localisation_and_range":"FGF9 is flagged as secreted and FGFR3 as transmembrane [flag]; the prostate paper describes epithelium-to-stroma paracrine signalling [PMID:15231666].","caveats":"Several papers were read as abstracts only. BaF3 assays measure mitogenesis, not binding. BioGRID lists reconstituted complex and affinity capture records [DB:BioGRID], and IntAct an SPR record [DB:IntAct]. No affinity values reported.","key_references":[{"PMID":"8576175","why":"FGF9 binds and activates FGFR3c and FGFR3b"},{"PMID":"15231666","why":"Epithelial FGF9 to stromal FGFR3 paracrine binding and mitogenesis"},{"PMID":"10574949","why":"Soluble FGFR3 binds FGF9; domain mapping"}],"covers":["LR000643","LR004127"]},"LR000644":{"pair":"FGF9 -> FGFR4","headline":"FGF9 activates FGFR4 in mitogenic assays; support is functional only and mouse and human are projected.","interaction_type":"functional only","direction_and_effect":"FGFs of the FGF9 subfamily activated FGFRc isoforms and FGFR4 with high activity in BaF3 mitogenesis assays [PMID:16597617]. A second BaF3 study covers FGF9 specificity across receptor splice variants [PMID:8663044].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BaF3 experiments is unspecified [PMID:16597617][PMID:8663044]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"FGF9 is flagged secreted and FGFR4 transmembrane [flag].","caveats":"No direct binding data and no database records. Both papers are functional mitogenic readouts; the FGFR4 statement comes from the sentence on the FGF9 subfamily [PMID:16597617]. The sentence cited from PMID:8663044 does not mention FGFR4 explicitly.","key_references":[{"PMID":"16597617","why":"FGF9-subfamily FGFs activate FGFR4"},{"PMID":"8663044","why":"BaF3 receptor specificity of FGFs"}],"covers":["LR000644","LR004128"]},"LR005180":{"pair":"FGL1 -> LAG3","headline":"FGL1 binds LAG-3 with nanomolar affinity and inhibits T cell activation; well supported.","interaction_type":"direct binding","direction_and_effect":"FGL1 is a major LAG-3 functional ligand independent of MHC-II; it inhibits antigen-specific T cell activation, FGL1 ablation in mice promotes T cell immunity, and antibody blockade of the interaction stimulates tumour immunity [PMID:30580966]. UniProt lists FGL1 as a LAG3 ligand [DB:UniProt].","molecular_requirements":"MHC-II is the canonical LAG-3 ligand, but FGL1 acts independently of it [PMID:30580966]. Other requirements not reported.","affinity_potency":[{"value":"Kd ~1.5 nM","assay":"Octet bio-layer interferometry","system":"FGL1 with LAG3","cite":"PMID:30580966"}],"species_and_systems":"Interaction conserved in human and mouse; mouse tumour models used for blockade [PMID:30580966].","localisation_and_range":"FGL1 is a liver-secreted protein [PMID:30580966]; FGL1 flagged secreted and LAG3 transmembrane [flag]; acts at range.","caveats":"Paper read as abstract plus excerpts. Single primary paper, with IntAct recording bio-layer interferometry from it [DB:IntAct]; UniProt cites follow-up papers [DB:UniProt]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"30580966","why":"Identifies FGL1 as MHC-II-independent LAG-3 ligand, Kd ~1.5 nM"}],"covers":["LR001825","LR005180"]},"LR002642":{"pair":"FLRT1 -> ADGRL1","headline":"FLRT proteins are reported as ligands for latrophilins; FLRT1-LPHN1 evidence is a general family statement.","interaction_type":"direct binding","direction_and_effect":"FLRT1-3 are reported as endogenous ligands for LPHN1 and LPHN3 [PMID:22405201]. Direction/effect on signalling is not reported in our evidence for FLRT1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor-ligand binding assays; species recorded as human, though the dossier lists the pair as human ortholog-inferred and mouse not inferred [PMID:22405201].","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; FLRT proteins are single-pass transmembrane [PMID:22405201], so contact-dependent.","caveats":"The excerpts concern FLRT3 and FLRT2 pull-downs; FLRT1 named only in the family sentence [PMID:22405201]. One confirmed paper; others were review-only or abstract-insufficient. No database records.","key_references":[{"PMID":"22405201","why":"FLRTs as latrophilin ligands"}],"covers":["LR002642","LR005908"]},"LR007205":{"pair":"FLRT1:TENM4 -> ADGRL1","headline":"Complex-as-ligand pair with a single IntAct coimmunoprecipitation record and no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper. IntAct lists an association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54534689, PMID:33961781]; direction and effect are not reported in our evidence.","molecular_requirements":"Subunit requirements and which member contacts ADGRL1 are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; pair listed as human.","localisation_and_range":"Complex flagged membrane-bound, not secreted [flag].","caveats":"Support is a single database record; the record's participants are not detailed in our evidence, so it may not concern FLRT1:TENM4 as a joint ligand.","key_references":[],"covers":["LR007205"]},"LR002651":{"pair":"FLRT2 -> ITGB4","headline":"FLRT2 is reported to associate with integrin beta 4 in endothelial cells, restraining senescence; evidence is co-association rather than a ligand-receptor binding study.","interaction_type":"functional only","direction_and_effect":"FLRT2 silencing increased ITGB4 phosphorylation (Y1510) and senescence; silencing ITGB4 reversed AKT activation and the rise in p53/p21 [PMID:38587072]. FLRT2 and ITGB4 were co-associated in FLAG-FLRT2-overexpressing cells, and colocalised by immunofluorescence and Duolink [PMID:38587072]. The curated row labels the effect antagonist.","molecular_requirements":"ITGB4 only (no alpha subunit) is mentioned; partner subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC), aged rat and human vascular tissue, and mice (FLRT2 silencing and overexpression) [PMID:38587072].","localisation_and_range":"FLRT2 is flagged secreted and transmembrane [flag]; ITGB4 was found in plasma membrane lipid rafts [PMID:38587072].","caveats":"Co-immunoprecipitation, colocalisation and proximity ligation do not prove direct binding; the curated assay_class is direct_binding.","key_references":[{"PMID":"38587072","why":"FLRT2-ITGB4 association and senescence control."}],"covers":["LR002651","LR005917"]},"LR002660":{"pair":"FLRT3 -> UNC5C","headline":"FLRT3 binds UNC5C in a high-throughput screen; one primary study, no affinity.","interaction_type":"direct binding","direction_and_effect":"All three FLRTs bound all four Unc5s near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Neurons responded to FLRT3 stripes with 8% attractive and 8% repulsive responses (n=37/438 and n=33/438) and to Unc5C stripes with 11% repulsion (n=45/396) [PMID:26633812]; these are separate stripe assays, not the pair tested together.","molecular_requirements":"Purified ectodomains were sufficient [PMID:26633812].","affinity_potency":[],"species_and_systems":"Screen with purified ectodomains, CHO.K1 aggregation, mouse retinal neurons [PMID:26633812].","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5C transmembrane [flag].","caveats":"Based on a single paper. The human pair is ortholog-inferred. No affinity in our evidence.","key_references":[{"PMID":"26633812","why":"Binding screen of all FLRT x Unc5 combinations"}],"covers":["LR002660","LR005926"]},"LR000653":{"pair":"FLT3LG -> FLT3","headline":"Well supported human FLT3LG-FLT3 binding with structures, curated databases and functional papers; agonist.","interaction_type":"direct binding","direction_and_effect":"FL induces dimerization of Flt3, forming a ternary complex without homotypic receptor interactions [PMID:21389326]. FL stimulated chemokinetic migration of CD34+ and Ba/F3-Flt3 cells and enhanced CXCL12-induced migration [PMID:15618475]; FL activated AKT and inactivated FoxO3 [PMID:15147956]. Flt3 ligand-receptor interaction maintains early thymic progenitors in mice [PMID:19830725]. Agonist.","molecular_requirements":"One FL dimer engages two Flt3 chains via a compact epitope at the tip of extracellular domain 3 [PMID:21389326]; reactions are recorded as FLT3LG dimer binding FLT3 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins in the crystal structure and cell assays [PMID:21389326] [PMID:15618475]; mouse experiments in [PMID:19830725] and [PMID:15147956] (murine FLT3 in FDC-P1); the original cloning used murine proteins [PMID:7505204].","localisation_and_range":"Ligand flagged both secreted and transmembrane [flag]; the cloned murine ligand is a type I transmembrane protein with an active soluble form [PMID:7505204].","caveats":"All papers were read as abstracts only. GtoPdb lists the interaction without type, action or affinity [DB:GtoPdb]. Thermodynamic binding was reported but no numbers are in our evidence [PMID:21389326].","key_references":[{"PMID":"21389326","why":"crystal structure of the FL-Flt3 complex, dimerization"},{"PMID":"7505204","why":"expression cloning of ligand binding the receptor"},{"PMID":"15618475","why":"functional migration synergy with CXCL12"}],"covers":["LR000653"]},"LR007016":{"pair":"FN1 -> ITGA10:ITGB1","headline":"No curated paper supports fibronectin binding to ITGA10:ITGB1; evidence is generic fibronectin-integrin database records.","interaction_type":"database-asserted only","direction_and_effect":"Database records show fibronectin with ITGB1 (BioGRID reconstituted complex, affinity capture-Western) and IntAct SPR/FACS records [DB:BioGRID] [DB:IntAct]. The structural and pathway records are for the alpha5beta1 complex with fibronectin [DB:PDB 7NWL] [DB:Reactome]. Direction and effect are not reported for this pair.","molecular_requirements":"ITGA10:ITGB1 is a complex; the cited records concern ITGB1 or alpha5beta1, not this alpha chain, so alpha-chain specificity is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; BioGRID and IntAct experiment species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted; the integrin complex is flagged transmembrane or receptor [flag].","caveats":"No confirmed paper. Support is inferred from ITGB1/alpha5beta1 records.","key_references":[],"covers":["LR007016"]},"LR004145":{"pair":"FN1 -> ITGA8","headline":"Fibronectin is a ligand of integrin alpha8beta1 in two independent 1995 papers; no database records.","interaction_type":"direct binding","direction_and_effect":"FN1 is annotated stimulatory [flag]. Alpha8beta1 mediates cell adhesion to fibronectin, and alpha8beta1 binds fibronectin-Sepharose, eluted by GRGDSP [PMID:7559467]; it is a fibronectin receptor promoting attachment, spreading and neurite outgrowth, binding the RGD site [PMID:7626807].","molecular_requirements":"The binding entity is the alpha8beta1 heterodimer (alpha8 associates with beta1) [PMID:7559467]; ITGB1 is therefore needed with ITGA8.","affinity_potency":[],"species_and_systems":"293 cells transfected with alpha8 cDNA [PMID:7559467]; K562 transfectants [PMID:7626807]. The second paper's ligand/receptor species are unspecified in the dossier; the first is labelled human. Mouse pair is ortholog-inferred.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Abstract-only evidence. No database records support this pair. No affinity data reported in our evidence. One further paper is pending.","key_references":[{"PMID":"7559467","why":"Affinity chromatography and adhesion: alpha8beta1 binds fibronectin"},{"PMID":"7626807","why":"K562 alpha8beta1 transfectants adhere and spread on fibronectin via RGD"}],"covers":["LR000661","LR004145"]},"LR000662":{"pair":"FN1 -> ITGA9","headline":"The EIIIA segment of fibronectin is reported as a ligand of integrin alpha9beta1; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The EIIIA segment of fibronectin is a ligand for integrins alpha9beta1 and alpha4beta1 [PMID:11839764].","molecular_requirements":"Binding is through the alternatively spliced EIIIA segment, so only EIIIA-containing FN1 isoforms apply [PMID:11839764]. The receptor is the alpha9beta1 heterodimer.","affinity_potency":[],"species_and_systems":"Experimental species not specified in the dossier [PMID:11839764].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"One paper, abstract-only, with the same paper entered twice for the subunit and complex pairs. No database records. No affinity reported in our evidence.","key_references":[{"PMID":"11839764","why":"First identification of integrins binding the EIIIA segment"}],"covers":["LR000662","LR004146"]},"LR004154":{"pair":"FN1 -> SDC2","headline":"Syndecan-2 heparan sulfate chains bind fibronectin and cooperate with alpha5beta1; mouse cell evidence, human inferred.","interaction_type":"direct binding","direction_and_effect":"Syndecan-2 heparan sulfate side chains bound the fibronectin substrate; antisense knockdown of syndecan-2 prevented stress-fibre formation on fibronectin [PMID:10772816].","molecular_requirements":"Acts in cooperation with integrin alpha5beta1; the heparan sulfate chains mediate binding [PMID:10772816].","affinity_potency":[],"species_and_systems":"Mouse Lewis lung carcinoma P29 cells; human and mouse pairs both ortholog-inferred [PMID:10772816].","localisation_and_range":"Receptor flagged transmembrane [flag]; fibronectin flagged secreted, substrate-bound in the assay [flag].","caveats":"One paper, abstract only; no affinity. Binding is via glycosaminoglycan chains, so it depends on proteoglycan glycosylation. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10772816","why":"Syndecan-2 heparan sulfate binds fibronectin"}],"covers":["LR000670","LR004154"]},"LR000671":{"pair":"FN1 -> TSHR","headline":"Fibronectin anchors TSHR and modulates its responsiveness; not a signalling ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"Fibronectin/ECM interaction concentrated TSHR at lamellipodia; ECM attachment increased TSH-stimulated adenylate cyclase but not PLC, and constitutive activity appeared only in attached cells [PMID:11981027]. Fibronectin does not itself activate TSHR in this evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human thyroid cells and transfected cells [PMID:11981027]; mouse is inferred.","localisation_and_range":"TSHR flagged transmembrane receptor [flag]; fibronectin matrix-bound.","caveats":"Abstract only; no direct binding assay or affinity. The homologous LH receptor, which does not interact with ECM, served as a negative control [PMID:11981027]. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11981027","why":"TSHR-ECM/fibronectin interaction modulates signalling"}],"covers":["LR000671","LR004155"]},"LR011057":{"pair":"FRAS1:FREM2:NPNT -> ITGA8:ITGB1","headline":"Database-asserted: nephronectin binds integrin alpha8beta1; the FRAS1/FREM partners are not shown.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says NPNT is probably the functional ligand of the integrin in kidney genesis [DB:UniProt]. Direction or effect is otherwise not reported in our evidence.","molecular_requirements":"BioGRID lists NPNT-ITGA8 in reconstituted complex and affinity capture-western assays [DB:BioGRID]; Reactome has an NPNT:ITGA8:ITGB1 complex [DB:Reactome R-HSA-9830935]. A role for FRAS1 or FREM2 in the complex is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No curator-verified papers (three pending). Database evidence concerns NPNT with ITGA8 only; the ligand complex as a unit is unsupported.","key_references":[],"covers":["LR011057"]},"LR007214":{"pair":"GALP -> GALR1:GPR151","headline":"No primary evidence for a GALR1:GPR151 complex; support is for GALR1 alone from GtoPdb.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. GtoPdb lists GALP as an agonist at GALR1 alone [DB:GtoPdb].","molecular_requirements":"Whether GPR151 is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments for this complex are in our evidence; the papers judged were review-only or had insufficient abstracts.","localisation_and_range":"GALP is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Support rests on GALR1 records, not on GPR151 participation [DB:GtoPdb]. Treat as the single-receptor pair.","key_references":[],"covers":["LR007214"]},"LR004163":{"pair":"GAS6 -> AXL","headline":"Well-supported direct agonist interaction: crystal structure, Kd binding and receptor activation, all in curator-verified papers.","interaction_type":"direct binding","direction_and_effect":"GAS6 is an agonist that activates AXL; Gas6 binds Axl and stimulates its phosphorylation [PMID:8939948], and a purified factor identified as the Gas6 product stimulated Axl [PMID:7854420]. Activation by GAS6 varies with context: soluble ligand, apoptotic cells, phosphatidylserine vesicles or enveloped virus [PMID:25074926].","molecular_requirements":"The crystal structure of a minimal human Gas6/Axl complex shows 2:2 stoichiometry; Gas6's first laminin G-like domain crosslinks two Axl immunoglobulin-like domains, and both a major and a minor contact site are needed for signalling [PMID:16362042]. The Gla domain and EGF-like repeats were not required for receptor binding; the G-domain region is sufficient to bind [PMID:8621659]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926]. PDB structures exist [DB:PDB 2C5D] [DB:PDB 4RA0] [DB:PDB 5VXZ].","affinity_potency":[{"value":"Kd 0.4 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Axl-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Human Gas6 and human Axl in the structural and reporter studies [PMID:16362042] [PMID:25074926]; the Kd comes from rat Gas6 binding Axl-Fc, with activation tested in CHO cells [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and AXL transmembrane [flag]; GAS6 can also bridge phosphatidylserine on apoptotic cells or virus envelope to AXL [PMID:25074926] [DB:UniProt].","caveats":"All papers were read as abstracts only. One further paper was review-only. Gas6 also binds other TAM receptors, so AXL signalling is not unique to this ligand [PMID:8939948].","key_references":[{"PMID":"16362042","why":"Crystal structure of the Gas6/Axl 2:2 complex"},{"PMID":"8939948","why":"Kd of Gas6 for Axl-Fc and Gas6-induced Axl phosphorylation"},{"PMID":"25074926","why":"Context-dependent TAM activation by GAS6 and need for gamma-carboxylation"}],"covers":["LR000679","LR004163"]},"LR000680":{"pair":"GAS6 -> MERTK","headline":"Direct agonist interaction supported by binding with a Kd and by Mer phosphorylation; moderate affinity.","interaction_type":"direct binding","direction_and_effect":"GAS6 is an agonist of MERTK: Gas6 induced rapid phosphorylation of Mer in several cell types, followed by transient p42 MAP kinase activation [PMID:9160883], and stimulated Mer phosphorylation in CHO cells [PMID:8939948].","molecular_requirements":"Gas6 bound soluble Mer-Fc in co-precipitation, and protein S did not [PMID:8939948]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926]. Partner chains beyond Mer are not reported in our evidence.","affinity_potency":[{"value":"Kd 29 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Mer-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Curators record human ligand and receptor; the Kd used rat Gas6 and Mer-Fc, with phosphorylation in CHO cells [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and MERTK transmembrane [flag]. Reactome records MERTK binding Gas6 or Protein S [DB:Reactome].","caveats":"Abstract-only reading for all papers. The 29 nM Kd is the weakest of the three TAM receptors in the same study (0.4 and 2.7 nM for Axl and Sky) [PMID:8939948]. One paper is still pending.","key_references":[{"PMID":"8939948","why":"Kd of rat Gas6 for Mer-Fc"},{"PMID":"9160883","why":"Gas6 induces Mer phosphorylation and MAP kinase activation"},{"PMID":"25074926","why":"TAM reporter-line activation by GAS6"}],"covers":["LR000680","LR004164"]},"LR007223":{"pair":"GDF11 -> ACVR1B:ACVR2A","headline":"Database-asserted only: UniProt notes direct ACVR2A interaction by similarity; no verified paper for the complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: GDF11 interacts directly with ACVR2A (By similarity) [DB:UniProt].","molecular_requirements":"The ACVR1B partner is not addressed by the record shown [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"No judged papers (two review-only); the database line covers ACVR2A only.","key_references":[],"covers":["LR007223"]},"LR004172":{"pair":"GDF11 -> ACVR2A","headline":"GDF11 binds ActRIIA (ACVR2A) and ActRIIB and induces Smad2 phosphorylation, with supporting structural and binding work.","interaction_type":"direct binding","direction_and_effect":"Gdf11 binds both ActRIIA and ActRIIB and induces Smad2 phosphorylation; the two receptors cooperate in axial vertebral patterning [PMID:12414726]. A 2022 study lists GDF11 among high-affinity ACVR2A growth factors [PMID:35643319].","molecular_requirements":"ActRIIA and ActRIIB can compensate for one another; the type I receptor is not established there [PMID:12414726].","affinity_potency":[],"species_and_systems":"Mouse genetics plus biochemistry [PMID:12414726]; human proteins in SPR and crystallography of ACVR2A with activin A [PMID:35643319].","localisation_and_range":"GDF11 flagged secreted and ACVR2A transmembrane [flag].","caveats":"Both papers are abstract-level for this pair. The 2022 crystal structure is of ACVR2A with activin A, not GDF11; GDF11 data come from SPR (80 nM injections) and no GDF11 affinity value is quoted in our evidence.","key_references":[{"PMID":"12414726","why":"Gdf11 binds ActRIIA and ActRIIB, Smad2 phosphorylation"},{"PMID":"35643319","why":"ACVR2A high-affinity ligand panel including GDF11"}],"covers":["LR000688","LR004172"]},"LR011219":{"pair":"GDF3 -> BMPR2","headline":"Recombinant GDF3 binds BMPR2 directly by SPR, BLI and ITC; the paper calls it a BMPR2 antagonist, unlike the GtoPdb agonist record.","interaction_type":"direct binding","direction_and_effect":"GDF3 binds BMPR2 in three assays [PMID:40360531]. The paper concludes that GDF3 blocks BMP signalling by acting as a BMPR2 antagonist [PMID:40360531]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"Receptors were tested as Fc-fused ectodomains; GDF3 also bound ACVR2A and ACVR2B with high affinity but not TGFBR2 [PMID:40360531]. GDF3 showed negligible ITC interaction with BMP2, BMP4 and BMP9 [PMID:40360531].","affinity_potency":[{"value":"KD 6.01E-10 M","assay":"SPR","system":"rhGDF3 with rhBMPR2","cite":"PMID:40360531"},{"value":"KD 1.310E-08 M","assay":"BLI","system":"rmGDF3 with rhBMPR2","cite":"PMID:40360531"}],"species_and_systems":"Recombinant human and mouse GDF3 against human BMPR2-Fc; physiology in mice [PMID:40360531].","localisation_and_range":"GDF3 is flagged secreted [flag]; range not reported otherwise in our evidence.","caveats":"Effect conflicts: GtoPdb and the interaction record say agonist or stimulatory, the paper says antagonist. Fc-fusion receptor, not full-length membrane receptor.","key_references":[{"PMID":"40360531","why":"SPR, BLI and ITC binding of GDF3 to BMPR2; antagonist action"}],"covers":["LR011219"]},"LR004181":{"pair":"GDF5 -> ACVR2B","headline":"GDF5 binds ActR-IIB with nanomolar affinity in biosensor work, and in COS-1 cells; well supported.","interaction_type":"direct binding","direction_and_effect":"GDF5 binds preferentially to BMPR-IB and ActR-IIB [PMID:19735544]. GDF-5 also bound ActR-IIB in COS-1 transfectants [PMID:8702914]. Agonist per curators [PMID:8702914].","molecular_requirements":"Binding was measured with immobilised receptor ectodomains; CHAPS changed affinities and specificities [PMID:19735544]. Whether ActR-IIB acts with a type I partner is not reported in our evidence.","affinity_potency":[{"value":"KD (kin) 4.0 \u00b1 1.24 nM; KD (eq) 5.6 \u00b1 0.90 nM","assay":"biosensor (kinetic and equilibrium)","system":"GDF-5 over immobilised ActR-IIB ectodomain","cite":"PMID:19735544"}],"species_and_systems":"Recombinant ectodomain biosensor and COS-1 transfectants; curators label human [PMID:19735544][PMID:8702914].","localisation_and_range":"The receptor is flagged transmembrane [flag].","caveats":"Two of four confirmed rows shown. The biosensor used high salt buffer (500 mM NaCl) [PMID:19735544].","key_references":[{"PMID":"19735544","why":"Biosensor kinetics of GDF5 with type II receptors"},{"PMID":"8702914","why":"GDF-5 binds ActR-IIB in COS-1 cells"}],"covers":["LR000697","LR004181"]},"LR007232":{"pair":"GDF5 -> ACVR2B:BMPR1A","headline":"Complex pair with no curator-verified paper; rests on BioGRID, IntAct and UniProt records for single subunits.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says GDF5 binds BMPR1B with high affinity and BMPR1A with less affinity [DB:UniProt]. BioGRID has ACVR2B - GDF5 affinity capture-western [PMID:8702914][DB:BioGRID].","molecular_requirements":"The complex is assembled from separate subunit records and not shown as a unit in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"Only review-level sources were judged. The BioGRID records shown name BMPR1B and the type II subunit, not BMPR1A; IntAct entries are SPR records [DB:IntAct].","key_references":[],"covers":["LR007232"]},"LR007241":{"pair":"GDF7 -> ACVR2A:BMPR1B","headline":"GDF7 -> ACVR2A:BMPR1B: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ActRIIA shRNA suppressed GDF7 signalling, with ALK6 as the type I chain, in the curator's reading [PMID:16049014]. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of ACVR2A and BMPR1B (ALK6). Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007241"]},"LR004190":{"pair":"GDF7 -> BMPR1A","headline":"GDF7 binds BMPR1A (ALK3) directly with high affinity and functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ALK3 (BMPR1A) with high affinity, similar to rhBMP13 (GDF6) (numeric KD not in our excerpts) [PMID:21702718]. ALK3 overexpression in COS7 cells conferred GDF7 signalling, and ALK3 shRNA suppressed signalling by all three orphan ligands [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type I receptor; a type II receptor partner is implicated: BMPRII and ActRIIA shRNA suppressed GDF7 signalling [PMID:16049014].","affinity_potency":[],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Numeric affinities are not in the excerpts. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000706","LR004190"]},"LR000707":{"pair":"GDF7 -> BMPR2","headline":"GDF7 binds BMPR2 directly (KD 52.1 nM for rhBMP12) with functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound BMPR2 with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. BMPRII shRNA suppressed GDF7 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II receptors act with a type I partner: ALK3 or ALK6 overexpression conferred GDF7 signalling [PMID:16049014].","affinity_potency":[{"value":"KD 52.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs BMPR2 ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. BMPR2 binding was more than 10-fold weaker than type I binding [PMID:21702718]. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000707","LR004191"]},"LR000716":{"pair":"GHRH -> GHRHR","headline":"GHRH binds and activates the GHRH receptor; two cloning papers (abstract-only) plus structure and database support.","interaction_type":"direct binding","direction_and_effect":"Human GHRH binds the GHRHR with high affinity and stimulates cAMP production in transfected cells, consistent with agonism [PMID:1333056][PMID:7680413]. A specific GHRH antagonist blocked both binding and the second-messenger response [PMID:7680413]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone expressed in cells was sufficient for binding and cAMP signalling [PMID:7680413]; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in HEK293 and COS cells with human GHRH [PMID:1333056][PMID:7680413]. The mouse pair is projected from human evidence (ortholog-inferred). A structure is listed [DB:PDB 7CZ5].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]. GHRHR mRNA was mostly in anterior pituitary, so action is endocrine-type [PMID:7680413].","caveats":"Both papers read as abstracts only; no affinity value reported in our evidence.","key_references":[{"PMID":"1333056","why":"Cloned GHRHR; membrane binding of human GHRH and cAMP"},{"PMID":"7680413","why":"Human GHRH-R cloned; saturable binding, cAMP, antagonist block"}],"covers":["LR000716","LR004199"]},"LR010553":{"pair":"GLS2:SLC1A1 -> GRIN1:GRIN2A","headline":"Protein-association records only; no paper confirms GLS2:SLC1A1 -> GRIN1:GRIN2A as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010553"]},"LR010625":{"pair":"GNAI2 -> CNR1","headline":"GNAI2-CNR1 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western [DB:BioGRID][PMID:11168387]; PDB 7WV9 is a Gi-bound cannabinoid receptor 1 structure [DB:PDB 7WV9][PMID:35637350]; UniProt names CNR1 among interacting GPCRs [DB:UniProt][PMID:12359238]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR010625"]},"LR001832":{"pair":"GPHB5 -> TSHR","headline":"GPHB5, as part of the GPHA2:GPHB5 heterodimer, binds and activates TSHR; evidence is for the heterodimer, not the lone chain.","interaction_type":"direct binding","direction_and_effect":"The GPHA2/GPHB5 heterodimer (CGH, thyrostimulin) activates TSHR; 125I-CGH binding to TSHR cells was saturable, specific and of high affinity [PMID:16210345]. Agonist. In vivo CGH given to mice produced a hyperthyroid phenotype [PMID:16210345].","molecular_requirements":"The tested ligand is the GPHA2/GPHB5 heterodimer; GPHB5 alone was not shown to bind TSHR in our evidence. Unlabeled TSH did not compete for CGH binding, and the data are consistent with two binding sites, one shared with TSH and one binding CGH alone [PMID:16210345].","affinity_potency":[],"species_and_systems":"TSHR-transfected baby hamster kidney cells and mice; curators list human ligand and receptor [PMID:16210345].","localisation_and_range":"GPHB5 is flagged as secreted [flag].","caveats":"Chain-only caveat: support for GPHB5 is via the heterodimer. Abstract read only, and no affinity value reported in our evidence. Reactome records list TSHR binding TSH/thyrostimulin [DB:Reactome].","key_references":[{"PMID":"16210345","why":"Saturable high-affinity CGH binding to TSHR and competition data"}],"covers":["LR001832","LR005187"]},"LR000725":{"pair":"GPI -> AMFR","headline":"Secreted GPI (autocrine motility factor) binds its receptor AMFR/gp78; two abstract-only papers plus database records.","interaction_type":"direct binding","direction_and_effect":"GPI acts as a cytokine (autocrine motility factor) on binding its 78 kDa seven-transmembrane receptor gp78/AMF-R [PMID:12527360]. Agonist: AMF stimulates cell motility, and mutants with reduced receptor binding also lost motility stimulation [PMID:16563432].","molecular_requirements":"Enzymatic activity of GPI is not required for receptor binding or cytokine function [PMID:12527360]. Residues contacting the substrate phosphate group and the C-terminal region matter for binding and motility [PMID:16563432]. The receptor N-glycan is needed: mutant AMFR lacking it did not respond to AMF [PMID:16563432].","affinity_potency":[],"species_and_systems":"Recombinant human AMF and human receptor mutants in cell assays; abstracts do not name cell lines [PMID:12527360] [PMID:16563432].","localisation_and_range":"GPI is flagged as secreted [flag].","caveats":"Both papers read as abstract only; no affinity values reported in our evidence. One further paper is still pending and one was abstract_insufficient. BioGRID lists affinity capture-western and reconstituted complex records [DB:BioGRID]; UniProt describes AMFR as the receptor for GPI/AMF [DB:UniProt].","key_references":[{"PMID":"12527360","why":"Receptor binding and cytokine function independent of enzymatic activity"},{"PMID":"16563432","why":"Point mutants and AMFR glycan requirement for binding and motility"}],"covers":["LR000725"]},"LR002705":{"pair":"GPNMB -> GPR39","headline":"GPR39 is reported as a receptor for circulating GPNMB in cardiac repair; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"GPNMB was identified as a ligand for GPR39: GPR39 absence negated the beneficial effects of GPNMB after myocardial infarction [PMID:39455836]. Agonist-like effect: GPNMB enhanced myocyte contraction and reduced fibroblast activation in single-cell data [PMID:39455836].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Failing human and mouse hearts after MI; mouse loss-of-function models and viral delivery of GPNMB [PMID:39455836]. Human pair is ortholog-inferred.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the abstract refers to circulating GPNMB and a type I transmembrane protein [PMID:39455836].","caveats":"Abstract only. The binding claim in the title is not backed by a described binding assay in our evidence; the evidence is genetic (GPR39 absence).","key_references":[{"PMID":"39455836","why":"GPR39 identified as receptor for circulating GPNMB in cardiac repair"}],"covers":["LR002705","LR005970"]},"LR004208":{"pair":"GREM1 -> KDR","headline":"Gremlin binds and activates VEGFR2 (KDR) in several systems; monomeric gremlin acts as an antagonist.","interaction_type":"direct binding","direction_and_effect":"Gremlin binds VEGFR2 independently of BMP and activates it like VEGF-A, driving angiogenesis in vitro and in vivo [PMID:20660291]. Agonist effects were also reported in kidney cells, with NF-kB-linked inflammation [PMID:25810250], and in retinal pigment epithelial cells via Akt-mTORC2 [PMID:27894090]. In contrast, monomeric gremlin engages VEGFR2 non-productively and antagonises angiogenesis driven by dimeric gremlin or VEGF-A165 [PMID:27174917].","molecular_requirements":"Oligomeric state matters: the dimer activates, while the C141A mutant and wild-type monomers do not, and wild-type dimer induced VEGFR2 complex formation and internalisation while C141A did not [PMID:27174917]. Gremlin binding to VEGFR2 was fully competed by VEGF-A165 [PMID:27174917].","affinity_potency":[],"species_and_systems":"Human proteins in endothelial cells, murine kidney and renal cells, ARPE-19 cells, chick CAM and mouse Matrigel plug assays [PMID:20660291] [PMID:25810250] [PMID:27174917] [PMID:27894090].","localisation_and_range":"GREM1 is flagged as secreted [flag]; gremlin also binds heparan sulphate proteoglycans on cells [PMID:27174917].","caveats":"Effect depends on gremlin oligomeric form. A surface plasmon resonance comparison is mentioned only as prior work, with no numeric value in our evidence [PMID:27174917]. Most papers read as abstract only. IntAct has a cross-linking record [DB:IntAct]. Four of eight confirmed rows are shown.","key_references":[{"PMID":"20660291","why":"Original report of gremlin binding and activating VEGFR2"},{"PMID":"27174917","why":"Monomer versus dimer: antagonist versus agonist"},{"PMID":"25810250","why":"Gremlin-VEGFR2 signalling in kidney inflammation"}],"covers":["LR000726","LR004208"]},"LR011156":{"pair":"GZMA -> F2R","headline":"Granzyme A may cleave and activate PAR1, weakly, in one in vitro study; a second paper is computational.","interaction_type":"functional only","direction_and_effect":"GzmK and, to a lesser extent, GzmA were reported to activate PAR1 and PAR2 using peptides and full-length proteins; cleavage occurs at the canonical arginine P1 residue [PMID:35881628]. A glioblastoma scRNA-seq study lists GZMA-F2R among receptor-ligand interactions [PMID:40678806].","molecular_requirements":"Cleavage involves exosite interactions between protease and receptor [PMID:35881628].","affinity_potency":[],"species_and_systems":"Peptides, full-length proteins and A549 cells [PMID:35881628]; scRNA-seq of glioblastoma [PMID:40678806].","localisation_and_range":"F2R is flagged transmembrane receptor [flag]. GzmA is not flagged secreted.","caveats":"The first paper focuses on GzmK; GzmA is secondary and abstract-only. The second paper is computational. This is protease cleavage activation, not classical ligand binding.","key_references":[{"PMID":"35881628","why":"GzmK and GzmA activate PAR1/PAR2"},{"PMID":"40678806","why":"Computational GZMA-F2R interaction in GBM scRNA-seq"}],"covers":["LR011156"]},"LR000734":{"pair":"HBEGF -> CD44","headline":"HB-EGF binds heparan sulfate-modified CD44 isoforms in COS-cell transfectants; binding depends on the sugar chain.","interaction_type":"direct binding","direction_and_effect":"HS-modified CD44 isoforms bound HB-EGF and b-FGF but not amphiregulin; binding was eliminated by heparitinase or free heparin [PMID:7532176]. CD44 here presents the growth factor; signalling effect is not reported in our evidence.","molecular_requirements":"Requires CD44 isoforms containing exon V3 that carry heparan sulfate; CD44H lacking V3 on activated endothelial cells showed no detectable HS modification [PMID:7532176]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human cells: COS transfectants and keratinocytes; HB-EGF binding shown for the transfectants [PMID:7532176]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted and transmembrane [flag]; presentation at cell surfaces during inflammation is the authors' proposal [PMID:7532176].","caveats":"Binding is heparan sulfate-mediated, so it may not be a protein-protein ligand-receptor interaction. One paper; no affinity.","key_references":[{"PMID":"7532176","why":"HS-modified CD44 V3 isoforms bind HB-EGF"}],"covers":["LR000734","LR004216"]},"LR004217":{"pair":"HBEGF -> CD9","headline":"CD9 physically associates with membrane HB-EGF and boosts its diphtheria toxin binding; a co-receptor-like partner.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation and cross-linking suggest tight association of CD9 with membrane HB-EGF, and CD9 increased cell-surface DT-binding sites 15-fold [PMID:8194524]. Reactome has DT:HBEGF:CD9 complexes [DB:Reactome R-HSA-5334770].","molecular_requirements":"Human and monkey CD9 up-regulated DT binding but mouse CD9 did not; residues between Ala156 and Asp183, notably Gly158, Val159 and Thr175, were required [PMID:11735113].","affinity_potency":[],"species_and_systems":"Mouse L cell transfectants with monkey CD9 [PMID:8194524]; human/monkey/mouse CD9 chimeras [PMID:11735113]. Mouse pair is ortholog-inferred, and mouse CD9 lacked up-regulation activity here [PMID:11735113].","localisation_and_range":"Membrane-bound proHB-EGF with CD9 in the same membrane (juxtacrine) [flag].","caveats":"Readouts are diphtheria toxin binding, not HB-EGF signalling. Abstracts only; two further judged papers were insufficient.","key_references":[{"PMID":"8194524","why":"CD9 associates with HB-EGF/DTR, co-IP and cross-linking"},{"PMID":"11735113","why":"CD9 residues needed for up-regulation"}],"covers":["LR000735","LR004217"]},"LR003713":{"pair":"Hc -> C5ar1","headline":"C5a (mouse Hc) acts at C5aR in human systems; the only papers are human, and the mouse pair is inferred.","interaction_type":"direct binding","direction_and_effect":"Mutational mapping showed the C terminus of C5a is responsible for all agonist activity at human C5aR, with Arg206 and Arg175 contacting the C-terminal carboxylate [PMID:15661745]. Small cyclic antagonists blocked human recombinant C5a effects on PMN and umbilical artery [PMID:10602324].","molecular_requirements":"Receptor residues Ile116, Arg175, Arg206, Glu199, Asp282 and Val286 were tested [PMID:15661745]. Complex or coreceptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"All experiments used human C5a and human receptors (PMNs, umbilical artery, mutant receptors); the mouse pair is ortholog-inferred [PMID:15661745][PMID:10602324].","localisation_and_range":"Hc is flagged secreted [flag], so acting as a soluble paracrine or systemic ligand.","caveats":"Abstracts only. The third paper, PMID:11773063, concerns C5L2 (C5ar2) rather than C5aR [PMID:11773063]. No mouse experiments in our evidence.","key_references":[{"PMID":"15661745","why":"C5a C-terminus binding site on human C5aR"},{"PMID":"10602324","why":"Antagonists of C5aR block C5a responses"}],"covers":["LR003713"]},"LR000743":{"pair":"HGF -> CD44","headline":"HGF binds CD44 variants directly (CD44v6 in the micromolar range; CD44v3 via heparan sulfate), but CD44 acts as a co-receptor for MET rather than a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"CD44v3 binds HGF/SF through its heparan sulfate chains and enhances HGF-induced c-Met phosphorylation and ERK1/2 activation, acting as a co-receptor [PMID:10037743]. CD44v6 ectodomain, but not CD44s, reduced HGF-induced Met and Erk activation in a dose-dependent way [PMID:26181364].","molecular_requirements":"Isoform-specific: CD44v3 (heparan sulfate-modified; binding abolished by heparitinase) [PMID:10037743] and CD44v6 (binding heparan sulfate-independent) [PMID:26181364]. CD44s did not promote Met activation [PMID:10037743][PMID:26181364]. MET is also needed for signalling.","affinity_potency":[{"value":"micromolar range (no number given in the dossier)","assay":"MicroScale Thermophoresis, fluorescence correlation spectroscopy, fluorescence anisotropy","system":"CD44v6 with HGF","cite":"PMID:26181364"}],"species_and_systems":"Cell models: Namalwa lymphoma cells co-transfected with c-Met [PMID:10037743]; BSp73ASs6 cells and purified CD44v6 ectodomain [PMID:26181364]. Species of the proteins is not stated beyond the dossier labels; the mouse pair is ortholog-inferred.","localisation_and_range":"HGF flagged secreted; CD44 flagged transmembrane and also secreted [flag]; HGF acts on cell-surface CD44 as a presenting co-receptor.","caveats":"CD44 is a co-receptor presenting HGF to MET, not a classical signalling receptor, so scoring HGF-CD44 as an independent pair may overstate it. Both papers were abstract-level for the first and full-text for the second; one IntAct cross-linking record also exists [DB:IntAct].","key_references":[{"PMID":"10037743","why":"CD44v3 binds HGF/SF via heparan sulfate and enhances c-Met signalling"},{"PMID":"26181364","why":"Direct binding of CD44v6 to HGF with micromolar affinity"}],"covers":["LR000743","LR004224"]},"LR004226":{"pair":"HGF -> SDC1","headline":"Syndecan-1 binds HGF through heparan sulfate and presents it to Met; a co-receptor, supported by one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Syndecan-1 binds HGF via its heparan sulfate moieties, and this promotes HGF-mediated Met activation and downstream PI3K/PKB and RAS/MAPK signalling in multiple myeloma cells [PMID:11830493]. It acts as a co-receptor presenting HGF to Met, not as an independent signalling receptor [PMID:11830493].","molecular_requirements":"Heparan sulfate chains on syndecan-1 mediate HGF binding; Met is needed for signalling [PMID:11830493].","affinity_potency":[],"species_and_systems":"Human multiple myeloma cells [PMID:11830493]. The mouse pair is ortholog-inferred, not experimentally tested in our evidence.","localisation_and_range":"SDC1 is annotated as a transmembrane receptor, and HGF as secreted [flag].","caveats":"One paper, read as an abstract. BioGRID lists a reconstituted-complex record from the same paper [DB:BioGRID]. Binding is glycan-mediated, so it may be shared with other heparan sulfate proteoglycans.","key_references":[{"PMID":"11830493","why":"Syndecan-1 binds HGF and enhances Met signalling in myeloma"}],"covers":["LR000745","LR004226"]},"LR002714":{"pair":"HHLA2 -> KIR3DL3","headline":"KIR3DL3 identified as an inhibitory receptor for HHLA2 by receptor screen and flow-cytometry binding; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"KIR3DL3 is an inhibitory receptor for HHLA2 on T and NK cells, and HHLA2/KIR3DL3 antibodies block HHLA2's immune-inhibitory activity while preserving the costimulatory signal [PMID:33229411]. HHLA2 also binds TMIGD2 [PMID:33229411].","molecular_requirements":"A 5,500 cDNA screen identified only KIR3DL3; HHLA2-Ig bound KIR3DL3 and not other KIR family members [PMID:33229411]. No co-receptor is reported.","affinity_potency":[],"species_and_systems":"Human proteins; binding tested on mouse 300.19 pre-B cells and human 293T cells overexpressing KIR3DL3, which are recombinant systems [PMID:33229411].","localisation_and_range":"HHLA2 is annotated as not secreted [flag], so signalling is likely contact-dependent (juxtacrine).","caveats":"Single paper. The relative KIR3DL3 and TMIGD2 affinities were described only as similar 50% maximal binding, with no values [PMID:33229411]. One further paper is pending.","key_references":[{"PMID":"33229411","why":"KIR3DL3 identified as inhibitory HHLA2 receptor"}],"covers":["LR002714"]},"LR000752":{"pair":"HLA-B -> KLRD1","headline":"Weak, single 1994 functional study of CD94 (Kp43) as an HLA-B7 receptor; no binding data.","interaction_type":"functional only","direction_and_effect":"Kp43 (CD94) molecules function as receptors for HLA-B7; the interaction results in inhibition of NK cytolytic activity [PMID:8046333]. Cross-linking Kp43 with XA185 mAb strongly inhibited cytolysis of HLA-B7-specific NK clones [PMID:8046333].","molecular_requirements":"Not reported in our evidence; partner chains such as NKG2 are not discussed in the dossier.","affinity_potency":[],"species_and_systems":"Human NK clones with HLA-class I transfected target cells [PMID:8046333].","localisation_and_range":"KLRD1 has no transmembrane flag in the entity record, though HLA-B is flagged transmembrane [flag]; localisation otherwise not reported.","caveats":"Evidence is a single abstract-level functional paper with redirected-killing and mAb data, not physical binding. It covers HLA-B7 only; the curator note says it was not seen for B27. Two further rows are pending. No database records.","key_references":[{"PMID":"8046333","why":"Kp43/CD94 as inhibitory receptor for HLA-B7"}],"covers":["LR000752"]},"LR002723":{"pair":"HLA-C -> KIR2DL2","headline":"Direct binding of KIR2DL2 to HLA-C group C1 (Asn80) is reported in one 2017 study; otherwise only review-level support.","interaction_type":"direct binding","direction_and_effect":"KIR2DL2 is an inhibitory KIR binding HLA-C of group C1 (Asn80) [PMID:28352266].","molecular_requirements":"Binding to C1 allotype HLA-C*08:02 occurred with only a subset of peptides, and cross-reactive KIR2DL2-C2 binding was restricted to even fewer peptides [PMID:28352266].","affinity_potency":[],"species_and_systems":"Human proteins with eluted endogenous peptides [PMID:28352266].","localisation_and_range":"HLA-C is annotated transmembrane [flag]; KIR2DL2 has no transmembrane flag in our evidence.","caveats":"One confirmed paper; two others were judged review-only. Only an abstract plus excerpts were available. No affinity.","key_references":[{"PMID":"28352266","why":"KIR2DL2-C1 binding is peptide-selective"}],"covers":["LR002723"]},"LR000761":{"pair":"HLA-E -> KLRC2","headline":"Direct binding of HLA-E to activating KLRC2 (NKG2C, with CD94), at lower affinity than NKG2A.","interaction_type":"direct binding","direction_and_effect":"NKG2C/CD94 is activating and binds HLA-E, at significantly lower affinity than NKG2A/CD94 and NKG2E/CD94 [PMID:15728498]. HLA-E tetramer also bound CD94/NKG2C transfectants [PMID:9486650].","molecular_requirements":"Tested as CD94/NKG2C heterodimer; KLRC2 alone not reported in our evidence. UniProt: KLRD1-KLRC2 complex binds with low affinity to HLA-E loaded with self-peptides [DB:UniProt]. Peptide identity influenced affinity [PMID:15728498].","affinity_potency":[],"species_and_systems":"Human; purified receptor/HLA-E complexes and transfectants [PMID:15728498][PMID:9486650].","localisation_and_range":"Annotation flags: HLA-E secreted and transmembrane, KLRC2 transmembrane [flag].","caveats":"No numeric affinity in our evidence. Abstract-only papers. One paper abstract-insufficient, one review-only, one different entity.","key_references":[{"PMID":"15728498","why":"NKG2C/CD94 binds HLA-E with lower affinity"},{"PMID":"9486650","why":"HLA-E tetramer binds CD94/NKG2C"}],"covers":["LR000761"]},"LR001841":{"pair":"HLA-F -> LILRB1","headline":"HLA-F binds LILRB1 (ILT2) by surface plasmon resonance; one older abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"HLA-F tetramer binding was conferred on non-binding cells by transfecting ILT2 or ILT4, and surface plasmon resonance showed direct HLA-F interaction with ILT2 and ILT4 [PMID:11169396]. Signalling effect not reported in our evidence.","molecular_requirements":"HLA-F was refolded with beta2-microglobulin as a complex [PMID:11169396]. A PDB structure (5KNM) with HLA-F and LILRB1 chains is listed [DB:PDB 5KNM].","affinity_potency":[],"species_and_systems":"Human recombinant protein and transfected cells [PMID:11169396].","localisation_and_range":"HLA-F is flagged transmembrane [flag]; it was undetected at the cell surface in the authors' hands [PMID:11169396].","caveats":"Abstract only; no affinity value in the dossier. Authors note physiological relevance depends on HLA-F surface expression [PMID:11169396]. BioGRID and UniProt support is reconstituted-complex or annotation [DB:BioGRID, DB:UniProt]. One more row was abstract_insufficient and one pending.","key_references":[{"PMID":"11169396","why":"SPR and tetramer binding of HLA-F to ILT2/ILT4"}],"covers":["LR001841"]},"LR002732":{"pair":"HLA-G -> CD8A","headline":"HLA-G bound by CD8alphaalpha at low affinity by surface plasmon resonance; co-receptor interaction, one abstract.","interaction_type":"direct binding","direction_and_effect":"CD8alphaalpha bound class I MHC molecules in surface plasmon resonance; the curator records HLA-G as bound normally [PMID:10809759]. Signalling effect not reported in our evidence.","molecular_requirements":"CD8alpha homodimer; binding mapped to the alpha3 domain of MHC [PMID:10809759].","affinity_potency":[{"value":"Kd ~150 microM","assay":"surface plasmon resonance","system":"CD8alphaalpha with HLA-G","cite":"PMID:10809759"}],"species_and_systems":"Human recombinant proteins [PMID:10809759].","localisation_and_range":"HLA-G and CD8A flagged secreted and transmembrane [flag].","caveats":"Very weak affinity, similar to classical MHC (90-220 microm) [PMID:10809759]; HLA-G value comes from curator notes, not the abstract. This is a co-receptor interaction.","key_references":[{"PMID":"10809759","why":"SPR of CD8alphaalpha binding class I MHC including HLA-G"}],"covers":["LR002732"]},"LR002741":{"pair":"HMGB1 -> TREM1","headline":"One recent paper reports HMGB1 binding TREM-1 in solution and on monocytes, with activation; no Kd reported.","interaction_type":"direct binding","direction_and_effect":"HMGB1 binds TREM-1 at high affinity in solution and on the cell surface; binding causes lymphocytes to release IL-2, IL-1b, IL-6, TNF and Ifny, and cytotoxic lymphocytes capable of lysing HLA-negative tumour cells appear in PBMC [PMID:38203798]. Release of soluble TREM-1 from monocytes rises dose-dependently with HMGB1 [PMID:38203798]. UniProt lists HMGB1 among TREM1 activating ligands [DB:UniProt].","molecular_requirements":"HMGB1 appears to bind the TREM-1 monomer (about 52 kDa cross-linked complex, an equimolar 27 + 26 kDa complex) [PMID:38203798]. The paper's text recalls that HMGB1 is considered to need co-activating molecules for TREM-1 activation (background, not tested here).","affinity_potency":[{"value":"I50 1 \u00b1 0.2 nM","assay":"half-maximal cytotoxicity of lymphocytes versus HMGB1 concentration (functional potency, not binding)","system":"human PBMC","cite":"PMID:38203798"}],"species_and_systems":"Human proteins and human PBMC/monocytes [PMID:38203798]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged as secreted [flag]; the paper describes secretion during inflammation and binding to monocyte surface TREM-1 [PMID:38203798].","caveats":"Read as abstract plus excerpts; the high-affinity claim has no Kd in our evidence. Binding was shown by cross-linking, immunoprecipitation and confocal colocalisation.","key_references":[{"PMID":"38203798","why":"HMGB1 binds TREM-1 in solution and on monocytes and activates cytotoxic lymphocytes"}],"covers":["LR002741","LR005989"]},"LR000770":{"pair":"HP -> ITGB2","headline":"Haptoglobin binds the CD11b/CD18 integrin on monocytic cells; evidence is chain-level for ITGB2 (CD18) from one 1996 paper.","interaction_type":"direct binding","direction_and_effect":"Haptoglobin binds purified CD11b/CD18, indicating direct binding; anti-CD11b mAb44 inhibits haptoglobin binding to THP1/U937 cells, and an anti-CD18 mAb partly inhibits it [PMID:8786317]. Binding was increased by Ca2+/ADP and inhibited by fibrinogen [PMID:8786317].","molecular_requirements":"The functional receptor is the CD11b/CD18 heterodimer; the CD18 antibody inhibited only partly, so the beta chain alone is not shown sufficient [PMID:8786317]. No interference from anti-CD11a or anti-CD11c mAbs [PMID:8786317].","affinity_potency":[{"value":"Kd 6.5 x 10(-6)","assay":"radioiodinated haptoglobin binding, one receptor class, 1.7 x 10(5) sites per cell (low affinity)","system":"human THP1 cells","cite":"PMID:8786317"}],"species_and_systems":"Human haptoglobin and human monocytic cell lines (THP1, U937), monocytes and granulocytes [PMID:8786317]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading. The affinity was measured on whole cells, not on the single chain. One further row is pending.","key_references":[{"PMID":"8786317","why":"Haptoglobin binds CD11b/CD18 on THP1 cells and purified integrin"}],"covers":["LR000770","LR004229"]},"LR002750":{"pair":"HSP90B1 -> SCARF1","headline":"gp96 is endocytosed via SREC-I (SCARF1) in transfected cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Ectopic SREC-I expression in CHO cells confers recognition and uptake of calreticulin and gp96; uptake is competed by fucoidin and acetylated LDL [PMID:15371419]. SREC-I overexpression in macrophages increases chaperone endocytosis [PMID:15371419].","molecular_requirements":"SREC-I acts in addition to scavenger receptor class A; not all AcLDL-binding scavenger receptors bind these chaperones [PMID:15371419].","affinity_potency":[],"species_and_systems":"CHO cells and macrophages; curated as human [PMID:15371419]. The mouse pair is listed without ortholog inference.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; the paper treats gp96 as an extracellular chaperone endocytosed by the receptor [PMID:15371419].","caveats":"Abstract-only reading; the evidence is uptake and competition, no Kd.","key_references":[{"PMID":"15371419","why":"SREC-I mediates endocytosis of calreticulin and gp96"}],"covers":["LR002750","LR005998"]},"LR004235":{"pair":"HSPG2 -> ITGA2","headline":"Endorepellin, the perlecan C-terminal fragment, signals through alpha2beta1 integrin in endothelial cells; evidence is for the fragment, not full-length perlecan.","interaction_type":"functional only","direction_and_effect":"The interaction between endorepellin and alpha2beta1 integrin raised cAMP, activated PKA and FAK, transiently activated p38 and HSP27, and led to disassembly of actin stress fibers and focal adhesions, blocking endothelial migration and angiogenesis [PMID:15240572]. Reactome records endorepellin binding alpha2beta1 integrin [DB:Reactome R-HSA-4088220].","molecular_requirements":"Acting form is the soluble C-terminal fragment (endorepellin; LG3 module said to hold most activity), paired with alpha2beta1, so ITGB1 is also needed [PMID:15240572] [DB:Reactome R-HSA-4088236].","affinity_potency":[],"species_and_systems":"Endothelial cells including HUVECs, in vitro, per the paper [PMID:15240572]. Species of the receptor assay beyond that is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Perlecan is flagged secreted [flag]; endorepellin is described as a soluble proteolytic fragment released from basement membrane [PMID:15240572].","caveats":"Evidence is for a fragment, not full-length HSPG2. Two other papers judged abstract_insufficient and are not shown. The alpha2 chain alone is not shown to be sufficient.","key_references":[{"PMID":"15240572","why":"Endorepellin-alpha2beta1 integrin signalling in endothelial cells"}],"covers":["LR000777","LR004235"]},"LR008024":{"pair":"IAPP -> CALCRL:RAMP1","headline":"Weakly supported: GtoPdb and PDB records exist, but the dossier's structures and UniProt text point to CALCR:RAMP1, not CALCRL; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IAPP-RAMP1 full agonist records [DB:GtoPdb]. UniProt describes RAMP1 together with CALCR (not CALCRL) as the AMYR1 receptor for amylin [DB:UniProt].","molecular_requirements":"Records name RAMP1 but pair it with CALCR [DB:UniProt]; PDB 9BLW lists chains of P10997 and O60894 only, i.e. IAPP and RAMP1 [DB:PDB 9BLW].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"IAPP is flagged secreted and the complex transmembrane [flag].","caveats":"No curated paper confirms it: judged rows were review_only (1), different_entity (1) and abstract_insufficient (3). The CALCRL (AM1) partner is not supported by the database text.","key_references":[],"covers":["LR008024"]},"LR004244":{"pair":"ICAM1 -> ITGAX","headline":"Single abstract-level report of direct ICAM-1 binding to CD11c/CD18 by surface plasmon resonance; one paper only.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 acts as agonist/adhesion ligand for CD11c/CD18 (alphaXbeta2); surface plasmon resonance showed direct interaction, and soluble ICAM-1-Fc and a mimicking peptide competed for CD11c/CD18 binding [PMID:16252253].","molecular_requirements":"The evidence is for the alphaXbeta2 heterodimer, not ITGAX alone; ICAM-1 domain D4 was required, and the peptide did not bind alphaMbeta2 [PMID:16252253]. ITGB2 is therefore needed alongside ITGAX.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; mouse pair is projected from human evidence (ortholog inferred). Recombinant/in vitro binding [PMID:16252253].","localisation_and_range":"ICAM1 carries a secreted annotation flag [flag], but the evidence here is cell-surface adhesion, i.e. membrane-bound, contact-dependent signalling; the flag-based secreted label should be read with care.","caveats":"Single paper, read as abstract only [PMID:16252253]. One further judged row was abstract_insufficient. No database records.","key_references":[{"PMID":"16252253","why":"SPR and competition showing ICAM-1 binds CD11c/CD18 via domain D4"}],"covers":["LR000786","LR004244"]},"LR007043":{"pair":"ICAM3 -> ITGAL:ITGB2","headline":"ICAM-3 engages LFA-1 as a weaker co-stimulatory ligand than ICAM-1; one functional abstract, plus PDB structure and UniProt.","interaction_type":"direct binding","direction_and_effect":"T cells co-stimulated through LFA-1 on immobilised ICAM-3 showed weak proliferation relative to ICAM-1 (high) and ICAM-2 (intermediate), with distinct IL-10 and TNF-alpha profiles [PMID:10427988]. A PDB structure has chains of ICAM-3 and ITGAL [DB:PDB 1T0P].","molecular_requirements":"UniProt gives ITGAL:ITGB2 as the ICAM-3 receptor [DB:UniProt]; the structure contains only the ITGAL chain [DB:PDB 1T0P].","affinity_potency":[],"species_and_systems":"Human T cells on immobilised ICAMs [PMID:10427988].","localisation_and_range":"Membrane-bound; contact-dependent. UniProt also notes ICAM3-ITGAL/ITGB2 in apoptotic neutrophil phagocytosis [DB:UniProt].","caveats":"Single paper, abstract only; its evidence sentence is general LFA-1 background. IntAct has an x-ray crystallography record [DB:IntAct].","key_references":[{"PMID":"10427988","why":"Graded T-cell co-stimulation by ICAM-1/2/3 through LFA-1"}],"covers":["LR007043"]},"LR004253":{"pair":"ICAM4 -> ITGAV","headline":"alphaV-family integrins, notably alphaVbeta3, interact with ICAM-4; evidence is cell-based with abstract-only reading.","interaction_type":"direct binding","direction_and_effect":"Cell-surface ICAM-4 interacts with cell-surface alphaVbeta3 [PMID:15355350]. Adhesion of alpha4beta1-negative cells to ICAM-4-Fc is mediated by RGD-inhibitable alphaV integrins (notably alphaVbeta1 and alphaVbeta5), by antibody inhibition [PMID:11435317].","molecular_requirements":"The alphaVbeta3 contact site uses residues on both faces of D1 and the C'-E loop of D2, distinct from but overlapping the alphaIIbbeta3 site [PMID:15355350]. Partner beta chain varies (beta1, beta3, beta5) across studies.","affinity_potency":[],"species_and_systems":"Human ICAM-4 in [PMID:15355350]; the curated species for [PMID:11435317] is mouse here, although the abstract does not state it.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. UniProt notes ITGA2B:ITGB3 as an erythrocyte ICAM4 receptor [DB:UniProt].","caveats":"Both papers abstract only. [PMID:11435317] rests on peptide and antibody inhibition. A further judged row was abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"alphaVbeta3 contact site on ICAM-4"},{"PMID":"11435317","why":"alphaV-family integrins mediate adhesion to ICAM-4-Fc"}],"covers":["LR000799","LR004253"]},"LR008312":{"pair":"ICAM5 -> IGDCC3","headline":"Binding seen in a high-throughput human IgSF interactome screen with SPR validation, but the paper names PUNC (and PUNC e11); no other evidence.","interaction_type":"direct binding","direction_and_effect":"In an ELISA-based screen of recombinant human cell-surface and secreted proteins, PUNC e11 and PRTG bound ICAM5; ICAM5 and PUNC (and PUNC e11) are listed among SPR-validated PPIs in Table 1. Direction and effect are not reported in our evidence [PMID:32822567].","molecular_requirements":"Recombinant extracellular-domain Fc fusions were used; subunit requirements are not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, in vitro screen and SPR [PMID:32822567].","localisation_and_range":"ICAM5 carries a secreted flag [flag]; the paper describes ICAM5 as brain-expressed and cites a cleaved ECD, which is background [PMID:32822567].","caveats":"Single high-throughput paper; the evidence sentence names PUNC e11, so the match to IGDCC3 relies on the alias. Affinity not reported in our evidence.","key_references":[{"PMID":"32822567","why":"Human IgSF interactome with SPR validation"}],"covers":["LR008312"]},"LR006008":{"pair":"ICAM5 -> ITGB1","headline":"beta1 integrins co-purify with ICAM-5 from mouse brain and regulate spine maturation; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"beta1 integrins were immunoprecipitated with ICAM-5 from mouse brain, and antibodies to ICAM-5 and beta1 integrins altered spine maturation [PMID:23015592].","molecular_requirements":"The binding region in ICAM-5 maps to its first two Ig domains; which alpha partner is needed is not reported in our evidence [PMID:23015592].","affinity_potency":[],"species_and_systems":"Mouse brain and neurons [PMID:23015592]; the human interaction is ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the paper notes shedding of the ICAM-5 ectodomain promotes spine maturation, and beta1 integrins lie juxtaposed to filopodia tips [PMID:23015592].","caveats":"One paper, abstract only; a second confirmed row is not shown. Co-immunoprecipitation from tissue does not prove direct contact. Affinity not reported.","key_references":[{"PMID":"23015592","why":"beta1 integrins as ICAM-5 binding partners in synapse formation"}],"covers":["LR002762","LR006008"]},"LR001850":{"pair":"ICOSLG -> ICOS","headline":"Established costimulatory pair; mouse in vitro and in vivo evidence, plus human cell-line data and database complex records.","interaction_type":"functional only","direction_and_effect":"ICOS-ICOSL interaction is stimulatory. B7RP-1 co-stimulates T cells [PMID:10617205]. Blocking the interaction reduced airway hyperreactivity and ILC2 function and survival via STAT5 [PMID:25769613]. In human CIK cells, anti-ICOSL antibody attenuated ICOS-driven cytotoxicity [PMID:21955433].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (T cells, ILC2s, transgenic mice) [PMID:10617205] [PMID:25769613], humanised mice and human ILC2 blocking [PMID:25769613], human CIK cells [PMID:21955433]. The human pair is ortholog-inferred. Database records (BioGRID, IntAct SPR, Reactome, PDB 6X4G) cover the human proteins [DB:BioGRID] [DB:IntAct] [DB:Reactome] [DB:PDB 6X4G].","localisation_and_range":"Both flagged transmembrane (membrane-bound, contact) [flag]. ILC2s express both ICOS and ICOS-L; trans interaction was suggested, cis possible [PMID:25769613].","caveats":"Papers are functional; two of three were read as abstract only [PMID:10617205] [PMID:21955433]. ICOS is flagged secreted, which looks like an annotation oddity [flag].","key_references":[{"PMID":"25769613","why":"Full-text ICOS:ICOS-L requirement in ILC2s"},{"PMID":"10617205","why":"Original murine ICOS/B7RP-1 pair"},{"PMID":"21955433","why":"Human CIK cell ICOS-ICOSL blocking"}],"covers":["LR001850"]},"LR000806":{"pair":"IFNA10 -> IFNAR2","headline":"Direct binding of the IFNAR2 chain by alpha-IFNs at nanomolar affinity (class statement).","interaction_type":"direct binding","direction_and_effect":"IFNA10 is a stimulatory agonist at IFNAR2 [PMID:21856167] [DB:GtoPdb].","molecular_requirements":"Chain-only evidence on isolated IFNAR2 [PMID:21856167].","affinity_potency":[{"value":"0.4-5 nM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated receptor chains.","localisation_and_range":"IFNA10 flagged secreted [flag].","caveats":"Abstract only; IFNA10 not named in the abstract.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR000806"]},"LR011714":{"pair":"IFNA16 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA16 to a complex listing IFNA2, IFNAR1 and IFNAR2 rests only on GtoPdb; no paper was verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA16 as an agonist at IFNAR1 and at IFNAR2 [DB:GtoPdb]. No curator-verified paper supports the pair.","molecular_requirements":"The receptor entry includes IFNA2 as a member alongside IFNAR1 and IFNAR2, which is unexpected for a receptor complex; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experiment in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Judged papers were all abstract_insufficient or about a different entity, so none confirms the pair. Support is from GtoPdb records for the individual chains only; affinity not given (units '-') [DB:GtoPdb].","key_references":[],"covers":["LR011714"]},"LR000815":{"pair":"IFNA21 -> IFNAR1","headline":"IFNA21 binds IFNAR1 only on class-wide evidence from one abstract; the chain is the weak-affinity subunit.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM [PMID:21856167]. GtoPdb lists IFNA21 as an agonist at IFNAR1 [DB:GtoPdb].","molecular_requirements":"IFNAR1 binds about 1000-fold more weakly than IFNAR2 per the curator's reading; IFNAR2 is the tighter chain [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA21. Binding is to the isolated chain, not the functional heterodimer.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000815"]},"LR000824":{"pair":"IFNA6 -> IFNAR2","headline":"IFNA6 binds IFNAR2 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000824","LR004268"]},"LR004262":{"pair":"Ifna9 -> Ifnar2","headline":"Mouse Ifna9 to Ifnar2 is projected from human alpha-IFN binding data; no mouse experiment, no database records.","interaction_type":"direct binding","direction_and_effect":"Human alpha-IFN subtypes bind isolated human receptor chains [PMID:21856167]. No database records are listed. Effect direction for the mouse pair is not reported in our evidence.","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Experiments used human proteins [PMID:21856167]; the mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Support is an orthology projection from a class-wide human study read as abstract only; Ifna9 is not individually tested [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR004262"]},"LR011723":{"pair":"IFNB1 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNB1 to an IFNA2:IFNAR1:IFNAR2 complex has no verified paper; support is database records on individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNB1 as an agonist at IFNAR1 and IFNAR2 [DB:GtoPdb]. UniProt says IFNB1 signals via the high-affinity IFNAR2 and low-affinity IFNAR1 heterodimeric receptor [DB:UniProt]. Reactome has a binding reaction 'IFN alpha/beta binds to IFNAR2' [DB:Reactome]. IntAct records a physical association by anti tag coimmunoprecipitation [DB:IntAct].","molecular_requirements":"The entity includes IFNA2, a ligand, alongside IFNAR1 and IFNAR2 [flag]; subunit requirements for this exact complex are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no verified experiments (three papers pending) in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"No curator-verified paper; three papers remain pending. Support is databases only.","key_references":[],"covers":["LR011723"]},"LR004271":{"pair":"IFNG -> IFNGR1","headline":"IFN-gamma binds IFNGR1 directly; crystal structures and a human loss-of-binding study support it, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"IFN-gamma is the agonist ligand; GtoPdb lists Type=Agonist [DB:GtoPdb]. The curated modulatory effect is Stimulatory. Cells from patients with IFNGR1 ligand-binding-domain mutations showed no specific binding of (125)I-IFN-gamma and did not respond to IFN-gamma [PMID:10811850].","molecular_requirements":"IFNGR1 is the ligand-binding chain [PMID:10811850]. A 2:1 receptor-ligand complex plus an unexpected third receptor molecule (3:1) was seen in the crystal [PMID:10986460]. A monovalent IFN-gamma variant bound one IFNGR1 ectodomain and still had antiviral activity [PMID:11250200]. The second chain IFNGR2 forms the full signalling receptor (UniProt: heterodimer with IFNGR2) [DB:UniProt].","affinity_potency":[{"value":"Crystal structure at 2.9 A resolution","assay":"X-ray crystallography, multiwavelength anomalous diffraction (structural, not an affinity)","system":"human IFN-gamma with soluble glycosylated IFNGR1 extracellular part","cite":"PMID:10986460"}],"species_and_systems":"Human proteins throughout: crystallography with recombinant human ectodomains [PMID:10986460, PMID:11250200], patient-derived human cells [PMID:10811850], WISH and Jurkat cells [PMID:12165521]. The mouse pair is projected from human evidence (ortholog inferred), not tested.","localisation_and_range":"IFNG is flagged secreted and non-transmembrane [flag], so it is expected to act at a distance (paracrine/endocrine); the receptor is flagged transmembrane [flag].","caveats":"Most papers were read as abstracts only. The 12165521 paper is a trafficking study that assumes the pair and uses IFN-gamma binding only as a control. The monovalent ligand in 11250200 is engineered; native IFN-gamma is a homodimer. Structures also exist in PDB 1FG9, 1FYH, 6E3K and 6E3L [DB:PDB 1FG9].","key_references":[{"PMID":"10986460","why":"crystal structure of the human IFN-gamma/IFNGR1 complex"},{"PMID":"10811850","why":"loss of IFN-gamma binding with IFNGR1 mutations"},{"PMID":"11250200","why":"1:1 complex structure with monovalent IFN-gamma"}],"covers":["LR000831","LR004271"]},"LR000833":{"pair":"IFNL1 -> IL10RB","headline":"IFN-lambda1 and IL10RB: IL10RB is the shared second chain of the receptor; evidence is a single abstract.","interaction_type":"functional only","direction_and_effect":"IFN-lambda1 (IL-29) interacts with a receptor consisting of IL-10Rbeta and IL-28Ralpha [PMID:12469119]; GtoPdb lists Agonist for IFNL1-IL10RB [DB:GtoPdb].","molecular_requirements":"IL10RB is the shared second chain of the IFN-lambda receptor [PMID:12469119]; chain-only binding of IFNL1 to IL10RB is not shown in our evidence. Reactome lists IFNL1 binding IL10RB:TYK2 and IFNLR1:JAK1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human, human cells [PMID:12469119].","localisation_and_range":"IFNL1 is flagged secreted and non-transmembrane [flag].","caveats":"Single abstract-only paper that describes the heterodimer, not IL10RB alone; IL10RB is the shared chain, so a standalone binding is not shown in our evidence.","key_references":[{"PMID":"12469119","why":"heterodimeric receptor with IL-10Rbeta"}],"covers":["LR000833"]},"LR000842":{"pair":"IGF2 -> IGF2R","headline":"IGF2 binds the mannose 6-phosphate/IGF-II receptor with high affinity; two verified classic papers map and demonstrate the binding.","interaction_type":"direct binding","direction_and_effect":"The receptor binds IGF-II with high affinity; purified human receptor fragments cross-linked 125I-IGF-II [PMID:7797478]. Rat placental receptor bound 125I-IGF-II, and Man-6-P increased apparent affinity by about two times [PMID:2964083]. UniProt agrees [DB:UniProt].","molecular_requirements":"Repeat 11 (amino acids 1508-1650) of the receptor is sufficient for IGF-II binding, and residues 1508-1566 are proposed to form the binding site; repeat 10 alone failed [PMID:7797478]. Mannose-6-phosphate sites are cooperative with the IGF-II site [PMID:2964083].","affinity_potency":[],"species_and_systems":"Human purified receptor and fusion proteins [PMID:7797478]; rat cDNA and rat placental receptor [PMID:2964083]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted; IGF2R is flagged transmembrane [flag].","caveats":"Both papers were read as abstracts only; no numeric affinity is reported in our evidence. The receptor also binds Man-6-P proteins, so it is not IGF-II-specific. The interaction is annotated stimulatory, but IGF2R is known in these papers only as a binder, not a signaling effect.","key_references":[{"PMID":"7797478","why":"Maps IGF-II binding site to repeat 11"},{"PMID":"2964083","why":"One receptor binds IGF-II and Man-6-P"}],"covers":["LR000842","LR004274"]},"LR006017":{"pair":"IGF2 -> ITGB3","headline":"Integrin alphavbeta3 binds IGF2 in one verified study; ITGB3 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphavbeta3 heterodimer was tested; blocking antibody 7E3 (anti-beta3) reduced adhesion to IGF2 [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002771","LR006017"]},"LR006026":{"pair":"IHH -> GPC3","headline":"One mouse liver abstract reports GPC3-Indian Hh binding changes; mechanism is competition with patched-1.","interaction_type":"direct binding","direction_and_effect":"The study tested the hypothesis that GPC3 down-regulates Hh signalling by competing with patched-1 for HH binding; GPC3-Indian HH binding fell at peak proliferation in mouse liver, followed by a rise in glioblastoma 1 protein [PMID:23665349]. Effect direction is not reported in our evidence beyond the hypothesis.","molecular_requirements":"Co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse liver regeneration [PMID:23665349]; the human pair is ortholog-inferred.","localisation_and_range":"GPC3 is flagged non-secreted [flag], consistent with a membrane-bound glypican; range from annotation only.","caveats":"Abstract only; the binding assay type is not stated in the dossier. Binding was measured as a change over time in tissue, not a purified-protein affinity. A single paper.","key_references":[{"PMID":"23665349","why":"GPC3-Indian Hh binding in regenerating mouse liver"}],"covers":["LR002783","LR006026"]},"LR004280":{"pair":"IHH -> HHIP","headline":"HIP binds all three mammalian Hedgehog proteins with an affinity comparable to Ptc-1; abstract only.","interaction_type":"direct binding","direction_and_effect":"Hip encodes a membrane glycoprotein that binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1 [PMID:10050855]. The curator lists the interaction as inhibitory in the database annotation [flag]; the abstract excerpt does not describe the effect on signalling.","molecular_requirements":"Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor per the curator [PMID:10050855]; the human pair is ortholog-inferred. IntAct lists a solid-phase assay between Q96QV1 and Q14623 [DB:IntAct].","localisation_and_range":"HHIP is flagged non-transmembrane in our annotation [flag] although the paper describes a membrane glycoprotein [PMID:10050855]; Hip-expressing cells lie next to Hh-expressing cells [PMID:10050855].","caveats":"Abstract only. IHH is covered by the phrase 'all three mammalian Hedgehog proteins', not individually resolved. No numeric affinity is given.","key_references":[{"PMID":"10050855","why":"Hip binds all three mammalian Hedgehog proteins"}],"covers":["LR000850","LR004280"]},"LR000851":{"pair":"IHH -> PTCH1","headline":"PTCH1 binds all Hedgehog family members including IHH in a biochemical assay; abstract only.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]. In chick cartilage, Ihh regulates Ptc and Gli expression and misexpression blocks hypertrophic differentiation [PMID:8662546]. UniProt describes PTCH1 as a negative regulator of smoothened signalling that is a receptor for SHH, IHH and DHH [DB:UniProt].","molecular_requirements":"PTCH forms a complex with SMO [PMID:9811851]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assay species not stated in the dossier [PMID:9811851]; chicken Ihh with mouse tissue work [PMID:8662546]. Human pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Both papers are abstract only. The 1996 paper infers Ihh-Ptc engagement from target gene regulation, not binding. No numeric affinity is given.","key_references":[{"PMID":"9811851","why":"PTCH binds all Hedgehog family members"},{"PMID":"8662546","why":"Ihh regulates Ptc in cartilage differentiation"}],"covers":["LR000851","LR004281"]},"LR008006":{"pair":"IL12A:IL27 -> IL12RB2:IL27RA","headline":"Unsupported as a pair: no usable paper, and database records belong to separate IL12A and IL27 interactions.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for this combination. GtoPdb has separate agonist records IL12A-IL12RB2 and IL27-IL27RA [DB:GtoPdb].","molecular_requirements":"Not reported. UniProt describes IL27RA as the signal-transducing subunit for a heterodimer of IL27/p28 and soluble EBI3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID shows IL27-IL27RA affinity capture-Western [DB:BioGRID]. No species-specific experiment is given for the combined complex.","localisation_and_range":"Not reported in our evidence.","caveats":"No confirmed paper; the single judged paper had insufficient abstract. Records support IL27-IL27RA and IL12A-IL12RB2 separately, not a complex with these partners together.","key_references":[],"covers":["LR008006"]},"LR000860":{"pair":"IL12B -> IL12RB2","headline":"IL12RB2 binds the IL-12 heterodimer, with p35 and p40 both contributing; p40 alone is not shown to bind IL12RB2.","interaction_type":"direct binding","direction_and_effect":"Blocking studies in human cells indicate IL-12 binds IL-12Rbeta2 via heterodimer-specific regions to which p35 and p40 both contribute [PMID:9498755]. IL12RB2-deficient mice lost IL-12-induced function [PMID:11086056]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-12Rbeta1 and IL-12Rbeta2 individually bind IL-12 with low affinity and together with high affinity [PMID:9498755]. Cryo-EM structures 8XRP and 8YI7 contain an IL12B chain and an IL12RB2 chain [DB:PDB 8XRP].","affinity_potency":[],"species_and_systems":"Human COS-7 cells and lymphoblasts [PMID:9498755]; knockout mice [PMID:11086056]. Both human and mouse pairs are present.","localisation_and_range":"IL12B is flagged secreted [flag].","caveats":"Both papers are abstract-only. The binding evidence uses the heterodimer-specific antibody 20C2, so it does not show p40 alone binds IL12RB2. No affinity value is reported. The knockout paper does not test binding.","key_references":[{"PMID":"9498755","why":"IL-12 contacts IL-12Rbeta2 via heterodimer-specific regions"},{"PMID":"11086056","why":"IL12RB2 required for IL-12 function in mice"}],"covers":["LR000860","LR004290"]},"LR010634":{"pair":"IL16 -> GRIN2D","headline":"Database-asserted only: a UniProt subunit note lists GRIN2D as an IL16 isoform 1 interactor; no papers support a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt states that isoform 1 interacts with GRIN2D, KCNJ10, KCNJ15 and CACNA1C (By similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"UniProt annotation 'By similarity' only; no experiment species reported in our evidence [DB:UniProt].","localisation_and_range":"IL16 is annotated as secreted [flag]; no localisation annotation for the partner in our evidence.","caveats":"No curated paper evidence; the interaction was judged a different entity in our curation. The UniProt statement is inferred by similarity, not shown directly for this pair.","key_references":[],"covers":["LR010634"]},"LR004307":{"pair":"IL19 -> IL20RB","headline":"IL-19 signals via IL20RB as the shared partner in the IL20RA/IL20RB complex; complex-level evidence in human transfected cells.","interaction_type":"functional only","direction_and_effect":"IL-19 acts as an agonist through the IL-20RA/IL-20RB complex, with STAT3 phosphorylation and promoter activation [PMID:11564763, PMID:12351624]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL20RB works with IL20RA; IL-19 uses only the type I complex and not IL-22R/IL-20Rbeta [PMID:11564763]. IL20RB alone is not shown to bind IL-19 in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines expressing transfected receptors [PMID:11564763, PMID:12351624]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers read as abstracts; single-chain row inherits complex-level evidence. Growth inhibition in one line needed levels two orders of magnitude above STAT activation [PMID:12351624].","key_references":[{"PMID":"11564763","why":"IL-19 uses the IL-20Ralpha/IL-20Rbeta complex"},{"PMID":"12351624","why":"Reporter and STAT assays across receptor combinations"}],"covers":["LR000877","LR004307"]},"LR011732":{"pair":"IL1A -> IL1B:IL1R1:IL1RAP","headline":"Database-asserted only: no verified paper; the receptor complex is odd because it lists IL1B as a receptor member.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1A-IL1R1 and IL1A-IL1RAP as agonist [DB:GtoPdb]. UniProt says IL1A binds IL1R1 with IL1RAP to form the high affinity receptor complex [DB:UniProt].","molecular_requirements":"IL1R1 plus IL1RAP form the high affinity complex per UniProt [DB:UniProt] and Reactome IL1R1:IL1:IL1RAP [DB:Reactome].","affinity_potency":[],"species_and_systems":"No experiments in our evidence; species not reported beyond the human entity record.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers are still pending curation. Affinity not reported.","key_references":[],"covers":["LR011732"]},"LR007304":{"pair":"IL1B -> IL1R1:IL1RAP","headline":"IL-1beta signals through IL1R1 plus IL1RAP; structure for IL1R1 and mouse knockout for IL1RAP.","interaction_type":"functional only","direction_and_effect":"IL-1beta binds IL1R1 (crystal structure of the extracellular domain) [PMID:9062193] and the IL1R1/IL1RAP complex is required for signalling by all IL-1 agonists [PMID:9820540]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Both chains needed: without AcP, ligands still bind via IL1R1 but do not signal, and IL-1beta affinity falls 70-fold [PMID:9820540]. IL1RAP is not in the binary IL1R1 structure [PMID:9062193]. PDB 3O4O and 4DEP are structures of related complexes [DB:PDB 4DEP].","affinity_potency":[],"species_and_systems":"Human proteins in the structure [PMID:9062193]; mouse knockouts in [PMID:9820540].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers abstract only. The ternary complex itself is not shown in a dossier paper; PDB 4DEP is a database record only. Several other rows were review-only or unresolvable.","key_references":[{"PMID":"9062193","why":"IL-1beta/IL1R1 ectodomain structure"},{"PMID":"9820540","why":"IL1RAP required for signalling"}],"covers":["LR007304"]},"LR006035":{"pair":"IL1B -> ITGB3","headline":"IL-1beta binds integrin alphavbeta3 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alphaVbeta3); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGAV:ITGB3 binds to IL1B and this binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002792","LR006035"]},"LR000905":{"pair":"IL2 -> IL2RG","headline":"IL2RG binds IL-2 only very weakly alone; it acts mainly as the shared gamma chain with IL2RB.","interaction_type":"direct binding","direction_and_effect":"Gamma-chain binding of IL-2 is detectable but of very low affinity in the absence of beta [PMID:8049354]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL2RG needs IL2RB for useful binding [PMID:8049354]; IL-2 and IL-15 receptors share the beta and gamma chains with a private alpha chain [PMID:15265897].","affinity_potency":[{"value":"apparent KI > 15 microM","assay":"soluble ectodomain binding","system":"insect-cell-expressed IL-2R gamma ectodomain, without beta","cite":"PMID:8049354"}],"species_and_systems":"Soluble ectodomains from insect cells [PMID:8049354]; BioGRID Affinity Capture-Western [DB:BioGRID]. Mouse pair projected from human evidence.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"Abstract only. Gamma alone binds at very low affinity, so single-chain scoring overstates IL2RG as a direct receptor. PMID:15265897 is background.","key_references":[{"PMID":"8049354","why":"Gamma ectodomain binds IL-2 at very low affinity without beta"}],"covers":["LR000905","LR004334"]},"LR004334":{"pair":"IL2 -> IL2RG","headline":"IL2RG binds IL-2 only very weakly alone; it acts mainly as the shared gamma chain with IL2RB.","interaction_type":"direct binding","direction_and_effect":"Gamma-chain binding of IL-2 is detectable but of very low affinity in the absence of beta [PMID:8049354]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL2RG needs IL2RB for useful binding [PMID:8049354]; IL-2 and IL-15 receptors share the beta and gamma chains with a private alpha chain [PMID:15265897].","affinity_potency":[{"value":"apparent KI > 15 microM","assay":"soluble ectodomain binding","system":"insect-cell-expressed IL-2R gamma ectodomain, without beta","cite":"PMID:8049354"}],"species_and_systems":"Soluble ectodomains from insect cells [PMID:8049354]; BioGRID Affinity Capture-Western [DB:BioGRID]. Mouse pair projected from human evidence.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"Abstract only. Gamma alone binds at very low affinity, so single-chain scoring overstates IL2RG as a direct receptor. PMID:15265897 is background.","key_references":[{"PMID":"8049354","why":"Gamma ectodomain binds IL-2 at very low affinity without beta"}],"covers":["LR000905","LR004334"]},"LR007313":{"pair":"IL20 -> IL20RB:IL22RA1","headline":"IL-20 uses IL22RA1:IL20RB as a second (type II) receptor in addition to IL20RA:IL20RB; supported by three papers.","interaction_type":"direct binding","direction_and_effect":"IL-20 and mda-7, but not IL-19, bind the type II receptor complex IL-22R/IL-20Rbeta, and binding leads to STAT3 phosphorylation [PMID:11564763]; IL-20 can also use IL-22R/IL-20RB [PMID:12351624]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Needs IL20RB and IL22RA1 together [PMID:11564763]; IL20RB binds IL-20 with high affinity in binary form [PMID:14580208]. IntAct lists SPR between IL20 and Q8N6P7 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Transfected cell lines for signalling [PMID:11564763] [PMID:12351624]; PMID:14580208 used IL20RA/IL20RB soluble ectodomains, not IL22RA1.","localisation_and_range":"IL-20 flagged secreted; complex flagged transmembrane [flag].","caveats":"All papers abstract only. PMID:14580208 concerns IL-20RA-containing complex, so it supports IL20RB but not the IL22RA1 pairing.","key_references":[{"PMID":"11564763","why":"IL-20 binds the type II IL-20R complex"},{"PMID":"12351624","why":"IL-20 signals through IL-22R/IL-20RB"}],"covers":["LR007313"]},"LR004325":{"pair":"IL23A -> IL12RB1","headline":"IL-23 binds IL12RB1 via its IL-12p40 partner chain; abstract-level support in two papers.","interaction_type":"direct binding","direction_and_effect":"IL-23 binds IL-12R beta 1 but not IL-12R beta 2, and activates Stat4 in PHA blast T cells [PMID:11114383]; like IL-12, IL-23 binds IL-12Rbeta1 [PMID:12023369]. GtoPdb lists agonists [DB:GtoPdb].","molecular_requirements":"The ligand is a heterodimer of p19 (IL23A) and IL-12p40; IL-23R pairs with IL-12Rbeta1 to confer IL-23 responsiveness [PMID:12023369][PMID:11114383]. IL23A alone is not shown to bind IL12RB1.","affinity_potency":[],"species_and_systems":"Human IL-23 in human cells; mouse memory T cells were used for a proliferation readout [PMID:11114383]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL23A is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The row credits IL23A with binding that rests on the heterodimeric ligand. IntAct anti bait coimmunoprecipitation [DB:IntAct].","key_references":[{"PMID":"11114383","why":"IL-23 binds IL-12Rbeta1, not beta2"},{"PMID":"12023369","why":"IL-23R pairs with IL-12Rbeta1"}],"covers":["LR000895","LR004325"]},"LR005207":{"pair":"IL33 -> IL1RL1","headline":"IL-33 binds ST2 (IL1RL1) directly (crystal structure) and signals through it; well supported by structure and functional work, mostly read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-33 acts as an agonist: it signals via ST2, activating NF-kappaB and MAP kinases and driving Th2-associated cytokines [PMID:16286016]. ST2 siRNA reduced IL-33-dependent IL-8 in lung endothelial and epithelial cells [PMID:20926795]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"ST2 is the primary ligand-binding receptor and IL-1RAcP is the accessory chain; IL-1RAcP cannot bind the ligand directly [PMID:23980170]. UniProt/Reactome describe a 1:1:1 IL33:IL1RL1:IL1RAP complex [DB:UniProt][DB:Reactome]. In pancreatic myofibroblasts, responsiveness needed prior ST2L upregulation [PMID:19996325].","affinity_potency":[],"species_and_systems":"Crystal structure of IL-33 with the ST2 ectodomain at 3.27 A, human [PMID:23980170]; cell assays in human cells [PMID:16286016][PMID:19996325][PMID:20926795]. Mouse pair is ortholog-inferred; no mouse experiment shown.","localisation_and_range":"Ligand flagged secreted [flag]; acts on ST2-expressing cells in paracrine fashion by inference only.","caveats":"All four papers shown were read as abstracts only. No affinity value is reported in our evidence.","key_references":[{"PMID":"23980170","why":"Crystal structure of IL-33:ST2 ectodomain"},{"PMID":"16286016","why":"Original IL-33/ST2 signalling report"},{"PMID":"20926795","why":"ST2 knockdown in human lung cells"}],"covers":["LR001862","LR005207"]},"LR007322":{"pair":"IL36A -> IL1RAP:IL1RL2","headline":"IL-36 acting on the IL1RAP:IL1RL2 complex rests on database records only; no judged papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for both IL1RAP and IL1RL2 [DB:GtoPdb]; Reactome has a binding reaction IL36:IL1RL2 with IL1RAP [DB:Reactome]. UniProt describes signalling through IL1RL2/IL-36R activating NF-kappa-B and MAPK [DB:UniProt].","molecular_requirements":"Complex of IL1RAP and IL1RL2 (listed members); which subunit binds the ligand is not reported in these records.","affinity_potency":[],"species_and_systems":"Human only; no experimental paper in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor complex annotated transmembrane [flag].","caveats":"No papers (three review-only rows). Support is database assertion only.","key_references":[],"covers":["LR007322"]},"LR006044":{"pair":"IL36B -> IL1RAP","headline":"IL1RAP is a required co-receptor for IL-36 signalling in one functional paper; no direct ligand binding shown.","interaction_type":"functional only","direction_and_effect":"Antibodies against IL-1RAcP and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6, IL-1F8 and IL-1F9, so IL-1RAcP is required alongside IL-1Rrp2 [PMID:14734551]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as co-receptor with IL-1Rrp2 (IL1RL2); IL1RAP alone is not shown to bind the ligand [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human cell lines (Jurkat, NCI/ADR-RES) [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Single abstract-only paper. It names the ligands IL-1F6/F8/F9; the abstract does not state which is IL36B. Reactome entry links the paper to IL36:IL1RL2 binding IL1RAP [DB:Reactome].","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for IL-1F6/F8/F9 signalling"}],"covers":["LR002802","LR006044"]},"LR002804":{"pair":"IL36G -> IL1RAP","headline":"IL1RAP is a co-receptor in IL-36 signalling (one functional paper); a PDB structure is also listed.","interaction_type":"functional only","direction_and_effect":"IL-1RAcP antibodies and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6/F8/F9 [PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as an obligate co-receptor with IL-1Rrp2 [PMID:14734551]. PDB 9I7X contains chains of Q9NZH8 and Q9NPH3 [DB:PDB 9I7X].","affinity_potency":[],"species_and_systems":"Human cell lines [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"One abstract-only paper that names IL-1F6/F8/F9. No affinity reported.","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for signalling"}],"covers":["LR002804","LR006046"]},"LR011228":{"pair":"IL36RN -> IL1RAP","headline":"IL36RN acting on IL1RAP is a GtoPdb antagonist assertion only; no usable papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists Antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Three papers judged abstract-insufficient. IL1RAP is a co-receptor, so a direct IL-36Ra binding site on it is not shown.","key_references":[],"covers":["LR011228"]},"LR000914":{"pair":"IL4 -> IL4R","headline":"IL4 binds IL4R-alpha with high affinity (KD 150 pM) and is an agonist; well supported.","interaction_type":"direct binding","direction_and_effect":"IL4 is an agonist at IL4R [DB:GtoPdb]. Cysteine-substituted IL4 mutants keep 60-100% of wild-type IL4R binding affinity [PMID:7918378].","molecular_requirements":"IL4R then recruits IL2RG (type 1) or IL13RA1 (type 2) as signalling partner [DB:UniProt]. The binding interface has two clusters, with D72 of the receptor forming an ion pair with IL-4 R88 [PMID:11786020].","affinity_potency":[{"value":"KD 150 pM","assay":"mutational binding analysis of IL4-BP","system":"human recombinant IL4R extracellular domain","cite":"PMID:11786020"}],"species_and_systems":"Human ligand and receptor; recombinant receptor domain [PMID:11786020]; IL4R-bearing tumour cells [PMID:7918378]. Co-crystal structures exist [DB:PDB 3BPL].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Both papers abstract only. Two other judged rows are pending and are not shown.","key_references":[{"PMID":"11786020","why":"KD 150 pM and binding-cluster dissection"},{"PMID":"7918378","why":"IL4 mutants retain IL4R binding"}],"covers":["LR000914"]},"LR004343":{"pair":"IL5 -> CSF2RB","headline":"CSF2RB (common beta chain) is the shared signalling subunit of the IL5 receptor; support is indirect via the receptor description and database records.","interaction_type":"functional only","direction_and_effect":"Agonistic ligation of the alpha and common beta subunits triggers proteasomal degradation of the betac cytoplasmic domain, ending signalling [PMID:11748263]. GtoPdb lists IL5 as agonist at CSF2RB [DB:GtoPdb].","molecular_requirements":"IL5 signals through IL5RA plus CSF2RB [DB:UniProt]; a cryo-EM structure of the IL-5 signalling complex exists [DB:PDB 8TLD]. Reactome lists IL5RA:betac:JAK2 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell system and species not reported for the experiment row; abstract-level only [PMID:11748263].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Only one paper is shown, abstract-only, and it concerns IL-5, IL-3 and GM-CSF receptors together rather than IL5-CSF2RB binding. Betac does not bind IL5 on its own in our evidence; the alpha chain is needed [DB:UniProt]. Affinity not reported.","key_references":[{"PMID":"11748263","why":"Ligand-induced betac degradation in IL-5/IL-3/GM-CSF receptors"}],"covers":["LR000915","LR004343"]},"LR011741":{"pair":"IL6 -> IL6:IL6R:IL6ST","headline":"Complex entity includes IL6 itself as a member; no curated papers, only database records of the IL6-IL6R-gp130 assembly.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence is confirmed (all rows pending). Databases record IL6 and gp130 as agonist targets [DB:GtoPdb] and IL6:IL6R binding IL6ST [DB:Reactome].","molecular_requirements":"IL6 first binds IL6R, then the IL6:IL6R complex associates with IL6ST; IL6ST does not itself bind IL6 [DB:UniProt]. A structure of IL6 with IL6ST exists [DB:PDB 1P9M].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Pair rests on databases alone. The receptor complex contains IL6 as a member, so this is better described as the ligand-receptor assembly than as a ligand to receptor pair.","key_references":[],"covers":["LR011741"]},"LR007331":{"pair":"IL7 -> IL2RG:IL7R","headline":"IL7 acts on the IL2RG:IL7R complex; both chains named in confirmed papers, functional evidence only.","interaction_type":"functional only","direction_and_effect":"IL-7 engagement of IL-7R recruits PtdIns 3-kinase p85 [PMID:7522165]; the high-affinity IL-7R is a heterodimer of IL-7Ralpha and common gamma [PMID:11858939]. GtoPdb: agonist for both chains [DB:GtoPdb].","molecular_requirements":"Both IL7R (alpha) and IL2RG are needed for the high-affinity receptor [PMID:11858939]. Tyr449 in the alpha chain mediates p85 binding [PMID:7522165]. IntAct has IL2RG-IL7R co-immunoprecipitation from PMID:8266077 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human cells; lymphoid cells [PMID:7522165] and non-haematopoietic tumour lines [PMID:11858939].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Composition is background in both papers; neither measures binding to IL-7 directly. Abstracts only.","key_references":[{"PMID":"7522165","why":"IL-7 signalling through alpha chain, gamma chain stated"},{"PMID":"11858939","why":"Functional IL-7R heterodimer in tumour lines"}],"covers":["LR007331"]},"LR004352":{"pair":"INHA -> ACVR2B","headline":"Inhibin competes with BMPs for ACVR2B, facilitated by betaglycan; conflicting rows on one abstract.","interaction_type":"conflicting","direction_and_effect":"Inhibin competes with BMPs for type II activin receptors, facilitated by betaglycan [PMID:12493742]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"Betaglycan (TGFBR3) facilitates the competition [PMID:12493742].","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; abstract-level read. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag].","caveats":"A pair_absent judgement for the same PMID coexists with the confirmed one; the confirmed read is from the abstract only, and names ACVR2B only generically as type II receptors.","key_references":[{"PMID":"12493742","why":"Inhibin and betaglycan versus activin/BMP at type II receptors"}],"covers":["LR000929","LR004352"]},"LR000932":{"pair":"INHBA -> ACVR1B","headline":"Activin A signals through ACVR1B (ALK4) with type II receptors; two verified papers, one abstract-only.","interaction_type":"functional only","direction_and_effect":"Activin A engages ACVR1B to activate Smad2/3 signalling (agonist) [PMID:32515349]. In receptor reconstitution, activin A signals through activin type II receptors plus ALK4, and all activins activate ActRIIA plus ALK4 with various levels of potency [PMID:15196700]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Needs a type II receptor together with ACVR1B; activin A binding to type II receptors is required for signalling through ACVR1B [PMID:32515349]. UniProt lists ACVR1B or ACVR1C as type I partners with ACVR2A, ACVR2B or BMPR2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse receptor reconstitution [PMID:15196700]; human system with HEK293 reporter cells and agonist-only muteins [PMID:32515349].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Evidence is functional signalling; direct binding of activin A to ACVR1B alone is not shown in our evidence. 15196700 was read as abstract only [PMID:15196700]; the 32515349 sentence comes from work focused on ACVR1 [PMID:32515349].","key_references":[{"PMID":"15196700","why":"Activin A signals through type II receptors plus ALK4 in reconstitution."},{"PMID":"32515349","why":"Agonist-only activin A muteins activate ACVR1B Smad2/3 signalling."}],"covers":["LR000932","LR004355"]},"LR004361":{"pair":"INHBB -> ACVR1B","headline":"Activin B activates ACVR1B (ALK4) with ActRIIA in vitro; one abstract-level paper, plus database records.","interaction_type":"functional only","direction_and_effect":"Activin B, like all activins, activated an ActRIIA plus ALK4 combination with varying potency; effect is agonist [PMID:15196700]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Signalling used the ActRIIA/ALK4 receptor combination, so ACVR1B alone may not suffice [PMID:15196700]. The same paper says activin B prefers ActRIIA/ALK7 [PMID:15196700].","affinity_potency":[],"species_and_systems":"Curator fields list human ligand and receptor [PMID:15196700]; the pair's mouse entry is ortholog-inferred. Beta-cell line MIN6 is named in the abstract [PMID:15196700].","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine. Receptor transmembrane flag is not set.","caveats":"Evidence is abstract only [PMID:15196700]; potency differences are not given numerically. Binding is supported by BioGRID records for INHBB with ACVR2A, not ACVR1B [PMID:9202237].","key_references":[{"PMID":"15196700","why":"Activin isoforms and type I receptor usage (ALK4, ALK7)"}],"covers":["LR000938","LR004361"]},"LR000941":{"pair":"INHBB -> ACVR2B","headline":"Activin binds ACVR2B in competition assays in CHO cells; one abstract-level paper that concerns inhibin displacing activin.","interaction_type":"direct binding","direction_and_effect":"Labelled activin bound activin type II receptors, especially type IIB, and inhibin displaced it [PMID:9202237]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Displacement occurred at type II receptors, not type I receptors [PMID:9202237].","affinity_potency":[],"species_and_systems":"Chinese hamster ovary cells; ligand and receptor species not recorded in curator fields [PMID:9202237]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Abstract only; the paper studies activin versus inhibin and does not name activin B specifically in the abstract [PMID:9202237]. No affinity reported.","key_references":[{"PMID":"9202237","why":"Competition binding at activin type II receptors"}],"covers":["LR000941","LR004364"]},"LR002813":{"pair":"INHBB -> TGFBR3","headline":"Inhibin (INHA plus INHBB) uses betaglycan (TGFBR3) as a co-receptor with ActRII; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin with high affinity and enhances binding in cells co-expressing ActRII and betaglycan; it makes cells inhibin-sensitive [PMID:10746731].","molecular_requirements":"Co-receptor function with ActRII, not a standalone signalling receptor; ligand is the inhibin heterodimer INHA plus INHBB [PMID:10746731].","affinity_potency":[],"species_and_systems":"Curator fields list human ligand and receptor; recombinant and endogenous betaglycan were crosslinked to inhibin [PMID:10746731]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Abstract only; no affinity value given beyond 'high affinity'. Abstract speaks of inhibin generally.","key_references":[{"PMID":"10746731","why":"Betaglycan as inhibin co-receptor"}],"covers":["LR002813","LR006053"]},"LR006053":{"pair":"INHBB -> TGFBR3","headline":"Inhibin (INHA plus INHBB) uses betaglycan (TGFBR3) as a co-receptor with ActRII; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin with high affinity and enhances binding in cells co-expressing ActRII and betaglycan; it makes cells inhibin-sensitive [PMID:10746731].","molecular_requirements":"Co-receptor function with ActRII, not a standalone signalling receptor; ligand is the inhibin heterodimer INHA plus INHBB [PMID:10746731].","affinity_potency":[],"species_and_systems":"Curator fields list human ligand and receptor; recombinant and endogenous betaglycan were crosslinked to inhibin [PMID:10746731]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Abstract only; no affinity value given beyond 'high affinity'. Abstract speaks of inhibin generally.","key_references":[{"PMID":"10746731","why":"Betaglycan as inhibin co-receptor"}],"covers":["LR002813","LR006053"]},"LR000950":{"pair":"INS -> INSR","headline":"Insulin is the canonical INSR agonist, with binding-site mutagenesis, structures and database records.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists insulin as an agonist of INSR [DB:GtoPdb]. Transfected cells with an altered 240-250 region of the human receptor alpha-subunit showed higher insulin-binding affinity, slower dissociation and more sensitive tyrosine kinase activity and alpha-aminoisobutyric acid uptake [PMID:2550426].","molecular_requirements":"Residues 240-250 in the cysteine-rich region of the alpha-subunit form one insulin-interacting site [PMID:2550426]. Reactome describes an insulin:phosphorylated insulin receptor complex at the plasma membrane [DB:Reactome R-HSA-74678].","affinity_potency":[],"species_and_systems":"Human receptor expressed in rat hepatoma (HTC) cells [PMID:2550426]. Structures and interaction records include X-ray crystallography, electron microscopy and surface plasmon resonance [DB:IntAct] [DB:PDB 3W11].","localisation_and_range":"Ligand is flagged secreted [flag]. INSR is a transmembrane receptor [flag].","caveats":"The curated paper is a mutant study read as abstract only; the quoted evidence sentence restates earlier work. Numerical affinity is not reported in our evidence.","key_references":[{"PMID":"2550426","why":"Mutating residues 240-250 of the human INSR alpha-subunit raises insulin affinity and signalling"}],"covers":["LR000950"]},"LR004370":{"pair":"INSL3 -> RXFP2","headline":"INSL3 is the established ligand of RXFP2 (LGR8), with binding, cAMP signalling and structure-function data.","interaction_type":"direct binding","direction_and_effect":"INSL3 stimulated cAMP production in LGR8-expressing cells but not LGR7, and ligand-receptor cross-linking showed their interaction [PMID:12114498]. INSL3 behaved as a partial agonist at RXFP2, with low maximal cAMP response but high binding potency [PMID:15649866]. INSL3 can only bind and activate RXFP2 [PMID:22973049]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Binding is mainly via the INSL3 B-chain, while A-chain elements, including its N terminus, are needed for activation [PMID:20560146] [PMID:18434306]. The RXFP2 ectodomain holds the primary high-affinity site and a secondary lower-affinity site lies in the transmembrane region [PMID:15649866].","affinity_potency":[{"value":"pKi 9.34000015258789 to 9.699999809265137","assay":"GtoPdb affinity range, full agonist","system":"RXFP2","cite":"PMID:15649866"}],"species_and_systems":"Recombinant receptor-expressing cells; cultured gubernacular cells responded to INSL3 [PMID:12114498]. Curators recorded human experiments for most papers. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]. Gubernaculum expression of LGR8 is reported at transcript level [PMID:12114498].","caveats":"All shown papers were read as abstracts. Eight confirmed rows exist, four shown. The antagonist reading in [PMID:20560146] concerns a synthetic B-chain dimer, not INSL3.","key_references":[{"PMID":"12114498","why":"INSL3 identified as LGR8 ligand by cAMP and cross-linking"},{"PMID":"15649866","why":"Two-site pharmacology of RXFP1/RXFP2 with chimeras; INSL3 partial agonist"},{"PMID":"22973049","why":"INSL3 binds and activates RXFP2 only; ECD binding site"}],"covers":["LR000947","LR004370"]},"LR002822":{"pair":"ISG15 -> ITGB2","headline":"ITGB2 (CD18) is the obligate partner of CD11a in the LFA-1 receptor that ISG15 engages; the binding evidence is on ITGAL.","interaction_type":"direct binding","direction_and_effect":"ISG15 is an agonist at LFA-1, stimulating IFN-gamma secretion [PMID:29100055].","molecular_requirements":"ISG15 binding to HEK293T cells needed CD11a and CD18 expressed together [PMID:29100055]. The direct binding to the alphaI domain concerns CD11a, not CD18 [PMID:29100055].","affinity_potency":[],"species_and_systems":"Human NK-92 and HEK293T cells; CD11a-/- mouse splenocytes [PMID:29100055].","localisation_and_range":"ISG15 flagged secreted [flag]; ITGB2 is a membrane receptor chain.","caveats":"This row inherits evidence from the ITGAL row; the dossier shows no direct test of CD18 alone. Curators read it as abstract only.","key_references":[{"PMID":"29100055","why":"Shows ISG15 binding needs CD11a plus CD18"}],"covers":["LR002822","LR006061"]},"LR006062":{"pair":"ITGA5 -> ADGRE5","headline":"Integrin alpha5beta1 binds CD97 (ADGRE5) in HUVEC assays; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Soluble CD97 drives integrin-dependent HUVEC migration and invasion, and CD97alpha promotes angiogenesis in vivo [PMID:15576472]. Alpha5beta1 is described as a high-affinity counterreceptor for CD97 [PMID:15576472].","molecular_requirements":"Alpha5beta1 together with chondroitin sulfate proteoglycan synergistically promotes endothelial invasion; alphaVbeta3 also contributes to attachment [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human cells (HUVEC) and an in vivo angiogenesis assay [PMID:15576472]. The mouse pair is projected by orthology.","localisation_and_range":"Soluble CD97 extracellular domain acts as chemoattractant [PMID:15576472]; ADGRE5 is flagged secreted and transmembrane [flag].","caveats":"Abstract only. The ITGA5 entity is a single chain labelled alpha5beta1. No affinity values. The assay_class direct_binding rests on the abstract wording 'strong interactions'.","key_references":[{"PMID":"15576472","why":"CD97 binds alpha5beta1 and drives endothelial invasion"}],"covers":["LR002823","LR006062"]},"LR002831":{"pair":"IZUMO1 -> IZUMO1R","headline":"IZUMO1 binds JUNO (IZUMO1R) in the sperm-egg interaction; crystal structure and human oocyte antibody blocking.","interaction_type":"direct binding","direction_and_effect":"The IZUMO1-JUNO interaction is needed for sperm-oocyte interaction [PMID:27309808]. An anti-human-JUNO antibody completely blocked gamete fusion [PMID:30517645]; UniProt calls the interaction necessary adhesion but not sufficient for fusion [DB:UniProt].","molecular_requirements":"1:1 complex [DB:UniProt]. The central beta-hairpin of IZUMO1 is the main JUNO-binding platform [PMID:27309808]. UniProt notes FCRL3/MAIA replaces JUNO after adhesion [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins crystallised [PMID:27309808]; human zona-free oocytes with sperm [PMID:30517645]. Mouse pair orthology-projected.","localisation_and_range":"Both membrane-bound; juxtacrine gamete contact [PMID:27309808].","caveats":"Abstracts only. No affinity in the dossier. IZUMO1 not flagged as receptor.","key_references":[{"PMID":"27309808","why":"Crystal structure of IZUMO1-JUNO complex"},{"PMID":"30517645","why":"Anti-JUNO antibody blocks human gamete fusion"}],"covers":["LR002831","LR006068"]},"LR006071":{"pair":"JAM3 -> ITGAM","headline":"JAM3 binds the integrin Mac-1 (ITGAM/ITGB2) directly; purified-protein and cell-adhesion evidence in human cells, plus database records.","interaction_type":"direct binding","direction_and_effect":"JAM-3 acts as a counterreceptor for Mac-1 on leukocytes: myelo-monocytic cells adhere to immobilised JAM-3, and purified JAM-3 or anti-JAM-3 antibodies block platelet-neutrophil interaction [PMID:12208882]. A second paper reports JAM-C (JAM3) availability regulates alpha(M)beta2-dependent leukocyte adhesion [PMID:16093349].","molecular_requirements":"Evidence is for the Mac-1 heterodimer (alphaM/ITGAM with beta2/ITGB2), not ITGAM alone: binding was strong for Mac-1, weaker for p150.95 (alphaXbeta2), and absent for LFA-1 or beta1-integrins [PMID:12208882]. Adhesion needed a beta2-integrin and was blocked by anti-Mac-1 antibody [PMID:12208882].","affinity_potency":[],"species_and_systems":"Human platelets, U937 cells, K562 transfectants, CHO transfectants and purified proteins [PMID:12208882]; species of the second paper's experiments is not specified [PMID:16093349]. The dossier covers human and mouse entries; the experiments shown are human.","localisation_and_range":"JAM-3 is a type I transmembrane glycoprotein [PMID:12208882], so signalling is contact-dependent (juxtacrine); the entity flags also mark JAM3 as secreted [flag], which the papers do not support.","caveats":"The ITGAM evidence is complex-level, so ITGAM and ITGB2 both inherit it. Both papers were read as abstracts by the curators (the first also has full-text excerpts) [PMID:12208882, PMID:16093349]. The second paper is a functional adhesion study. No affinity reported in our evidence.","key_references":[{"PMID":"12208882","why":"Direct JAM-3/Mac-1 binding with integrin specificity panel"},{"PMID":"16093349","why":"JAM-C availability regulates alphaMbeta2-dependent leukocyte adhesion"}],"covers":["LR002834","LR006071"]},"LR012425":{"pair":"KLB -> FGFR2","headline":"Only a BioGRID affinity capture-western record from one paper; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond the curated Stimulatory annotation [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID records an affinity capture-western experiment in PMID 17623664; species and system are not reported in our evidence [DB:BioGRID].","localisation_and_range":"Not reported in our evidence.","caveats":"No confirmed paper: three papers were judged abstract_insufficient, so support is a database record only [DB:BioGRID].","key_references":[],"covers":["LR012425"]},"LR002840":{"pair":"KLRF2 -> CLEC2A","headline":"NKp65 (KLRF2) binds KACL (CLEC2A) with high affinity and activates NK cells; supported by SPR, ITC and a crystal structure.","interaction_type":"direct binding","direction_and_effect":"NKp65 is an activating receptor that binds KACL, stimulating NK cytotoxicity and proinflammatory cytokine release on engagement of cell-bound KACL [PMID:20194751].","molecular_requirements":"NKp65 has an amino-terminal hemITAM required for its cytotoxicity function; KACL is a non-disulfide-linked homodimeric surface receptor [PMID:20194751].","affinity_potency":[],"species_and_systems":"Human NK92MI cells and freshly isolated keratinocytes [PMID:20194751]. IntAct lists surface plasmon resonance, X-ray crystallography and isothermal titration calorimetry; PDB 4IOP [DB:IntAct][DB:PDB 4IOP].","localisation_and_range":"Both are membrane-bound, so signalling is by cell contact [flag]. KACL expression is mainly restricted to keratinocytes [PMID:20194751].","caveats":"The paper says binding is of 'high affinity' but gives no number in our evidence. Read as an abstract only. Note the site direction has KLRF2 as ligand while the paper describes KLRF2 as the activating receptor on NK cells and KACL as the ligand on keratinocytes.","key_references":[{"PMID":"20194751","why":"Identification of NKp65 as the KACL receptor"}],"covers":["LR002840"]},"LR005216":{"pair":"L1CAM -> ALCAM","headline":"Functional adhesion evidence only: ALCAM or L1 itself identified as endothelial binding partner for L1-CAM-high breast cancer cells.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies and recombinant-protein-coated flow channels identified ALCAM or L1 itself, but not ICAM-1, as potential binding partners on endothelial cells; L1-CAM on cancer cells promotes adherence to activated endothelium [PMID:22983139]. Direction is cancer-cell L1-CAM to endothelial ALCAM.","molecular_requirements":"Not reported in our evidence beyond a Reactome L1:ALCAM complex record [DB:Reactome R-HSA-443658].","affinity_potency":[],"species_and_systems":"Human breast cancer cells (MDA-MB231-Fra2) and human pulmonary microvascular endothelial cells; only the abstract was read [PMID:22983139]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-to-membrane adhesion between cells (juxtacrine), as implied by the cell adhesion assays [PMID:22983139]; flags list both as secreted and transmembrane [flag].","caveats":"Only one paper, abstract only; the paper says 'potential binding partners' and does not show direct binding. The ALCAM-or-L1 result is not resolved between the two.","key_references":[{"PMID":"22983139","why":"Blocking and adhesion assays implicate ALCAM"}],"covers":["LR001874","LR005216"]},"LR006080":{"pair":"L1CAM -> ITGA2B","headline":"Direct heterophilic binding of L1 Ig6 (RGD) to alphaIIbbeta3 supports platelet adhesion; ITGA2B alone is a chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"The sixth Ig-like domain of human L1 (L1-Ig6) functions as a heterophilic ligand for integrins including alphaIIbbeta3, supporting rapid attachment of activated human platelets [PMID:9396761]. Adhesion-promoting (agonist-like).","molecular_requirements":"Binding needs the single RGD motif in L1-Ig6; mutation abrogated it, and a RGD peptide blocked it. Evidence concerns the alphaIIbbeta3 heterodimer, so ITGA2B alone is chain-level only; ITGB3 is also required [PMID:9396761].","affinity_potency":[],"species_and_systems":"Human L1-Ig6 and human integrins, cell adhesion assays with human platelets; abstract read, though dossier lists full text [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; L1 de novo expression on blood vessels in neoplastic and inflammatory disease is noted by the curator [PMID:9396761]. ITGA2B has no secreted flag [flag].","caveats":"Single paper, no affinity; use the ITGA2B:ITGB3 complex row for scoring.","key_references":[{"PMID":"9396761","why":"L1-Ig6 RGD binds alphaIIbbeta3"}],"covers":["LR002845","LR006080"]},"LR007052":{"pair":"L1CAM -> ITGAV:ITGB3","headline":"One paper shows RGD-dependent L1-Ig6 binding of alphavbeta3 supporting endothelial adhesion; related ELISA evidence in sibling rows.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 binds L1-Ig6 and supports HUVEC adhesion [PMID:9396761]. Binding is blocked by the PSITWRGDGRDLQEL peptide.","molecular_requirements":"RGD-dependent, abrogated by RGD mutation; beta3 binding in Ca2+, Mg2+ or Mn2+ [PMID:9396761]. Highest in the stated hierarchy.","affinity_potency":[],"species_and_systems":"Human L1-Ig6, HUVEC and activated platelets; CHO cells [PMID:9396761].","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Single paper for this row, no affinity. Curator note says the row is unique to non-connectome sources.","key_references":[{"PMID":"9396761","why":"alphavbeta3 binds L1-Ig6 via RGD"}],"covers":["LR007052"]},"LR004406":{"pair":"LAMA2 -> ITGB1","headline":"Laminin-211/221 shows only partial, non-saturating binding to alpha7beta1; weak direct evidence plus abstract-only functional support.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 showed only partial saturation at the highest recombinant integrin concentration tested [PMID:16413178]. Alpha7beta1 mediates myoblast migration on laminin-2 [PMID:11278916]. Labelled Stimulatory [flag].","molecular_requirements":"ITGB1 acts as part of alpha-beta heterodimers; alpha7beta1 is the one tested here [PMID:11278916].","affinity_potency":[],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human myoblasts [PMID:11278916]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged not secreted [flag].","caveats":"The curator calls the positive weak; Kd was not determinable (ND(+)) and the ligand is the trimer, not LAMA2 alone [PMID:16413178]. Two other confirmed rows are not shown.","key_references":[{"PMID":"16413178","why":"Partial saturation with laminin-211/221"},{"PMID":"11278916","why":"Alpha7beta1 migration on laminin-2"}],"covers":["LR000986","LR004406"]},"LR011039":{"pair":"LAMA3 -> ITGA6:ITGB1","headline":"No paper evidence; supported only by a Reactome record that names a different integrin.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a Reactome binding reaction [DB:Reactome].","molecular_requirements":"Complex alpha6/beta1 (ITGA6 plus ITGB1) is the nominal receptor; no experiment on it in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Rests on database alone. The Reactome record R-HSA-349626 describes integrin alpha2beta1 binding laminin-332, not alpha6beta1 [DB:Reactome]. Related papers for LAMA3-ITGA6 are on the ITGA6 pair card.","key_references":[],"covers":["LR011039"]},"LR011390":{"pair":"LAMA3 -> ITGA7:ITGB1","headline":"No paper evidence; only a Reactome record naming a different integrin.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a Reactome binding reaction [DB:Reactome].","molecular_requirements":"Receptor is the alpha7beta1 complex; no experiment on it in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Rests on database alone. Reactome R-HSA-349626 describes integrin alpha2beta1 binding laminin-332, not alpha7beta1 [DB:Reactome].","key_references":[],"covers":["LR011390"]},"LR004415":{"pair":"LAMA5 -> ITGA6","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha6beta1 with sub-nM Kd; supported by binding and antibody-blocked adhesion.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha6beta1 [PMID:16413178]. Mouse FDCP-mix cell adhesion to alpha5-laminins involved integrin alpha6 and beta1 chains by antibody perturbation [PMID:10194432]. Annotated stimulatory.","molecular_requirements":"Binding was shown for the assembled heterotrimer with the alpha6beta1 heterodimer, not for single chains [PMID:16413178]. A PDB entry has a chain of O15230 and a chain of P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse cell adhesion [PMID:10194432]. Mouse pair is ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA6 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Heterotrimer-level evidence. The adhesion paper was read as an abstract only and is a functional antibody readout [PMID:10194432].","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta1 for laminin-511/521"},{"PMID":"10194432","why":"Mouse cell adhesion to alpha5-laminins via alpha6/beta1"}],"covers":["LR000996","LR004415"]},"LR011381":{"pair":"LAMB1 -> ITGA3:ITGB1","headline":"Complex row for laminin beta1 and integrin alpha3beta1; only PDB and similarity-based UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P05556 [DB:PDB 7CEC]; UniProt notes ITGB1 interacts with LAMB1 (by similarity) [DB:UniProt].","molecular_requirements":"Receptor is the ITGA3:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA3:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Three papers pending, none judged for this row; the UniProt note is by similarity and concerns ITGB1 only. Paper evidence exists on the separate LAMB1 -> ITGA3 row but is not counted here.","key_references":[],"covers":["LR011381"]},"LR004424":{"pair":"LAMB3 -> ITGA6","headline":"LAMB3 (in laminin-332) binds integrin alpha6beta1 at Kd 7.5 nM in recombinant assays; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha6beta1 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder tested is the alpha6beta1 heterodimer, ligand the assembled heterotrimer; ITGA6 alone and LAMB3 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. One confirming paper; three others were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-332"}],"covers":["LR001006","LR004424"]},"LR004433":{"pair":"LAMC2 -> ITGA6","headline":"Recombinant integrin alpha6beta1 binds laminin-332 (contains LAMC2) with Kd 7.5 nM; LAMC2 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha6beta1 bound laminin-332 in solid-phase assays [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The ligand tested is the assembled laminin-332 heterotrimer and the receptor the alpha6beta1 heterodimer; individual chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha6beta1 ectodomain","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Chain-level assignment inferred from heterotrimer and heterodimer binding.","key_references":[{"PMID":"16413178","why":"Laminin isoform binding by recombinant integrins"}],"covers":["LR001015","LR004433"]},"LR006107":{"pair":"LCN2 -> MC4R","headline":"In mice, bone-derived LCN2 binds MC4R in hypothalamic neurons and suppresses appetite in an MC4R-dependent manner.","interaction_type":"functional only","direction_and_effect":"LCN2 crosses the blood-brain barrier, binds MC4R in paraventricular and ventromedial hypothalamic neurons and activates an MC4R-dependent anorexigenic pathway; curated as agonist [PMID:28273060].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments in vivo, both ligand and receptor [PMID:28273060]. Human pair is also listed.","localisation_and_range":"LCN2 is a secreted osteoblast-enriched hormone acting endocrine on the brain [PMID:28273060]; MC4R flagged transmembrane [flag].","caveats":"Curated from the abstract; the dossier shows no excerpt of a direct binding assay, so the binding claim rests on the abstract statement.","key_references":[{"PMID":"28273060","why":"LCN2 binds MC4R and suppresses appetite in mice"}],"covers":["LR002873","LR006107"]},"LR008330":{"pair":"LEP -> ISLR2","headline":"Leptin binding to ISLR2 was shown by ELISA, SPR and cell staining in a human interactome screen.","interaction_type":"direct binding","direction_and_effect":"Leptin bound ISLR2 ECD and the LRR1-7 truncation equally, not Ig1-3, and bound ISLR2-transfected but not control cells [PMID:32822567]. Leptin pre-incubated with LEPR did not bind ISLR2, suggesting leptin cannot bind LEPR and ISLR2 simultaneously [PMID:32822567]. Agonist or antagonist effect not reported in our evidence.","molecular_requirements":"The leucine-rich repeat region (LRR1-7) of ISLR2 is sufficient for leptin binding [PMID:32822567].","affinity_potency":[],"species_and_systems":"Recombinant human proteins (SPR, ECIA, flow cytometry on transfected cells); human leptin was also tested on mouse Islr2 by ECIA, result not given in our excerpts [PMID:32822567].","localisation_and_range":"Leptin flagged secreted; ISLR2 flagged receptor [flag]. Signalling and range not reported in our evidence.","caveats":"Binding only, no functional readout. Binding is competed by LEPR, so ISLR2 may not co-engage with leptin-LEPR. Affinity values for this pair are not in our excerpts.","key_references":[{"PMID":"32822567","why":"Cell IgSF interactome; leptin-ISLR2 SPR, ECIA and cell binding"}],"covers":["LR008330"]},"LR006116":{"pair":"LGALS3 -> IL13RA2","headline":"Galectin-3 physically interacts with IL-13Ralpha2 and displaces TMEM219 from it, shown in Hermansky-Pudlak lung work.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 physically interacted with IL-13Ralpha2 and CHI3L1 and competed with TMEM219 for IL-13Ralpha2 binding; recombinant galectin-3 diminished TMEM219 binding to IL-13Ralpha2, abrogating the chitosome complex and its antiapoptotic signalling [PMID:29427412]. Effect is antagonist for epithelial apoptosis protection, but augmented macrophage Wnt/beta-catenin signalling [PMID:29427412].","molecular_requirements":"Competes with TMEM219 for IL-13Ralpha2, so the IL-13Ralpha2/TMEM219 complex is the relevant context [PMID:29427412]. IntAct lists anti-bait coimmunoprecipitation [DB:IntAct].","affinity_potency":[],"species_and_systems":"HPS bronchoalveolar lavage fluid, lung fibroblasts and macrophages, with recombinant human galectin-3; curators list human [PMID:29427412]. Human pair ortholog-inferred, mouse not.","localisation_and_range":"Galectin-3 flagged secreted; extracellular galectin-3 drives epithelial apoptosis [PMID:29427412].","caveats":"Affinity not reported in our excerpts. Read depth is abstract only although the excerpts quote full text; IL-13Ralpha2 is also a decoy for other ligands.","key_references":[{"PMID":"29427412","why":"Gal-3 binds IL-13Ralpha2 and competes with TMEM219"}],"covers":["LR002882","LR006116"]},"LR002903":{"pair":"LGALS9 -> BCR","headline":"Galectin-9 binds IgM B-cell receptor and strongly dampens BCR signalling; the entity named BCR here is likely the B-cell receptor, not the BCR gene.","interaction_type":"functional only","direction_and_effect":"Recombinant galectin-9 nearly completely abolished BCR signaling; Gal9-deficient B cells showed enhanced BCR microclusters and ERK1/2 phosphorylation (antagonist/inhibitory) [PMID:30120235].","molecular_requirements":"Galectin-9 merges IgM-BCR nanoclusters, immobilizes it, and relocalizes it with CD45 and CD22 [PMID:30120235].","affinity_potency":[],"species_and_systems":"Experiments used primary mouse naive B cells (WT and Gal9-KO); human pair is ortholog-inferred [PMID:30120235].","localisation_and_range":"Galectin-9 is secreted by flag [flag]; acts on the B cell surface.","caveats":"Abstract and excerpts only; curated assay class is functional. IgM-BCR as a ligand is stated in the abstract; no affinity. The entity symbol BCR may be ambiguous.","key_references":[{"PMID":"30120235","why":"IgM-BCR identified as galectin-9 ligand that suppresses BCR signaling"}],"covers":["LR002903","LR006132"]},"LR006134":{"pair":"LGALS9 -> IGHM","headline":"Galectin-9 reported to bind IgM-BCR on B cells and inhibit BCR signalling; one paper, abstract-only.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 is identified as a ligand for IgM-BCR; it merges and immobilises IgM-BCR nanoclusters and relocalises them with inhibitory CD45/CD22 [PMID:30120235]. Abstract states exogenous recombinant galectin-9 nearly completely abolishes BCR signalling [PMID:30120235].","molecular_requirements":"Relocalisation with CD45 and CD22 is part of the mechanism; whether the BCR heavy chain alone suffices is not reported in our evidence [PMID:30120235].","affinity_potency":[],"species_and_systems":"Super-resolution imaging and single-particle tracking in B cells; excerpts mention C57BL/6 and Lgals9 knockout mice, so the work is mouse [PMID:30120235]. The human pair is ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted [flag]; it is found bound to the surface of primary naive B cells [PMID:30120235].","caveats":"Single paper, read as abstract only for the curator judgement; no affinity reported. Direction is inhibitory on BCR signalling, not a classical agonist.","key_references":[{"PMID":"30120235","why":"Galectin-9 binds IgM-BCR, inhibits BCR signalling"}],"covers":["LR002907","LR006134"]},"LR005225":{"pair":"LGI1 -> ADAM11","headline":"LGI1 binds ADAM11 with significant ability in one study, secondary to ADAM22; Reactome also lists it.","interaction_type":"direct binding","direction_and_effect":"ADAM11 had a significant binding ability to LGI1 or LGI4, so ADAM22 is not the sole receptor [PMID:18974846]. Reactome lists LGI1 binds ADAM11 and an LGI1 dimer:ADAM11 complex [DB:Reactome]. Effect direction not reported in our evidence.","molecular_requirements":"Reactome describes an LGI1 dimer:ADAM11 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curator labels both partners human; excerpts describe mouse brain and mouse HA-tagged LGI1 in cell-based ELISA [PMID:18974846]. Human pair is ortholog-inferred.","localisation_and_range":"LGI1 is a secreted protein and the ADAM binds on the cell surface [PMID:18974846]; ADAM11 flagged non-secreted receptor [flag].","caveats":"The abstract does not say whether the ADAM11 binding was to LGI1 or LGI4 ('LGI1 or LGI4'), and no affinity is given; read as abstract only [PMID:18974846]. The excerpts focus on ADAM22.","key_references":[{"PMID":"18974846","why":"LGI-ADAM binding specificity incl. ADAM11"}],"covers":["LR001883","LR005225"]},"LR005234":{"pair":"LGI4 -> ADAM22","headline":"LGI4 binds ADAM22 directly and strongly, and acts on axonal Adam22 to drive Schwann cell differentiation.","interaction_type":"direct binding","direction_and_effect":"Schwann-cell Lgi4 signals in a paracrine manner to axonal Adam22 to drive Schwann cell differentiation in peripheral nerve myelination; agonist [PMID:20220021]. In cell-ELISA LGI4 bound ADAM22 most strongly of the ADAMs tested [PMID:18974846].","molecular_requirements":"Lgi4 binds Adam22 directly without a requirement for additional membrane-associated factors [PMID:20220021]. Adam22 is required on axons, Lgi4 comes from Schwann cells [PMID:20220021]. ADAM22 is not the sole LGI4 receptor; ADAM11 and ADAM23 also bind [PMID:18974846].","affinity_potency":[],"species_and_systems":"Mouse: cell-ELISA with mouse LGI4 and ADAM22 [PMID:18974846]; Schwann cell-sensory neuron cocultures and cell-type-specific knockout in mice [PMID:20220021].","localisation_and_range":"Paracrine: Lgi4 is secreted by Schwann cells and acts on axonal Adam22 [PMID:20220021]. LGI4 is flagged secreted [flag].","caveats":"Both papers are abstract-based for this pair or read via excerpts; no affinity value is reported. Promiscuous ADAM binding means receptor choice depends on expression [PMID:18974846]. The dossier labels 18974846 species as human although its text concerns mouse proteins.","key_references":[{"PMID":"20220021","why":"Direct Lgi4-Adam22 binding and paracrine signalling in vivo"},{"PMID":"18974846","why":"Cell-ELISA, LGI4 strongest with ADAM22"}],"covers":["LR001892","LR005234"]},"LR004442":{"pair":"LIF -> IL6ST","headline":"LIF signals through gp130 (IL6ST) as the shared signalling chain; evidence is functional and computational, plus structures.","interaction_type":"functional only","direction_and_effect":"LIF signals through a gp130(IL6ST)/LIFR receptor complex, gp130 being a shared signal-transducing subunit; agonist [PMID:16051226]. GtoPdb records an agonist [DB:GtoPdb]. UniProt says ligand binding to LIFR induces heterodimerization with IL6ST and JAK activation [DB:UniProt].","molecular_requirements":"IL6ST works with LIFR; the receptor complex has two signalling subunits, IL6ST and LIFR [DB:UniProt]. A homology model suggests gp130 and the membrane-proximal LIFR CBD heterodimerize and bind LIF [PMID:9568895]. PDB structures 1PVH and 8D6A contain chains of both proteins [DB:PDB 1PVH][DB:PDB 8D6A].","affinity_potency":[],"species_and_systems":"Human receptors in cell-based signalling [PMID:16051226]; the 1998 study is computational [PMID:9568895]. The mouse pair is ortholog-inferred.","localisation_and_range":"LIF is flagged secreted and IL6ST as transmembrane [flag].","caveats":"Neither paper directly measures LIF binding to IL6ST alone: one is signalling in cells, the other homology modelling, both abstract-read. IL6ST alone is not shown to be sufficient; LIFR is needed.","key_references":[{"PMID":"16051226","why":"LIF signals through gp130/LIFR complex in cells"},{"PMID":"9568895","why":"Homology model of gp130-LIFR dimer binding LIF"}],"covers":["LR001025","LR004442"]},"LR002912":{"pair":"LINGO1 -> LINGO1","headline":"LINGO-1 ectodomain binds full-length LINGO-1 in trans and inhibits oligodendrocyte differentiation; one abstract-read paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"Soluble LINGO-1 ectodomain interacts with itself in trans by binding CHO cells expressing full-length LINGO-1; antagonist of oligodendrocyte differentiation and myelination [PMID:22514275]. The abstract states this activates RhoA per curator note.","molecular_requirements":"Homophilic: one protein is both ligand and receptor. No other subunits are reported.","affinity_potency":[],"species_and_systems":"Mouse; recombinant ectodomain and CHO cells, oligodendrocyte precursor and DRG cocultures [PMID:22514275]. Human pair is ortholog-inferred. IntAct has an anti-tag coimmunoprecipitation for the human self-pair [DB:IntAct].","localisation_and_range":"Membrane-bound with trans (cell-contact) action; soluble ectodomain also acts [PMID:22514275]. Neither entity is flagged secreted [flag].","caveats":"One paper read from abstract only. No affinity reported. Homodimer pairs complicate CCC scoring.","key_references":[{"PMID":"22514275","why":"LINGO-1 ectodomain self-interacts in trans and inhibits OPC differentiation"}],"covers":["LR002912","LR006138"]},"LR006143":{"pair":"LRFN5 -> PTPRF","headline":"LRFN5 (SALM5) binds LAR (PTPRF) via its Ig domains with Kd 8.96 nM; one paper, direct measurement.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells, LAR-Ecto-Fc","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity measured directly for LAR. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002918","LR006143"]},"LR002921":{"pair":"LRIG1 -> VSIR","headline":"LRIG1 binds VISTA (VSIR) directly with nanomolar affinity, and the pair inhibits T cell receptor signalling; evidence comes from one paper.","interaction_type":"direct binding","direction_and_effect":"The paper describes LRIG1 as an inhibitory receptor engaging VISTA and suppressing TCR signalling [PMID:38758807]. T cell-specific LRIG1 deletion in mice gave superior antitumor CTL responses [PMID:38758807]. Curators label the effect antagonist [PMID:38758807].","molecular_requirements":"In the murine T cell line D10.G4.1, VISTA or LRIG1 alone was functionally inert; coexpression of both inhibited phosphorylation of LAT, PLC-gamma, SLP76, AKT S473 and ERK1/2 [PMID:38758807]. The LRIG1 extracellular domain is needed for binding, and cis and trans binding were both seen [PMID:38758807].","affinity_potency":[{"value":"KD 1.20 nM (pH 7.4)","assay":"SPR, recombinant ECDs","system":"murine","cite":"PMID:38758807"},{"value":"KD 3.44 nM (pH 6.0)","assay":"SPR, recombinant ECDs","system":"murine","cite":"PMID:38758807"},{"value":"KD 1.86 nM (pH 7.4)","assay":"SPR, recombinant ECDs","system":"human","cite":"PMID:38758807"},{"value":"KD 0.23 nM (pH 6.0)","assay":"SPR, recombinant ECDs","system":"human","cite":"PMID:38758807"}],"species_and_systems":"Binding was shown by proximity labelling, co-IP, SPR and a luciferase complementation assay, in murine T cells, HEK293 cells and B16.OVA tumours; SPR used murine and human proteins [PMID:38758807]. The mouse pair is listed separately and is not ortholog-inferred.","localisation_and_range":"Both are type-I transmembrane or membrane proteins per annotation [flag]. The paper shows cis (same cell) and trans (APC to T cell) binding, so signalling is contact-dependent [PMID:38758807]. LRIG1 was induced on T cells after anti-CD3/CD28 stimulation and absent on naive cells [PMID:38758807].","caveats":"Only one paper, read as abstract plus excerpts. Our pair lists LRIG1 as ligand and VSIR as receptor, but the paper calls LRIG1 the receptor and VISTA the ligand, so direction is assignment-dependent. Human functional data are correlative (LRIG1 expression and immunotherapy resistance) [PMID:38758807].","key_references":[{"PMID":"38758807","why":"Identifies LRIG1 as a VISTA binding partner, with SPR affinities and T cell function"}],"covers":["LR002921","LR006146"]},"LR004451":{"pair":"LRPAP1 -> LRP2","headline":"RAP (LRPAP1) binds LRP2 (gp330) with high affinity at two mapped RAP sites; foundational 1994 evidence plus structure and database records.","interaction_type":"direct binding","direction_and_effect":"RAP binds gp330 with high affinity in a Ca2+-dependent manner and is an effective inhibitor of ligand binding to gp330 and LRP [PMID:7512726]. Curators label it an antagonist [PMID:7512726].","molecular_requirements":"gp330 binds two separate sites on RAP, residues 85-148 and 178-248; the heparin site is between residues 261 and 323 [PMID:7512726].","affinity_potency":[],"species_and_systems":"Biochemical binding studies (ligand blotting, affinity chromatography, fusion proteins); the paper's species is listed as human [PMID:7512726]. Databases: PDB structure [DB:PDB 9QAW], BioGRID [DB:BioGRID], UniProt [DB:UniProt]. Both listed species are ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The abstract says RAP is most abundant in the ER lumen and may function in receptor folding or trafficking [PMID:7512726].","caveats":"No affinity value in our evidence. RAP is a chaperone/inhibitor, not a signalling ligand. Abstract only.","key_references":[{"PMID":"7512726","why":"gp330 binds RAP with high affinity; two RAP binding sites mapped"}],"covers":["LR001037","LR004451"]},"LR006152":{"pair":"LRRTM1 -> NRXN1","headline":"LRRTM1 binds neurexin-1 lacking the splice site 4 insert; binding code shown in vitro and by LRRTM2 structure, with LRRTM1 data from abstracts.","interaction_type":"direct binding","direction_and_effect":"LRRTM1 and LRRTM2 bind the Nrxn splice variant lacking an insert at splice site 4 (S4) [PMID:30262834]. The binding code first characterised for LRRTM2 is conserved in LRRTM1 and is functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Binding requires neurexin lacking the S4 insert [PMID:30262834, PMID:20519524]. The crystal structure was of Nrxn1beta with LRRTM2, not LRRTM1; the excerpts say LRRTM2 key residues Glu348, Asp352 and Phe357 are completely conserved in LRRTM1 [PMID:30262834].","affinity_potency":[],"species_and_systems":"The structure paper used human proteins per the curator fields [PMID:30262834]; the 2010 paper does not specify species in our evidence [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; the papers describe postsynaptic LRRTMs binding presynaptic neurexins in trans [PMID:30262834].","caveats":"The direct structure is for LRRTM2, so LRRTM1 binding rests on conservation and an abstract-level statement. Both papers were read as abstracts (the structure paper also has excerpts). Affinity for LRRTM1 not reported in our evidence.","key_references":[{"PMID":"20519524","why":"shows LRRTM2 neurexin code is conserved in LRRTM1"},{"PMID":"30262834","why":"Nrxn1beta-LRRTM2 structure; S4-lacking selectivity"}],"covers":["LR002927","LR006152"]},"LR002930":{"pair":"LRRTM2 -> NRXN1","headline":"LRRTM2 binds neurexin-1 lacking the S4 insert; well supported by binding assays, a crystal structure and knockdown, in several systems.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 acts as a neurexin ligand that promotes excitatory synapse formation; neurexin-1alpha and -1beta bound avidly to LRRTM2 only when lacking an insert at SS#4 [PMID:20064387]. Recombinant neurexin-1beta blocks LRRTM2-promoted presynaptic differentiation [PMID:20064387], and Nrxn1 knockdown abolishes LRRTM2-induced presynaptic differentiation [PMID:20064388]. Truncated NRXN1 and NRXN2 mutants fail to bind LRRTM2 in cell binding assays [PMID:21424692].","molecular_requirements":"Neurexin must lack the S4 insert; binding is Ca2+-dependent and reversed by EGTA [PMID:20064387]. The Nrxn1beta-LRRTM2 structure (3.4 A resolution) shows a calcium ion in the interface; LRRTM2 E348Q and Nrxn1beta D141A mutations abolished or almost abolished binding, and Nrxn1beta binds the LRRTM2 C-terminal cap [PMID:30262834].","affinity_potency":[],"species_and_systems":"Affinity chromatography used rat brain and recombinant Ig-fusions, binding assays used HEK293T cells [PMID:20064387]; the structure used human proteins [PMID:30262834]. Both alpha and beta neurexin-1 bind [PMID:20064387, PMID:20064388].","localisation_and_range":"Both partners are flagged transmembrane [flag]. Papers describe trans-interaction, with LRRTM2 postsynaptic and neurexin presynaptic, producing cell-adhesion junctions [PMID:20064387].","caveats":"No affinity value in our evidence (SPR sensorgrams are mentioned without values). Two of five papers were read as abstracts only [PMID:20519524, PMID:21424692]; the 2011 paper uses the pair only as a readout of mutation effects.","key_references":[{"PMID":"20064387","why":"affinity chromatography and cell binding; S4 dependence, Ca2+ dependence"},{"PMID":"30262834","why":"crystal structure of Nrxn1beta-LRRTM2 complex"},{"PMID":"20064388","why":"Nrxn1 knockdown abrogates LRRTM2 synaptogenic activity"}],"covers":["LR002930","LR006155"]},"LR006161":{"pair":"LRRTM4 -> GPC4","headline":"LRRTM4 binds GPC4 in a heparan sulfate-dependent trans-synaptic manner; one paper with reciprocal affinity chromatography.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103]. Reciprocal affinity chromatography with GPC4-Fc identified LRRTM3 and LRRTM4 but not LRRTM1 or LRRTM2 [PMID:23911103]. LRRTM4 triggers GPC4 clustering in contacting axons and GPC4 induces LRRTM4 clustering in contacting dendrites, HS-dependently; LRRTM4 synaptogenic activity requires neuronal-surface HS [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC4 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. Evidence is specific to GPC4 in the abstract. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002936","LR006161"]},"LR001049":{"pair":"MADCAM1 -> ITGA4","headline":"MADCAM1 is a ligand of integrin alpha4beta7; evidence is for the heterodimer, and ITGA4 alone is a subunit-level entry.","interaction_type":"direct binding","direction_and_effect":"MADCAM1 binds integrin alpha4beta7 and mediates lymphocyte adhesion; stimulatory effect per the interaction annotation. The paper-level evidence shows alpha4beta7 is a receptor for MAdCAM-1 [PMID:7687523]. Chemokines tune this: CCL25 raised alpha4beta7-MAdCAM-1 adhesion frequency from 31% to 55%, while CXCL10 lowered it to 25% [PMID:29789438].","molecular_requirements":"Needs the alpha4/beta7 pair. Alpha4beta1 does not support efficient binding to MAdCAM-1 [PMID:7687523]; beta7 residues 46-386 account for MAdCAM-1 specificity [PMID:9233649]. Alpha4 Tyr(187) is key for adhesion to soluble MAdCAM-1-Ig [PMID:10702270]. ITGB7 must be co-expressed when scoring.","affinity_potency":[],"species_and_systems":"Human cells in most assays (RPMI 8866-CXCR3 lymphocyte line, K562 transfectants) [PMID:29789438][PMID:10702270]; one paper does not state species [PMID:7687523]. Mouse pair is ortholog-inferred.","localisation_and_range":"MADCAM1 is flagged transmembrane, not secreted [flag]; contact-dependent adhesion (juxtacrine).","caveats":"Four of the confirmed papers were read as abstracts only except PMID:29789438, which has full-text excerpts. Activity depends on integrin conformation: Mn2+ opens alpha4beta7 for both MAdCAM-1 and VCAM-1 [PMID:29789438]. Reactome, IntAct and PDB records describe the alpha4beta7 complex, not ITGA4 alone [DB:Reactome][DB:PDB 9P95].","key_references":[{"PMID":"7687523","why":"alpha4beta7 identified as receptor for MAdCAM-1; alpha4beta1 does not bind"},{"PMID":"29789438","why":"conformer-dependent ligand switching with single-cell force data"},{"PMID":"9233649","why":"beta7 region specifying MAdCAM-1 binding"}],"covers":["LR001049","LR004462"]},"LR006170":{"pair":"MAG -> RTN4R","headline":"MAG binds NgR1 (RTN4R) and its inhibition of neurite outgrowth depends on it, shown in mouse; one confirmed paper concerns NgR2 instead.","interaction_type":"direct binding","direction_and_effect":"MAG interacts with NgR1 to inhibit neurite outgrowth (agonist). MAG precipitates NgR from NgR-expressing cells, DRG and cerebellar neurons; soluble NgR, NgR antibody or dominant-negative NgR each block MAG inhibition; MAG and Nogo66 compete for NgR [PMID:12160746]. NgR1 also supports MAG binding in neurons in a sialic acid-dependent manner [PMID:15673660].","molecular_requirements":"NgR is GPI-linked with no transmembrane domain and needs a signalling partner [PMID:12160746]. Binding to NgR-expressing cells was sialic acid independent in one study [PMID:12160746] but sialic acid dependent in neurons in another [PMID:15673660].","affinity_potency":[{"value":"IC50 120 nM","assay":"Nogo66-AP competition for MAG-Fc binding (not a MAG-NgR Kd)","system":"neurons on immobilized MAG-Fc","cite":"PMID:12160746"}],"species_and_systems":"Mouse cells and neurons [PMID:12160746]; PMID:15673660 is labelled human but is abstract-only. Mouse pair of this dossier is ortholog-inferred.","localisation_and_range":"MAG is flagged secreted; RTN4R is flagged transmembrane [flag], whereas the paper describes NgR as GPI-linked without a transmembrane domain [PMID:12160746]. Contact/paracrine myelin-to-axon signalling is not stated explicitly.","caveats":"PMID:15673660 mainly shows NgR2 binds MAG with greater affinity than NgR1; no NgR1 affinity is given. Sialic acid dependence differs between the two papers. UniProt lists RTN4R as receptor for MAG [DB:UniProt].","key_references":[{"PMID":"12160746","why":"reciprocal binding, co-precipitation and loss-of-function of MAG-NgR"},{"PMID":"15673660","why":"NgR1 vs NgR2 as MAG receptors"}],"covers":["LR002945","LR006170"]},"LR001058":{"pair":"MDK -> ITGB1","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Beta1 integrin bound a midkine-agarose column and was eluted mostly with EDTA; alpha4 and alpha6 were the binding alpha-subunits [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt]. ITGB1 is the shared chain; the alpha partner matters for scoring.","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001058","LR004471"]},"LR005243":{"pair":"MDK -> NOTCH2","headline":"Midkine reported to bind NOTCH2 and activate its signalling in human keratinocytes; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MK binds the Notch2 receptor in HaCaT keratinocytes and activates Notch2 signalling (agonist), linked to Hes1 and Jak2/Stat3 and to EMT [PMID:18469519].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes [PMID:18469519]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK flagged secreted; NOTCH2 flagged transmembrane [flag]. Paracrine.","caveats":"Single paper, abstract only; binding assay not described. Curator notes this is a non-canonical pairing. Reactome has binding and complex records [DB:Reactome].","key_references":[{"PMID":"18469519","why":"MK-Notch2 binding and signalling in HaCaT cells"}],"covers":["LR001901","LR005243"]},"LR001067":{"pair":"MFAP5 -> NOTCH1","headline":"Paper supports MAGP-2 (MFAP5) interacting with Notch1 EGF-like repeats and activating it; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MAGP-2 interacted with Notch1 EGF-like repeats; co-expression released the Notch1 ectodomain and activated Notch signalling, as an agonist [PMID:16492672].","molecular_requirements":"The C-terminal domain of MAGP-2 is required for binding and activation; release requires furin-like heterodimer formation but not ADAM cleavage [PMID:16492672].","affinity_potency":[],"species_and_systems":"Human proteins, cell co-expression assays [PMID:16492672]. Both species pairs are ortholog-inferred.","localisation_and_range":"MFAP5 is flagged secreted [flag]; described as a microfibril-associated protein [PMID:16492672].","caveats":"Abstract only; the abstract does not use the MFAP5 name, so mapping MAGP-2 to MFAP5 is a curator assumption. No affinity reported.","key_references":[{"PMID":"16492672","why":"MAGP-2 binds Notch1 EGF repeats and induces activation"}],"covers":["LR001067","LR004480"]},"LR001904":{"pair":"MIF -> CD74","headline":"MIF binds CD74 directly with a Kd of about 9 nM and activates ERK signalling; this is well supported by two papers.","interaction_type":"direct binding","direction_and_effect":"MIF is an agonist at CD74: CD74 is required for MIF-induced ERK1/2 activation, proliferation and PGE2 production, and soluble CD74 inhibits MIF-mediated ERK activation [PMID:12782713]. In human melanoma cells, autocrine MIF-CD74 activates PI3K/AKT; blocking the interaction reduced AKT phosphorylation and suppressed xenograft tumour growth [PMID:26039541].","molecular_requirements":"The CD74 extracellular domain binds MIF; a membrane-truncated CD74 lacking it did not, and residues 109-149 appear important [PMID:12782713]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 9.0 x 10-9 M (about 9 nM)","assay":"surface plasmon resonance (BIAcore), MIF on chip, soluble CD74 extracellular domain","system":"recombinant proteins","cite":"PMID:12782713"}],"species_and_systems":"Human: COS-7 cells, THP-1 cells and recombinant protein [PMID:12782713]; human melanoma cell lines and a mouse xenograft model [PMID:26039541]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIF is flagged secreted [flag]; secreted MIF binds cell-surface CD74 in an autocrine manner [PMID:26039541].","caveats":"The melanoma paper's blockade used the inhibitor ISO-1 and was read with full text; its binding claim is indirect [PMID:26039541]. BioGRID, Reactome and UniProt records support the interaction [DB:BioGRID] [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"12782713","why":"Expression cloning, binding, SPR Kd of about 9 nM"},{"PMID":"26039541","why":"Autocrine MIF-CD74 drives AKT signalling in melanoma"}],"covers":["LR001904","LR005244"]},"LR001076":{"pair":"MMP7 -> CD44","headline":"CD44 heparan sulfate proteoglycan recruits MMP-7 into a surface complex with pro-HB-EGF; mouse knockout evidence, abstract only.","interaction_type":"functional only","direction_and_effect":"CD44HSPG recruits active MMP-7 and pro-HB-EGF into a surface complex; MMP-7 processes HB-EGF and the mature HB-EGF activates ErbB4 [PMID:11825873]. In CD44-/- mice MMP-7 localisation was altered and pro-HB-EGF processing and ErbB4 activation fell [PMID:11825873].","molecular_requirements":"The complex contains CD44HSPG, MMP-7, HB-EGF and ErbB4 [PMID:11825873].","affinity_potency":[],"species_and_systems":"Tumour cell lines, and mouse postpartum uterus and lactating mammary gland, with CD44-/- mice [PMID:11825873]. BioGRID records an Affinity Capture-Western from the same PMID [DB:BioGRID]; Reactome lists a CD44:MMP2, MMP7, MMP9 complex [DB:Reactome].","localisation_and_range":"CD44 is annotated both secreted and transmembrane [flag]; the paper describes a cell-surface complex [PMID:11825873].","caveats":"CD44 acts as a docking scaffold rather than a signalling receptor for MMP-7. Direct binding is not shown in the abstract. Abstract only. The human row is not ortholog-inferred, but the experiments were in mouse and tumour cell lines.","key_references":[{"PMID":"11825873","why":"CD44-/- mice and complex assembly of CD44 with MMP-7 and pro-HB-EGF"}],"covers":["LR001076","LR004488"]},"LR005252":{"pair":"Muc1 -> Siglece","headline":"Mouse pair projected from human MUC1-Siglec-9 work; the paper itself tested Siglec-9, not Siglec-E.","interaction_type":"functional only","direction_and_effect":"MUC1 carrying sialylated core 1 glycans (MUC1-ST) engaged Siglec-9 on monocytes and macrophages and induced activating signals (calcium flux, MEK-ERK) instead of SHP-1/SHP-2 recruitment [PMID:27595232].","molecular_requirements":"Binding depended on sialic acid (lost after neuraminidase treatment) and on the MUC1 backbone, since a multivalent sialylated core 1 polymer bound only weakly [PMID:27595232].","affinity_potency":[],"species_and_systems":"Experiments used human primary monocytes/macrophages, recombinant MUC1-ST and the T47D breast cancer line, with a Siglec-9 blocking antibody. The mouse Siglece pair is ortholog-inferred, not tested [PMID:27595232].","localisation_and_range":"Ligand is flagged secreted and receptor-capable [flag]; the paper used recombinant soluble MUC1-ST and cell-surface MUC1 on T47D [PMID:27595232].","caveats":"No Siglec-E data in our evidence. MUC1-ST also bound Siglecs-3, 7 and 10, with Siglec-9 the strongest [PMID:27595232]. The anti-Siglec-9 antibody can itself act as an activating antibody [PMID:27595232].","key_references":[{"PMID":"27595232","why":"MUC1-ST binds and signals through human Siglec-9 on myeloid cells"}],"covers":["LR005252"]},"LR001913":{"pair":"MYL9 -> CD69","headline":"Myl9 reported as a functional CD69 ligand in mouse asthma models and human nasal polyps; abstract-only.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are new functional ligands for CD69; blockade of the interaction ameliorated allergic airway inflammation [PMID:28783682]. Curator labels it agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse asthma models and human eosinophilic chronic rhinosinusitis nasal polyps; curator fields list human for this row, but the functional work in the abstract is in mouse [PMID:28783682].","localisation_and_range":"Ligand flagged secreted [flag]; platelet-derived Myl9/12 formed intravascular net-like structures with CD69+ cells nearby [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682].","key_references":[{"PMID":"28783682","why":"Myl9/12 as CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR001913","LR005253"]},"LR001085":{"pair":"MYOC -> FZD4","headline":"Myocilin-AP fusion bound FZD4 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. Two further judged rows were classed as a different entity.","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001085","LR004496"]},"LR006206":{"pair":"NCAN -> NCAM1","headline":"Neurocan binds NCAM1 directly in two full-text-supported papers, with a Kd of approximately 1 nM; the interaction is glycosaminoglycan-dependent.","interaction_type":"direct binding","direction_and_effect":"Neurocan binds NCAM and inhibits NCAM/EphA3 association and ephrin-A5-induced growth cone collapse [PMID:29670169]. Neurocan also inhibits neuronal adhesion and neurite outgrowth via NCAM-family binding [PMID:7513709].","molecular_requirements":"Neurocan binds the NCAM Ig2 domain, and binding is chondroitin-sulfate/GAG-dependent, though the core glycoprotein also has binding activity [PMID:29670169][PMID:7513709]. Polysialylated NCAM bound less efficiently than non-polysialylated NCAM [PMID:29670169].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"solid-phase 125I-neurocan binding, Scatchard analysis","system":"soluble neurocan on coated N-CAM microwells","cite":"PMID:7513709"}],"species_and_systems":"Recombinant human neurocan and NCAM-Fc pulldowns, mouse brain co-IP and HEK293T cells [PMID:29670169]. The 1994 binding assay used purified proteins; the species of the proteins is not reported in our evidence (the paper stains rat cerebellum) [PMID:7513709].","localisation_and_range":"Both entities carry a secreted flag [flag]; neurocan is a proteoglycan of the perineuronal net and neuronal surface, so it likely acts in the extracellular matrix near neurons [PMID:29670169].","caveats":"PMID:7513709 was read as abstract/excerpts only. BioGRID and Reactome also list this pair [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"29670169","why":"Full-text pulldowns with purified proteins, Ig2 domain mapping"},{"PMID":"7513709","why":"Scatchard affinity, GAG dependence"}],"covers":["LR002981","LR006206"]},"LR001922":{"pair":"NECTIN2 -> TIGIT","headline":"Direct, structurally characterised binding with weak affinity and inhibitory NK effect; human data.","interaction_type":"direct binding","direction_and_effect":"TIGIT, an inhibitory NK-cell receptor, binds Nectin-2 (PVRL2) and inhibits NK cytotoxicity directly through its ITIM; binds PVR and PVRL2 but not PVRL3 [PMID:19815499]. TIGIT binds the membrane-distal Ig domain of nectin-2 [PMID:28515320].","molecular_requirements":"Crystal structure of TIGIT with nectin-2 first Ig domain; an aromatic key of nectin-2 is critical and the C-C' loop dictates binding hierarchy [PMID:28515320]. TIGIT binding disrupts pre-assembled nectin-2 oligomers, so receptor-ligand and ligand-ligand association are mutually exclusive [PMID:28515320].","affinity_potency":[{"value":"Kd 6 \u03bcm","assay":"binding to nectin-2 Ig domain (assay named in abstract only as affinity; crystal structure also solved)","system":"human recombinant proteins","cite":"PMID:28515320"}],"species_and_systems":"Human ligand and receptor (recombinant protein, human NK cells) [PMID:28515320] [PMID:19815499]. Mouse pair is ortholog-projected.","localisation_and_range":"Both transmembrane by flag [flag]; cell-surface, contact-dependent [PMID:19815499].","caveats":"Both relevant papers read as abstracts only. Affinity is lower than TIGIT/necl-5 (3.2 \u03bcm) [PMID:28515320]. PMID 37542773 concerns nectin-4 and mentions nectin-2 only as a benchmark. Database records agree [DB:PDB 5V52] [DB:IntAct].","key_references":[{"PMID":"28515320","why":"Structure and 6 \u03bcm affinity of TIGIT-nectin-2"},{"PMID":"19815499","why":"TIGIT binds PVRL2 not PVRL3; inhibits NK cytotoxicity"}],"covers":["LR001922","LR005261"]},"LR005261":{"pair":"NECTIN2 -> TIGIT","headline":"Direct, structurally characterised binding with weak affinity and inhibitory NK effect; human data.","interaction_type":"direct binding","direction_and_effect":"TIGIT, an inhibitory NK-cell receptor, binds Nectin-2 (PVRL2) and inhibits NK cytotoxicity directly through its ITIM; binds PVR and PVRL2 but not PVRL3 [PMID:19815499]. TIGIT binds the membrane-distal Ig domain of nectin-2 [PMID:28515320].","molecular_requirements":"Crystal structure of TIGIT with nectin-2 first Ig domain; an aromatic key of nectin-2 is critical and the C-C' loop dictates binding hierarchy [PMID:28515320]. TIGIT binding disrupts pre-assembled nectin-2 oligomers, so receptor-ligand and ligand-ligand association are mutually exclusive [PMID:28515320].","affinity_potency":[{"value":"Kd 6 \u03bcm","assay":"binding to nectin-2 Ig domain (assay named in abstract only as affinity; crystal structure also solved)","system":"human recombinant proteins","cite":"PMID:28515320"}],"species_and_systems":"Human ligand and receptor (recombinant protein, human NK cells) [PMID:28515320] [PMID:19815499]. Mouse pair is ortholog-projected.","localisation_and_range":"Both transmembrane by flag [flag]; cell-surface, contact-dependent [PMID:19815499].","caveats":"Both relevant papers read as abstracts only. Affinity is lower than TIGIT/necl-5 (3.2 \u03bcm) [PMID:28515320]. PMID 37542773 concerns nectin-4 and mentions nectin-2 only as a benchmark. Database records agree [DB:PDB 5V52] [DB:IntAct].","key_references":[{"PMID":"28515320","why":"Structure and 6 \u03bcm affinity of TIGIT-nectin-2"},{"PMID":"19815499","why":"TIGIT binds PVRL2 not PVRL3; inhibits NK cytotoxicity"}],"covers":["LR001922","LR005261"]},"LR009113":{"pair":"NGF -> BEX3","headline":"Database-asserted only: Reactome lists NGF:p75NTR:NADE, with no paper supporting a direct NGF-BEX3 interaction.","interaction_type":"database-asserted only","direction_and_effect":"No papers were confirmed. Reactome records p75NTR binding NADE and an NGF:p75NTR:NADE complex [DB:Reactome]; effect direction is not reported in our evidence.","molecular_requirements":"BEX3 appears only as a downstream component of an NGF:p75NTR complex [DB:Reactome]; direct NGF binding is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"NGF is annotated secreted and not transmembrane [flag]; BEX3 localisation is not reported in our evidence.","caveats":"The pair rests on a complex record only; other judged papers were review only, abstract-insufficient or a different entity. It is likely a co-complex member rather than a ligand-receptor contact.","key_references":[],"covers":["LR009113"]},"LR009302":{"pair":"NGF -> KIDINS220","headline":"Database-asserted only: Reactome TrkA signalling complexes include KIDINS220 (ARMS); no confirming paper.","interaction_type":"database-asserted only","direction_and_effect":"No papers were confirmed. Reactome lists active TrkA receptor complexes containing ARMS [DB:Reactome]; the interaction is annotated stimulatory [flag].","molecular_requirements":"KIDINS220 appears as a component of active TrkA:ARMS:Crk complexes, not as a direct NGF binder [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"NGF is annotated secreted [flag]; KIDINS220 localisation is not reported in our evidence; Reactome places the complexes at the plasma membrane [DB:Reactome].","caveats":"No curator-verified paper; other judged papers were review only or abstract-insufficient. Likely an intracellular adaptor downstream of TrkA rather than a receptor for NGF.","key_references":[],"covers":["LR009302"]},"LR001094":{"pair":"NGF -> NTRK1","headline":"Well-supported direct NGF-TrkA interaction with a human crystal structure and extensive database records.","interaction_type":"direct binding","direction_and_effect":"NGF binds TrkA as a stimulatory ligand [flag]; the TrkA-d5 domain is described as necessary and sufficient for NGF binding [PMID:10490030]. UniProt calls NGF an extracellular ligand for NTRK1 and NGFR, and says NGF dimer binding induces NTRK1 homodimerisation [DB:UniProt].","molecular_requirements":"The NGF homodimer interacts with a single NTRK1 chain [DB:UniProt]. The structure shows two interface patches: the central beta-sheet with TrkA-d5 loops, and the NGF N-terminus packing against TrkA-d5 [PMID:10490030].","affinity_potency":[],"species_and_systems":"Human NGF with human TrkA-d5 crystal structure at 2.2 A resolution [PMID:10490030]; curator records human ligand and receptor for the Trk specificity paper, which used neuronal and nonneuronal cells [PMID:7679912]. Mouse pair is ortholog-inferred. Structures: PDB 1WWW, 2IFG [DB:PDB 1WWW].","localisation_and_range":"NGF annotated secreted and NTRK1 transmembrane [flag].","caveats":"All three papers were read as abstracts only. The sortilin paper states TrkA binding as background rather than showing it [PMID:14985763].","key_references":[{"PMID":"10490030","why":"Crystal structure of human NGF with TrkA-d5 at 2.2 A"},{"PMID":"7679912","why":"NGF is the preferred TrkA ligand in neuronal and non-neuronal cells"}],"covers":["LR001094","LR004505"]},"LR004505":{"pair":"NGF -> NTRK1","headline":"Well-supported direct NGF-TrkA interaction with a human crystal structure and extensive database records.","interaction_type":"direct binding","direction_and_effect":"NGF binds TrkA as a stimulatory ligand [flag]; the TrkA-d5 domain is described as necessary and sufficient for NGF binding [PMID:10490030]. UniProt calls NGF an extracellular ligand for NTRK1 and NGFR, and says NGF dimer binding induces NTRK1 homodimerisation [DB:UniProt].","molecular_requirements":"The NGF homodimer interacts with a single NTRK1 chain [DB:UniProt]. The structure shows two interface patches: the central beta-sheet with TrkA-d5 loops, and the NGF N-terminus packing against TrkA-d5 [PMID:10490030].","affinity_potency":[],"species_and_systems":"Human NGF with human TrkA-d5 crystal structure at 2.2 A resolution [PMID:10490030]; curator records human ligand and receptor for the Trk specificity paper, which used neuronal and nonneuronal cells [PMID:7679912]. Mouse pair is ortholog-inferred. Structures: PDB 1WWW, 2IFG [DB:PDB 1WWW].","localisation_and_range":"NGF annotated secreted and NTRK1 transmembrane [flag].","caveats":"All three papers were read as abstracts only. The sortilin paper states TrkA binding as background rather than showing it [PMID:14985763].","key_references":[{"PMID":"10490030","why":"Crystal structure of human NGF with TrkA-d5 at 2.2 A"},{"PMID":"7679912","why":"NGF is the preferred TrkA ligand in neuronal and non-neuronal cells"}],"covers":["LR001094","LR004505"]},"LR006215":{"pair":"NID2 -> LGR4","headline":"Nidogen-2 reported to bind LGR4 directly (Kd 26.77 nM) and protect against vascular calcification; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Nidogen-2 directly binds LGR4 with KD 26.77 nM; LGR4 deficiency abolishes the protective effect of nidogen-2 against VSMC calcification, and the abstract describes biased activation of LGR4-Galphaq-PKCalpha-AMPKalpha1 signalling [PMID:36354004]. The curator's effect label reads 'antagonist' while its note calls nidogen-2 a biased agonist; the functional readout is anti-calcification.","molecular_requirements":"LGR4 is required for the effect (its deficiency abolishes protection) [PMID:36354004]; co-receptors or subunits are not reported in our evidence.","affinity_potency":[{"value":"Kd 26.77 nM","assay":"binding after coimmunoprecipitation/interactome; the abstract lists SPR among its methods but does not tie it to this value","system":"purified nidogen-2 and VSMC membrane protein","cite":"PMID:36354004"}],"species_and_systems":"Curator lists human; the abstract also uses mouse models (three calcification models, Nidogen-2-/- mice) and VSMCs. Mouse pair is ortholog-projected [PMID:36354004].","localisation_and_range":"Nidogen-2 is a basement-membrane protein flagged secreted [flag]; the paper calls it a vascular extracellular matrix component, so action is local/paracrine in the matrix [PMID:36354004].","caveats":"Abstract only (truncated); the assay behind the Kd is not clearly stated. Effect label is inconsistent between curator fields.","key_references":[{"PMID":"36354004","why":"Direct binding Kd 26.77 nM and genetic LGR4 dependence"}],"covers":["LR002991","LR006215"]},"LR004514":{"pair":"NLGN1 -> NRXN2","headline":"Neuroligin-neurexin binding is reported for beta-neurexins as a class; NRXN2 is not individually resolved. Abstract-level.","interaction_type":"direct binding","direction_and_effect":"Binding studies show all three neuroligins bind beta-neurexins, as native brain and recombinant proteins [PMID:8576240]. Direction/effect on NRXN2 specifically is not reported in our evidence.","molecular_requirements":"Tight binding was seen only for beta-neurexins lacking an insert in splice site 4 [PMID:8576240].","affinity_potency":[],"species_and_systems":"Species unspecified in the dossier for this row [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists NRXN2-NLGN1 as a reconstituted complex [DB:BioGRID].","caveats":"The paper reports 'beta-neurexins' as a class, so NRXN2 is not individually shown. Abstract only; two further papers were abstract-insufficient. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"}],"covers":["LR001103","LR004514"]},"LR004523":{"pair":"NMB -> NMBR","headline":"Well-supported direct agonist-receptor pair: radioligand binding and signalling in human cells, plus mutagenesis and antisense work.","interaction_type":"direct binding","direction_and_effect":"NMB acts as an agonist: it stimulates inositol phosphate formation in cells expressing human NMBR [PMID:7838118], and NMBR antisense blocks NMB-induced colonic smooth muscle contraction [PMID:8253343].","molecular_requirements":"Single receptor chain; no co-receptor reported in our evidence. Ile216 in transmembrane domain V is critical for high-affinity NMB binding [PMID:8392057].","affinity_potency":[{"value":"Ki = 8.1 +/- 5.2 nM","assay":"agonist competition binding","system":"human NMBR in BALB/3T3 fibroblasts","cite":"PMID:7838118"},{"value":"EC50 = 9.3 +/- 1.4 nM","assay":"[3H]inositol phosphate generation","system":"human NMBR in BALB/3T3 fibroblasts","cite":"PMID:7838118"},{"value":"IC50 0.052-0.054 nM","assay":"radioligand competition binding (as stated in full-text excerpt: 'high affinity (i.e. 0.052-0.054 nM)')","system":"hNMBR-containing human cell lines","cite":"PMID:21729729"}],"species_and_systems":"Experiments are mainly human receptors in transfected or cancer cell lines [PMID:7838118][PMID:21729729]; human and rabbit colon smooth muscle for antisense [PMID:8253343]; Xenopus oocytes for cloned receptor [PMID:1655761]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMB is flagged secreted and NMBR transmembrane [flag], so paracrine signalling is likely; the papers do not address range.","caveats":"Most papers were read as abstracts only; only PMID:21729729 was read in full. PMID:10454496 supports competitive binding of an antagonist with NMB, not NMB affinity itself. The mouse entry has no experiments of its own in our evidence.","key_references":[{"PMID":"7838118","why":"Human NMBR affinity and EC50 for NMB, with ~600-fold selectivity over GRP"},{"PMID":"21729729","why":"Full-text human binding data for NMB at hNMBR cell lines"},{"PMID":"8392057","why":"Mutagenesis: Ile216 in TM-V needed for high-affinity binding"}],"covers":["LR001112","LR004523"]},"LR011750":{"pair":"NODAL -> ACVR1B:ACVR2A:CRIPTO","headline":"No curator-verified papers; support is database annotation only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states cell-associated CRIPTO acts as a Nodal coreceptor in cis [DB:UniProt]; BioGRID lists reconstituted complexes of NODAL with TDGF1 and ACVR2A [DB:BioGRID].","molecular_requirements":"Includes the co-receptor CRIPTO plus ACVR1B and ACVR2A by the row definition; individual subunit evidence is not shown.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Nodal flagged secreted [flag]; CRIPTO described as cell-associated and acting in cis [DB:UniProt].","caveats":"Two papers are still pending curation; nothing experimental is verified for this row.","key_references":[],"covers":["LR011750"]},"LR004541":{"pair":"NPPB -> NPR2","headline":"BNP activates NPR2 (ANP-B receptor) preferentially over ANP in one 1989 study using porcine BNP.","interaction_type":"functional only","direction_and_effect":"The cloned human ANP-B receptor is preferentially activated by porcine BNP rather than human alpha-ANP [PMID:2570358].","molecular_requirements":"Receptor-only guanylate cyclase; no further requirements reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor, porcine BNP, abstract-only [PMID:2570358]. Human BNP not tested in the evidence shown. BioGRID reconstituted complex records [DB:BioGRID].","localisation_and_range":"Not reported beyond annotation; BNP is flagged secreted [flag].","caveats":"Single abstract-only paper with porcine ligand; no affinity given. Other evidence is BioGRID only.","key_references":[{"PMID":"2570358","why":"Cloning of ANP-B receptor with BNP preference"}],"covers":["LR001131","LR004541"]},"LR006224":{"pair":"NPTX2 -> NPTXR","headline":"NPTXR is enriched on NP2 affinity columns; one abstract-level paper, no databases.","interaction_type":"direct binding","direction_and_effect":"NPR (NPTXR) was enriched by affinity chromatography on columns of NP2, NP1 and a toxin [PMID:9261167]. Direction or effect not reported in our evidence.","molecular_requirements":"NPTXR has a putative N-terminal transmembrane domain and is glycosylated; NPR shares 48% identity with NP2 [PMID:9261167].","affinity_potency":[],"species_and_systems":"Affinity chromatography; species not stated in dossier [PMID:9261167]. Human pair is not ortholog-inferred; mouse is.","localisation_and_range":"NPTXR is a putative integral membrane pentraxin [PMID:9261167]; NPTX2 annotated secreted [flag].","caveats":"Single abstract-only paper; association rather than measured affinity. Two further papers were abstract-insufficient.","key_references":[{"PMID":"9261167","why":"Identification of NPR as NP2-binding protein"}],"covers":["LR003000","LR006224"]},"LR001139":{"pair":"NPW -> NPBWR2","headline":"NPW activates NPBWR2 (GPR8) at sub-nanomolar potency; three binding/activation papers, abstract level.","interaction_type":"direct binding","direction_and_effect":"NPW is an agonist of NPBWR2: NPW23/NPW30 activated and bound GPR7 and GPR8 [PMID:12130646]; human NPW activates GPR8 with EC50 0.51 nM [PMID:12719537]; GtoPdb lists a full agonist [DB:GtoPdb]. Binding inhibited forskolin-stimulated cAMP via pertussis-toxin-sensitive signalling [PMID:12401809].","molecular_requirements":"Single receptor chain; both mature forms bind [PMID:12130646]. No co-receptor reported.","affinity_potency":[{"value":"EC50 0.51 nM","assay":"binding and activation by synthetic human NPW","system":"human GPR8","cite":"PMID:12719537"},{"value":"pIC50 9.6","assay":"curator-recorded affinity for L7/L8 peptides","system":"CHO-K1, human receptors","cite":"PMID:12401809"}],"species_and_systems":"Human receptors in CHO cells; porcine-purified ligand in one paper [PMID:12130646]; human peptides in the others [PMID:12719537][PMID:12401809]. Only a human pair is listed.","localisation_and_range":"NPW is flagged secreted and NPBWR2 transmembrane [flag]; range is inferred from flags only.","caveats":"All papers read as abstracts only. NPW is essentially non-selective between GPR7 and GPR8 [PMID:12719537]. The pIC50 is curator-recorded, not in the abstract.","key_references":[{"PMID":"12719537","why":"Human NPW EC50 0.51 nM at GPR8"},{"PMID":"12130646","why":"NPW identified as ligand of GPR7 and GPR8"},{"PMID":"12401809","why":"Low nanomolar binding at GPR7/GPR8 in CHO-K1"}],"covers":["LR001139"]},"LR004550":{"pair":"NPY -> NPY1R","headline":"NPY is a well-supported agonist of NPY1R, with cryo-EM structure, many database records and one binding paper.","interaction_type":"direct binding","direction_and_effect":"NPY is an agonist of Y1. A cryo-EM structure of NPY-bound Y1 has been reported [PMID:35165283]; NPY displays highest affinities for Y1, Y2 and Y5 subtypes [PMID:15966750]; GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor needed according to the structure listing, with several PDB entries (7VGX, 7X9A, 8K6M, 8K6O) [DB:PDB 7VGX].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers [PMID:35165283][PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY1R transmembrane [flag].","caveats":"Both papers were read as abstract only, and the structure abstract is truncated. The binding paper gives only a qualitative selectivity statement [PMID:15966750]. NPY also binds other Y receptors; no affinity number for Y1 appears in our evidence.","key_references":[{"PMID":"35165283","why":"Cryo-EM structure of NPY-bound Y1"},{"PMID":"15966750","why":"NPY highest affinities at Y1, Y2, Y5"}],"covers":["LR001141","LR004550"]},"LR001148":{"pair":"NRG1 -> ERBB4","headline":"NRG1 binds and activates ERBB4 directly; supported by several abstract-level binding studies and database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: heregulin activates ErbB4; all mutants tested induced ERBB4 phosphorylation and MAPK activation [PMID:9565587]. Region 177-226 of heregulin beta is sufficient for binding and receptor phosphorylation [PMID:7721889]. NRG-1 binding to ErbB-4 was displaceable by NRG-4 [PMID:10348342].","molecular_requirements":"Wild-type phage-displayed HRGbeta EGF domain bound ErbB4-IgG; binding was affected by mutation of residues throughout the EGF domain, and ErbB4 appeared less stringent than ErbB3 [PMID:9565587]. Single-molecule imaging examined ErbB3/B4 on MCF-7 cells [PMID:22891299]. ERBB4 can bind alone; ERBB2 is not required in the evidence shown.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; phage display, receptor-IgG fusions, synthetic peptides, MCF-7 cells. The mouse pair is projected from human evidence.","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag]; not tested in the papers.","caveats":"All shown papers were abstract-only reads, and 6 further papers were judged abstract_insufficient. The single-molecule paper analyses ErbB3/B4 together, so its ERBB4-specific contribution is not separated [PMID:22891299]. PMID 10995872 is background framing. No affinity for ERBB4 is quoted in our evidence; GtoPdb lists pKd and pIC50 records without values [DB:GtoPdb].","key_references":[{"PMID":"9565587","why":"HRGbeta EGF domain binds ErbB4-IgG and activates ERBB4"},{"PMID":"7721889","why":"Heregulin beta 177-226 sufficient for binding"},{"PMID":"22891299","why":"Single-molecule HRG kinetics on ErbB3/B4 in live cells"}],"covers":["LR001148","LR004557"]},"LR006233":{"pair":"NRG3 -> ERBB2","headline":"NRG3 activates ERBB2 only when co-expressed with ERBB3, from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"NRG-3 activated erbB2 and erbB3 when expressed together, an agonist effect [PMID:9772300].","molecular_requirements":"ERBB2 is not shown to respond alone; activation required erbB3 co-expression [PMID:9772300]. In scoring, ERBB2 should be treated as a heterodimer partner, not a standalone receptor.","affinity_potency":[],"species_and_systems":"Human breast cancer cells and transfected 32D cells [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; activation not binding; no affinity. Direct binding to ERBB2 is not shown in our evidence.","key_references":[{"PMID":"9772300","why":"erbB2 and erbB3 activated together by NRG-3"}],"covers":["LR003009","LR006233"]},"LR010940":{"pair":"NRP1 -> KDR","headline":"NRP1 and KDR form a VEGF165-dependent complex; evidence conflicts on whether it raises VEGF165 binding.","interaction_type":"conflicting","direction_and_effect":"VEGF165 bridges NRP1 and KDR: an NRP1-KDR complex was immunoprecipitated from endothelial cells only with VEGF165, not VEGF121 [PMID:11948691]. The complex potentiates VEGF165 signalling potency [PMID:11333271].","molecular_requirements":"Requires VEGF165 as bridge; KDR and NRP1 on the same cell or on neighbouring cells; soluble NRP1 dimer bound KDR-only cells in a VEGF165-dependent way [PMID:11948691].","affinity_potency":[],"species_and_systems":"Endothelial cells, co-culture with NRP1-expressing breast carcinoma cells [PMID:11948691]; species not stated in abstracts.","localisation_and_range":"Complexes also form in a juxtacrine manner via tumour-cell NRP1 and endothelial KDR [PMID:11948691]. NRP1 is annotated secreted and transmembrane [flag].","caveats":"One paper says the complex markedly increased 125I-VEGF165 binding to KDR [PMID:11948691]; another finds no increase in VEGF165 binding affinity and proposes receptor clustering [PMID:11333271]. Both abstract only. 7 papers were abstract_insufficient. NRP1 is a co-receptor, not a free ligand.","key_references":[{"PMID":"11948691","why":"VEGF165-dependent NRP1-KDR ternary complex"},{"PMID":"11333271","why":"NRP1-KDR complex, no affinity increase, clustering role"}],"covers":["LR010940"]},"LR012434":{"pair":"NRP2 -> FLT4:KDR","headline":"NRP2 with FLT4:KDR: one abstract reports NRP2-VEGFR2 only; FLT4 has no support.","interaction_type":"functional only","direction_and_effect":"NRP2 physically interacts with VEGFR2 (KDR) through the intracellular SEA domain to activate STAT3 and SOX2 [PMID:35986103].","molecular_requirements":"Only KDR is supported; FLT4 is not mentioned and no database record is present.","affinity_potency":[],"species_and_systems":"Prostate cancer cells; species not stated in the abstract [PMID:35986103].","localisation_and_range":"Transmembrane receptor-receptor association [flag].","caveats":"Abstract only; no affinity; 2 papers different_entity, 3 abstract_insufficient. FLT4 member unsupported.","key_references":[{"PMID":"35986103","why":"NRP2 interacts with VEGFR2"}],"covers":["LR012434"]},"LR006242":{"pair":"NRXN1 -> LRRTM1","headline":"Neurexin binding code reported conserved in LRRTM1 and functional in a coculture assay; abstract only.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexin-1beta lacking an insert at splice site 4; the authors further show this binding code is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Binding depends on neurexin splice site 4: LRRTM2 binds neurexins 1, 2, 3 alpha and beta variants lacking an insert at SS4; LRRTM1 is said to share this code [PMID:20519524].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; mouse and human pairs are ortholog-inferred.","localisation_and_range":"Both are transmembrane [flag]; trans-synaptic hemisynapse assay.","caveats":"Abstract only. The LRRTM1 result is stated briefly; details of the assay and affinity are not in our evidence. Biochemical characterisation was mainly for LRRTM2.","key_references":[{"PMID":"20519524","why":"LRRTM2 neurexin binding code conserved in LRRTM1"}],"covers":["LR003018","LR006242"]},"LR006251":{"pair":"NRXN2 -> LRRTM2","headline":"Direct neurexin-LRRTM2 binding is shown, but the full-text paper names neurexins generically; NRXN2 specifically is not pinned down.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds alpha- and beta-neurexins directly in cell-surface labeling assays and mediates cell adhesion in a trans-interaction [PMID:20064387]. Ca2+-dependent binding [PMID:20064387].","molecular_requirements":"Binding requires neurexins lacking an insert in splice site #4; Ca2+ dependent [PMID:20064387]. LRRTM2 and neuroligin-1 cannot bind neurexin-1beta simultaneously [PMID:20064387].","affinity_potency":[],"species_and_systems":"Recombinant Ig-fusions in HEK293/HEK293T cells and rat brain affinity chromatography [PMID:20064387]. The dossier covers human and mouse pairs; the human pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as transmembrane, non-secreted [flag], so contact-dependent (juxtacrine/trans-synaptic) signalling is implied; the paper shows trans cell adhesion [PMID:20064387].","caveats":"The only verified paper tests neurexins generically (neurexin-1 alpha/beta in binding; excerpts do not show NRXN2 binding); two further papers were judged abstract-insufficient. The curator note says the sentence names neurexins generically and that all three beta-neurexins bound [PMID:20064387].","key_references":[{"PMID":"20064387","why":"Direct neurexin-LRRTM2 binding and trans cell adhesion"}],"covers":["LR003027","LR006251"]},"LR003029":{"pair":"NRXN3 -> CLSTN3","headline":"Beta-neurexins bind Clstn3 directly according to one abstract-only paper; NRXN3 specifically is not named.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns directly interact via their LNS domain with Clstn3 and its cadherin domains [PMID:32434929]. Clstn3 synaptogenic activity depended on SS4-positive beta-Nrxn variants [PMID:32434929].","molecular_requirements":"SS4 insert-positive Nrxns are required; insert-negative variants do not rescue [PMID:32434929].","affinity_potency":[],"species_and_systems":"Experiment species unspecified; neuron cultures, conditional knockout mice and hippocampal slices described in abstract [PMID:32434929]. Mouse pair is non-inferred.","localisation_and_range":"Both flagged transmembrane, non-secreted [flag]; Clstn3 is described as a postsynaptic adhesion molecule acting via presynaptic neurexins [PMID:32434929].","caveats":"Abstract only; Nrxn paralogue (NRXN3) is not named. The abstract notes that direct binding had been a matter of debate [PMID:32434929].","key_references":[{"PMID":"32434929","why":"Beta-Nrxn LNS domain directly binds Clstn3, SS4-dependent"}],"covers":["LR003029","LR006253"]},"LR008501":{"pair":"NRXN3 -> NLGN3","headline":"Rat brain affinity data show all neuroligins bind all three neurexins; NRXN3 is named, though the source was read in a browser and is unverified.","interaction_type":"direct binding","direction_and_effect":"All neuroligins bound preferentially to beta-neurexins lacking an insert, and all bound to all three neurexins [PMID:8576240]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Preference for beta-neurexins lacking a splice-site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat brain proteins on immobilised beta-neurexin-IgG, immunoblot with neuroligin antibodies [PMID:8576240].","localisation_and_range":"Both flagged transmembrane, non-secreted [flag].","caveats":"Curator notes the browser-read quote is unverifiable and a spot-check is pending; the abstract only mentions binding of neuroligins to beta-neurexins [PMID:8576240].","key_references":[{"PMID":"8576240","why":"Neuroligins 1-3 bind neurexins, splice-site dependent"}],"covers":["LR008501"]},"LR001157":{"pair":"NTF3 -> NTRK1","headline":"NT-3 is a lower-affinity heterologous ligand of TrkA with agonist and partly antagonistic character; abstract-only support.","interaction_type":"direct binding","direction_and_effect":"NT-3 binds TrkA as a lower affinity heterologous ligand [PMID:17439940]. Docking on both site 1 (D5) and site 2 (D4) gives full agonism, additive with NGF; site 1 alone is partially agonistic but noncompetitively antagonizes NGF binding [PMID:17439940].","molecular_requirements":"Two TrkA extracellular sites: D5 hot spot (site 1) and D4 (site 2) [PMID:17439940].","affinity_potency":[],"species_and_systems":"Binding studies with truncated and chimeric human TrkA extracellular subdomains plus survival assays [PMID:17439940]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK1 transmembrane [flag].","caveats":"Abstract only; no numeric affinity reported. One review-only row is not shown. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"17439940","why":"TrkA D5 and D4 docking sites for NT-3"}],"covers":["LR001157","LR004566"]},"LR001166":{"pair":"NTN1 -> UNC5B","headline":"Netrin-1 to UNC5B has binding and functional support, but only from abstracts; strongest are a 1997 binding study and a 2026 co-IP.","interaction_type":"direct binding","direction_and_effect":"UNC5 homologues were shown to be netrin-binding proteins [PMID:9126742]. Co-immunoprecipitation validated a Netrin-1-UNC5B interaction in NCI-H1299 lung cancer cells, linked to UNC5B-PI3K signalling and epithelial-mesenchymal transition [PMID:42284640].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cloned UNC-5 homologues [PMID:9126742]; NCI-H1299 NSCLC cells and xenograft [PMID:42284640]. Also IntAct co-immunoprecipitation and avexis records and Reactome [DB:IntAct][DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5B is transmembrane [flag].","caveats":"Both papers read as abstracts only. The 1997 abstract does not name UNC5B specifically. The 2026 paper is an eupatilin pharmacology study where the interaction is a supporting experiment, and its abstract is truncated [PMID:42284640].","key_references":[{"PMID":"9126742","why":"UNC-5 homologues as netrin-binding proteins"},{"PMID":"42284640","why":"Co-IP of Netrin-1 with UNC5B in NSCLC cells"}],"covers":["LR001166","LR004575"]},"LR006260":{"pair":"NTN3 -> UNC5A","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5A is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred and the mouse pair too [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003036","LR006260"]},"LR003038":{"pair":"NTN3 -> UNC5C","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5C is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003038","LR006262"]},"LR001175":{"pair":"NTS -> NTSR2","headline":"Neurotensin binds NTSR2 but evidence conflicts on effect: one paper reports no signalling and functional antagonism, while databases say agonist.","interaction_type":"conflicting","direction_and_effect":"In human NT2 receptor expressed in CHO cells, neurotensin binding did not elicit a second-messenger response and antagonised the agonist activity of SR48692 and SR142948A [PMID:9851594]. GtoPdb nevertheless lists an agonist record [DB:GtoPdb], and the interaction carries a 'Stimulatory' annotation. Mouse NTRL (NTSR2) internalised iodinated neurotensin, followed by recycling, without detectable adenylate cyclase, guanylate cyclase or phospholipase C modulation [PMID:9480852]. Neurotensin binding triggers internalisation of NTR2 [PMID:11801734].","molecular_requirements":"Single receptor chain, no co-receptor reported. Mouse NTR2 recycling depends on tyrosine 237 in the third intracellular loop, where human NTR2 has a cysteine and does not recycle [PMID:11801734].","affinity_potency":[{"value":"IC50 0.49 nm","assay":"competition binding, neurotensin","system":"NTR2 (species not stated in our excerpt)","cite":"PMID:16087676"}],"species_and_systems":"Human receptor in CHO cells [PMID:9851594]; mouse receptor in HEK293 [PMID:9480852]; mouse/human/rat receptors in trafficking study [PMID:11801734]. The mouse pair is ortholog-inferred.","localisation_and_range":"Neuropeptide flagged secreted [flag]; receptor is a membrane GPCR.","caveats":"Effect direction is unresolved: antagonism or inactivity in [PMID:9851594] and [PMID:9480852] versus agonist labels in GtoPdb and the curated rows. PMID:16087676 binding quote was browser-read and its spot-check is pending, and the same paper's abstract says SK-N-SH cells lack NTR2. PMID:9480852's evidence sentence is just the title. Species differences in recycling matter.","key_references":[{"PMID":"9851594","why":"Human NT2 receptor binds neurotensin without signalling and neurotensin antagonises SR compounds"},{"PMID":"9480852","why":"Mouse NTSR2 binding, internalisation and recycling"},{"PMID":"11801734","why":"Species difference in NTR2 recycling"}],"covers":["LR001175","LR004584"]},"LR003047":{"pair":"OMG -> PTPRU","headline":"OMG binds PTPRU with a KD of ~70 nM by SPR; PTPRU was the top hit of the OMG CRISPRa screen.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRU the receptor. In the paper's OMG CRISPRa screen PTPRU was the top-ranking hit with a positive enrichment trajectory over all three selection rounds, and binding was confirmed by SPR [PMID:36178190]. Effect on PTPRU activity is not reported in our evidence.","molecular_requirements":"PTPRU ectodomain alone was sufficient for SPR binding; among R2B RPTPs only PTPRU bound OMG [PMID:36178190].","affinity_potency":[{"value":"KD ~70 nM","assay":"SPR, 1:1 binding model","system":"recombinant human PTPRU-ECD and human OMG","cite":"PMID:36178190"}],"species_and_systems":"Human proteins, cell-based CRISPRa screen plus SPR [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. The PTPRU entity has a receptor flag only, no transmembrane or secreted flag [flag].","caveats":"Single paper, no independent confirmation, no database records. Quoted KD is approximate.","key_references":[{"PMID":"36178190","why":"Screen hit and SPR KD for OMG-PTPRU"}],"covers":["LR003047","LR006271"]},"LR001193":{"pair":"OXT -> OXTR","headline":"Oxytocin is the cognate agonist of OXTR, with nanomolar binding and functional responses in human recombinant systems; many confirmations.","interaction_type":"direct binding","direction_and_effect":"OXT binds the oxytocin receptor with high affinity and stimulates inositol phosphate accumulation (EC50 = 4.1 nM) in 293 cells [PMID:7475979]. Expression-cloned human OXTR in Xenopus oocytes specifically responds to oxytocin with an inward current [PMID:1313946]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single GPCR chain; coupling to G protein shown by guanine nucleotide sensitivity of agonist affinity [PMID:7475979]. Co-receptor requirement not reported.","affinity_potency":[{"value":"Kd 0.32nM","assay":"[3H]OT saturation binding","system":"human OXTR stably expressed in 293 cells","cite":"PMID:7475979"},{"value":"Ki in mean = 6.8 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"EC50 = 4.1 nM","assay":"inositol phosphate accumulation","system":"293/OTR cells","cite":"PMID:7475979"}],"species_and_systems":"Human receptor in 293 cells, CHO cells and Xenopus oocytes; human and rat receptor in one paper [PMID:12660315]. Mouse pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted and OXTR a transmembrane receptor [flag].","caveats":"All papers are abstract only. Several (PMID:16158071, PMID:12660315) use OXT only as background to characterise other compounds. PMID:10698266 is computational modelling, not experimental. PDB 7QVM and 7RYC contain chains of OXT and OXTR [DB:PDB].","key_references":[{"PMID":"7475979","why":"Kd and signalling of OT at cloned human OXTR"},{"PMID":"1313946","why":"expression cloning, oxytocin-specific response"},{"PMID":"10519430","why":"competition Ki, OXTR versus V1a"}],"covers":["LR001193","LR004602"]},"LR009041":{"pair":"P4HB -> MTTP","headline":"P4HB (PDI) and MTTP form a stable heterodimer; this is a protein-complex subunit relationship, not a signalling ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states MTTP heterodimerizes with P4HB/PDI [DB:UniProt]. No signalling direction or effect is reported in our evidence.","molecular_requirements":"P4HB is a subunit of the MTTP:PDI:lipid complex in the ER lumen [DB:Reactome R-HSA-174681]; structures contain chains of both [DB:PDB 6I7S] [DB:PDB 8EOJ].","affinity_potency":[],"species_and_systems":"BioGRID lists Affinity Capture-Western [DB:BioGRID]; species of experiments not reported in our evidence.","localisation_and_range":"Both partners act in the endoplasmic reticulum lumen per Reactome [DB:Reactome R-HSA-174681]; P4HB is flagged non-receptor and non-transmembrane [flag].","caveats":"No papers supported the pair; the one judged row was a different entity. Support rests on databases only.","key_references":[],"covers":["LR009041"]},"LR003065":{"pair":"PCDHGA10 -> PCDHGA10","headline":"Mouse Pcdhga10 is homophilic in K562 aggregation assays; the only confirming paper was read via browser.","interaction_type":"functional only","direction_and_effect":"Seven \u03b3-Pcdh isoforms including A10 showed highly specific, strictly homophilic interaction in K562 quantitative and microscopic aggregation assays [PMID:20679223].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 cells [PMID:20679223]; human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Curator note marks the quote as unverifiable with spot-check pending; two other papers were abstract_insufficient. Isoform-specific; paralogs cannot substitute.","key_references":[{"PMID":"20679223","why":"homophilic aggregation of seven gamma-Pcdh isoforms"}],"covers":["LR003065","LR006288"]},"LR003074":{"pair":"PCDHGA8 -> PCDHGA8","headline":"Mouse Pcdhga8 binds itself in trans (aggregation and SPR) with strict specificity versus \u03b3A9.","interaction_type":"direct binding","direction_and_effect":"\u03b3A8 and \u03b3A9 do not engage in heterophilic interactions despite 91-97% identity in EC2-EC3 [PMID:25171406]; mutations disrupting the \u03b3A8 trans interface inhibited homophilic binding [PMID:35253643].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse proteins in K562 aggregation and SPR of EC1-4 fragments [PMID:25171406] [PMID:35253643]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. No heterophilic binding for \u03b3A8/9 with a lower limit KD of ~200 \u03bcM [PMID:35253643].","key_references":[{"PMID":"25171406","why":"homophilic specificity"},{"PMID":"35253643","why":"trans-interface mutagenesis by SPR"}],"covers":["LR003074","LR006297"]},"LR006305":{"pair":"PCDHGC3 -> PCDHGC3","headline":"Mouse gammaC3 shows homophilic binding in K562 assays across two papers; one is abstract-only.","interaction_type":"direct binding","direction_and_effect":"Homophilic interaction of the C-type isoform gammaC3 [PMID:25171406]; strictly homophilic trans interaction across seven gamma isoforms including C3 [PMID:20679223]. No agonist/antagonist effect reported.","molecular_requirements":"gammaC3 was detected at the cell surface when tagged [PMID:25171406]. Specificity is mediated by EC2-EC3 and gamma-Pcdhs form cis multimers [PMID:20679223].","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 aggregation assays [PMID:25171406][PMID:20679223]; human pair ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. The PNAS paper is abstract-only with an unverified browser-read quote [PMID:20679223].","key_references":[{"PMID":"25171406","why":"Names gammaC3 as homophilic and surface-detected."},{"PMID":"20679223","why":"Strictly homophilic trans interaction of gamma-Pcdh isoforms incl. C3."}],"covers":["LR003082","LR006305"]},"LR003083":{"pair":"PCDHGC5 -> PCDHGC5","headline":"Mouse gammaC5 forms aggregates in K562 cells, indicating homophilic binding; single full-text paper.","interaction_type":"functional only","direction_and_effect":"gammaC5 forms cell aggregates when assayed individually, consistent with homophilic trans interaction [PMID:25171406]. No agonist/antagonist effect reported.","molecular_requirements":"Not reported in our evidence beyond the family-level need for cis partners for Pcdh-alpha delivery [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse proteins, K562 cell aggregation assay [PMID:25171406]; human pair by orthology.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. Evidence is an aggregation readout, not direct binding measurement. Four other papers were abstract-insufficient.","key_references":[{"PMID":"25171406","why":"Systematic aggregation of 58 Pcdhs; gammaC5 aggregates."}],"covers":["LR003083","LR006306"]},"LR001931":{"pair":"PCNA -> NCR2","headline":"PCNA binds NKp44 directly (SPR, KD 3.4 nM) and inhibits NK function, though PCNA is normally intracellular.","interaction_type":"direct binding","direction_and_effect":"NKp44 recognises PCNA and the interaction inhibits NK cell function via the NKp44 ITIM, so PCNA acts as an inhibitory ligand (antagonist direction) [PMID:22021614]. PCNA-overexpressing HeLa cells reduced IFN-gamma secretion and lysis by NKp44-high NK cells [PMID:22021614].","molecular_requirements":"NKp44-Ig bound PCNA; NKp30, NKp46, NKG2D, LIR1 and KIR2DL4 bound only marginally [PMID:22021614]. Target-cell PCNA must be recruited to the NK immunological synapse for physical interaction [PMID:22021614].","affinity_potency":[{"value":"KD = 3.4 \u00d7 10\u22129 M","assay":"surface plasmon resonance, NKp44-Ig vs immobilised PCNA","system":"recombinant human proteins","cite":"PMID:22021614"}],"species_and_systems":"Human recombinant proteins, HeLa/HEK293 lysates, transfected BW cells, human NK cells and NK-92 lines [PMID:22021614].","localisation_and_range":"PCNA is annotated non-secreted [flag]; it is made accessible to the surface receptor by relocation to the synapse, so signalling is by cell contact [PMID:22021614].","caveats":"Abstract-level curation but full-text excerpts support it. The excerpt notes the negative control also bound recombinant NKp44 considerably (data not shown) [PMID:22021614]. IntAct lists one record from the same paper [DB:IntAct].","key_references":[{"PMID":"22021614","why":"Direct binding by ELISA, pulldown, SPR and cell assays; inhibitory function."}],"covers":["LR001931"]},"LR005270":{"pair":"PDCD1LG2 -> PDCD1","headline":"PD-L2 binds PD-1 (SPR, crystal structure); a separate paper shows an additional PD-1-independent PD-L2 receptor.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds PD-1 with affinity comparable to PD-L1 but different kinetics; PD-L1 and PD-L2 compete for PD-1, and an antagonist PD-1 mAb blocks both and enhances T-cell proliferation [PMID:20587542]. A crystal structure of the human PD-1/PD-L2 complex exists [PMID:31727844]. In mouse tumour work B7DC promoted CD8 T-cell tumour rejection [PMID:12810690].","molecular_requirements":"Not reported in our evidence. The structure used a high-affinity triple-mutant PD-1, and PD-L2 binding forms a pocket in PD-1 [PMID:31727844].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells (SPR, structure) [PMID:20587542][PMID:31727844]; mouse tumour and PD-1-knockout T-cell experiments [PMID:12810690]; mouse pair listed as not ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted [flag]; the interaction is between membrane proteins in the cited work.","caveats":"The structure is of a triple-mutant PD-1 [PMID:31727844]. PMID 12810690 shows B7DC binds PD-1-deficient cells and enhances killing through a PD-1-independent route, implying another receptor; PD-1 interaction there is background [PMID:12810690]. All papers abstract-only.","key_references":[{"PMID":"20587542","why":"SPR kinetics of PD-L1 and PD-L2 binding to PD-1."},{"PMID":"31727844","why":"Crystal structure of human PD-1/PD-L2 complex."},{"PMID":"12810690","why":"Shows non-PD-1 receptor for B7DC (caveat)."}],"covers":["LR001932","LR005270"]},"LR004604":{"pair":"PDGFB -> LRP1","headline":"PDGF-BB binds purified LRP1 by SPR; LRP1 acts as a co-receptor rather than the main PDGF receptor.","interaction_type":"direct binding","direction_and_effect":"Only PDGF, not bFGF, EGF or IGF-1, bound purified LRP on a sensor chip; PDGF-BB induced transient Src-dependent phosphorylation of the LRP cytoplasmic domain at the second NPXY motif and recruited Shc [PMID:11854294]. UniProt lists the PDGFB-LRP1 interaction [DB:UniProt].","molecular_requirements":"LRP1 modulates PDGF receptor signalling as a co-receptor, so it likely functions alongside PDGF receptors [PMID:11854294].","affinity_potency":[],"species_and_systems":"Human proteins, SPR with purified LRP [PMID:11854294]; mouse pair ortholog-inferred.","localisation_and_range":"PDGFB annotated secreted [flag].","caveats":"Abstract only; no affinity reported in our evidence. BioGRID records the same paper [DB:BioGRID].","key_references":[{"PMID":"11854294","why":"SPR of PDGF binding to purified LRP with negative controls."}],"covers":["LR001195","LR004604"]},"LR006314":{"pair":"PECAM1 -> ITGAV","headline":"CD31 is a ligand for integrin alpha v beta 3 in human leukocyte adhesion and precipitation experiments.","interaction_type":"direct binding","direction_and_effect":"Soluble recombinant CD31 supports leukocyte adhesion through its second Ig-like domain, blocked by alpha v beta 3-specific antibodies, and precipitated alpha v beta 3 from cell lysates [PMID:7542249]. Reactome has an integrin alphaVbeta3:PECAM1 complex [DB:Reactome].","molecular_requirements":"The receptor is the alpha v beta 3 heterodimer; ITGAV is one chain, so the beta3 chain is also needed [PMID:7542249]. CD31 Ig domain 2 mediates binding [PMID:7542249].","affinity_potency":[],"species_and_systems":"Human leukocytes and LAK cell lysates; abstract and some full text [PMID:7542249]. BioGRID lists only co-localization with ITGB3 [DB:BioGRID].","localisation_and_range":"PECAM1 is a membrane protein [flag]; used as soluble recombinant in the assay, natural interaction is cell-surface contact [PMID:7542249].","caveats":"No affinity in our evidence. Human pair is ortholog-inferred. ITGAV alone is not shown to bind.","key_references":[{"PMID":"7542249","why":"CD31 binds integrin alpha v beta 3 in adhesion and precipitation assays"}],"covers":["LR003091","LR006314"]},"LR003092":{"pair":"PECAM1 -> ITGB3","headline":"CD31 binds integrin alpha v beta 3, which includes ITGB3, in human leukocyte adhesion and precipitation experiments.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD31 precipitated alpha v beta 3 from cell lysates and leukocyte adhesion through CD31's second Ig-like domain was inhibited by alpha v beta 3 antibodies [PMID:7542249]. Reactome has an integrin alphaVbeta3:PECAM1 complex [DB:Reactome]; BioGRID has a co-localization record [DB:BioGRID].","molecular_requirements":"The receptor is the alpha v beta 3 heterodimer, so ITGAV is also needed [PMID:7542249].","affinity_potency":[],"species_and_systems":"Human leukocytes and LAK lysates; abstract and some full text [PMID:7542249].","localisation_and_range":"PECAM1 is a membrane protein [flag]; recombinant soluble form used in vitro [PMID:7542249].","caveats":"No affinity in our evidence. The evidence concerns the heterodimer, not ITGB3 alone. Human pair is ortholog-inferred.","key_references":[{"PMID":"7542249","why":"CD31 binds integrin alpha v beta 3"}],"covers":["LR003092","LR006315"]},"LR006323":{"pair":"PIP -> AQP5","headline":"PIP is the AQP5 C-terminus-binding protein in mouse lacrimal gland, an intracellular trafficking relationship rather than a classical extracellular ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"A 17-kDa AQP5 C-terminal-peptide-binding protein from ICR mouse lacrimal glands was identified by LC-MS/MS as PIP; antisense PIP oligonucleotides decreased apical AQP5 immunostaining, suggesting PIP binding drives AQP5 apical transport [PMID:18696337]. Curated effect direction: agonist [PMID:18696337].","molecular_requirements":"The binding site is the AQP5 C-terminal portion [PMID:18696337]. Other requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; lacrimal gland homogenates, ICR versus NOD (Sjogren's model) mice [PMID:18696337]. The human pair is projected from mouse (ortholog_inferred).","localisation_and_range":"PIP carries a secreted flag [flag]; the paper's binding is to the AQP5 C-terminus in gland homogenate [PMID:18696337].","caveats":"Abstract only. Binding was to a synthetic C-terminal peptide on an affinity column, not to intact receptor on a cell surface. In NOD mice a 21-kDa protein (MUP4) bound instead [PMID:18696337]. Human evidence: none in our evidence.","key_references":[{"PMID":"18696337","why":"PIP identified as AQP5 C-terminus binder in mouse lacrimal gland"}],"covers":["LR003102","LR006323"]},"LR004622":{"pair":"PLA2G10 -> PLA2R1","headline":"Mouse sPLA2-X binds mouse PLA2R in two abstract-only papers; human pair projected from mouse.","interaction_type":"direct binding","direction_and_effect":"sPLA2-X bound recombinant PLA2R expressed in COS-7 cells, and specific binding in mouse lung membranes was abolished by PLA2R deficiency [PMID:10922494]. Mature mouse sPLA2-X was a high-affinity ligand for native and recombinant mouse PLA2R [PMID:11019817]. Receptor-mediated signalling effect: not reported in our evidence.","molecular_requirements":"Cross-linking gave a binding-site size of 180 kDa, similar to PLA2R [PMID:10922494]. Mature form was used for binding in [PMID:11019817]; pro-form propeptide removal is needed for optimal enzyme activity [PMID:11019817].","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor: MC3T3-E1 cells, COS-7 recombinant, mouse lung membranes, spleen cells [PMID:10922494][PMID:11019817]. Human is ortholog-inferred.","localisation_and_range":"Secreted, per PLA2G10 secreted flag [flag].","caveats":"Numeric affinity not reported in our evidence. Arachidonic-acid release by sPLA2-X was not different between wild-type and PLA2R-deficient spleen cells, so enzymatic and receptor-binding functions are separable [PMID:11019817]. Human experimental evidence: none.","key_references":[{"PMID":"10922494","why":"sPLA2-X binds PLA2R in COS-7 and mouse lung membranes, lost in PLA2R-deficient mice"},{"PMID":"11019817","why":"Mature sPLA2-X is a high-affinity ligand for native and recombinant mouse PLA2R"}],"covers":["LR001219","LR004622"]},"LR001940":{"pair":"PLA2G2A -> ITGAV","headline":"sPLA2-IIA binds integrin alphavbeta3 with Kd 2 x 10(-7) M and activates it via site 2; two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound integrin alphavbeta3 at high affinity [PMID:18635536]. It directly activated purified soluble and cell-surface alphavbeta3 independent of catalysis or M-type receptor [PMID:25398877]. Arg-74 and Arg-100 are critical for binding; the integrin-binding-defective R74E/R100E mutant did not induce proliferation or ERK1/2 activation in monocytic cells [PMID:18635536]. Agonist.","molecular_requirements":"alphavbeta3 heterodimer; a site 2 peptide from integrin beta1 bound sPLA2-IIA and suppressed activation [PMID:25398877].","affinity_potency":[{"value":"KD 2 x 10(-7) M","assay":"binding to integrin alphavbeta3","system":"human sPLA2-IIA and integrin; abstract-only","cite":"PMID:18635536"}],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract only. Site 2 binding in [PMID:25398877] is a docking prediction supported by peptide competition, not a direct structure. Stored per subunit although the heterodimer binds.","key_references":[{"PMID":"18635536","why":"Kd for alphavbeta3, mutagenesis, signalling dependence"},{"PMID":"25398877","why":"Site 2 activation of alphavbeta3"}],"covers":["LR001940","LR005277"]},"LR006332":{"pair":"PLAUR -> ITGA6","headline":"Direct cell-based binding of soluble uPAR to alpha6 (ITGA6) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta1 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003111","LR006332"]},"LR001229":{"pair":"PLG -> F3","headline":"Direct binding of plasminogen to tissue factor is shown by biosensor; one paper plus a database record.","interaction_type":"direct binding","direction_and_effect":"Plasminogen bound the TF extracellular domain (amino acids 1-219) by optical biosensor; TF-expressing CHO cells bound 70% more plasminogen [PMID:9490681]. TF enhanced two-chain uPA activation of Glu-plasminogen (half-maximal at 59pmol/L) yet inhibited fibrinolysis ~74% (14nmol/L) [PMID:9490681].","molecular_requirements":"Kringles 1-3 bound; isolated kringle 4 and miniplasminogen did not; the site differs from the factor VII/VIIa site [PMID:9490681].","affinity_potency":[{"value":"half-maximal 59pmol/L","assay":"TF enhancement of uPA activation of plasminogen (potency of enhancement, not Kd)","system":"purified components","cite":"PMID:9490681"}],"species_and_systems":"Human proteins; CHO cells transfected with TF [PMID:9490681]. BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted; TF is membrane-bound.","caveats":"Abstract only. Effects on fibrinolysis are mixed (promotes activation yet inhibits fibrinolysis). No binding Kd reported.","key_references":[{"PMID":"9490681","why":"biosensor binding of plasminogen to TF"}],"covers":["LR001229","LR004632"]},"LR003119":{"pair":"PLG -> IGF2R","headline":"IGF2R (soluble form) binds plasminogen and acts as a decoy that blocks activation; evidence is abstract-level.","interaction_type":"direct binding","direction_and_effect":"The soluble, TACE-shed M6P/IGF2R ectodomain bound plasminogen, preventing its binding to the cell surface and uPA and inhibiting activation; peptide 18-36 mimicked this [PMID:21273553]. Membrane IGF2R expression down-regulated uPA/CD87-driven plasminogen activation [PMID:12189157]. Effect is antagonist/decoy.","molecular_requirements":"The N-terminal region of IGF2R is described as needed for binding CD87 and Plg jointly [PMID:12189157]. The functional form is the shed soluble ectodomain [PMID:21273553].","affinity_potency":[],"species_and_systems":"Human CD222 in mouse fibroblasts [PMID:12189157]; human endothelial cells plus in vivo models [PMID:21273553].","localisation_and_range":"Ligand flagged secreted; receptor has secreted and transmembrane flags [flag]; the soluble ectodomain acts at range [PMID:21273553].","caveats":"Abstract only for both. Plasminogen binding is stated jointly with CD87 and without separate assay or affinity [PMID:12189157]. IGF2R is not a classical signalling receptor here. Two further confirmed rows are not shown.","key_references":[{"PMID":"21273553","why":"soluble IGF2R binds plasminogen, blocks activation"},{"PMID":"12189157","why":"IGF2R N-terminus binds CD87 and Plg"}],"covers":["LR003119","LR006340"]},"LR008213":{"pair":"PLG -> ITGA9:ITGB1","headline":"Plasmin kringles bind alpha9beta1 in CHO cells; migration also requires PAR-1 signalling.","interaction_type":"direct binding","direction_and_effect":"Plasmin specifically interacts with alpha9beta1 and induced migration of alpha9-transfected CHO cells; PAR-2 and PAR-4 agonists were ineffective [PMID:15247268].","molecular_requirements":"Kringle binding, catalytic activity and PAR-1 activation are all required [PMID:15247268].","affinity_potency":[],"species_and_systems":"Human proteins, alpha9-CHO cells; abstract only [PMID:15247268].","localisation_and_range":"Ligand flagged secreted.","caveats":"Active species is plasmin, not intact plasminogen; angiostatin alone is a ligand and antagonist [PMID:15247268].","key_references":[{"PMID":"15247268","why":"plasmin-alpha9beta1 binding with PAR-1 requirement"}],"covers":["LR008213"]},"LR006341":{"pair":"PLG -> MELTF","headline":"Membrane-bound melanotransferrin acts as a plasminogen binding site in cells; antibody and soluble-MTf blockade, abstract level.","interaction_type":"direct binding","direction_and_effect":"mMTf expression in CHO cells raised plasminogen binding about 2-fold and plasminogen activation about 2.5-fold; anti-MTf antibody L235 and soluble MTf abolished binding [PMID:15936756]. It promoted motility, migration and invasion about 3-fold [PMID:15936756].","molecular_requirements":"Membrane-bound MTf is the form studied; soluble truncated MTf blocks [PMID:15936756].","affinity_potency":[],"species_and_systems":"Human MTf in CHO cells and SK-MeL-28 melanoma cells; abstract only [PMID:15936756].","localisation_and_range":"Ligand flagged secreted; receptor membrane-bound (scaffold at cell surface).","caveats":"Described as a 'potential' plasminogen receptor; no affinity or purified-protein binding.","key_references":[{"PMID":"15936756","why":"melanotransferrin as cell-surface plasminogen receptor"}],"covers":["LR003120","LR006341"]},"LR001238":{"pair":"PODXL -> SELL","headline":"PODXL from high endothelial venules binds recombinant L-selectin and supports lymphocyte rolling; supported by two papers plus database records.","interaction_type":"direct binding","direction_and_effect":"PODXL (PCLP) on high endothelial venules binds recombinant L-selectin, and purified HEV-derived PCLP supports tethering and rolling of lymphocytes under physiological flow in vitro [PMID:9625756]. Sialofucosylated PODXL also acts as a functional L-selectin ligand on pancreatic cancer cells [PMID:22814396].","molecular_requirements":"The sialofucosylated glycoform of PODXL is the functional ligand in the cancer-cell study [PMID:22814396]. Which glycan or chain features are needed is not reported in our evidence for the HEV study beyond MECA-79 reactivity [PMID:9625756].","affinity_potency":[],"species_and_systems":"Human tissue and cells in both papers [PMID:9625756][PMID:22814396]; mouse pair is ortholog-inferred.","localisation_and_range":"PODXL flagged transmembrane and not secreted [flag]; PCLP concentrated on the luminal surface of high endothelial cells [PMID:9625756]. Contact-dependent adhesion.","caveats":"No affinity reported. Both papers read as abstract or limited full text; the cancer paper does not separate E- from L-selectin. BioGRID lists an Affinity Capture-Western [DB:BioGRID] and IntAct a solid phase assay [DB:IntAct].","key_references":[{"PMID":"9625756","why":"PCLP on HEV binds L-selectin and supports rolling"},{"PMID":"22814396","why":"sialofucosylated PODXL as selectin ligand in cancer cells"}],"covers":["LR001238","LR004640"]},"LR004640":{"pair":"PODXL -> SELL","headline":"PODXL from high endothelial venules binds recombinant L-selectin and supports lymphocyte rolling; supported by two papers plus database records.","interaction_type":"direct binding","direction_and_effect":"PODXL (PCLP) on high endothelial venules binds recombinant L-selectin, and purified HEV-derived PCLP supports tethering and rolling of lymphocytes under physiological flow in vitro [PMID:9625756]. Sialofucosylated PODXL also acts as a functional L-selectin ligand on pancreatic cancer cells [PMID:22814396].","molecular_requirements":"The sialofucosylated glycoform of PODXL is the functional ligand in the cancer-cell study [PMID:22814396]. Which glycan or chain features are needed is not reported in our evidence for the HEV study beyond MECA-79 reactivity [PMID:9625756].","affinity_potency":[],"species_and_systems":"Human tissue and cells in both papers [PMID:9625756][PMID:22814396]; mouse pair is ortholog-inferred.","localisation_and_range":"PODXL flagged transmembrane and not secreted [flag]; PCLP concentrated on the luminal surface of high endothelial cells [PMID:9625756]. Contact-dependent adhesion.","caveats":"No affinity reported. Both papers read as abstract or limited full text; the cancer paper does not separate E- from L-selectin. BioGRID lists an Affinity Capture-Western [DB:BioGRID] and IntAct a solid phase assay [DB:IntAct].","key_references":[{"PMID":"9625756","why":"PCLP on HEV binds L-selectin and supports rolling"},{"PMID":"22814396","why":"sialofucosylated PODXL as selectin ligand in cancer cells"}],"covers":["LR001238","LR004640"]},"LR011192":{"pair":"PORCN -> WNT1","headline":"UniProt notes a WNT1-PORCN interaction; this is an enzyme-substrate relation, not a verified ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states WNT1 interacts with PORCN [DB:UniProt]. Direction and signalling effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No papers shown; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database-only; the one judged paper was a different_entity. PORCN is not flagged secreted and is marked as a non-receptor entry in our flags, so ligand-receptor classification is doubtful.","key_references":[],"covers":["LR011192"]},"LR003128":{"pair":"POSTN -> STAB2","headline":"Periostin was independently confirmed as a circulating ligand of Stab1/Stab2 in one mouse atherosclerosis study, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Periostin, reelin and TGFBi were independently confirmed as novel circulating ligands of Stab1/2 [PMID:36325910]. Stab1/2 mediate clearance of circulating plasma molecules; ApoE-Stab1-KO and ApoE-Stab2-KO mice show reduced atherogenesis [PMID:36325910]. Receptor clearance, not signalling agonism, is the described effect.","molecular_requirements":"Not reported in our evidence; the curator's notes mention GST-pulldown and endocytosis assays [PMID:36325910].","affinity_potency":[],"species_and_systems":"Mouse knockout and plasma proteomics plus in vitro assays; read as abstract only [PMID:36325910]. Human pair is the dossier species; the mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Periostin is flagged secreted [flag]; the paper describes circulating ligands cleared by liver sinusoidal endothelium [PMID:36325910].","caveats":"Single abstract-level paper, with no affinity or species-of-binding detail. The paper confirms five ligand-receptor combinations at once, and the abstract does not give per-pair detail. Stab1 and Stab2 are paralogs with shared ligands; one study covers both.","key_references":[{"PMID":"36325910","why":"Stab1/2 identified as clearance receptors for periostin, reelin and TGFBi"}],"covers":["LR003128","LR006349"]},"LR001247":{"pair":"PPBP -> CXCR1","headline":"NAP-2 (PPBP) binds CXCR1 with low affinity and induces chemotaxis; CXCR2 is the higher-affinity receptor.","interaction_type":"direct binding","direction_and_effect":"CXCR1-transfected Jurkat cells bind IL-8 with high affinity (Kd 1-4 nM) and NAP-2 with low affinity, and all ligands drive chemotaxis [PMID:8137938]. CXCR1 shows low-affinity NAP-2 binding (KD > or = 700 nM) [PMID:8195702]. CXCR1 antibodies reduce the second, high-concentration optimum of NAP-2 chemotaxis [PMID:9373270]. A CXCR1/2 inhibitor blocks CXCL7-driven ccRCC growth in nude mice [PMID:24335961].","molecular_requirements":"Neutrophil NAP-2 chemotaxis involves both CXCR2 (first optimum) and CXCR1 (second, high-dose optimum) [PMID:9373270].","affinity_potency":[{"value":"350.0 nM","assay":"radioligand binding, NAP-2 at CXCR1 (value as given in curator field)","system":"CXCR1-transfected Jurkat cells","cite":"PMID:8137938"},{"value":"KD > or = 700 nM","assay":"radioligand binding","system":"COS-1 cells with CXCR1","cite":"PMID:8195702"}],"species_and_systems":"Human receptors in transfected cells and neutrophils [PMID:8137938][PMID:8195702][PMID:9373270]; nude mice with human ccRCC [PMID:24335961]. All read as abstracts.","localisation_and_range":"PPBP flagged secreted [flag]; paracrine chemoattractant action per chemotaxis assays [PMID:9373270].","caveats":"Affinity is low, so effect may need high NAP-2. The in vivo paper uses a dual CXCR1/CXCR2 inhibitor and cannot separate CXCR1 [PMID:24335961]. The 350.0 nM figure comes from a curator field, not stated in the abstract text shown.","key_references":[{"PMID":"8137938","why":"CXCR1 binding and chemotaxis for IL-8, GROalpha and NAP-2"},{"PMID":"8195702","why":"Quantified low-affinity NAP-2 binding at CXCR1"},{"PMID":"9373270","why":"CXCR1 role in high-dose NAP-2 chemotaxis"}],"covers":["LR001247"]},"LR006350":{"pair":"PPIA -> BSG","headline":"Extracellular PPIA is an established BSG ligand per database records, with a 2012 cell paper showing BSG is involved but not the only receptor.","interaction_type":"direct binding","direction_and_effect":"UniProt describes BSG as a signalling receptor for cyclophilins, essential for PPIA-dependent signalling [DB:UniProt]; Reactome has a BSG:PPIA complex [DB:Reactome]; IntAct and BioGRID record co-IP, affinity capture and chromatography [DB:IntAct][DB:BioGRID]. In cell assays, extracellular PPIA signals via multiple receptors beyond BSG, and BSG knockdown affected some responses [PMID:22631225].","molecular_requirements":"BSG alone is not sufficient to explain PPIA activity; other unidentified receptors are implicated [PMID:22631225].","affinity_potency":[],"species_and_systems":"Human cell lines with recombinant PPIA [PMID:22631225]; mouse pair is ortholog-inferred. The paper was read as abstract with full-text excerpts.","localisation_and_range":"PPIA is flagged secreted and BSG transmembrane [flag]; extracellular PPIA acts on cells in culture [PMID:22631225].","caveats":"The one paper shown is background on BSG and shows it is not the sole receptor; no affinity reported. Binding support is mainly from databases.","key_references":[{"PMID":"22631225","why":"Extracellular PPIA signals through BSG and other receptors"}],"covers":["LR003129","LR006350"]},"LR006800":{"pair":"PRNP -> FPR2","headline":"Database-asserted only: GtoPdb lists PRNP as an FPR2 agonist; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an agonist interaction with affinity in pEC50 [DB:GtoPdb]; no value or direction is verified by a paper in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence; the GtoPdb record cites PMID 23549262, which was not verified.","localisation_and_range":"PRNP is flagged non-secreted and FPR2 transmembrane [flag].","caveats":"No confirmed papers: three abstract_insufficient and one review_only. Support rests on one database record.","key_references":[],"covers":["LR006800"]},"LR001256":{"pair":"PROC -> PROCR","headline":"Well-established direct binding of protein C and activated protein C to EPCR, with mutagenesis, Kd values and PDB structures.","interaction_type":"direct binding","direction_and_effect":"Protein C and activated protein C bind EPCR on endothelium saturably and Ca2+-dependently [PMID:7929370]. Binding requires 10 EPCR residues, including Arg-81 and Leu-82 [PMID:11099506]. Reactome records PROCR binding protein C [DB:Reactome].","molecular_requirements":"Ten EPCR residues required for protein C/APC binding; carbohydrate moieties are not critical [PMID:11099506]. Soluble EPCR also binds fluorescein-APC [PMID:10681521].","affinity_potency":[{"value":"Kd = 30 nM","assay":"saturable binding of protein C and APC to endothelium","system":"human endothelial cells","cite":"PMID:7929370"},{"value":"K(d) = 27 +/- 13 nM","assay":"fluorescence spectroscopy, sEPCR with Fl-APC","system":"soluble EPCR, purified","cite":"PMID:10681521"}],"species_and_systems":"Human protein C and EPCR; endothelial cells, recombinant proteins and cloned receptor [PMID:7929370].","localisation_and_range":"PROC is flagged secreted [flag]; EPCR is described as an endothelial transmembrane protein [PMID:11099506]. A soluble EPCR form circulates in plasma [PMID:10681521].","caveats":"All three papers were read as abstracts only. EPCR also augments protein C activation by thrombin-thrombomodulin, and soluble EPCR inhibits APC anticoagulant activity [PMID:10681521]. PDB structures exist [DB:PDB 1LQV].","key_references":[{"PMID":"7929370","why":"Cloning of EPCR, Kd = 30 nM"},{"PMID":"11099506","why":"Mutagenesis of EPCR residues for protein C binding"},{"PMID":"10681521","why":"Soluble EPCR binds APC"}],"covers":["LR001256"]},"LR001265":{"pair":"PSAP -> LRP1","headline":"LRP1 takes up the saposin precursor for lysosomal delivery; endocytic receptor evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"LRP1 mediates cellular uptake of the saposin precursor and its lysosomal delivery, alongside the mannose-6-phosphate receptor route from the secretory pathway [PMID:9707421]. The curator labelled the assay direct_binding, but the quoted sentence describes uptake.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fibroblast uptake assays [PMID:9707421]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"PSAP flagged secreted [flag]; LRP1 takes up secreted precursor from outside the cell [PMID:9707421].","caveats":"One abstract-only paper; an endocytic or sorting receptor, not a signalling receptor. No affinity reported. The dossier lists a second confirmed row but shows only one paper.","key_references":[{"PMID":"9707421","why":"LRP1-mediated uptake and lysosomal delivery of saposin precursor."}],"covers":["LR001265","LR004665"]},"LR010409":{"pair":"PTGDS -> PTGDR","headline":"PTGDS and PTGDR co-purify in one study recorded in BioGRID and IntAct; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID and IntAct list affinity capture-Western and co-IP between PTGDS and PTGDR [DB:BioGRID][DB:IntAct]. No direction or effect is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond human entities.","localisation_and_range":"Not reported in our evidence.","caveats":"None of the judged papers were confirmed (review_only, abstract_insufficient or different_entity). PTGDS is an enzyme; a physical association is not evidence of a ligand-receptor action.","key_references":[],"covers":["LR010409"]},"LR001274":{"pair":"PTH -> PTH2R","headline":"PTH activates PTH2R, which PTHrP does not; supported by two abstract-level papers and databases.","interaction_type":"functional only","direction_and_effect":"PTH is an agonist at the PTH2 receptor and PTHrP does not activate it [PMID:7797535][PMID:9482662].","molecular_requirements":"The amino terminus and third extracellular domain of the receptor determine selectivity [PMID:9482662].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator; chimeric receptor studies [PMID:9482662].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Both papers abstract only; no affinity values in our evidence. Two further rows pending.","key_references":[{"PMID":"7797535","why":"Identification of PTH2 receptor activated by PTH not PTHrP."},{"PMID":"9482662","why":"Chimeras define structural basis of PTH2R selectivity."}],"covers":["LR001274","LR004674"]},"LR003146":{"pair":"PTN -> ITGAV","headline":"PTN binds integrin alphavbeta3 directly in an RGD-independent way; the ITGAV chain is only implied by the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 directly interacts with PTN and mediates PTN-induced endothelial cell migration; a function-blocking anti-alphavbeta3 antibody abolished it [PMID:19141530]. PTN stimulated migration of alphavbeta3-positive U87MG cells but decreased migration of glioma cells lacking alphavbeta3 [PMID:19141530].","molecular_requirements":"Binding is RGD-independent and uses the beta3 specificity loop (residues 177-184); PTN-induced beta3 Tyr773 phosphorylation depends on RPTPbeta/zeta and c-Src [PMID:19141530]. Contribution of the alphaV chain alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial and glioma cell lines [PMID:19141530]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only. The binding determinant lies on beta3, so ITGAV-only evidence is lacking. BioGRID lists ITGB3-PTN and UniProt lists ITGAV:ITGB3 binding PTN [DB:BioGRID] [DB:UniProt]. Midkine did not interact with alphavbeta3 [PMID:19141530].","key_references":[{"PMID":"19141530","why":"Direct RGD-independent PTN-alphavbeta3 binding and migration"}],"covers":["LR003146","LR006367"]},"LR003155":{"pair":"PTN -> SDC4","headline":"Only evidence is BIAcore binding of PTN to syndecan-4 chains in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"PTN bound both heparan sulfate and chondroitin sulfate chains of syndecan-4, with stronger CS binding than syndecan-1 [PMID:15226297]. Receptor activation not reported in our evidence.","molecular_requirements":"Glycosaminoglycan-chain dependent; simultaneous HS and CS binding suggested to form a ternary complex [PMID:15226297].","affinity_potency":[],"species_and_systems":"Syndecans from normal murine mammary gland epithelial cells [PMID:15226297]; dossier species label is human.","localisation_and_range":"Not reported in our evidence beyond the ectodomain used in vitro.","caveats":"Abstract only; no affinity; glycan-mediated binding that is not specific to PTN; the same paper serves the SDC1 pair.","key_references":[{"PMID":"15226297","why":"BIAcore of PTN binding to syndecan-4 chains"}],"covers":["LR003155","LR006376"]},"LR003164":{"pair":"PTPRG -> CNTN3","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN3 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN3 not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. The PTPRG-CNTN3 evidence is the family-level statement, not a CNTN3-specific structure.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003164","LR006385"]},"LR003173":{"pair":"PTPRZ1 -> CNTN1","headline":"PTPRZ1 (PTPRZ) binds CNTN1: co-crystal structure, binding assays and in vivo oligodendrocyte data; well supported.","interaction_type":"direct binding","direction_and_effect":"PTPRZ binds only CNTN1 among contactins [PMID:20133774]. The cocrystal structure and binding assays show PTPRZ binds CNTN1 on oligodendrocyte precursor cells; in PTPRZ-deficient versus wild-type mice, PTPRZ-CNTN1 binding inhibits precursor proliferation and promotes maturation into oligodendrocytes (curated effect: antagonist) [PMID:21969550]. An earlier paper found F3 (mouse contactin 1) binds PTPzeta/RPTPbeta directly [PMID:10103110].","molecular_requirements":"The carbonic anhydrase-like domain of PTPRZ binds tandem Ig repeats of CNTN1 [PMID:21969550] [DB:PDB 3S97]. UniProt records the same domain-level interaction [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in the structural papers (abstracts) and mice for the in vivo data [PMID:21969550]; mouse brain extracts and astrocyte cultures for F3 [PMID:10103110]. Both species pairs are direct.","localisation_and_range":"PTPRZ1 is flagged secreted [flag], and the 1999 paper's phosphacan/PTPzeta isoforms were affinity-isolated from brain, so secreted and membrane forms may both exist, but which acts here is not reported.","caveats":"Structural papers were read as abstract only. The 1999 paper used mouse F3 and unspecified species for the PTPzeta isoforms, and its abstract says binding was 'highest affinity' without a value. Two further rows were abstract_insufficient.","key_references":[{"PMID":"21969550","why":"PTPRZ-CNTN1 cocrystal structure; effect on oligodendrogenesis"},{"PMID":"20133774","why":"Domain specificity: PTPRZ binds only CNTN1"},{"PMID":"10103110","why":"F3/contactin binds PTPzeta/RPTPbeta directly"}],"covers":["LR003173","LR006394"]},"LR001283":{"pair":"PYY -> NPY5R","headline":"PYY activates human NPY5R in a beta-arrestin assay, with a database agonist record; no direct binding evidence in our dossier.","interaction_type":"functional only","direction_and_effect":"PYY stimulated beta-arrestin 2 association with the Y5 receptor (t1/2 4.6 min; maximal response about 60% of Y1) [PMID:12665544]. GtoPdb lists PYY as a full agonist of NPY5R [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; beta-arrestin 2 recruitment was the readout [PMID:12665544].","affinity_potency":[],"species_and_systems":"BRET2 assay with GFP2-beta-arrestin 2 in the paper, human receptors [PMID:12665544]. Human and mouse pairs are projected from evidence (ortholog inferred).","localisation_and_range":"PYY is flagged secreted [flag].","caveats":"Readout is receptor-arrestin association, not ligand binding, and the paper was read as abstract. GtoPdb gives pKi as unit without a value in our evidence [DB:GtoPdb]. Another paper was review only and one pending.","key_references":[{"PMID":"12665544","why":"PYY-induced beta-arrestin 2 association with Y5"}],"covers":["LR001283","LR004683"]},"LR001292":{"pair":"RELN -> LRP8","headline":"Reelin is a well-supported direct ligand of ApoER2 (LRP8), with nM-range affinity and genetic necessity evidence.","interaction_type":"direct binding","direction_and_effect":"Reelin binds ApoER2 directly and calcium-dependently [PMID:10571240]. Purified Reelin associated more readily with ApoER2 than VLDLR, with agonist-type signalling (Dab1 tyrosine phosphorylation) [PMID:12670700]. Reelin enhanced LTP in hippocampal slices and this was abolished in ApoER2 knockouts [PMID:12167620]. UniProt lists LRP8 as a cell surface receptor for Reelin [DB:UniProt].","molecular_requirements":"Acidic residues in apoER2 complement-type repeats 1 and 3 are required; Reelin appears to engage two or more apoER2 molecules for high-affinity signalling [PMID:12899622]. Both ApoER2 and VLDLR were needed for complete Dab1 phosphorylation [PMID:12670700] and for LTP enhancement [PMID:12167620]. Binding is inhibited by apoE [PMID:10571240].","affinity_potency":[{"value":"KD 0.2 nM","assay":"surface plasmon resonance","system":"Reelin and apoER2, human","cite":"PMID:12899622"}],"species_and_systems":"Mixed: mouse/human Reelin with human receptor [PMID:10571240]; purified human Reelin with mouse neurons [PMID:12670700]; SPR with human proteins [PMID:12899622]; mouse hippocampal slices [PMID:12167620].","localisation_and_range":"RELN is flagged secreted [flag]. LRP8 is flagged transmembrane [flag].","caveats":"Four papers shown were all read as abstracts only. One abstract is truncated. BioGRID also lists reconstituted-complex and affinity-capture records [DB:BioGRID].","key_references":[{"PMID":"12899622","why":"SPR affinity of Reelin for apoER2"},{"PMID":"10571240","why":"Direct binding of Reelin to VLDLR and ApoER2"},{"PMID":"12670700","why":"Purified Reelin prefers ApoER2; Dab1 phosphorylation"}],"covers":["LR001292","LR004691"]},"LR006404":{"pair":"RELN -> STAB2","headline":"Reelin was reported as a circulating Stabilin-2 ligand in one mouse atherosclerosis study; single-source.","interaction_type":"direct binding","direction_and_effect":"Reelin was among ligands independently confirmed for Stab1/Stab2 by GST-pulldown and endocytosis assays; clearance by the scavenger receptors is linked to reduced monocyte activation [PMID:36325910]. Curated as agonist, but the receptor is a clearance (scavenger) receptor, so effect is uptake rather than signalling per the abstract [PMID:36325910].","molecular_requirements":"Not reported in our evidence beyond Stab2 being a single-chain receptor.","affinity_potency":[],"species_and_systems":"Mouse knockout and antibody studies; ligand-binding assays species not stated in the abstract (curator lists human) [PMID:36325910]. The mouse pair is ortholog-inferred.","localisation_and_range":"Reelin is described as a circulating plasma ligand cleared by liver sinusoidal endothelium [PMID:36325910]; RELN is flagged secreted [flag].","caveats":"Only an abstract was read, and it is truncated; the binding evidence is a pulldown, with no affinity reported. Reelin is one of several ligands confirmed in a screen focused on atherosclerosis [PMID:36325910].","key_references":[{"PMID":"36325910","why":"Stab1/2 targeting in atherosclerosis; Reelin as novel circulating ligand"}],"covers":["LR003184","LR006404"]},"LR012371":{"pair":"RNF43 -> FZD3:LRP6","headline":"RNF43 -> FZD3:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 3). ","key_references":[],"covers":["LR012371"]},"LR003191":{"pair":"ROBO1 -> ROBO3","headline":"ROBO3 binds ROBO1 heterophilically per one abstract-only paper; no database support.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to Robo1 (and NCAM) [PMID:16226035]. This is adhesion between family members; no signalling effect for this pair is reported.","molecular_requirements":"Two human Robo3 isoforms (Robo3A/Robo3B) differ by a 26-residue N-terminal insertion and differ in Slit binding; which isoform binds Robo1 is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; orthologs reported expressed in mouse embryo [PMID:16226035]. Mouse pair is ortholog-projected.","localisation_and_range":"Both entities carry a membrane-bound flag [flag]; no range data from the paper.","caveats":"Abstract only; one sentence supports the Robo1 interaction and the assay type is not detailed. No database records.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1 heterophilically; isoform study"}],"covers":["LR003191","LR006411"]},"LR006413":{"pair":"ROBO3 -> NCAM1","headline":"ROBO3 binds NCAM1 heterophilically in one abstract-only paper; no database support.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to NCAM [PMID:16226035]; no agonist or antagonist effect is reported for this pair.","molecular_requirements":"Robo3A and Robo3B isoforms differ by a 26-residue N-terminal insertion; which isoform binds NCAM is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; mouse pair projected from human [PMID:16226035].","localisation_and_range":"Robo3 membrane flag; NCAM1 is flagged both secreted and transmembrane [flag].","caveats":"Abstract only, one sentence of evidence, assay not detailed. No database records. NCAM isoform is not specified.","key_references":[{"PMID":"16226035","why":"Robo3 heterophilic binding to Robo1 and NCAM"}],"covers":["LR003193","LR006413"]},"LR012407":{"pair":"ROR1 -> FZD4","headline":"ROR1 co-immunoprecipitates with FZD4 in transfected cells; a co-receptor association from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"ROR1 coimmunoprecipitated with FZD4 and LRP6 in transfected HEK 293 cells and colocalized with FZD4 at the surface of transfected L cells [PMID:27709494]. Pairwise silencing of ROR1 and FZD4 inhibited Wnt-3a-induced neuronal differentiation [PMID:27709494]. Wnt-3a did not appear to affect these interactions.","molecular_requirements":"Silencing single receptors did not affect differentiation; pairwise silencing of ROR1 with FZD4 or FZD5 was needed [PMID:27709494]. ROR1 also associated with LRP6.","affinity_potency":[],"species_and_systems":"Human embryonic stem cell-derived neural stem cells (silencing); HEK 293 and L cells (co-IP, colocalisation) [PMID:27709494].","localisation_and_range":"Receptor-receptor pair, not a secreted ligand; both are cell-surface receptors [flag].","caveats":"Abstract only. Co-IP in overexpressing cells shows association, not necessarily direct binding. Two other candidate rows were judged as different entities.","key_references":[{"PMID":"27709494","why":"ROR1-FZD4 co-IP and joint requirement in NSC differentiation"}],"covers":["LR012407"]},"LR012416":{"pair":"ROR2 -> FZD7","headline":"ROR2-FZD7 rests only on IntAct comigration records; no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the annotation is stimulatory without paper support here.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct entries cite PMID 36994853 (gel comigration) [DB:IntAct]; system not stated.","localisation_and_range":"Both are receptors [flag].","caveats":"No papers judged (2 pending). Support is two IntAct comigration records only.","key_references":[],"covers":["LR012416"]},"LR004703":{"pair":"RSPO1 -> FZD8","headline":"RSPO1 physically interacts with the FZD8 ectodomain per one abstract-only paper that used the R-spondin family.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins physically interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro and induced TCF reporter activity and beta-catenin stabilisation [PMID:16543246].","molecular_requirements":"R-spondin failed to form a ternary complex with both LRP6 and Fzd8 together [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse cristin/R-spondin proteins [PMID:16543246]; human pair ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag; FZD8 non-secreted receptor [flag].","caveats":"Abstract only. Family-level result, not paralogue-resolved for RSPO1.","key_references":[{"PMID":"16543246","why":"R-spondin family binds Fzd8 and LRP6 ectodomains"}],"covers":["LR001306","LR004703"]},"LR004712":{"pair":"RSPO3 -> FZD8","headline":"Cristin/R-spondin proteins bind the FZD8 ectodomain in one abstract-only paper; RSPO3 itself is covered only as a family member.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins act as FZD8 ligands and induce canonical Wnt/beta-catenin signalling, with TCF reporter activity and beta-catenin stabilisation [PMID:16543246].","molecular_requirements":"The proteins physically interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro, but failed to form a ternary complex with both together [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse Cristin/R-spondin proteins per the title; assay system not otherwise reported in our evidence. The human pair is ortholog-inferred, the mouse pair is not [PMID:16543246].","localisation_and_range":"RSPO3 is flagged secreted [flag], so a paracrine or autocrine ligand; FZD8 is flagged as a receptor [flag].","caveats":"Family-level result: the experiments do not resolve RSPO3 from other R-spondin paralogues. Abstract only. No database records support this pair.","key_references":[{"PMID":"16543246","why":"Cristin/R-spondin family binds Fzd8 and LRP6 ectodomains and activates beta-catenin signalling"}],"covers":["LR001315","LR004712"]},"LR001319":{"pair":"RSPO3 -> LRP6","headline":"Cristin/R-spondin proteins bind the LRP6 ectodomain in one abstract-only paper; RSPO3 is covered only as a family member.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins act as LRP6 ligands and induce canonical Wnt/beta-catenin signalling with TCF reporter activity [PMID:16543246].","molecular_requirements":"They interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro, but did not form a ternary complex with both [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse Cristin/R-spondin proteins per the title; both human and mouse pairs in the dossier are ortholog-inferred.","localisation_and_range":"RSPO3 is flagged secreted and LRP6 transmembrane [flag].","caveats":"Family-level result without paralogue resolution. Abstract only. No database records support this pair.","key_references":[{"PMID":"16543246","why":"Cristin/R-spondin family binds LRP6 and Fzd8 ectodomains"}],"covers":["LR001319","LR004716"]},"LR004721":{"pair":"RTN4 -> CNTNAP1","headline":"Nogo-66 appears to bind Caspr (CNTNAP1) directly in trans at CNS paranodes, in one abstract-only rat paper.","interaction_type":"direct binding","direction_and_effect":"Nogo-A interacts in trans with axonal Caspr at CNS paranodes, with possible roles in axon-glial junction architecture and K+ channel localisation [PMID:14592966]. Activating or inhibitory effect is not reported.","molecular_requirements":"CHO cells cotransfected with Caspr and F3 bound Nogo-66 peptide and GST-Nogo-66 substrates, F3 alone did not; binding persisted after PI-PLC removal of GPI-linked F3, suggesting direct Nogo-66-Caspr interaction [PMID:14592966].","affinity_potency":[],"species_and_systems":"Rat tissue and CHO cells; EAE rats and Shiverer and CGT-/- mice for pathology [PMID:14592966].","localisation_and_range":"Membrane-bound juxtacrine contact at paranodes (oligodendroglial Nogo-A with axonal Caspr) [PMID:14592966]; RTN4 flagged non-secreted [flag].","caveats":"Abstract only; no affinity. Binding was tested with Nogo-66 peptide in cell-substrate assays, not purified protein affinity. BioGRID lists affinity capture-Western records from the same paper [DB:BioGRID]. Distinct from the canonical NgR pathway.","key_references":[{"PMID":"14592966","why":"Nogo-A/Nogo-66 binds Caspr at paranodes"}],"covers":["LR001324","LR004721"]},"LR001328":{"pair":"RTN4 -> TNFRSF19","headline":"TAJ (TNFRSF19) binds NgR1 and joins the Nogo receptor complex; direct Nogo-TAJ binding is not shown.","interaction_type":"functional only","direction_and_effect":"TAJ replaces p75 in the p75/NgR1/LINGO-1 complex to activate RhoA in the presence of myelin inhibitors; exogenous TAJ reversed MAIF-induced neurite outgrowth inhibition, and Taj-deficient mouse neurons were more resistant [PMID:15694322].","molecular_requirements":"TAJ needs NgR1 and LINGO-1 in the complex [PMID:15694322].","affinity_potency":[],"species_and_systems":"Neurons including Taj-deficient mouse neurons, in vitro [PMID:15694322]; curators record human ligand and receptor.","localisation_and_range":"RTN4 flagged non-secreted [flag]; the complex acts at the neuronal surface.","caveats":"TAJ is shown to bind NgR1, not Nogo/RTN4 directly; this pair is the complex-level interpretation. Abstract only. No database records.","key_references":[{"PMID":"15694322","why":"TAJ binds NgR1 and replaces p75 in the Nogo receptor complex"}],"covers":["LR001328","LR004725"]},"LR009203":{"pair":"RTN4R -> RTN4","headline":"RTN4R is the Nogo-66 receptor, so this is the established Nogo ligand-NgR pair, but listed in reversed orientation and rests on one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"The paper identifies a brain-specific leucine-rich-repeat protein with high affinity for soluble Nogo-66, and Nogo-66 receptor expression is sufficient to impart Nogo-66 axonal inhibition to unresponsive neurons [PMID:11201742]. So Nogo (RTN4) is the inhibitory ligand and RTN4R the receptor. UniProt also gives RTN4R as receptor for RTN4, OMG and MAG [DB:UniProt].","molecular_requirements":"The extracellular 66-residue domain (Nogo-66) is the active part; cleavage of GPI-linked proteins from axons removes sensitivity [PMID:11201742]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell system noted as transfected cells and oligodendrocytes; species stated as human in the record, but the abstract does not give species [PMID:11201742].","localisation_and_range":"Nogo-66 is displayed at the extracellular surface of transfected cells and oligodendrocytes, and RTN4 and RTN4R carry no secreted flag, so contact-mediated myelin-axon signalling is suggested [PMID:11201742][flag].","caveats":"Only the abstract was read; the curator's own note rates confidence medium. No affinity value in our evidence. The database stores RTN4R as ligand and RTN4 as receptor, the reverse of the biology described.","key_references":[{"PMID":"11201742","why":"identification of the Nogo-66 receptor"}],"covers":["LR009203"]},"LR006422":{"pair":"RTN4RL1 -> ADGRB3","headline":"RTN4RL1 binds BAI3 with nanomolar affinity per one paper's family-wide statement; the human pair is projected.","interaction_type":"direct binding","direction_and_effect":"All three RTN4-receptor isoforms bind a TSR domain of BAIs with nanomolar affinity [PMID:34758294]. BAI1- and BAI3-expressing cells aggregated with RTN4R-expressing cells and RTN4RL1 was a top pulldown interactor [PMID:34758294]. Signalling effect is not reported in our evidence for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 bound RTN4Rs and formed a complex by SEC [PMID:34758294]; RTN4RL1 specifically with BAI3 was not shown separately in the excerpts. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Recombinant ectodomains and HEK 293F cells [PMID:34758294]. The human pair is ortholog-inferred; a mouse pair is not.","localisation_and_range":"Trans-cellular adhesion, so contact-dependent [PMID:34758294]. No secreted flag on either partner [flag].","caveats":"Evidence for this specific pair comes from a statement covering all RTN4R-family members and BAIs; the curator row was recorded from the abstract. The nanomolar Kd values reported (1.9 nM, 30.0 nM) are for other family pairs, not specified for RTN4RL1-BAI3.","key_references":[{"PMID":"34758294","why":"family-wide binding of RTN4Rs to BAI1 and BAI3"}],"covers":["LR003202","LR006422"]},"LR006431":{"pair":"S100A4 -> AGER","headline":"S100A4 binds RAGE in a chondrocyte pulldown and signals to MMP-13; RAGE dependence supported by soluble and dominant-negative RAGE.","interaction_type":"direct binding","direction_and_effect":"S100A4 stimulates chondrocytes to raise Pyk-2 and MAP kinase phosphorylation, activate NF-kappaB and increase MMP-13; this is blocked by soluble RAGE, AGE-BSA or dominant-negative RAGE [PMID:16948116].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human articular chondrocytes, with osteoarthritic cartilage [PMID:16948116]. An IntAct record lists an SPR interaction [DB:IntAct]. Mouse pair is projected.","localisation_and_range":"S100A4 is flagged secreted [flag]; acts on chondrocytes as an extracellular ligand [PMID:16948116].","caveats":"Abstract only; affinity not reported in our evidence. The IntAct record cites a different paper [DB:IntAct].","key_references":[{"PMID":"16948116","why":"Biotin-S100A4 pulldown and RAGE-dependent MMP-13 induction"}],"covers":["LR003213","LR006431"]},"LR003218":{"pair":"S100A4 -> EMB","headline":"Embigin is reported as a new S100A4 receptor by pull-down in prostate cancer cells; one abstract-only curation.","interaction_type":"direct binding","direction_and_effect":"Extracellular S100A4 binding to embigin inhibits AMPK, activates NF-kappaB, MMP9 and mTORC1, inhibits autophagy and increases prostate cancer cell motility [PMID:30041429].","molecular_requirements":"Embigin's cytoplasmic tail matters for in vivo tumour growth; embigin also acts independently of S100A4 [PMID:30041429].","affinity_potency":[],"species_and_systems":"Human prostate cancer cells (DU145) and a mouse growth model [PMID:30041429].","localisation_and_range":"S100A4 is flagged secreted [flag]; the paper describes extracellular S100A4 binding embigin, a transmembrane glycoprotein [PMID:30041429].","caveats":"Binding shown by pull-down and immunoprecipitation; no affinity reported. Of S100 proteins tested only S100A4 bound embigin [PMID:30041429]. Abstract-level curation.","key_references":[{"PMID":"30041429","why":"Embigin as S100A4 receptor in prostate cancer"}],"covers":["LR003218","LR006436"]},"LR006440":{"pair":"S100A8 -> AGER","headline":"In diabetic mice S100A8/A9 acts through RAGE on Kupffer cells to raise IL-6; evidence is for the S100A8/A9 pair, functional.","interaction_type":"functional only","direction_and_effect":"Neutrophil-derived S100A8/A9 interact with RAGE on hepatic Kupffer cells, increasing IL-6 and causing thrombocytosis; paquinimod, which inhibits S100A8/A9-RAGE binding, reduced thrombocytosis and atherogenesis [PMID:28504650].","molecular_requirements":"Evidence is for the S100A8/A9 complex; S100A8 alone is not separated [PMID:28504650].","affinity_potency":[],"species_and_systems":"Diabetic mice and type 2 diabetes patients [PMID:28504650]. Human pair is projected from mouse evidence.","localisation_and_range":"S100A8 is flagged secreted [flag].","caveats":"Abstract only; no binding assay or affinity in our evidence. Human pair is ortholog-inferred.","key_references":[{"PMID":"28504650","why":"S100A8/A9-RAGE axis in diabetic thrombocytosis"}],"covers":["LR003223","LR006440"]},"LR003227":{"pair":"S100A8 -> CD69","headline":"Binding of the S100A8/S100A9 complex to CD69 supported by one abstract-only paper; S100A8 acts as part of the complex.","interaction_type":"direct binding","direction_and_effect":"The S100A8/S100A9 complex was identified as the natural ligand of CD69 in human PBMCs; the association was confirmed by in vitro binding and competition assay, and CD69-S100A8/S100A9 association was required for SOCS3 up-regulation and inhibited STAT3 signalling, supporting Treg differentiation [PMID:26296369]. Agonist-like. UniProt also records the interaction [DB:UniProt].","molecular_requirements":"The ligand is the S100A8/S100A9 complex, not S100A8 alone; the paper does not test S100A8 separately in our evidence [PMID:26296369]. Binding depends on CD69 glycosylation: peptide-N-glycosidase treatment significantly abolished it [PMID:26296369].","affinity_potency":[],"species_and_systems":"Human PBMCs and in vitro binding with human proteins; mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD69 is flagged as a receptor [flag].","caveats":"Abstract only was read. Complex-level evidence; S100A8 contribution alone is not reported in our evidence. UniProt entries cite the same paper, so they are not independent.","key_references":[{"PMID":"26296369","why":"Identifies S100A8/S100A9 as CD69 ligand, glycosylation-dependent"}],"covers":["LR003227","LR006444"]},"LR003236":{"pair":"S100A9 -> CD33","headline":"S100A9 and CD33 form a functional ligand/receptor pair in MDS myeloid cells; abstract-only, one IntAct record.","interaction_type":"functional only","direction_and_effect":"S100A9 and CD33 formed a functional ligand/receptor pair that recruited components to CD33's ITIM, inducing IL-10 and TGF-beta secretion by immature myeloid cells and MDSC expansion [PMID:24216507]. Effect is inhibitory-signalling via ITIM but stimulates suppressive cytokines. IntAct lists an affinity-chromatography interaction cited to this paper [DB:IntAct].","molecular_requirements":"CD33 signals through its ITIM; interrupting CD33 signalling with active DAP12 rescued the phenotype in mice [PMID:24216507].","affinity_potency":[],"species_and_systems":"Transfected cell models, MDS patient bone marrow and S100A9 transgenic mice; the ligand species of the cell models is not stated in the abstract [PMID:24216507].","localisation_and_range":"Ligand secreted [flag].","caveats":"Abstract only. Only one paper; the IntAct record cites the same paper, so is not independent. No affinity reported.","key_references":[{"PMID":"24216507","why":"S100A9-CD33 ligand/receptor pair driving MDSC expansion"}],"covers":["LR003236"]},"LR003245":{"pair":"SCGB1A1 -> CUBN","headline":"CCSP (SCGB1A1) binds cubilin by SPR and is taken up through it; supported by one study.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed CCSP binds cubilin, and binding led to uptake and lysosomal degradation of CCSP in cultured cells; cubilin-deficient patients excrete CCSP in urine [PMID:11278724]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Megalin acts as an endocytic co-receptor that associates with cubilin [PMID:11278724].","affinity_potency":[],"species_and_systems":"Human CCSP and cubilin; SPR and cultured cells, plus patient observations. Mouse pair is ortholog-inferred [PMID:11278724].","localisation_and_range":"CCSP is secreted [flag]; cubilin is a peripheral membrane protein on proximal tubular cells [PMID:11278724].","caveats":"Abstract only; no affinity value in our evidence. Role is clearance/uptake rather than classical signalling.","key_references":[{"PMID":"11278724","why":"SPR binding of CCSP to cubilin and uptake"}],"covers":["LR003245","LR006461"]},"LR004730":{"pair":"SCGB3A2 -> MARCO","headline":"UGRP1 (SCGB3A2) identified as a MARCO ligand by expression cloning, with FRET and UniProt support.","interaction_type":"direct binding","direction_and_effect":"Retroviral expression cloning identified MARCO as a receptor for UGRP1; LPS competed with UGRP1 for MARCO and bacterial binding [PMID:12847263]. BioGRID lists a FRET interaction and UniProt states SCGB3A2 binds MARCO [DB:BioGRID][DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; expression cloning, MARCO expressed by alveolar macrophages [PMID:12847263]. Mouse pair is ortholog-inferred.","localisation_and_range":"UGRP1 is secreted [flag]; expressed by lung Clara-like cells, with MARCO on alveolar macrophages [PMID:12847263].","caveats":"Abstract only; no affinity. A second confirmed row is not shown. Binding to bacteria and competition with LPS suggest a scavenger-type role.","key_references":[{"PMID":"12847263","why":"Expression cloning of MARCO as UGRP1 receptor"}],"covers":["LR001334","LR004730"]},"LR003254":{"pair":"SDC2 -> ADGRA2","headline":"SDC2 guides were enriched in an ADGRA2 binding-probe CRISPRa screen; one screen, no direct binding test.","interaction_type":"functional only","direction_and_effect":"SDC1 and SDC2 guides were enriched in an ADGRA2 ligand selection, consistent with known ADGRA2-glycosaminoglycan interactions; effect direction is not reported in our evidence [PMID:30477585].","molecular_requirements":"Syndecans are heparan sulfate proteoglycans, so glycosaminoglycan chains may matter [PMID:30477585]; not tested directly.","affinity_potency":[],"species_and_systems":"Genome-wide CRISPRa in cells selected with a recombinant ADGRA2 probe; a single screen per bait [PMID:30477585]. Species not reported in our evidence.","localisation_and_range":"SDC2 is flagged transmembrane and not secreted [flag], so contact-dependent signalling is plausible, but this is from annotation only.","caveats":"Indirect enrichment evidence only; the same sentence covers SDC1 and SDC2. Not validated by a binding assay in our evidence.","key_references":[{"PMID":"30477585","why":"CRISPRa selection enriched SDC1 and SDC2 guides with ADGRA2 probe"}],"covers":["LR003254","LR006470"]},"LR011525":{"pair":"SELL -> GLYCAM1","headline":"No papers in our evidence; support is only Reactome records on L-selectin ligand binding.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists L-selectin interacting with known ligands and ligands binding L-selectin [DB:Reactome]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the pair is annotated human only.","localisation_and_range":"SELL is annotated transmembrane [flag]; GLYCAM1 has no localisation flags in our evidence.","caveats":"No curator-verified paper. The Reactome records are generic L-selectin ligand reactions and do not name GLYCAM1 specifically in the shown examples [DB:Reactome].","key_references":[],"covers":["LR011525"]},"LR001337":{"pair":"SELPLG -> SELE","headline":"Well supported E-selectin ligand: binding, kinetics and function across several papers; requires sialyl Lewis x glycans.","interaction_type":"direct binding","direction_and_effect":"PSGL-1 serves as an E-selectin ligand under flow [PMID:11402070] [PMID:9128259]. E-selectin-Fc, described as agonistic, protected myeloma cells from melphalan, and PSGL-1 knockdown or blocking antibodies abolished macrophage protection [PMID:22996336].","molecular_requirements":"Needs sialylated, fucosylated core 2 O-glycans; tyrosine sulfation is needed for P- but not E-selectin [PMID:8621728]. Sialyl Lewis x on Thr16 within the first 19 residues suffices, with more than one E-selectin site [PMID:9128259]. Binding needs sialyl Lewis x on O- and N-glycans [PMID:26124272].","affinity_potency":[],"species_and_systems":"Human cells and proteins: CHO transfectants, hematopoietic progenitor cells, SPR with native ligands from extracts, myeloma-macrophage cocultures plus a SCID mouse model [PMID:8621728] [PMID:11402070] [PMID:26124272] [PMID:22996336]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both annotated membrane-bound [flag]; contact-dependent rolling adhesion [PMID:9128259].","caveats":"Glycoform-dependent. Monomeric E-selectin binds with fast on/off rates and dimeric with slow ones [PMID:26124272]. CD44 is a stronger E-selectin ligand on progenitor cells [PMID:11402070]. Most papers read as abstract only; 22996336 does not separate E- from P-selectin in the abstract. Database records: Reactome, IntAct [DB:Reactome] [DB:IntAct].","key_references":[{"PMID":"9128259","why":"PSGL-1 N-terminal determinants for E-selectin rolling"},{"PMID":"26124272","why":"SPR kinetics of E-selectin with native PSGL-1"},{"PMID":"8621728","why":"glycosylation and sulfation requirements"}],"covers":["LR001337","LR004733"]},"LR003263":{"pair":"SEMA3A -> L1CAM","headline":"L1 acts with NRP1 in Sema3A responses, but direct Sema3A-L1 binding is not shown; functional only.","interaction_type":"functional only","direction_and_effect":"Upon Sema3A binding to NP-1, L1 and NP-1 are co-internalized through a clathrin-dependent mechanism mediated by L1; an L1-mimetic peptide blocked endocytosis and growth cone collapse [PMID:15121181].","molecular_requirements":"L1 works as part of an L1/NP-1 complex; NP-1 is the Sema3A-binding subunit [PMID:15121181].","affinity_potency":[],"species_and_systems":"COS7 cells and neuronal cultures; species not specified in our evidence [PMID:15121181].","localisation_and_range":"Sema3A is flagged secreted and L1CAM membrane-bound [flag].","caveats":"Only one paper, read as abstract only. Sema3A binds NP-1, not shown to bind L1 directly, so L1 is a co-receptor rather than a demonstrated binder [PMID:15121181]. No database records.","key_references":[{"PMID":"15121181","why":"L1/NP-1 co-internalization after Sema3A"}],"covers":["LR003263","LR006479"]},"LR001346":{"pair":"SEMA3B -> NRP1","headline":"SEMA3B binds NRP1 in binding assays and co-immunoprecipitation; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"SEMA3B (SemA) binds NRP1; in colorectal carcinoma cells SEMA3B competitively inhibits VEGF signalling by binding NRP1 [PMID:37701532]. Interaction class is stimulatory [flag].","molecular_requirements":"Not reported in our evidence beyond NRP1 binding; co-IP showed both SEMA3B and VEGF bind NRP1 but not each other [PMID:37701532].","affinity_potency":[],"species_and_systems":"Colorectal carcinoma cells [PMID:37701532]; AP-fusion binding to mouse NP-1 [PMID:10196546]. Human pair is ortholog-inferred from mouse [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"The 1998 paper uses SemA nomenclature and the quote is browser-read, spot-check pending [PMID:10196546]. No affinity values in our evidence.","key_references":[{"PMID":"10196546","why":"AP-fusion binding of SemA to mouse NP-1"},{"PMID":"37701532","why":"SEMA3B-NRP1 co-IP and VEGF competition in CRC cells"}],"covers":["LR001346","LR004742"]},"LR001355":{"pair":"SEMA3F -> PLXNA1","headline":"Weak support: one paper whose evidence sentence is a cited reference title; no direct SEMA3F-PLXNA1 result is shown.","interaction_type":"functional only","direction_and_effect":"The only paper concerns Sema3A signalling through PlexinA1/NP1 and says Sema3F is an NP1 antagonist [PMID:11239433]. No SEMA3F-PLXNA1 interaction result is reported in the shown excerpts.","molecular_requirements":"Not reported in our evidence for SEMA3F. The paper reports PlexinA1 activation depends on NP1 for Sema3A [PMID:11239433].","affinity_potency":[],"species_and_systems":"Curator labelled mouse/mouse [PMID:11239433].","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Evidence sentence is the title of a cited NRP2 paper (a reference list entry), not a result of this paper. Two further rows were abstract_insufficient.","key_references":[{"PMID":"11239433","why":"only paper; does not test SEMA3F-PLXNA1 directly"}],"covers":["LR001355","LR004751"]},"LR003272":{"pair":"SEMA3F -> PLXNA2","headline":"Functional evidence only: Sema3F contracted COS-7 cells expressing NP2 with PlexA2 in one paper; mouse pair is ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"In COS-7 cells expressing NP2 plus PlexA1 or PlexA2, Sema3F caused contraction, whereas Sema3A and Sema3C did not [PMID:11239433]. This is a signalling readout, not binding.","molecular_requirements":"NP2 co-expression was part of the assay, so PlexA2 acts with NP2 [PMID:11239433]. Whether PlexA2 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS-7 cell contraction assay, full text read; species not specified for the experiment [PMID:11239433]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Single paper; no direct binding or affinity reported. Interaction rests on co-expression of NP2.","key_references":[{"PMID":"11239433","why":"COS-7 contraction by Sema3F with NP2/PlexA1 or PlexA2"}],"covers":["LR003272","LR006488"]},"LR001364":{"pair":"SEMA4G -> PLXNB2","headline":"Sema4G is a minor Plexin-B2 ligand in cerebellar development; one paper, with limited effect when deleted alone.","interaction_type":"direct binding","direction_and_effect":"Sema4G protein specifically bound Plexin-B2-expressing cerebellar granule cells, and Sema4G elicited migration of wild-type but not Plxnb2-/- granule cell precursors, indicating Plexin-B2 mediation [PMID:21122816].","molecular_requirements":"Plexin-B2 alone named. Sema4C and Sema4G appear to act in parallel as Plexin-B2 ligands [PMID:21122816].","affinity_potency":[],"species_and_systems":"Mouse knockouts and cerebellar cells (dossier labels species human) [PMID:21122816]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4G flagged transmembrane, not secreted [flag].","caveats":"Sema4G deletion alone caused no overt phenotype; double deletion with Sema4C was less severe than Plexin-B2 loss, suggesting other ligands [PMID:21122816]. Binding claim read from abstract plus excerpts. No database support.","key_references":[{"PMID":"21122816","why":"Sema4C and Sema4G as Plexin-B2 ligands"}],"covers":["LR001364","LR004760"]},"LR003281":{"pair":"SEMA5A -> PLXNA2","headline":"Supported by one full-text mouse study showing Sema5A-Fc binding to hippocampal neurons that depends on PlexinA2 and a functional requirement in granule cells.","interaction_type":"direct binding","direction_and_effect":"Sema5A-Fc binding was greatly reduced in Plxna2-/- hippocampal neurons and virtually absent in Plxna1-/-;Plxna2 double mutants [PMID:25313870]. Plxna2-/- GCs had increased spine density (1.94 \u00b1 0.04 vs WT 1.47 \u00b1 0.05 spines/\u00b5m in culture), similar to Sema5A-/- GCs (2.23 \u00b1 0.08), so Sema5A acts through PlexA2 to suppress spines [PMID:25313870].","molecular_requirements":"Binding was also reduced in Plxna1-/- neurons, so PlexA1 may contribute to binding; a Plxna3 knockout did not reduce it [PMID:25313870].","affinity_potency":[],"species_and_systems":"Mouse neurons and mice (ligand and receptor both mouse). Human and mouse pairs in the dossier are both ortholog-inferred.","localisation_and_range":"Ligand is flagged membrane-bound, not secreted [flag]; the paper discusses signalling in cis or in trans [PMID:25313870].","caveats":"Single paper only; binding was measured on neurons by loss of binding, not with purified proteins, and no affinity is reported.","key_references":[{"PMID":"25313870","why":"Sema5A-Fc binding and spine-density genetics with PlexA2"}],"covers":["LR003281","LR006497"]},"LR007403":{"pair":"SEMA7A -> ITGA1:ITGB1","headline":"Weakly supported for this complex: a keratinocyte-melanocyte paper implicates beta1-integrin, and Reactome lists the alpha1beta1 complex.","interaction_type":"functional only","direction_and_effect":"Keratinocyte-expressed Sema7A promotes spreading and dendricity in human melanocytes, with a beta1-integrin contribution examined [PMID:17671519]. Reactome lists SEMA7A:Integrin alpha1beta1 [DB:Reactome].","molecular_requirements":"Beta1 is implicated; the alpha1 subunit is not named in the abstract [PMID:17671519].","affinity_potency":[],"species_and_systems":"Human melanocytes and keratinocytes [PMID:17671519].","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; the paper calls it membrane-bound and expressed by keratinocytes and fibroblasts [PMID:17671519].","caveats":"Abstract only and truncated; the abstract names Plexin C1 as a Sema7a receptor on melanocytes. The second row was review_only.","key_references":[{"PMID":"17671519","why":"Sema7a drives melanocyte dendricity, involving beta1-integrin"}],"covers":["LR007403"]},"LR001373":{"pair":"SERPINC1 -> LRP1","headline":"Antithrombin III-thrombin complexes bind LRP1 in purified-protein assays and are internalised; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Antithrombin III-thrombin bound purified LRP, inhibited by RAP, and LRP-expressing fibroblasts internalised and degraded the complexes [PMID:8626456]. Only the sLRP4 homology region bound thrombin-antithrombin III complexes [PMID:14596620].","molecular_requirements":"Complex of ATIII with thrombin is the ligand; native or modified inhibitor alone was unable to bind [PMID:8626456]. Of the three LRP homology regions, only sLRP4 bound it [PMID:14596620].","affinity_potency":[],"species_and_systems":"Human proteins; purified LRP, mouse and HepG2 cells, rat clearance in vivo (RAP inhibited clearance of ATIII-125I-thrombin) [PMID:8626456]; recombinant sLRP fragments from Pichia pastoris [PMID:14596620]. The mouse pair is projected from human (ortholog_inferred).","localisation_and_range":"SERPINC1 is flagged secreted [flag]; cleared by endocytosis in the experiments [PMID:8626456].","caveats":"Both papers read as abstract only; free ATIII is not shown to bind. One further row is pending.","key_references":[{"PMID":"8626456","why":"Binding, uptake and in vivo clearance of ATIII-thrombin via LRP"},{"PMID":"14596620","why":"sLRP4 region specifically binds thrombin-ATIII"}],"covers":["LR001373","LR004768"]},"LR006503":{"pair":"SERPINC1 -> NRP1","headline":"Antithrombin III binds immobilised neuropilin-1 on an optical biosensor; a single paper, with no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Antithrombin III was among several heparin-binding proteins able to interact with Npn-1 immobilised on the sensor surface [PMID:15695515]. Effect on signalling is not reported in our evidence for antithrombin III.","molecular_requirements":"Interactions were ionic-strength dependent and inhibited by heparin, which the authors read as a heparin-mimetic site on Npn-1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Biosensor binding assay with immobilised Npn-1; the paper's functional work used FGF-2 on human umbilical vein endothelial cells, not antithrombin III [PMID:15695515]. Both human and mouse pairs here are ortholog-projected.","localisation_and_range":"NRP1 is flagged as secreted, receptor and transmembrane [flag]; localisation of the interaction is not reported.","caveats":"Single paper; the dossier shows its abstract was the curated read although full text is available. Antithrombin III is only listed among many binders; no kinetic values given for it. Multi-binder promiscuity of Npn-1 is a concern.","key_references":[{"PMID":"15695515","why":"Biosensor binding of antithrombin III to Npn-1"}],"covers":["LR003287","LR006503"]},"LR003290":{"pair":"SERPINE1 -> VLDLR","headline":"uPA:PAI-1 complex binds purified VLDL receptor with high affinity and is internalised; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"uPA complexed with PAI-1 bound purified VLDL receptor with high affinity; VLDLR-expressing fibroblasts internalised and degraded 125I-labelled complexes, while non-infected fibroblasts did not [PMID:7592875].","molecular_requirements":"The bound ligand is the uPA:PAI-1 complex; free PAI-1 is not reported [PMID:7592875].","affinity_potency":[],"species_and_systems":"Purified receptor and mouse embryonic fibroblasts deficient in VLDLR and LRP, rescued with an adenoviral VLDLR vector [PMID:7592875]. Mouse pair is ortholog-projected.","localisation_and_range":"VLDLR is flagged as a receptor and transmembrane [flag]; endocytic clearance.","caveats":"One paper, abstract only; the curated evidence sentence concerns lipoprotein lipase, not PAI-1.","key_references":[{"PMID":"7592875","why":"uPA:PAI-1 binding and internalisation by VLDL receptor"}],"covers":["LR003290","LR006506"]},"LR001382":{"pair":"SFTPA1 -> TLR2","headline":"SP-A binds the recombinant TLR2 extracellular domain and inhibits peptidoglycan-induced signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Inhibitory: SP-A reduced sTLR2 binding to peptidoglycan and attenuated PGN-induced NF-kappaB activity in TLR2-transfected HEK293 cells and TNF-alpha secretion by U937 cells and rat alveolar macrophages [PMID:11724772].","molecular_requirements":"Reactome lists binding to a TLR2:TLR1 complex [DB:Reactome]; subunit requirements are not tested in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant soluble TLR2 extracellular domain, HEK293 transfectants, U937 cells and rat alveolar macrophages; mouse pair is ortholog-inferred [PMID:11724772].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; the paper refers to SP-A generally. Peptidoglycan itself is not an SP-A ligand per the abstract.","key_references":[{"PMID":"11724772","why":"Direct SP-A binding to sTLR2 and inhibition of PGN responses"}],"covers":["LR001382","LR004777"]},"LR006512":{"pair":"SFTPA1 -> TLR4","headline":"SP-A binds recombinant TLR4 extracellular domain and antagonises LPS signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Antagonist: SP-A attenuated smooth-LPS cell-surface binding and NF-kappaB activation in TLR4/MD-2-expressing cells [PMID:16754682].","molecular_requirements":"MD-2 is also bound by SP-A, so the TLR4/MD-2 complex is the relevant target; binding is Ca2+-dependent and involves the CRD; oligomerisation is needed because the trimeric CRF had approximately 600-fold higher KD for TLR4 [PMID:16754682]. Reactome lists TLR4:LY96 [DB:Reactome].","affinity_potency":[{"value":"600-fold higher KD (CRF vs full SP-A), TLR4","assay":"BIAcore/solid-phase binding","system":"recombinant soluble TLR4","cite":"PMID:16754682"}],"species_and_systems":"Recombinant soluble human TLR4 and MD-2 (solid-phase, immunoprecipitation, BIAcore) and cell assays; mouse pair is ortholog-inferred [PMID:16754682].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; absolute KD not given.","key_references":[{"PMID":"16754682","why":"SP-A binds TLR4 and MD-2; oligomerisation matters"}],"covers":["LR003296","LR006512"]},"LR005306":{"pair":"SHH -> GAS1","headline":"SHH-GAS1 is supported by one functional axon-repulsion paper plus database records; direct binding is not measured in the dossier.","interaction_type":"functional only","direction_and_effect":"Shh secreted from gut epithelium excludes enteric axons from central projection; this requires its binding partner Gas1 and Smo in enteric neurons. Axons turn away from a point source of Shh in a Gas1-dependent manner [PMID:25535338]. UniProt describes GAS1 as a co-receptor that takes ShhN from the CDON-BOC heterodimer and transfers it to PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"Gas1 and Smo are required in enteric neurons; Gnaz (a Galphai) mediates the repulsive response [PMID:25535338]. A structure with a chain of SHH and a chain of GAS1 exists [DB:PDB 7RHQ].","affinity_potency":[],"species_and_systems":"Enteric neurons differentiated from neurospheres in vitro plus Gnaz-mutant intestines [PMID:25535338]; species not specified in the abstract.","localisation_and_range":"GAS1 is flagged not secreted [flag]; SHH is secreted [flag], acting as a paracrine cue at a distance [PMID:25535338].","caveats":"Abstract-only. The paper's effect is axon repulsion, not canonical activation, so the effect may be context dependent. Direct binding is asserted by the phrase 'binding partner' and by the PDB entry, not measured in the dossier.","key_references":[{"PMID":"25535338","why":"Gas1-dependent Shh repulsion of enteric axons"}],"covers":["LR001976","LR005306"]},"LR007412":{"pair":"SHH -> GAS1:PTCH2","headline":"Complex GAS1:PTCH2 rests on one abstract about PTCH2; GAS1's role is not shown here.","interaction_type":"functional only","direction_and_effect":"Ptch2 is reported to be a functional Shh receptor that regulates Smo localization and activity in vitro [PMID:25448692]. GAS1 is a co-receptor handing ShhN to PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"The paper does not mention GAS1 [PMID:25448692]. A structure with chains of SHH and GAS1 exists [DB:PDB 7RHQ].","affinity_potency":[],"species_and_systems":"In vitro and mouse limb bud genetics; cell system not specified [PMID:25448692].","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor. GAS1 is flagged not secreted [flag].","caveats":"Abstract-only; evidence is for PTCH2 alone.","key_references":[{"PMID":"25448692","why":"Ptch2 is a functional Shh receptor in vitro"}],"covers":["LR007412"]},"LR001391":{"pair":"SHH -> PTCH2","headline":"SHH-PTCH2 binding is shown in one abstract showing similar affinity to PTCH1; direct evidence is thin.","interaction_type":"direct binding","direction_and_effect":"PTCH2 binds all hedgehog family members with similar affinity to PTCH and can form a complex with SMO [PMID:9811851]. UniProt: SHH acts by binding to patched receptor PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"No co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PTCH2 gene isolated; biochemical analysis, system not detailed [PMID:9811851]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag].","caveats":"Abstract-only; affinity is not quantified in the dossier. The paper suggests PTCH2 may mediate Dhh activity in vivo [PMID:9811851].","key_references":[{"PMID":"9811851","why":"PTCH2 binds hedgehog proteins with similar affinity"}],"covers":["LR001391","LR004786"]},"LR006521":{"pair":"SIGLEC15 -> ITGAM","headline":"One full-text human study reports CD11b (ITGAM) as a sialic-acid-dependent Siglec-15 binding partner on T cells.","interaction_type":"direct binding","direction_and_effect":"Siglec-15-Fc bound CD11b/CD18 by ELISA and co-immunoprecipitation, and anti-CD11b blocking, CD11b knockdown and CD11b/CD18 overexpression changed Siglec-15 binding to human T cells [PMID:37311743]. Effect on signalling is not reported in our evidence (the curator labelled it agonist).","molecular_requirements":"A functional sialic-acid-binding domain is needed: the Siglec-15 R143A mutant bound CD11b much less [PMID:37311743]. CD11b and CD18 form a heterodimer; the assays used CD11b/CD18, so CD18 may be co-required, which is not tested separately in our evidence [PMID:37311743].","affinity_potency":[],"species_and_systems":"Human Siglec-15 and human T cells (CD4+, CD8+, n = 4 to 6 donors), plus recombinant proteins and STD-NMR [PMID:37311743]. Mouse pair is projected from human.","localisation_and_range":"Siglec-15 is annotated as membrane-bound [flag]; binding to CD11b is via sialylated N-glycans on T cells, so likely contact-dependent, but range is not tested.","caveats":"Single paper; the curator read only the abstract, though full-text excerpts are present. Binding depends on sialoglycans, and the interaction is a lectin-glycan one rather than a protein-protein one. No affinity reported.","key_references":[{"PMID":"37311743","why":"Siglec-15 binds CD11b/CD18 by ELISA, co-IP, STD-NMR and T-cell blocking assays"}],"covers":["LR003307","LR006521"]},"LR003308":{"pair":"SIGLEC9 -> MUC1","headline":"Two human studies support sialic-acid-dependent SIGLEC9 binding to MUC1 with downstream signalling; no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Soluble Siglec-9 bound MUC1 and drove beta-catenin recruitment to the MUC1 C-terminal domain and cell growth [PMID:24045940]. Cancer-type sialylated MUC1 (MUC1-ST) engaging Siglec-9 made myeloid cells release tumour-microenvironment factors and induced a TAM-like, PD-L1-high phenotype, with calcium flux and MEK-ERK activation instead of SHP-1/SHP-2 activation [PMID:27595232].","molecular_requirements":"Sialic acid is required: neuraminidase almost completely abolished the Siglec-9 effect [PMID:24045940], and non-sialylated MUC1-T failed to induce secretion [PMID:27595232]. Siglec-9 was the strongest of Siglecs-3, 7, 9 and 10 for MUC1-ST binding [PMID:27595232].","affinity_potency":[],"species_and_systems":"Human cells: MUC1-transfected mouse 3T3 and human HCT116 cells with recombinant Siglec-9 and HEK293 co-culture [PMID:24045940]; primary human monocytes/macrophages and T47D cells [PMID:27595232].","localisation_and_range":"MUC1 is flagged as secreted [flag]; the papers use membrane MUC1 on tumour cells and recombinant MUC1-ST, so both contact and soluble forms appear.","caveats":"Both curator reads were abstract-only. The anti-Siglec-9 antibody used can also act as an activating antibody [PMID:27595232]. Binding depends on glycoform, not just the protein.","key_references":[{"PMID":"24045940","why":"Siglec-9 binds MUC1 and triggers beta-catenin recruitment, sialic-acid dependent"},{"PMID":"27595232","why":"MUC1-ST engages Siglec-9 on myeloid cells; non-canonical activating signalling"}],"covers":["LR003308"]},"LR005315":{"pair":"SLIT3 -> ROBO1","headline":"SLIT3-ROBO1 is supported by mouse knockout phenotypes and co-expression; direct binding not shown in the papers' abstracts.","interaction_type":"functional only","direction_and_effect":"Slit3 and Robo1 knockout mice both show osteopenia, and osteoclast-secreted SLIT3 stimulates osteoblast migration and proliferation via beta-catenin [PMID:29504949]. In endothelial cells Robo1 is named a cognate receptor, but the migration effect is attributed to Robo4 [PMID:19741192].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse knockouts, human circulating SLIT3 association and ovariectomy rescue [PMID:29504949]; mouse endothelial cells [PMID:19741192]. Dossier covers human and mouse pairs.","localisation_and_range":"SLIT3 secreted; autocrine and paracrine, from osteoclasts or endothelial/smooth muscle cells [PMID:29504949][PMID:19741192].","caveats":"Both papers abstract only. PMID:19741192 does not test Robo1 separately. Reactome lists a ROBO1:SLIT3 complex [DB:Reactome]; UniProt records cited concern SLIT1/SLIT2 [DB:UniProt].","key_references":[{"PMID":"29504949","why":"Slit3 and Robo1 knockout osteopenia"},{"PMID":"19741192","why":"Slit3 angiogenesis; Robo1/Robo4 expression"}],"covers":["LR001986","LR005315"]},"LR005324":{"pair":"SLITRK6 -> PTPRS","headline":"SLITRK6-PTPsigma is supported by a knockdown/rescue synapse assay; binding not directly shown.","interaction_type":"functional only","direction_and_effect":"Knockdown of PTPsigma substrates (N-cadherin, p250RhoGAP) or liprin-alpha2/3 in neurons inhibited Slitrk6-induced, PTPsigma-mediated heterologous synapse formation [PMID:29934346].","molecular_requirements":"Intracellular PTPsigma partners are needed downstream; the receptor-side requirements for binding are not reported in our evidence [PMID:29934346].","affinity_potency":[],"species_and_systems":"Cultured rat hippocampal neurons [PMID:29934346]. Both pairs ortholog-inferred.","localisation_and_range":"Trans-synaptic; SLITRK6 flagged transmembrane [flag].","caveats":"Abstract only; the paper tests downstream pathway components, not binding. Four review-only rows not shown.","key_references":[{"PMID":"29934346","why":"Slitrk6-induced PTPsigma synapse assay"}],"covers":["LR001995","LR005324"]},"LR006530":{"pair":"SLPI -> ANXA2","headline":"SLPI binds annexin A2 (annexin II) on human macrophages by co-immunoprecipitation; a second paper reports an interaction from abstract only.","interaction_type":"direct binding","direction_and_effect":"SLPI acts as an antagonist: it disrupts the HIV-1 phosphatidylserine-annexin II interaction that supports macrophage infection [PMID:15545357]. In oral squamous cell carcinoma work, SLPI interacting with annexin A2 inhibits plasminogen activation and reduces plasmin generation [PMID:21641406].","molecular_requirements":"Annexin II was identified as the 36 kD SLPI-binding protein by LC-MS/MS and confirmed by coimmunoprecipitation; a ~42 kD band was actin, which associates with annexin II in a trimolecular complex rather than binding SLPI directly [PMID:15545357]. No other subunits reported in our evidence.","affinity_potency":[],"species_and_systems":"Human SLPI and human annexin II in primary human macrophages and monocytes [PMID:15545357]; human macrophages and OSCC cell lines [PMID:21641406]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted and annexin A2 is also flagged secreted [flag]. Binding occurs at the macrophage cell surface membrane [PMID:15545357].","caveats":"The curator read both papers from abstract level; the second paper's interaction claim comes from the abstract only [PMID:21641406]. Annexin II binding was higher on macrophages than monocytes and absent on the U937 line [PMID:15545357]. The authors say additional SLPI targets are not ruled out [PMID:15545357]. Annexin A2 is not a classical signalling receptor, and no downstream signalling is reported in our evidence.","key_references":[{"PMID":"15545357","why":"Co-IP and mass spectrometry identify annexin II as the SLPI membrane-binding protein on human macrophages"},{"PMID":"21641406","why":"SLPI-annexin A2 interaction inhibits plasminogen activation in OSCC (abstract only)"}],"covers":["LR003316","LR006530"]},"LR003317":{"pair":"SLURP2 -> CHRM1","headline":"SLURP-2 allosterically interacts with human M1 muscarinic receptor overexpressed in CHO cells; a single paper, with limited detail on this receptor.","interaction_type":"direct binding","direction_and_effect":"The paper reports an allosteric interaction with M1 and M3 muscarinic receptors; the direction of effect is not reported in our evidence [PMID:27485575]. UniProt states SLURP-2 interacts with CHRM1 and CHRM3 probably in an allosteric manner [DB:UniProt]. Muscarinic involvement in keratinocyte growth is called probable [PMID:27485575].","molecular_requirements":"Not reported in our evidence for CHRM1.","affinity_potency":[],"species_and_systems":"Human M1 overexpressed in CHO cells; recombinant SLURP-2; keratinocyte work used the human oral line Het-1A [PMID:27485575].","localisation_and_range":"SLURP2 is flagged secreted [flag]. Described as a secreted protein with auto/paracrine activity [PMID:27485575].","caveats":"The excerpts show no M1 binding data; they show atropine-sensitive effects on keratinocyte growth. The paper's main targets are nAChRs, where SLURP-2 acts at multiple subtypes. The UniProt entry rests on the same paper [DB:UniProt].","key_references":[{"PMID":"27485575","why":"Reports allosteric interaction of SLURP-2 with M1 and M3 mAChRs in CHO cells"}],"covers":["LR003317"]},"LR008402":{"pair":"SMOC1 -> SMOC2","headline":"SMOC1 binds SMOC2 ectodomain by SPR in a receptor-deorphanisation screen; SMOC2 has no established receptor role here.","interaction_type":"direct binding","direction_and_effect":"SMOC1 binding to SMOC2 was observed by SPR with SMOC2 ECD captured on a sensor and SMOC1 as analyte [PMID:36178190]. No signalling effect or direction is reported in our evidence.","molecular_requirements":"SMOC2 extracellular domain was used; other requirements not reported. The same table lists SMOC1-SMOC1 binding, so SMOC1 may also self-associate [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human proteins, recombinant ectodomains in a CRISPRa screen with SPR validation; the screen listed SMOC2 as a hit in a single-pass (TM1) library [PMID:36178190].","localisation_and_range":"SMOC2 is flagged as both secreted and receptor [flag]; SMOC1 carries no secreted flag in our record [flag]. Both are likely extracellular matrix-associated, but this is not stated in our evidence.","caveats":"Pair looks like secreted protein-protein association rather than a classical ligand-receptor pair. No affinity or cell-based functional validation reported in the excerpts. One paper.","key_references":[{"PMID":"36178190","why":"CRISPRa screen with SPR showing SMOC1 binding to SMOC2"}],"covers":["LR008402"]},"LR003326":{"pair":"SNCA -> APLP1","headline":"Pathologic alpha-synuclein fibrils bind Aplp1-transfected cells with Kd 430 nM; monomer does not bind; one paper.","interaction_type":"direct binding","direction_and_effect":"Alpha-syn pre-formed fibrils (PFF) bind Aplp1 in a saturable manner in a cell-surface binding assay [PMID:38821932]. Aplp1 interacts with Lag3 and the pair facilitates binding, internalization, transmission and toxicity of pathologic alpha-syn; anti-Lag3 blocks internalization by disrupting Aplp1-Lag3 interaction [PMID:38821932].","molecular_requirements":"The binding ligand is the fibrillar form; the curator note says the monomer does not bind [PMID:38821932]. Aplp1 works together with Lag3 for transmission [PMID:38821932].","affinity_potency":[{"value":"Kd 430 nM","assay":"cell-surface binding assay with biotinylated alpha-syn PFF","system":"Aplp1-transfected SH-SY5Y cells","cite":"PMID:38821932"}],"species_and_systems":"Aplp1-transfected SH-SY5Y cells, in vitro; in vivo knockout models in the same paper [PMID:38821932]. The mouse pair is the directly curated one; the human pair is projected from it.","localisation_and_range":"SNCA is flagged secreted and APLP1 secreted and receptor [flag]. The effect concerns cell-to-cell transmission of fibrils [PMID:38821932].","caveats":"Applies to fibrillar alpha-synuclein only, not the monomer. Binding was measured on cells, not purified proteins. The excerpt writes the constant as '15Kd of 430 nM' [PMID:38821932]. Human pair is ortholog-inferred.","key_references":[{"PMID":"38821932","why":"Aplp1 binds alpha-syn PFF and interacts with Lag3"}],"covers":["LR003326","LR006533"]},"LR005333":{"pair":"SPON1 -> LRP8","headline":"F-spondin effect on migration depends on LRP8 knockdown in one cell study; functional only.","interaction_type":"functional only","direction_and_effect":"The suppressive effect of F-spondin on M-CSF-induced migration was blocked by knockdown of LRP8 and by RAP, a pan-LDL-receptor-family antagonist [PMID:21488757]. Antagonist effect on migration; F-spondin also reduced RANKL-induced multinucleated cell formation.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse RAW 264 osteoclast precursor cells with recombinant F-spondin [PMID:21488757]. Both pairs are ortholog-inferred.","localisation_and_range":"F-spondin secreted, LRP8 transmembrane [flag].","caveats":"Abstract only; no binding data shown, so a direct interaction is inferred. No affinity. No database records.","key_references":[{"PMID":"21488757","why":"LRP8 knockdown blocks F-spondin suppression of migration"}],"covers":["LR002005","LR005333"]},"LR008231":{"pair":"SPON2 -> ITGA4:ITGB1","headline":"SPON2 signalling through alpha4beta1 integrin promotes macrophage recruitment in HCC; one abstract.","interaction_type":"functional only","direction_and_effect":"SPON2-alpha4beta1 integrin signalling activated RhoA and Rac1, increased F-actin reorganisation and promoted M1-like macrophage recruitment; F-actin accumulation then activated the Hippo pathway [PMID:29440144]. Agonist.","molecular_requirements":"The alpha4beta1 heterodimer is the receptor in this report [PMID:29440144].","affinity_potency":[],"species_and_systems":"Hepatocellular carcinoma tumour microenvironment; species per curator human [PMID:29440144].","localisation_and_range":"SPON2 flagged secreted [flag]; extracellular matrix protein acting on cell-surface integrin.","caveats":"Abstract only; physical binding not shown.","key_references":[{"PMID":"29440144","why":"SPON2-alpha4beta1 signalling in HCC macrophage recruitment"}],"covers":["LR008231"]},"LR004802":{"pair":"SPP1 -> ITGA9","headline":"Osteopontin binds alpha9beta1 via a non-RGD SVVYGLR sequence exposed by thrombin cleavage; three abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"alpha9-transfected cells adhere to an N-terminal osteopontin fragment and the SVVYGLR sequence directly binds alpha9beta1 [PMID:10593924]. Thrombin-cleaved OPN binds alpha9beta1 and alpha4beta1 to attract hemopoietic stem and progenitor cells [PMID:19417209].","molecular_requirements":"The thrombin-cleaved N-terminal fragment is a much better ligand than full-length osteopontin; alpha9beta1 does not use RGD; an MMP-predicted fragment did not support adhesion [PMID:16005200][PMID:10593924].","affinity_potency":[],"species_and_systems":"Human cells and proteins in adhesion assays (SW480, CHO, L-cells transfected with alpha9) [PMID:10593924]; murine and human HSCs [PMID:19417209].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; cleavage-dependent.","caveats":"All three papers are abstract-only; the binding is to a cleaved fragment, not necessarily full SPP1. Two further papers were abstract_insufficient.","key_references":[{"PMID":"10593924","why":"SVVYGLR sequence binds alpha9beta1"},{"PMID":"16005200","why":"Thrombin cleavage potentiates alpha9beta1; RGD-independent"},{"PMID":"19417209","why":"Thrombin-cleaved OPN and HSC migration via alpha9beta1"}],"covers":["LR001407","LR004802"]},"LR007061":{"pair":"SPP1 -> ITGAV:ITGB3","headline":"Osteopontin binds integrin alphavbeta3 at endometrial epithelium and supports RGD-dependent adhesion and migration; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Epithelial OPN binds alphavbeta3 at the maternal surface to support embryo adhesion at implantation [PMID:24442579]. Migration toward an osteopontin gradient depended on cell surface alphavbeta3 in smooth muscle cells [PMID:7532190].","molecular_requirements":"Adhesion of alphavbeta3-deficient cells to osteopontin was half that of alphavbeta3-containing cells; alphavbeta5 and alphavbeta1 also contribute [PMID:7532190].","affinity_potency":[],"species_and_systems":"Human Ishikawa endometrial cells with mouse and human blastocysts and OPN-coated beads [PMID:24442579]; human smooth muscle cells [PMID:7532190].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; epithelial surface adhesion context [PMID:24442579].","caveats":"Both papers abstract-only. The PMID:7532190 evidence sentence is background. Reactome records alphaVbeta3:SPP1 [DB:Reactome].","key_references":[{"PMID":"24442579","why":"OPN binds alphavbeta3 in implantation model"},{"PMID":"7532190","why":"alphavbeta3 required for migration to osteopontin"}],"covers":["LR007061"]},"LR001409":{"pair":"SPP1 -> ITGB1","headline":"Osteopontin binds integrin beta1 partners (alpha9beta1, alpha4beta1, alphavbeta1, alpha5beta1); several papers, mostly read as abstracts.","interaction_type":"direct binding","direction_and_effect":"Osteopontin acts as an agonist/adhesion ligand: thrombin-cleaved OPN binds alpha9beta1 and alpha4beta1 and acts as a chemoattractant for haemopoietic stem and progenitor cells [PMID:19417209]. SPP1 is reported to activate alpha5beta1 on nucleus pulposus cells, inhibiting mitophagy [PMID:39721032]. Spp1 is proposed to signal fibroblast-to-smooth-muscle cell via Itga8/Itgb1 [PMID:35414038].","molecular_requirements":"ITGB1 is the shared beta chain; the binding unit is an alpha/beta heterodimer (alpha9, alpha4, alphav, alpha5 or alpha8 named across papers). The N-terminal thrombin-cleaved OPN fragment is the active form for alpha9beta1 [PMID:19417209]; the SVVYGLR sequence is the alpha9beta1 site [PMID:10593924]; thrombin cleavage makes the fragment a much better ligand than full-length OPN for alpha9beta1 and alpha5beta1 [PMID:16005200]. Our curators note the data are stored per subunit [PMID:7592829].","affinity_potency":[{"value":"affinity 18 nM (Mn2+, alphavbeta1)","assay":"cell adhesion to GST-osteopontin","system":"HEK293 cells","cite":"PMID:7592829"}],"species_and_systems":"Human (HEK293, alpha9-transfected SW480/CHO/L-cells, human and murine haemopoietic cells); rat nucleus pulposus cells and a mouse Marfan model for the functional papers [PMID:7592829][PMID:10593924][PMID:19417209][PMID:39721032][PMID:35414038].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is described as an extracellular matrix protein acting on cell-surface integrins [PMID:7592829].","caveats":"Four of six papers were read as abstracts only. The integrin partner differs by paper, so beta1 alone does not define the complex. PMID:35414038 is a transcriptome/single-cell inference with limited direct testing. PMID:16005200 does not specify species. BioGRID lists a reconstituted complex [DB:BioGRID]; Reactome lists SPP1 with alpha5beta1, alpha9beta1 and alpha8beta1 [DB:Reactome].","key_references":[{"PMID":"7592829","why":"Adhesion via alphavbeta1 with 18 nM affinity"},{"PMID":"10593924","why":"Maps SVVYGLR recognition site for alpha9beta1"},{"PMID":"19417209","why":"Thrombin-cleaved OPN binds alpha9beta1/alpha4beta1"}],"covers":["LR001409","LR004804"]},"LR003335":{"pair":"SVEP1 -> ITGA4","headline":"SVEP1 binds integrin alpha4beta1 in one 2022 study; support is thin and abstract-level.","interaction_type":"direct binding","direction_and_effect":"SVEP1 was found to directly bind integrin alpha4beta1 [PMID:35802072]. In that study inhibition of SVEP1 or its integrins enhanced vasoconstrictor-induced calcium; UniProt summarises that ITGA4:ITGB1 via SVEP1 represses calcium influx and inhibits vasocontraction [DB:UniProt].","molecular_requirements":"The partner is the alpha4beta1 heterodimer (ITGA4 with ITGB1) [PMID:35802072][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human iPSC-derived vascular smooth muscle cells plus Svep1+/- mouse wire myography [PMID:35802072]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 is flagged secreted [flag], consistent with an extracellular matrix ligand.","caveats":"One paper, read as abstract only; the binding result is a side finding reported as 'additionally found', and the functional effects are not separated by integrin. Only the alpha chain is paired here; the beta1 chain is a separate dossier.","key_references":[{"PMID":"35802072","why":"SVEP1 binds alpha4beta1 and alpha9beta1 and regulates VSMC contraction"}],"covers":["LR003335","LR006542"]},"LR004811":{"pair":"TAC1 -> TACR2","headline":"Neurokinin A (TAC1) binds and activates the NK2 receptor (TACR2); supported by binding papers in human and rat, but all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"Agonist. NKA is described as the physiological peptide ligand of the NK2 receptor [PMID:7961636]; NKA(4-10) analogues act as agonists or partial agonists in human colon muscle [PMID:11137709]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence as a complex requirement. Mutagenesis of the human NK2 receptor identified Gln109, His198, Ile202 and Gly273 as critical for NKA binding [PMID:7961636]. In NKA(4-10), Asp4, Phe6, Val7, Leu9 and Met10 side chains matter for agonist activity [PMID:11137709].","affinity_potency":[{"value":"pKi 8.0-9.1","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK2 receptor mutants [PMID:7961636]; human colon circular muscle radioligand binding and contraction [PMID:11137709]; cultured rat anterior pituitary cells [PMID:12954451]. Structures of the complex are listed in PDB [DB:PDB 7XWO] [DB:PDB 9W1J]. The mouse pair is projected from human evidence.","localisation_and_range":"TAC1 is flagged secreted and TACR2 as a transmembrane receptor [flag], so signalling is expected to be paracrine or endocrine onto a membrane GPCR; this comes from annotation flags only.","caveats":"All papers were read as abstracts only. In rat pituitary cells NKA only fitted a two-site model with high and low affinity and the [3H]SR48968 binding had lower affinity than typical NK2-expressing cells [PMID:12954451]. Binding in that study used a labelled antagonist, not NKA itself. PMID 11786503 concerns hemokinin-1, with NKA only as tracer, and reports Ki=560 nM for hemokinin-1 at human NK2, not for NKA.","key_references":[{"PMID":"7961636","why":"Mutagenesis mapping of NKA binding residues in human NK2 receptor"},{"PMID":"11137709","why":"NKA(4-10) binding and function in human colon"},{"PMID":"12954451","why":"NKA displaces antagonist binding in rat pituitary cells"}],"covers":["LR001416","LR004811"]},"LR001418":{"pair":"TAC3 -> TACR1","headline":"NKB (TAC3) vasodilates human placenta via NK1 (TACR1), a functional cross-reactivity result from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Agonist-like vasodilation. NKB dilated the fetal vasculature in the perfused human placental cotyledon and selective receptor antagonists localised this to the NK(1) receptor [PMID:12727971].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"EC 1.89 nM","assay":"effective concentration in the circulation for NKB bolus","system":"perfused human placental cotyledon","cite":"PMID:12727971"},{"value":"pKi 6.1-6.4","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Ex vivo perfused human placenta [PMID:12727971].","localisation_and_range":"The paper describes NKB as a paracrine modulator in a non-innervated organ [PMID:12727971]; TAC3 flagged secreted [flag].","caveats":"No binding data; abstract only; antagonist localisation is indirect. The curators note NKB usually prefers NK3, and NK3 mRNA was not detected in placenta here [PMID:12727971]. RT-PCR found NK1 and NK2 mRNA.","key_references":[{"PMID":"12727971","why":"NKB vasodilation through NK1 in human placenta"}],"covers":["LR001418"]},"LR003344":{"pair":"TAFA2 -> ADGRL1","headline":"TAFA2 directly binds the lectin-like domain of ADGRL1 and is anti-apoptotic via cAMP/PKA/CREB/BCL2; abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. TAFA2 directly binds the lectin-like domain of ADGRL1, activating cAMP/PKA/CREB/BCL2 signalling that prevents cell death; recombinant TAFA2 suppressed apoptosis induced by ADGRL1 overexpression [PMID:37944639].","molecular_requirements":"The Lectin-like domain is required: ADGRL1 delta-Lec did not induce apoptosis or support TAFA2 responses [PMID:37944639].","affinity_potency":[],"species_and_systems":"Co-IP and mass spectrometry in V5 knockin mouse brain lysates, then in vitro and in vivo co-IP and pull-down, with knockout and overexpression cells [PMID:37944639].","localisation_and_range":"TAFA2 flagged secreted and ADGRL1 transmembrane [flag].","caveats":"Abstract only; one paper; no affinity reported; no database records. Species of the cells beyond mouse brain lysates is not reported in our evidence.","key_references":[{"PMID":"37944639","why":"TAFA2 binds ADGRL1 lectin-like domain and signals via cAMP/PKA/CREB"}],"covers":["LR003344","LR006551"]},"LR005342":{"pair":"TAFA4 -> FPR1","headline":"FAM19A4/TAFA4 is reported as an FPR1 agonist from one 2015 paper (abstract only), single-source.","interaction_type":"direct binding","direction_and_effect":"FAM19A4 was reported as a novel FPR1 ligand based on receptor internalization, radioligand binding and receptor blockage, with chemotaxis of macrophages, enhanced zymosan phagocytosis and ROS release [PMID:25109685]. Curators label it an agonist [PMID:25109685].","molecular_requirements":"Mature FAM19A4 is a 95-amino-acid protein [PMID:25109685]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and macrophages; in vitro and in vivo phagocytosis [PMID:25109685]. UniProt records for both proteins cite this paper [DB:UniProt].","localisation_and_range":"TAFA4 annotated secreted, FPR1 transmembrane receptor [flag].","caveats":"Paper read as abstract only; no affinity or independent replication in our evidence. UniProt support derives from the same paper [DB:UniProt].","key_references":[{"PMID":"25109685","why":"Reports FAM19A4 as FPR1 ligand with binding, internalization and macrophage assays"}],"covers":["LR002014","LR005342"]},"LR003353":{"pair":"TAFA5 -> FPR2","headline":"FAM19A5/TAFA5 acts through FPR2 in mouse macrophages and FPR2-expressing cells; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"FAM19A5 elicited chemotaxis of FPR2-expressing RBL-2H3 cells but not vector or FPR1 cells [PMID:29138422]. In mouse BMDMs, FAM19A5 inhibited RANKL-induced osteoclast formation, reversed by the FPR2 antagonist WRW4 or FPR2 deficiency, but not by the FPR1 antagonist cyclosporin H [PMID:29138422]. Curators label it an agonist [PMID:29138422].","molecular_requirements":"FPR2 alone suffices in RBL-2H3 cells; the effect is pertussis-toxin sensitive, consistent with G-protein signalling [PMID:29138422].","affinity_potency":[{"value":"2 \u00b5M","assay":"FAM19A5 concentration used in chemotaxis and osteoclast assays (not an EC50)","system":"mouse BMDMs, RBL-2H3 cells","cite":"PMID:29138422"}],"species_and_systems":"Mouse BMDMs, FPR2 knockout mice, RBL-2H3 cells expressing FPR1/FPR2 [PMID:29138422]. Human pair is projected from mouse evidence.","localisation_and_range":"FAM19A5 described as a brain-specific chemokine and annotated secreted [flag].","caveats":"Direct binding was not shown in the evidence we hold; the paper reads as a functional/antagonist-reversal study and was read as abstract plus excerpts [PMID:29138422].","key_references":[{"PMID":"29138422","why":"FPR2 antagonism and deficiency reverse FAM19A5 effects on macrophages"}],"covers":["LR003353","LR006556"]},"LR003362":{"pair":"TENM4 -> ADGRL2","headline":"Cell-aggregation evidence that teneurin-4 cells adhere to latrophilin-expressing cells; no binding data for ADGRL2 specifically.","interaction_type":"functional only","direction_and_effect":"Cells expressing Lphn1/2/3 formed large aggregates with cells expressing Ten2 or Ten4, indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Binding is mapped to the lectin-like domain of latrophilins in the abstract; ADGRL2 specific requirements are not reported in our evidence [PMID:24273166].","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay; species unspecified. The human pair and the mouse pair are both ortholog-inferred [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag]; the adhesion assay is consistent with contact-dependent interaction.","caveats":"The aggregation assay does not distinguish ADGRL2 from the other latrophilins in the abstract-level evidence. Pulldown binding in the same paper is described in our evidence for Lphn1 only. The curator quote is a browser read, unverifiable, spot-check pending.","key_references":[{"PMID":"24273166","why":"Latrophilin cells aggregate with Ten4 cells"}],"covers":["LR003362","LR006565"]},"LR001436":{"pair":"TGFA -> ERBB2","headline":"Co-IP of TGF-alpha precursor splice forms with ERBB2 in CHO cells; an intracellular, isoform-specific interaction, not classic extracellular signalling.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation was seen for the VaI and VaII variants but not the others; precursor-ErbB signalling effect is not reported in our evidence [PMID:10918572].","molecular_requirements":"Interaction is mediated by the precursor's cytoplasmic C-terminal region, shown with chimeras and mutants [PMID:10918572].","affinity_potency":[],"species_and_systems":"CHO cells overexpressing human TGF-alpha precursors (WT, VaI, VaII); mouse pair is ortholog-inferred [PMID:10918572].","localisation_and_range":"Membrane-anchored precursor with intracellular C-terminal interaction [PMID:10918572]; ligand also annotated secreted [flag].","caveats":"The wild-type precursor did not co-immunoprecipitate with ErbB2, so the interaction is splice-variant specific. Co-IP cannot exclude a bridging partner. Abstract only.","key_references":[{"PMID":"10918572","why":"Co-IP of TGFalpha precursor forms with ErbBs"}],"covers":["LR001436","LR004831"]},"LR001445":{"pair":"TGFB1 -> TGFBR3","headline":"TGF-beta1 binds the betaglycan (TGFBR3) ectodomain directly by SPR; betaglycan is a co-receptor, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is described as a coreceptor without kinase activity that presents ligand to the signalling receptors (curator note), so TGFB1 -> TGFBR3 is accessory rather than signal-transducing [PMID:19842711]. Annotated as stimulatory [flag].","molecular_requirements":"Two independent ligand-binding regions lie in the betaglycan ectodomain (membrane-distal and membrane-proximal halves); fragments bind TGF-beta but neutralise it poorly, and tethering the domains gives high affinity [PMID:19842711]. The type III ectodomain bound two TGF-beta molecules in SPR [PMID:11382746]. Reactome lists TGFB1,TGFB2:TGFBR3 and a TGFBR3:TGFBR2 complex [DB:Reactome].","affinity_potency":[{"value":"Kd in the low nanomolar range","assay":"SPR, soluble betaglycan, three TGF-beta isoforms","system":"recombinant soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Human ligand and receptor in the 2009 SPR work; the soluble betaglycan was a rat recombinant form made in insect cells [PMID:19842711]. Species in the 2001 BIAcore study were unspecified [PMID:11382746]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted, betaglycan membrane-anchored [flag]; also a proteolytically released soluble form that can block TGF-beta [PMID:19842711].","caveats":"Both primary papers were abstract-judged by curators; the 2009 affinity is stated only qualitatively for TGF-beta isoforms in general. BioGRID, IntAct, GtoPdb, UniProt also assert the pair [DB:BioGRID].","key_references":[{"PMID":"11382746","why":"BIAcore kinetics of TGF-beta isoforms with type III ectodomain"},{"PMID":"19842711","why":"Two ligand-binding domains of betaglycan, SPR affinities"}],"covers":["LR001445","LR004840"]},"LR007430":{"pair":"TGFB2 -> ACVR1:TGFBR2","headline":"Complex row ACVR1:TGFBR2 for TGF-beta2 rests on records for TGFBR2 alone; nothing in our evidence supports ACVR1 here.","interaction_type":"database-asserted only","direction_and_effect":"TGFB2 binds TGFBR2: BioGRID affinity capture-western [DB:BioGRID], GtoPdb agonist [DB:GtoPdb], and a TGF-beta2 / TGFBR2 ectodomain structure [DB:PDB 5TX4]. UniProt says TGFBR2 binds TGFB1-3 in the picomolar range without additional receptors [DB:UniProt].","molecular_requirements":"UniProt describes a heterohexamer of TGFBR1 and TGFBR2 [DB:UniProt]; ACVR1 is not mentioned in these records.","affinity_potency":[],"species_and_systems":"PDB 5TX4 is an engineered mouse TGF-beta2 derivative with human TGFBR2 ectodomain 15-130 [DB:PDB 5TX4].","localisation_and_range":"Receptor complex flagged transmembrane [flag].","caveats":"No papers; one review-only and one different-entity judgement. ACVR1 contribution not shown.","key_references":[],"covers":["LR007430"]},"LR001454":{"pair":"TGM2 -> ADGRG1","headline":"TGM2 (tissue transglutaminase) binds GPR56 (ADGRG1) in a melanoma study and is listed in UniProt; effect reported as tumour-suppressive.","interaction_type":"direct binding","direction_and_effect":"GPR56 binds specifically to TG2; GPR56 overexpression suppresses melanoma tumour growth and metastasis [PMID:16757564]. The curator labels this antagonist-like.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma cell lines [PMID:16757564]. The human pair is ortholog-inferred, as is the mouse pair.","localisation_and_range":"TG2 is a stromal component, and the abstract suggests GPR56 acts via the tumour microenvironment in vivo [PMID:16757564]. TGM2 is flagged secreted [flag].","caveats":"One paper, abstract only. No binding affinity is reported. UniProt cites the same paper and two others for the interaction [DB:UniProt]. The ADGRG1 entity is flagged secreted as well as transmembrane [flag].","key_references":[{"PMID":"16757564","why":"GPR56 binds TG2 and suppresses melanoma growth"}],"covers":["LR001454","LR004849"]},"LR003380":{"pair":"TGM2 -> LRP6","headline":"TG2 binds the LRP6 extracellular domain and activates beta-catenin signalling; supported by one abstract.","interaction_type":"direct binding","direction_and_effect":"TG2 functions as an activating ligand of LRP5/6 and synergizes with LRP6 in beta-catenin gene expression in Cos-7 cells [PMID:23993960]. Interfering with LRP5/6 attenuates TG2-induced activation [PMID:23993960].","molecular_requirements":"TG2 binds directly to the extracellular domain of LRP6, which is also a substrate for TG2 cross-linking; cross-linking inhibitors quench activation [PMID:23993960].","affinity_potency":[],"species_and_systems":"Cos-7 cells; species not stated in the abstract [PMID:23993960]. The human pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; the ligand acts on the LRP6 extracellular domain [PMID:23993960].","caveats":"Abstract-only read. An earlier paper was judged pair_absent for LRP6 (it names LRP5) [PMID:18405667]. No affinity is reported.","key_references":[{"PMID":"23993960","why":"TG2 binds the LRP6 extracellular domain and activates beta-catenin"}],"covers":["LR003380","LR006581"]},"LR001463":{"pair":"THBS1 -> CD47","headline":"Well-supported direct THBS1-CD47 interaction, with binding and functional evidence from several papers.","interaction_type":"direct binding","direction_and_effect":"THBS1 is described as a receptor ligand for CD47: cells expressing CD47 bind THBS1 and its C-terminal cell-binding domain, and CD47-negative cells do not [PMID:8550562]. Effects are mixed by context: agonist-like platelet activation via the CD47 peptide 4N1K [PMID:9169439], but inhibition of NO-stimulated cGMP signalling in vascular smooth muscle cells [PMID:19004835] and of T cell antigen receptor signalling and proliferation [PMID:11980922]. Reported in GtoPdb as binding [DB:GtoPdb] and in UniProt [DB:UniProt].","molecular_requirements":"The THBS1 C-terminal signature/cell-binding domain carries the CD47 site [PMID:19004835][PMID:8550562]. CD47 associates with alphaVbeta3 [PMID:8550562] and with alphaIIbbeta3 and alpha2beta1 in platelets [PMID:9169439][PMID:10397731]. In T cells CD47 was not required for some THBS1 responses and contributed indirectly to others [PMID:11980922].","affinity_potency":[],"species_and_systems":"Human cells and recombinant domains in most papers; platelet aggregation dependence on CD47 was shown with platelets from CD47-null mice [PMID:10397731]. Human-mouse pair; no ortholog inference flagged.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"Four of the five papers were read as abstracts only. The platelet and T cell results show that effect direction depends on cell type and partner integrin. Some T cell responses to THBS1 used fragments lacking the CD47 site, so CD47 acted indirectly there [PMID:11980922]. No affinity values are reported in our evidence.","key_references":[{"PMID":"8550562","why":"Affinity labelling and antibody blocking identify CD47 as the THBS1 cell-binding-domain receptor"},{"PMID":"19004835","why":"THBS1 signature domain competes with SIRPalpha for CD47 and is more potent than TSP-2/-4"},{"PMID":"11980922","why":"CD47 drives the inhibitory T cell arm of THBS1 signalling (full text)"}],"covers":["LR001463","LR004858"]},"LR001472":{"pair":"THBS1 -> SDC4","headline":"Syndecan-4 is proposed as a receptor for the THBS1 N-terminal domain, mediating pro-angiogenic tubulogenesis; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"An anti-syndecan-4 monoclonal antibody blocks TSP18-induced tubulogenesis, and TSP18 and derived peptides activate PKC-dependent Akt-PKB signalling [PMID:17879962]. Agonist-like pro-angiogenic effect.","molecular_requirements":"The N-terminal fragment (residues 1-174, TSP18) and two sequences, TSP Hep I and II, retain activity and compete with fibronectin Hep II for syndecan-4 binding on endothelial cells [PMID:17879962].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells with recombinant human THBS1 fragments [PMID:17879962].","localisation_and_range":"THBS1 flagged secreted [flag]; fragments used as coated substrates [PMID:17879962].","caveats":"Abstract only; the fragment, not full-length THBS1, was tested; binding was inferred from antibody inhibition and competition with endothelial cell extracts. One other row abstract_insufficient. No database records.","key_references":[{"PMID":"17879962","why":"Syndecan-4 as receptor for THBS1 N-terminal domain"}],"covers":["LR001472","LR004867"]},"LR006602":{"pair":"TIMP1 -> ITGB1","headline":"Database-only claim that TIMP-1 acts via integrin beta1; no curated paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TIMP1 activates signalling through CD63 and ITGB1 and is found in a complex with CD63 and ITGB1 [DB:UniProt].","molecular_requirements":"The UniProt complex includes CD63 [DB:UniProt]; whether ITGB1 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"TIMP1 is flagged secreted and ITGB1 as a receptor [flag].","caveats":"Two papers were judged abstract_insufficient, so no paper is confirmed. Support rests on UniProt annotation alone [DB:UniProt].","key_references":[],"covers":["LR003401","LR006602"]},"LR001481":{"pair":"TIMP3 -> KDR","headline":"TIMP-3 blocks VEGF binding to KDR in vitro, an antagonist action; supported by a full-text paper and UniProt.","interaction_type":"functional only","direction_and_effect":"TIMP3 inhibited VEGF-mediated angiogenesis by blocking VEGF binding to VEGF receptor-2 and reducing downstream signalling, independent of MMP inhibition; the authors conclude it specifically and competitively inhibits VEGF binding to KDR [PMID:12652295]. UniProt says it interacts directly with KDR to prevent VEGFA binding [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Specific cell or species not reported in our evidence for the curated row [PMID:12652295]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 flagged secreted; KDR flagged transmembrane receptor [flag].","caveats":"Curated as functional rather than direct binding; the competitive-inhibition claim is the authors' conclusion. Only one paper is in the dossier. TIMP3 here is an antagonist of VEGF binding, not an activating ligand.","key_references":[{"PMID":"12652295","why":"TIMP3 blocks VEGF binding to KDR"}],"covers":["LR001481","LR004876"]},"LR003407":{"pair":"TIMP3 -> MMP2","headline":"TIMP-3 binds gelatinase A (MMP-2) with rapid association; inhibitor-enzyme interaction with database structural support.","interaction_type":"direct binding","direction_and_effect":"TIMP-3 showed rapid association with gelatinases A and B, and isolated complexes on gelatin-agarose showed TIMP-3 binds both proenzymes [PMID:10196161]. The curated effect is antagonist, i.e. inhibition of the enzyme [PMID:10196161].","molecular_requirements":"The hemopexin domain of gelatinase A contributes to the interaction; residues 568-631 of gelatinase A were required for rapid association [PMID:10196161].","affinity_potency":[],"species_and_systems":"In vitro biochemical assay with purified proteins (human); human and mouse pairs are both ortholog-inferred [PMID:10196161].","localisation_and_range":"MMP2 is flagged secreted [flag], and TIMP-3 is sequestered in the extracellular matrix per the authors [PMID:10196161].","caveats":"Abstract-only, no affinity value in the dossier. Enzyme-inhibitor interaction rather than signalling; MMP2 receptor status is a flag annotation.","key_references":[{"PMID":"10196161","why":"TIMP-3 association with gelatinases"}],"covers":["LR003407","LR006608"]},"LR006611":{"pair":"TNC -> FN1","headline":"Tenascin-C binds fibronectin directly, but this is a matrix-matrix interaction rather than a cell-surface receptor pair.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C binds the 13th fibronectin type III repeat (FNIII13) and thereby interferes with syndecan-4 binding to the HepII site of fibronectin, impairing adhesion and increasing tumor-cell proliferation [PMID:11731446]. Binding is not a signalling agonist action on FN1.","molecular_requirements":"FNIII13 of fibronectin is the binding site; adhesion and proliferation were restored by adding FNIII13 [PMID:11731446].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator record; glioblastoma and breast carcinoma cells [PMID:11731446]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted [flag]; interaction occurs in the extracellular matrix.","caveats":"Curator notes this is a matrix-matrix interaction, not a classical receptor [PMID:11731446]. Abstract-only read. BioGRID lists reconstituted complex and affinity capture records, and Reactome a binding reaction [DB:BioGRID][DB:Reactome]. Relevance as a CCC signalling pair is doubtful.","key_references":[{"PMID":"11731446","why":"Direct tenascin-C binding to FNIII13 of fibronectin"}],"covers":["LR003410","LR006611"]},"LR001490":{"pair":"TNC -> PTPRB","headline":"The FNIII domain of RPTPbeta binds tenascin C in human glial tumor cells; abstract-only, nomenclature caveat.","interaction_type":"direct binding","direction_and_effect":"Affinity purification with the RPTPbeta FNIII domain isolated a 240 kDa protein identified as tenascin C; a soluble FNIII fragment abolished adhesion and spreading of RPTPbeta-expressing astrocytoma cells on TNC [PMID:11313993].","molecular_requirements":"Binding maps to alternatively spliced FNIII repeats A1,2,4 of tenascin C [PMID:11313993].","affinity_potency":[],"species_and_systems":"Human glioblastoma U118MG cells (source of tenascin C), SF763T astrocytoma cells and COS cells [PMID:11313993].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only. Curator notes 'RPTPbeta' is ambiguous between PTPRB and PTPRZ1.","key_references":[{"PMID":"11313993","why":"RPTPbeta FNIII domain binds tenascin C"}],"covers":["LR001490","LR004885"]},"LR005351":{"pair":"TNFRSF14 -> BTLA","headline":"HVEM (TNFRSF14) binds BTLA directly, with structural and binding studies; BTLA signals as an inhibitory receptor.","interaction_type":"direct binding","direction_and_effect":"HVEM was identified as the unique BTLA ligand, and HVEM engagement induced BTLA tyrosine phosphorylation and SHP-2 recruitment and repressed antigen-driven T cell proliferation [PMID:15568026]. Binding of HVEM to BTLA attenuates T cell activation, making it a coinhibitory pair [PMID:15647361]. An HVEM-based mutein acts as a selective BTLA agonist [PMID:29061848].","molecular_requirements":"BTLA bound the most membrane-distal cysteine-rich domain of HVEM, separate from the LIGHT and lymphotoxin-alpha sites [PMID:15568026]. HVEM can form a ternary complex with BTLA and either LIGHT or lymphotoxin alpha [PMID:15647361], and with LIGHT and CD160 [PMID:34709351]. BTLA and CD160 cross-compete for HVEM [PMID:29061848].","affinity_potency":[],"species_and_systems":"Human proteins in the binding papers [PMID:15647361]; the BTLA-HVEM interaction is described as conserved between mouse and human [PMID:15568026]. Crystal structures plus mouse knockin muteins were used [PMID:34709351]. PDB structure 2AW2 [DB:PDB 2AW2]. A mouse pair was projected from human evidence.","localisation_and_range":"HVEM is flagged membrane-bound (not secreted) and BTLA also membrane-bound [flag], so signalling needs cell contact; BTLA may act in cis or trans [DB:UniProt][PMID:19915044].","caveats":"Most papers were read as abstract only. The affinity is described as high but no value is in our evidence [PMID:15647361]. HVEM has other ligands (LIGHT, lymphotoxin alpha, CD160), so BTLA effects must be separated from those [PMID:34709351]. HVEM is the listed ligand, though it is also a TNF-family receptor.","key_references":[{"PMID":"15568026","why":"Identified HVEM as the BTLA ligand and mapped the binding domain"},{"PMID":"15647361","why":"HVEM binds BTLA with high affinity; ternary complex"},{"PMID":"34709351","why":"HVEM structures and muteins separate LIGHT and BTLA/CD160 functions"}],"covers":["LR002023","LR005351"]},"LR003416":{"pair":"TNFSF13 -> SDC1","headline":"APRIL binds heparan sulfate proteoglycans on tumour cells; syndecan-1 transfectants bind more APRIL, but the effect runs through heparan sulfate chains.","interaction_type":"direct binding","direction_and_effect":"APRIL specifically binds heparan sulfate proteoglycans on tumour cells through the heparan sulfate chains, and this is inhibited by heparin; the interaction is crucial for APRIL's tumour growth-promoting activity but does not affect APRIL-induced T-cell proliferation [PMID:15846369]. Syndecan-1-transfected Namalwa cells showed higher binding than CD44 variant cells [PMID:15846369]. Role: co-receptor-like, not a signalling receptor.","molecular_requirements":"BCMA and HSPG can bind APRIL simultaneously. A mutation of three lysines in a putative heparan sulfate-binding motif destroys HSPG binding while BCMA binding is unaffected [PMID:15846369].","affinity_potency":[],"species_and_systems":"Tumour cells and transfectants; the species of the experiments is not stated in our evidence [PMID:15846369].","localisation_and_range":"APRIL is flagged secreted; syndecan-1 carries secreted and transmembrane flags [flag]. Interaction is with heparan sulfate side chains.","caveats":"The authors conclude HSPG either serve as a receptor or let APRIL reach another receptor [PMID:15846369]. The binding is mediated by sugar chains shared among proteoglycans, so specificity for syndecan-1 itself is not shown. Seven other papers were abstract_insufficient.","key_references":[{"PMID":"15846369","why":"APRIL binding to HSPG and syndecan-1 transfectants"}],"covers":["LR003416","LR006617"]},"LR001508":{"pair":"TNFSF15 -> TNFRSF25","headline":"TL1A is a ligand for DR3; one abstract-only paper with functional data plus databases.","interaction_type":"functional only","direction_and_effect":"TL1A is a ligand for DR3; it induces NF-kappaB activation and apoptosis in DR3-expressing cell lines, antagonised by TR6-Fc, and costimulates primary T cells, increasing IL-2 responsiveness and proinflammatory cytokine secretion in vitro and in vivo [PMID:11911831].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell lines and primary T cells; species not stated beyond annotation; abstract only [PMID:11911831].","localisation_and_range":"TNFSF15 flagged secreted and transmembrane; TNFRSF25 transmembrane [flag].","caveats":"Abstract only; TR6/DcR3 neutralises TL1A [PMID:11911831]. BioGRID, Reactome, UniProt, IntAct and GtoPdb records also exist [DB:BioGRID][DB:Reactome][DB:UniProt].","key_references":[{"PMID":"11911831","why":"TL1A is a DR3 ligand and costimulates T cells"}],"covers":["LR001508","LR004898"]},"LR004901":{"pair":"TNFSF8 -> TNFRSF8","headline":"CD153 binds CD30 with Kd 23 nM; two abstract-only papers plus databases.","interaction_type":"direct binding","direction_and_effect":"Soluble trimeric CD153 bound membrane-anchored CD30 and triggered cell death and TNF-alpha production with cross-linking antibodies [PMID:11754357]. Soluble CD30 blocks cell-death signals from surface CD30 [PMID:11754357].","molecular_requirements":"Trimeric ligand was used; soluble monomeric CD30 binds with high affinity and acts as a decoy [PMID:11754357].","affinity_potency":[{"value":"KD = 23 nM","assay":"soluble trimeric CD153 binding to membrane CD30","system":"cells","cite":"PMID:11754357"},{"value":"KD 4.5 nM","assay":"BIAcore, soluble CD30/CD153","system":"recombinant","cite":"PMID:11754357"}],"species_and_systems":"Species of 11754357 not stated in our evidence; murine CD30L cloned from T cell clone 7B9 [PMID:8391931].","localisation_and_range":"TNFSF8 flagged transmembrane, not secreted; TNFRSF8 transmembrane [flag].","caveats":"Abstracts only; one further pending paper not judged. Also BioGRID, GtoPdb, Reactome records [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"11754357","why":"Kd 23 nM binding and decoy CD30"},{"PMID":"8391931","why":"Expression cloning of CD30 ligand"}],"covers":["LR001511","LR004901"]},"LR001517":{"pair":"TSLP -> IL7R","headline":"TSLP acts through IL7R only as part of the TSLPR/IL-7Ralpha heterodimer; IL7R alone is insufficient.","interaction_type":"functional only","direction_and_effect":"Agonist: cells transfected with both receptor subunits proliferated in response to purified, recombinant human TSLP, with induced phosphorylation of Stat3 and Stat5 [PMID:11418668]. GtoPdb lists TSLP-IL7R as Agonist [DB:GtoPdb].","molecular_requirements":"Needs the heterodimer with TSLPR (CRLF2); the curator notes IL7R alone is insufficient [PMID:11418668].","affinity_potency":[],"species_and_systems":"Transfected cells, recombinant human TSLP [PMID:11418668]. Mouse pair ortholog-inferred.","localisation_and_range":"TSLP flagged secreted [flag].","caveats":"Chain-only pair: direct binding of TSLP to IL7R alone is not reported in our evidence; abstract read only. In CCC tools use the complex CRLF2:IL7R.","key_references":[{"PMID":"11418668","why":"TSLP responses need TSLPR and IL-7Ralpha together"}],"covers":["LR001517","LR004907"]},"LR003425":{"pair":"TULP1 -> AXL","headline":"Tulp1 binds Axl as one of three TAM receptors (Tyro3, Axl, MerTK); one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Axl-specific activation is not separately described in the abstract. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003425","LR006626"]},"LR003434":{"pair":"UNC5B -> FLRT3","headline":"UNC5B-FLRT3 is supported by direct binding in a mouse-protein screen plus BioGRID and UniProt records.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5B is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"Unc5B stripes gave no significant neuronal response (n=3/380, 1% repulsive) [PMID:26633812]. BioGRID records a reconstituted complex [DB:BioGRID, PMID:21673655] and UniProt records extracellular-domain interaction [DB:UniProt]. No affinity is reported.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"},{"PMID":"21673655","why":"Source of the BioGRID reconstituted-complex record (abstract states Unc5B was shown to bind FLRT3)"}],"covers":["LR003434","LR006635"]},"LR001526":{"pair":"UTS2 -> UTS2R","headline":"Urotensin-II is an established agonist of the UT (GPR14) receptor, with binding and calcium signalling in several species.","interaction_type":"direct binding","direction_and_effect":"Human and goby U-II bind recombinant human GPR14 with high affinity, coupled to calcium mobilisation [PMID:10499587]. Porcine UII, isolated from spinal cord, activated rat SENR (GPR14) with EC50 1 nM in arachidonic acid release [PMID:10548501]. GtoPdb and Reactome both record agonist binding [DB:GtoPdb, DB:Reactome]. UTS2B (URP) also binds and activates UT receptors, so the receptor is shared [PMID:14550283].","molecular_requirements":"UT is a single GPCR; no extra subunit is reported in our evidence. Reactome models the complex as UTSR with UTS2 or UTS2B [DB:Reactome].","affinity_potency":[{"value":"Kd 654 pM","assay":"[125I]human U-II saturation binding","system":"cloned mouse UT receptor","cite":"PMID:11976263"},{"value":"Kd 214 pM","assay":"[125I]human U-II saturation binding","system":"cloned monkey UT receptor","cite":"PMID:11976263"},{"value":"EC50 3.2 nM","assay":"human U-II intracellular Ca2+ rise","system":"mouse UT receptor","cite":"PMID:11976263"},{"value":"EC50 1.1 nM","assay":"human U-II intracellular Ca2+ rise","system":"monkey UT receptor","cite":"PMID:11976263"},{"value":"EC50 1 nM","assay":"arachidonic acid metabolite release by synthetic UII","system":"CHO cells expressing rat SENR","cite":"PMID:10548501"}],"species_and_systems":"Recombinant human GPR14 [PMID:10499587]; rat GPR14 in HEK293 [PMID:10581185]; mouse and monkey receptors with human U-II [PMID:11976263]; rat SENR with porcine UII [PMID:10548501]. The human UT receptor is not tested in the affinity paper.","localisation_and_range":"UTS2 is annotated as secreted and UTS2R as transmembrane [flag]; human U-II acts as a circulating vasoconstrictor on arteries [PMID:10499587].","caveats":"All papers were read as abstracts only. Affinity values come from non-human receptors. Our evidence lists 10 confirmed papers but only 6 are shown here; 1 is abstract_insufficient, 1 is review_only and 1 is pending.","key_references":[{"PMID":"10499587","why":"Human U-II binds and activates human GPR14"},{"PMID":"10548501","why":"UII identified as endogenous ligand of GPR14/SENR"},{"PMID":"11976263","why":"Kd and EC50 values at mouse and monkey UT receptors"}],"covers":["LR001526","LR004915"]},"LR001535":{"pair":"VCAN -> SELP","headline":"Versican binds P-selectin via its chondroitin sulfate chain; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Human ACHN-derived versican binds P-selectin, mediated by the CS chain and the carbohydrate-binding domain [PMID:10950950].","molecular_requirements":"Inhibited by CS B, CS E and heparan sulfate; shares an overlapping site with L-selectin [PMID:10950950].","affinity_potency":[],"species_and_systems":"Human versican with soluble selectin [PMID:10950950]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted; SELP flagged transmembrane receptor [flag].","caveats":"Glycan-mediated; single abstract-level paper. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10950950","why":"versican CS chain binds P-selectin"}],"covers":["LR001535","LR004924"]},"LR003443":{"pair":"VEGFA -> CD44","headline":"Direct, high-affinity binding of VEGF165 to the CD44v6 ectodomain, shown in one full-text paper; no other papers.","interaction_type":"direct binding","direction_and_effect":"VEGF binds CD44v6 directly (pull-down) with nanomolar affinity, and binding to cells depends on CD44v6; CD44v6 acts as a co-receptor that is required for VEGFR-2 (KDR) activation, so this is a coreceptor/potentiating role rather than a stand-alone receptor [PMID:26181364].","molecular_requirements":"The v6 variant exon is needed: CD44s showed no fit by MST and weak binding (1300\u00b1600 nM) by FCS. Binding is heparan sulfate-independent [PMID:26181364].","affinity_potency":[{"value":"Kd 51\u00b19 nM","assay":"MicroScale Thermophoresis, VEGF165 vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"},{"value":"Kd 200\u00b140 nM","assay":"FCS, VEGF165-NT647 vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"},{"value":"Kd 65\u00b18 nM","assay":"FCS, VEGF165-ATTO 647N vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"}],"species_and_systems":"Recombinant rat CD44v6 ectodomain made in HEK293T cells; cell binding in rat BSp73ASs6 cells and HUVEC; VEGF165 [PMID:26181364]. The mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA is flagged secreted and CD44 as transmembrane [flag]; the paper's assays used a soluble ectodomain, so a membrane-bound CD44v6 acting on secreted VEGF is the implied geometry.","caveats":"One paper, with the Kd values coming from three methods that differ about four-fold. No second group or in vivo support in our evidence. The affinity for CD44s is much lower.","key_references":[{"PMID":"26181364","why":"Pull-down, MST/FCS Kd values and isoform specificity for VEGF165 and CD44v6"}],"covers":["LR003443","LR006644"]},"LR001544":{"pair":"VEGFB -> FLT1","headline":"VEGF-B binds VEGFR-1/Flt-1 selectively; foundational paper plus structural and pathway database support.","interaction_type":"direct binding","direction_and_effect":"VEGF-B binds selectively to VEGF receptor-1/Flt-1; binding to endothelial cells increases urokinase plasminogen activator and PAI-1 expression and activity; curators label it agonist [PMID:9751730].","molecular_requirements":"Binding was competed by excess VEGF, suggesting partially overlapping sites. Mutating Asp63, Asp64 and Glu67 reduced but did not abolish affinity. The 60-kDa VEGF-B186 dimer processed to a 34-kDa dimer contains the receptor-binding epitopes [PMID:9751730].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; abstract-level reading [PMID:9751730]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFB flagged secreted and FLT1 transmembrane [flag].","caveats":"Curator read the abstract only; no affinity value reported in our evidence. Support also from a PDB structure [DB:PDB 2XAC], BioGRID reconstituted-complex and affinity-capture records [DB:BioGRID], and Reactome [DB:Reactome]. GtoPdb lists the pair without type or action [DB:GtoPdb]. Other judged rows (review-only, pending) are not shown.","key_references":[{"PMID":"9751730","why":"VEGF-B binds Flt-1 selectively; mapped determinants"}],"covers":["LR001544","LR004933"]},"LR004136":{"pair":"VEGFD -> NRP2","headline":"VEGF-D binds NP2 in a heparin-dependent manner in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VEGF-D interacts with NP2 in a heparin-dependent manner; NP2 cointernalises with VEGFR-3 in lymphatic endothelial cells on VEGF-C or VEGF-D stimulation [PMID:16816121].","molecular_requirements":"Heparin is needed for VEGF-D/NP2 binding; NP2 coprecipitates with VEGFR-3, suggesting a co-receptor role [PMID:16816121].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, in vitro binding and lymphatic endothelial cells; abstract-level [PMID:16816121]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single paper; no affinity; one abstract_insufficient row not shown. No database records in this dossier.","key_references":[{"PMID":"16816121","why":"VEGF-C/VEGF-D binding to NP2 and VEGFR-3 complex"}],"covers":["LR000652","LR004136"]},"LR001553":{"pair":"VIP -> NPR3","headline":"One abstract-level study in Xenopus oocytes shows VIP displacing ANP from frog NPR-C; human and mouse pairs are inferred from it.","interaction_type":"direct binding","direction_and_effect":"VIP competitively and completely displaced [125I]ANP from Xenopus NPR-C expressed in oocytes. With PAC1 co-expressed, VIP and natriuretic peptides counteracted PACAP-induced cAMP [PMID:16723209]. So VIP acts as an antagonist of PACAP signalling via NPR-C in this system, not as a clear NPR-C agonist.","molecular_requirements":"NPR-C lacks the guanylyl cyclase domain and is negatively coupled to adenylyl cyclase via Gi; the antagonism required co-expression with PAC1 [PMID:16723209].","affinity_potency":[],"species_and_systems":"Experiments used Xenopus laevis NPR-C in oocytes; the ligand is annotated human. No human or mouse receptor data in our evidence [PMID:16723209].","localisation_and_range":"VIP is flagged secreted [flag]; NPR3 has no transmembrane flag in our entity record.","caveats":"Single paper, abstract only, non-mammalian receptor. No affinity value reported. Human and mouse pairs are ortholog-inferred. The paper calls the finding paradoxical [PMID:16723209].","key_references":[{"PMID":"16723209","why":"Sole evidence: VIP displaces ANP at frog NPR-C and antagonises PACAP signalling"}],"covers":["LR001553","LR004942"]},"LR001562":{"pair":"VTN -> ITGB3","headline":"Vitronectin binds beta3 integrins on platelets and acts through alphaVbeta3 in smooth muscle and ovarian cancer cells; three abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Vitronectin bound stimulated human platelets (GPIIb/IIIa) in a calcium-dependent, specific, saturable manner, inhibited by RGDS and anti-GPIIb/IIIa antibodies [PMID:1692034]. AlphaVbeta3-mediated adhesion to vitronectin changed uPA and PAI-1 expression [PMID:11331280]. Residues 177-184 of beta3 were necessary for vitronectin binding to alphaVbeta3 and for the response of smooth muscle cells to IGF-I [PMID:16195248].","molecular_requirements":"Beta3 pairs with an alpha chain: alphaIIb on platelets (GPIIb/IIIa) [PMID:1692034] or alphaV in the other papers [PMID:11331280] [PMID:16195248]. Beta3 residues 177-184 are required [PMID:16195248].","affinity_potency":[{"value":"Kd 320 nM","assay":"vitronectin binding to platelets","system":"thrombin-stimulated human platelets","cite":"PMID:1692034"},{"value":"Kd 93 and 116 nM","assay":"vitronectin binding to platelets","system":"epinephrine- or ADP-stimulated human platelets","cite":"PMID:1692034"}],"species_and_systems":"Human platelets, human ovarian cancer cells; smooth muscle cell species not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry; the evidence is for alphaIIbbeta3 or alphaVbeta3 heterodimers. All papers abstract only; 3 further abstracts were insufficient and 1 is pending.","key_references":[{"PMID":"1692034","why":"Kd values for vitronectin on stimulated platelets"},{"PMID":"16195248","why":"beta3 177-184 needed for vitronectin binding to alphaVbeta3"},{"PMID":"11331280","why":"alphaVbeta3-vitronectin adhesion alters gene expression"}],"covers":["LR001562","LR004951"]},"LR003452":{"pair":"VWF -> ITGA4","headline":"The VWF propolypeptide (not mature VWF) promotes alpha4beta1-dependent cell adhesion; one paper, functional only.","interaction_type":"functional only","direction_and_effect":"The propolypeptide of VWF (pp-vWF) promoted adhesion of MOLT-3 cells through alpha4beta1, binding the same 15 residue site (T2-15) as alpha9beta1 [PMID:10816592]. Blocking by anti-alpha4 antibody is noted by the curators.","molecular_requirements":"alpha4 pairs with beta1 in the cited cells; the ligand is the propolypeptide, a processed form [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human MOLT-3 and G-361 cells, with transfected SW480 cells for alpha9beta1 [PMID:10816592]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Ligand is pp-vWF cleaved from the precursor, so the result may not apply to mature circulating VWF. Cell adhesion assay, not binding. Chain-level evidence for alpha4.","key_references":[{"PMID":"10816592","why":"pp-vWF supports alpha4beta1 and alpha9beta1 mediated adhesion"}],"covers":["LR003452","LR006652"]},"LR003461":{"pair":"WFIKKN2 -> IGDCC4","headline":"WFIKKN2 is reported as a secreted axon-guidance ligand acting through IGDCC4 (Nope); evidence is a preprint abstract only.","interaction_type":"functional only","direction_and_effect":"WFIKKN2 guides mouse peripheral sensory axons through Nope-mediated repulsion, whereas its attraction of motor axons does not use Nope [PMID:37398498]. The curator labelled the effect as antagonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse axon-guidance experiments are described in the abstract; the dossier lists human proteins [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; the receptor is flagged as a receptor [flag].","caveats":"No direct binding assay for this pair in our evidence. Only one paper, a bioRxiv preprint read as abstract only [PMID:37398498]. Other judged rows were abstract_insufficient.","key_references":[{"PMID":"37398498","why":"WFIKKN2 repels sensory axons via Nope (abstract only)"}],"covers":["LR003461","LR006661"]},"LR011237":{"pair":"WNT1 -> FZD3:LRP5","headline":"WNT1 to FZD3:LRP5 has no verified evidence; only a UniProt note on LRP5.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt notes an LRP5 interaction enhanced by WNT1 or WNT3A [DB:UniProt]; FZD3 is not mentioned.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper; four rows were abstract_insufficient and one review_only. The single record does not name FZD3.","key_references":[],"covers":["LR011237"]},"LR010814":{"pair":"WNT1 -> FZD3:LRP6","headline":"WNT1 to FZD3:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Both judged rows are review_only. Reactome records are Wnt1:Frizzled1 complexes, not FZD3 [DB:Reactome].","key_references":[],"covers":["LR010814"]},"LR010832":{"pair":"WNT1 -> FZD9:LRP5","headline":"Database-asserted only: WNT1 with FZD9:LRP5, no papers; the UniProt notes concern LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence. UniProt notes an LRP5 subunit interaction enhanced in the presence of GSK3B and WNT1 or WNT3A [DB:UniProt].","molecular_requirements":"FZD9 is not named in any record shown.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Six judged papers were abstract_insufficient or review_only; nothing confirms FZD9 or the combined complex.","key_references":[],"covers":["LR010832"]},"LR005360":{"pair":"WNT10A -> FZD1","headline":"A glioblastoma abstract reports WNT10A-FZD1 co-IP and JNK pathway activation.","interaction_type":"direct binding","direction_and_effect":"Co-IP assays confirmed an interaction between WNT10A and FZD1, which activated the JNK/c-Jun/FOSB pathway and enhanced FOSB transcription [PMID:40099486].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Glioblastoma cells and orthotopic xenografts, abstract only; species not reported in our evidence [PMID:40099486]. The mouse pair is projected from human.","localisation_and_range":"GBM cells secreted WNT10A into the tumour microenvironment, acting on macrophages and astrocytes [PMID:40099486].","caveats":"Co-IP alone does not show direct binding; four other papers were abstract_insufficient.","key_references":[{"PMID":"40099486","why":"WNT10A-FZD1 co-IP in glioblastoma"}],"covers":["LR002034","LR005360"]},"LR008033":{"pair":"WNT10A -> FZD1:LRP6","headline":"WNT10A-FZD1 co-IP in glioblastoma supports the FZD1 member; LRP6 is not addressed.","interaction_type":"direct binding","direction_and_effect":"Co-IP assays confirmed an interaction between WNT10A and FZD1, activating JNK/c-Jun/FOSB signalling [PMID:40099486].","molecular_requirements":"LRP6 is not reported in our evidence; only FZD1 is supported.","affinity_potency":[],"species_and_systems":"Glioblastoma cells, abstract only; species not reported [PMID:40099486].","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Complex support comes from one subunit; four other papers were abstract_insufficient or review_only.","key_references":[{"PMID":"40099486","why":"WNT10A-FZD1 co-IP"}],"covers":["LR008033"]},"LR011246":{"pair":"WNT10B -> FZD1:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR011246"]},"LR010670":{"pair":"WNT10B -> FZD2:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010670"]},"LR010706":{"pair":"WNT10B -> FZD4:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010706"]},"LR003470":{"pair":"WNT10B -> LRP6","headline":"WNT10B acting through LRP6 is supported by co-culture IP and antibody-blocking assays; the binding evidence is indirect.","interaction_type":"functional only","direction_and_effect":"An anti-LRP6 antibody class that binds LRP6 propeller 1 blocked signalling by a group of Wnts including Wnt10b in a reporter assay [PMID:20713706]. SMOC-2 enhanced Wnt10b-LRP6 interaction in co-culture IP, with agonist direction annotated [PMID:30594556].","molecular_requirements":"LRP6 is treated as a Wnt co-receptor; Wnt10b is in the class inhibited by propeller-1 antibodies [PMID:20713706]. Whether Wnt10b binds LRP6 alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 and HEK293T cells (recombinant, tagged proteins); the mouse pair is projected from human evidence. Both papers were read as abstract only or by browser, not as stored text.","localisation_and_range":"Ligand is flagged secreted and LRP6 transmembrane [flag]; signalling is likely paracrine to a cell-surface receptor.","caveats":"Neither paper shows a Wnt10b-LRP6 binding measurement alone: the first shows SMOC-2-dependent enhancement, the second blockade by antibodies. No affinity reported.","key_references":[{"PMID":"20713706","why":"Wnt10b among Wnts blocked by Wnt1-class anti-LRP6 Fabs (SuperTopFlash, HEK293)"},{"PMID":"30594556","why":"Co-culture IP: SMOC-2 enhanced Wnt10b-LRP6 interaction"}],"covers":["LR003470","LR006670"]},"LR001571":{"pair":"WNT11 -> FZD7","headline":"WNT11 binds FZD7 by co-IP in Xenopus and a 2026 CRC paper reports direct interaction; both are supported mainly by abstract-level reads.","interaction_type":"direct binding","direction_and_effect":"Myc-tagged Xwnt11 co-immunoprecipitated with the extracellular domain of Xfz7 and Xfz7 recruited Xwnt11 to the plasma membrane; overexpression affected convergent extension [PMID:10862746]. A colorectal cancer paper states Wnt11 directly interacts with FZD7 to activate PCP/ROCK signalling and YAP [PMID:42760160].","molecular_requirements":"The Xenopus co-IP used the extra-cellular (secreted) form of Xfz7, so the receptor ectodomain suffices for binding there [PMID:10862746]. No co-receptor requirement reported.","affinity_potency":[],"species_and_systems":"Xenopus laevis embryos with Xenopus orthologs [PMID:10862746]; human colorectal cancer cells [PMID:42760160]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; Reactome lists WNT:FZD at the plasma membrane [DB:Reactome].","caveats":"The binding quote for 10862746 was browser-read and not spot-checked; the abstract-only CRC paper's method for 'direct' interaction is not stated. No affinity.","key_references":[{"PMID":"10862746","why":"Xwnt11 co-IPs with Xfz7 ectodomain; functional interaction in Xenopus"},{"PMID":"42760160","why":"Wnt11 reported to interact directly with FZD7 in CRC cells"}],"covers":["LR001571","LR004960"]},"LR002039":{"pair":"WNT16 -> LRP5","headline":"WNT16 acting via LRP5 is supported by knockdown in human osteoblast-like cells; no direct binding data.","interaction_type":"functional only","direction_and_effect":"IL-1beta raised Wnt16 and Lrp5/Fzd2; exogenous Wnt16 increased MMP-13 and proliferation, and siRNAs against Wnt16 and Lrp5 suppressed the IL-1beta-induced proliferation (agonist annotated) [PMID:26861315].","molecular_requirements":"Lrp5 was inferred together with Fzd2 as the Wnt receptor; whether LRP5 alone suffices is not reported in our evidence [PMID:26861315].","affinity_potency":[],"species_and_systems":"Human skeletal muscle stem cell-derived osteoblast-like cells, abstract only [PMID:26861315]. Mouse pair is not ortholog-inferred.","localisation_and_range":"Wnt16 flagged secreted and LRP5 transmembrane [flag].","caveats":"Knockdown cannot separate LRP5 binding from pathway effects. No affinity.","key_references":[{"PMID":"26861315","why":"IL-1beta to Wnt16 to Lrp5 to MMP-13 axis; siRNA rescue"}],"covers":["LR002039","LR005365"]},"LR001580":{"pair":"WNT2 -> FZD1","headline":"Fzd1 cooperates weakly with Wnt2 in TCF reporter assays; binding of Wnt2 was not shown.","interaction_type":"functional only","direction_and_effect":"Human Fzd1 enhanced TCF-dependent transcription with Wnt-3a, -3, -1 and to a lesser extent Wnt-2 in a paracrine assay [PMID:10557084]. UniProt states FZD1 is activated by WNT3A, WNT3, WNT1 and to a lesser extent WNT2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Hfz1 (human) in a cell reporter assay; Wnt species and cell line not reported in our evidence; abstract only. Mouse pair ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag]; paracrine mode was tested [PMID:10557084].","caveats":"Wnt-2 was a weaker partner. Co-IP was shown only for Wnt-3a and Wnt-5a, and the authors say signalling is not set by binding alone [PMID:10557084]. No affinity.","key_references":[{"PMID":"10557084","why":"Hfz1 enhances TCF signalling with Wnt-3a, -3, -1, weakly Wnt-2"}],"covers":["LR001580","LR004969"]},"LR010751":{"pair":"WNT2 -> FZD5:LRP6","headline":"WNT2 to FZD5:LRP6 has only a UniProt function statement and two review-only rows.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (Q13467) states that in vitro it activates WNT2, WNT10B, WNT5A, but not WNT2B or WNT4 signalling [DB:UniProt].","molecular_requirements":"LRP6 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"No judged paper. The UniProt text is marked as by similarity and does not state a species or assay.","key_references":[],"covers":["LR010751"]},"LR008123":{"pair":"WNT3A -> FZD10:LRP5","headline":"No curated paper confirms this complex; support is limited to database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this complex.","molecular_requirements":"Receptor is a complex of FZD10 and LRP5.; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our verified evidence. UniProt notes for LRP5 say an interaction is enhanced in the presence of GSK3B and WNT1 or WNT3A, without naming a direct WNT3A-receptor contact [DB:UniProt] [PMID:11336703] [PMID:14731402].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Only review articles or abstracts too thin to judge were found (outcome counts show review_only and abstract_insufficient), so no primary evidence is verified.","key_references":[],"covers":["LR008123"]},"LR008051":{"pair":"WNT3A -> FZD2:LRP6","headline":"One full-text paper supports FZD1/2/7 signalling with Wnt3/Wnt3a; the LRP6 component is not specifically tested.","interaction_type":"functional only","direction_and_effect":"FZD1, FZD2 and FZD7 share up to 75% homology and specifically induce signalling after binding Wnt3 and Wnt3a [PMID:28733458]; Wnt3/Wnt3a signalled via all FZDs in rescue experiments [PMID:28733458].","molecular_requirements":"The paper concerns FZD genes; LRP6 involvement is not tested in the quoted passages. FZD2 chain evidence is from a TCF4/Wnt reporter in FZD1,2,7-mutant HEK293T cells [PMID:28733458]. BioGRID lists LRP6-WNT3A Affinity Capture-Western [DB:BioGRID] [PMID:19910923]; IntAct and Reactome list WNT3A complex records [DB:IntAct] [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human cell lines (HEK293T) with CRISPR-mutant FZD alleles [PMID:28733458].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Chain-only evidence for FZD2; the evidence sentence does not mention LRP6. assay_class is direct_binding though the cited work is a functional reporter rescue. Read depth full text but no affinity.","key_references":[{"PMID":"28733458","why":"FZD1/2/7 rescue of Wnt3a signalling"}],"covers":["LR008051"]},"LR008060":{"pair":"WNT3A -> FZD4:LRP6","headline":"No curated paper for this complex; support is database records of WNT3A with LRP6 only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"The records concern LRP6 and WNT3A; UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]. Nothing in the records addresses FZD4 in the complex.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID affinity capture-western [DB:BioGRID], IntAct coimmunoprecipitation [DB:IntAct], and Reactome WNT3A:FZD:LRP5/6 complexes with FZD unspecified [DB:Reactome]. FZD4 specificity is not shown; papers were review_only or abstract_insufficient.","key_references":[],"covers":["LR008060"]},"LR006701":{"pair":"WNT4 -> FZD8","headline":"WNT4 shows strong binding to the FZD8 CRD in purified-protein assays.","interaction_type":"direct binding","direction_and_effect":"WNT-4 showed strong binding to the FZD8 CRD [PMID:25605717].","molecular_requirements":"Binding was measured to the CRD-Fc fusion alone [PMID:25605717].","affinity_potency":[],"species_and_systems":"Purified mouse proteins, bio-layer interferometry (Octet) [PMID:25605717]. Mouse pair is direct; human ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"KD values are in a table not shown in our evidence. Browser-read, not spot-checked. Binding only; signalling not reported here.","key_references":[{"PMID":"25605717","why":"BLI of WNT-4 binding to FZD CRDs"}],"covers":["LR003501","LR006701"]},"LR008042":{"pair":"WNT5A -> FZD1:LRP6","headline":"No paper-level evidence for WNT5A with the FZD1:LRP6 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records WNT5A - FZD1 and LRP6 - WNT5A Affinity Capture-Western [DB:BioGRID]; UniProt notes FZD1 is apparently not activated by WNT5A [DB:UniProt].","molecular_requirements":"The complex combines FZD1 and LRP6; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR008042"]},"LR008132":{"pair":"WNT5A -> FZD2:LRP5","headline":"No paper-level evidence for WNT5A with the FZD2:LRP5 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records FZD2 - WNT5A Affinity Capture-Western [DB:BioGRID]; Reactome lists WNT5A binding FZD and ROR receptors [DB:Reactome].","molecular_requirements":"The complex combines FZD2 and LRP5; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR008132"]},"LR001607":{"pair":"WNT5A -> FZD8","headline":"Direct binding to the FZD8 cysteine-rich domain, shown by two bio-layer interferometry studies with purified mouse proteins.","interaction_type":"direct binding","direction_and_effect":"WNT5A binds FZD8 CRD with high affinity [PMID:25605717]; the curated modulatory effect is stimulatory (annotation). In the same 32D cell study, WNT-5A did not activate the WNT-beta-catenin pathway through FZD2/4/5 [PMID:25605717].","molecular_requirements":"Binding was to the FZD8 CRD (CRD-Fc fusion) alone; no co-receptor was needed for binding [PMID:20093360].","affinity_potency":[{"value":"KD = 50 nm","assay":"biolayer interferometry (Octet), Wnt5a binding to Fz8 CRD-Fc","system":"purified mouse proteins","cite":"PMID:20093360"},{"value":"KD = 4-8 nm","assay":"bio-layer interferometry, WNT-5A/5B binding to FZD8 CRD","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Both papers used mouse ligand and mouse receptor fragments in vitro; the human pair is ortholog-inferred in the interaction list.","localisation_and_range":"WNT5A is flagged secreted and FZD8 non-secreted [flag].","caveats":"Both papers were read as abstracts in our text field though the curator notes mention browser reading with unverified quotes. The two KD values differ about 10-fold between studies. Recombinant CRD binding, not full-length receptor in cells.","key_references":[{"PMID":"25605717","why":"Systematic WNT-FZD CRD binding map; KD 4-8 nm for WNT-5A to FZD8 CRD"},{"PMID":"20093360","why":"Wnt5a KD = 50 nm to Fz8 CRD"}],"covers":["LR001607","LR004996"]},"LR003506":{"pair":"WNT5A -> LRP6","headline":"Physical interaction reported, but non-productive: Lrp6 binds Wnt5a without signalling and acts as an inhibitor of noncanonical Wnt5a signalling.","interaction_type":"direct binding","direction_and_effect":"Lrp6 physically interacts with Wnt5a without Lrp6 phosphorylation or Wnt/beta-catenin activation; Lrp6 overexpression blocks activation of Rac1, a Wnt5a target, and Lrp6-/- mouse defects were rescued by Wnt5a deletion [PMID:19056682]. Curated as antagonist.","molecular_requirements":"Effect depends on intact Lrp6 extracellular domains [PMID:19056682].","affinity_potency":[],"species_and_systems":"Mouse knockouts and Xenopus morphants plus in vitro cells [PMID:19056682]. BioGRID records an affinity capture-Western [DB:BioGRID 692083].","localisation_and_range":"Ligand flagged secreted, LRP6 transmembrane [flag].","caveats":"Abstract only; interaction method and affinity not reported in our evidence. Acts as a sequestering inhibitor, not an activating receptor, so treat as antagonist/decoy-like.","key_references":[{"PMID":"19056682","why":"Lrp6 binds Wnt5a and inhibits noncanonical signalling in mouse and Xenopus"}],"covers":["LR003506","LR006706"]},"LR006710":{"pair":"WNT5A -> TMEM67","headline":"TMEM67 binds Wnt5a in vitro and is needed for ROR2 phosphorylation by Wnt5a; mouse evidence, one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist-like: TMEM67 is essential for ROR2 phosphorylation on Wnt5a-conditioned medium stimulation, and Tmem67 mutant lung explants fail to respond to Wnt5a [PMID:26035863]. UniProt also records TMEM67 as interacting with WNT5A [DB:UniProt].","molecular_requirements":"The extracellular N-terminal domain (cysteine-rich domain) of TMEM67 binds Wnt5a; ROR2 acts as a co-receptor and interacts with TMEM67 [PMID:26035863].","affinity_potency":[],"species_and_systems":"Mouse knockout and mouse lung explants, in vitro binding assay [PMID:26035863]; pair is ortholog-inferred in both human and mouse.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only. Binding was seen at the ciliary transition zone context only for ROR2 [PMID:26035863].","caveats":"The binding is described as preferential, but the comparison proteins are not given in our evidence. No affinity reported. Curated from the abstract; excerpts available [PMID:26035863].","key_references":[{"PMID":"26035863","why":"TMEM67 binds Wnt5a and is needed for ROR2 phosphorylation and lung branching response"}],"covers":["LR003510","LR006710"]},"LR003515":{"pair":"WNT5B -> FZD7","headline":"WNT5B appears to bind the FZD7 CRD only weakly in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to the listed CRDs, which appear to include FZD7 [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The sentence names FZD7 only for WNT-5A; the WNT-5B statement says 'these' CRDs.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003515","LR006715"]},"LR002048":{"pair":"WNT6 -> FZD7","headline":"FZD7 is a putative Wnt6 receptor from co-expression and canonical signalling; weak, abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt6 signals through the canonical pathway in renal epithelial cells; FzD7 was identified as a putative receptor [PMID:27122540].","molecular_requirements":"Canonical beta-catenin/TCF-Lef signalling; no binding or subunit data [PMID:27122540].","affinity_potency":[],"species_and_systems":"Mouse developing kidney (mesonephros), human renal biopsies, renal epithelial cells in 3D culture [PMID:27122540].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"'Putative' receptor; no direct binding assay is described. Abstract only [PMID:27122540].","key_references":[{"PMID":"27122540","why":"Wnt6 canonical signalling with putative FzD7 receptor in renal epithelium"}],"covers":["LR002048","LR005374"]},"LR003524":{"pair":"WNT7A -> LRP5","headline":"WNT7A binds recombinant LRP5 ECD in HEK293 conditioned medium; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRP5 ECD bound WNT7A in conditioned medium from WNT7A-expressing HEK293 RECK-/- cells; DKK1, an LRP5/6 antagonist, dose-dependently inhibited RECK/GPR124/WNT7 signalling [PMID:30304675].","molecular_requirements":"LRP5/6 act with FZD and RECK/GPR124 in WNT7 canonical signalling [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 RECK-/- cells [PMID:30304675]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged transmembrane [flag].","caveats":"Single paper; no affinity reported. Active WNT7A is short-lived in medium [PMID:30304675]. The curated evidence sentence concerns FZD4 with LRP5 co-transfection, not LRP5 binding.","key_references":[{"PMID":"30304675","why":"LRP5 and LRP6 ECDs bound WNT7A"}],"covers":["LR003524","LR006724"]},"LR001616":{"pair":"WNT7A -> LRP6","headline":"WNT7A binds LRP6 ECD and is blocked by anti-LRP6 antibodies; binding plus functional support.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRP6 ECD bound WNT7A [PMID:30304675]. Anti-LRP6 Wnt1-class Fabs inhibited Wnt7a signalling in a SuperTopFlash reporter [PMID:20713706]. In rat PC12 cells WNT7A acted via a Frizzled-5.LRP6 complex and was antagonised by Dickkopf-1 and -3 [PMID:12857724].","molecular_requirements":"Evidence of PMID:12857724 is for the Frizzled-5/LRP6 complex rather than LRP6 alone. Wnt1-class Fabs bind the first propeller of LRP6 [PMID:20713706].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 [PMID:30304675, PMID:20713706]; human WNT7A on rat PC12 cells [PMID:12857724]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged transmembrane [flag].","caveats":"Two of three papers are abstract-only; the PNAS evidence is antibody inhibition, not binding. No affinity reported. Active WNT7A is short-lived in medium [PMID:30304675].","key_references":[{"PMID":"30304675","why":"LRP6 ECD binds WNT7A (full text)"},{"PMID":"20713706","why":"Anti-LRP6 Fabs block Wnt7a signalling"},{"PMID":"12857724","why":"WNT7A via Frizzled-5/LRP6, DKK antagonism"}],"covers":["LR001616","LR005005"]},"LR008114":{"pair":"WNT7B -> FZD1:LRP5","headline":"WNT7B with FZD1 and LRP5 has only UniProt annotations, with a conflicting UniProt note.","interaction_type":"conflicting","direction_and_effect":"UniProt says FZD1-related text 'Interacts with FZD1 and FZD10' and, for FZD1, 'Interacts with WNT7B (By similarity)'; it also says FZD1 is apparently not activated by WNT7B [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"No confirmed papers (one review-only, one abstract-insufficient). Database statements are contradictory [DB:UniProt].","key_references":[],"covers":["LR008114"]},"LR008150":{"pair":"WNT7B -> FZD5:LRP5","headline":"WNT7B-FZD5:LRP5 rests on an ovarian cancer abstract naming only WNT7B/FZD5.","interaction_type":"functional only","direction_and_effect":"The WNT7B/FZD5 pair positively modulated an LGR4-ELF3 regulatory loop in high-grade serous ovarian cancer cells [PMID:32980127].","molecular_requirements":"LRP5 is not named in the evidence.","affinity_potency":[],"species_and_systems":"HGSOC cells; species not stated [PMID:32980127].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only; functional context, not binding. Co-receptor is unsupported.","key_references":[{"PMID":"32980127","why":"WNT7B/FZD5 pair modulates LGR4-ELF3 loop"}],"covers":["LR008150"]},"LR003533":{"pair":"WNT8A -> ROR2","headline":"WNT8A activates ROR2 per one abstract on cytoneme-based Wnt transport; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Upon Wnt8a binding, the receptor tyrosine kinase Ror2 becomes activated, leading to Ror2/PCP signalling that induces cytonemes transporting Wnt8a to neighbouring cells (agonist) [PMID:30060804].","molecular_requirements":"Ror2 alone is described; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Zebrafish development, murine intestinal crypt and human cancer organoids [PMID:30060804]. The dossier labels the pair human, with the human and mouse entries projected from this evidence.","localisation_and_range":"Wnt8a is carried on cytonemes to neighbouring cells, giving contact-dependent paracrine delivery [PMID:30060804]; ligand also flagged secreted [flag].","caveats":"Abstract only. The 'binding' statement is part of a mechanism narrative; no binding assay or affinity is described. The only excerpt is a methods passage.","key_references":[{"PMID":"30060804","why":"Ror2 activation by Wnt8a drives cytoneme Wnt transport"}],"covers":["LR003533","LR006733"]},"LR002057":{"pair":"WNT9A -> FZD4","headline":"WNT9A signals through FZD4 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"Only the Frizzled receptor is tested; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts. The mouse pair is projected from the human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR002057","LR005383"]},"LR008141":{"pair":"WNT9B -> FZD4:LRP5","headline":"Complex rests on a single functional reporter study of WNT9B with FZD4; the LRP5 co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"WNT9B induced canonical signalling with FZD4 in a FZD rescue reporter map; effect is activating (canonical) [PMID:28733458].","molecular_requirements":"The cited study tested FZD receptors in rescue assays and does not report LRP5 as a tested subunit of this complex in our excerpts; the complex is a combination of the pair FZD4 and LRP5 not evaluated as a unit.","affinity_potency":[],"species_and_systems":"Human reporter cells, HEK293 FZD multiplex-knockout panel with rescue; full text read [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Evidence is for the Frizzled chain alone; LRP5 is not shown to be required. Functional readout only, no binding measured. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR008141"]},"LR005009":{"pair":"XCL1 -> XCR1","headline":"Well supported direct agonist pair: XCL1 binds XCR1 (Kd 10 nM) and activates it in human cell systems; mouse pair is also listed.","interaction_type":"direct binding","direction_and_effect":"XCL1 (SCM-1alpha) is an agonist of XCR1: it induced chemotaxis and calcium mobilisation in XCR1 (GPR5)-expressing L1.2 cells, with pertussis-toxin-sensitive migration indicating Galpha-type G protein coupling [PMID:9632725]. The monomeric XCL1 form binds and activates XCR1, while the dimer binds glycosaminoglycans and lacks XCR1 agonist activity [PMID:25497737]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Single-chain receptor, no co-receptor reported. The monomeric (Ltn10) conformation is the active form; the dimer is not [PMID:25497737]. Reactome describes an XCR1:XCL1,XCL2 complex [DB:Reactome]. A PDB structure with one chain of each partner exists [DB:PDB 9AST].","affinity_potency":[{"value":"Kd 10 nM","assay":"specific binding to receptor-expressing cells","system":"L1.2 cells expressing GPR5/XCR1, human SCM-1alpha","cite":"PMID:9632725"},{"value":"pEC50 7.3","assay":"functional activation by monomeric XCL1 (curator-recorded)","system":"human ligand and receptor","cite":"PMID:25497737"}],"species_and_systems":"Human ligand and receptor, recombinant, in murine L1.2 cells [PMID:9632725] and XCR1-transfected HEK 293 cells [PMID:25497737]. One further paper used mouse T cells in vitro and in vivo, but only correlated migration with XCR1 mRNA [PMID:11446740].","localisation_and_range":"XCL1 is flagged secreted and XCR1 transmembrane [flag]; this implies paracrine chemokine signalling. The dimeric form binds extracellular-matrix GAGs [PMID:25497737].","caveats":"The binding result was read from the abstract only [PMID:9632725]. The mouse study is correlative, not direct binding [PMID:11446740]. XCL2 shares the receptor, so XCL1 and XCL2 are not distinguishable by XCR1 expression alone [PMID:25497737].","key_references":[{"PMID":"9632725","why":"Identified XCR1 as the receptor; Kd 10 nM"},{"PMID":"25497737","why":"Monomer activates XCR1; dimer binds GAGs"},{"PMID":"11446740","why":"Mouse T-cell migration correlated with XCR1 mRNA"}],"covers":["LR001620","LR005009"]},"LR001625":{"pair":"ZG16B -> TLR5","headline":"Co-immunoprecipitation only: PAUF associated with TLR5 in HEK293T cells; no functional or affinity data.","interaction_type":"direct binding","direction_and_effect":"PAUF associated with TLR2, 5 and 6 but not TLR3, 8, 9 or 10 in co-immunoprecipitation, indicating binding to a subset of TLR family proteins [PMID:20802527]. Effect on TLR5 signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins overexpressed in HEK293T cells; the data are in a supplementary figure [PMID:20802527]. IntAct records an anti-tag co-immunoprecipitation [DB:IntAct].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"Co-immunoprecipitation does not show whether binding is direct or via TLR2, which PAUF binds directly. Supplementary data only; no replicate or affinity details in our evidence.","key_references":[{"PMID":"20802527","why":"PAUF co-immunoprecipitates with TLR2, 5 and 6"}],"covers":["LR001625"]},"LR008411":{"pair":"BTLA -> VTCN1","headline":"A single abstract-only paper reports B7x (VTCN1) as a ligand of BTLA; no database support.","interaction_type":"functional only","direction_and_effect":"The paper states B7x is a ligand of BTLA, and describes BTLA as an inhibitory receptor on T cells [PMID:12796776]. Direction for this pair is not further specified in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and cell system are unspecified for the ligand identification; the abstract describes T cells and BTLA-deficient mice [PMID:12796776].","localisation_and_range":"Both entities are annotated as membrane receptors, not secreted [flag]; the pair is listed as Receptor-Receptor [flag].","caveats":"Evidence is one sentence from an abstract re-read; no binding assay, affinity or database record is reported in our evidence [PMID:12796776].","key_references":[{"PMID":"12796776","why":"Identifies BTLA as an inhibitory receptor and B7x as its ligand (abstract only)"}],"covers":["LR008411"]},"LR004316":{"pair":"IL1RN -> IL1R2","headline":"Direct binding of IL-1ra to the type II IL-1 receptor shown by radioligand competition on human cells; database records agree.","interaction_type":"direct binding","direction_and_effect":"IL-1ra binds the type II receptor with an affinity equal to IL-1 alpha and 15-fold lower than IL-1 beta, suggesting it may be a weaker competitor of IL-1 [PMID:1834644]. Reactome lists an IL1R1:IL1R2:IL1RN complex [DB:Reactome]. The curated 'Stimulatory' label is not explained in our evidence.","molecular_requirements":"Single receptor chain IL1R2 on cells was sufficient for binding in the assay [PMID:1834644]. Co-receptor needs are not reported in our evidence.","affinity_potency":[{"value":"KD = 15 +/- 3 nM","assay":"radioligand competition binding","system":"human Raji B cells","cite":"PMID:1834644"},{"value":"KD = 8 +/- 4 nM","assay":"radioligand binding","system":"human polymorphonuclear leukocytes","cite":"PMID:1834644"},{"value":"KD = 1.4 +/- 0.2 microM","assay":"radioligand binding","system":"mouse 70Z/3 pre-B cells, human IL-1ra","cite":"PMID:1834644"}],"species_and_systems":"Human and rodent IL-1ra on human Raji and PMN cells and mouse pre-B cells; native cell receptors, not recombinant [PMID:1834644].","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Abstract only. Binding to mouse cells was weak and attributed to cell type rather than species [PMID:1834644]. Mouse pair is projected from human evidence.","key_references":[{"PMID":"1834644","why":"Binding affinity of IL-1ra to type II IL-1 receptor"}],"covers":["LR000886","LR004316"]}};